/* ÇEVİRİ jv · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("jv","olay",{
"OLAYLAR:1299-01:0":{"b": ["Adege Kadipaten Utsmaniyah", "9f0b7c0a"], "d": ["Wiwite Osman Ghazi saka suku Kayi tumindak mardika ing sakiwa-tengene Söğüt-Domaniç ditampa minangka wiwitan sing wis dadi tradhisi kanggo adege Nagara Utsmaniyah; sawetara sejarawan nganggep kamenangan Bapheus ing taun 1302 minangka titik owah-owahan sing sejatine. Amarga panggonane ing tlatah tapel wates Bizantium, kadipaten iku kanthi cepet nglumpukake kakuwatan liwat serangan ghaza. Ing kahanan nalika warisan Seljuk lagi ajur, Osman Ghazi nglumpukake para ahi, para ghazi lan wong Turkmen sing urip ngumbara ing sakiwa-tengene; sesambungan sing diadegake karo Syekh Edebali dianggep minangka dhasar legitimasi rohani kadipaten. Panggonan liya sing digabungake ing tanggal sing padha: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Penaklukan Bursa", "98c727fa"], "d": ["Bursa, sing wis pirang-pirang taun dikepung, nyerah marang Orhan Ghazi sing mimpin tahap pungkasan pengepungan; kutha iku didadèkaké ibu kutha gedhé kapisan kadipaten. Dicritakake yen kabar penaklukan iku diaturake marang Osman Ghazi sing lagi sekarat; miturut wasiyate, Osman Ghazi disarèkaké ing Bursa. Ora suwe kutha iku dilengkapi mesjid, dapur umum (imaret) lan madrasah, banjur dadi conto tata kutha Utsmaniyah ing mangsa wiwitan.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Penaklukan Iznik", "a846a811"], "d": ["Iznik (Nikaia), salah siji pusat Bizantium sing paling wigati ing Anatolia, kelangan pangarep-arep kanggo bertahan sawise kamenangan Pelekanon ing taun 1329, banjur nyerah marang Orhan Ghazi. Madrasah Utsmaniyah kapisan diadegake ing kene, lan ulama kaya Dâvûd-i Kayserî wiwit mulang; kutha iku dadi pusat ilmu ing mangsa wiwitan. Greja Hagia Sophia diowahi dadi mesjid, nuduhake conto wiwitan saka tradhisi penaklukan.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Penaklukan Izmit", "06a35035"], "d": ["Kanthi tibane Izmit (Nikomedia), bèntèng wigati pungkasan Bizantium ing sisih Anatolia uga mlebu ing pamaréntahan Utsmaniyah; kabeh semenanjung Kocaeli nganti tekan pesisir ing sabrangé Istanbul dadi wilayah Utsmaniyah. Kanthi mangkono kadipaten nguwasani kabeh pesisir kidul lan wétan Segara Marmara lan nyiapake dhasar kanggo nyabrang menyang Rumelia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Bèntèng Cimpe — nyabrang menyang Rumelia", "c2f0a07d"], "d": ["Suleyman Pasya, putrané Orhan Ghazi, ing taun 1352 wis ndadèkaké Bèntèng Cimpe, sing diwènèhaké nalika perang sedulur Bizantium, minangka pangkalan; sawisé lindhu gedhé sing ngrusak Gallipoli ing Maret 1354, bèntèng-bèntèng sing ditinggal kosong kanthi cepet dikuwataké lan semenanjung iku diowahi dadi pancadan Utsmaniyah sing tetep. Tumindak iki, sing didhukung kanthi manggonaké pendhudhuk Turkmen sing digawa saka Anatolia, minangka wiwitan anané Utsmaniyah ing bawana Éropah sing bakal lumaku luwih saka 550 taun.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Penaklukan Edirne", "2f54ebb0"], "d": ["Direbuté Edirne (Adrianopolis), kutha kunci ing Trakia, nemtokaké pangkalan utama lan arah penaklukan Balkan; tanggal penaklukané isih dadi pasulayan ing sumber-sumber, antarané 1361 lan 1369. Ora suwe kutha iku didadèkaké ibu kutha, sing ngumumaké yen pusat bobot nagara wis pindhah menyang Rumelia; kutha iku tetep dadi kutha tahta (payitaht) suwéné kira-kira 90 taun nganti penaklukan Istanbul.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I munggah tahta", "f8d48a26"], "d": ["Murad I (Hudavendigar), sing munggah tahta sawise sédané Orhan Ghazi, sajrone 27 taun mréntah nggawa nagara saka kadipaten tapel wates dadi rerangkèn kekaisaran. Liwat sistem pencik dipasang dhasar Korps Yenisari, tatanan timar disebarluaskan, Beylerbeylik Rumelia diadegake lan lembaga wazir dikuwataké. Penaklukan Balkan dadi kawicaksanan nagara sing tumata ing mangsa pamaréntahané.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Perang Kosovo I — Murad I gugur syahid", "10b8ddc9"], "d": ["Persekutuan Balkan sing dipimpin Pangeran Lazar dikalahaké kanthi mesthi ing Dhataran Kosovo; Serbia mlebu ing sangisoré kakuwasaan dhuwur Utsmaniyah. Murad I, sing lagi ngubengi papan perang, disuduk nganggo keris cilik déning bangsawan Serbia Miloš Obilić nganti gugur syahid — panjenengané iku siji-sijiné sultan Utsmaniyah sing séda ing papan perang. Minangka gantiné, Bayezid Yildirim diunggahaké tahta ing pakemahan; sedulure, Yakub Celebi, dijiret nganti mati, lan iki dadi salah siji conto wiwitan sing dimangertèni saka praktik matèni sedulur.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Kamenangan Nikopolis", "75716e96"], "d": ["Wadyabala Salib gedhé sing diklumpukaké amarga pangundangé raja Hungaria Sigismund, sing uga dimèlu para ksatria Prancis lan Burgundia, dikalahaké kanthi abot déning Bayezid Yildirim ing ngarep Nikopolis ing pinggir Kali Donau. Kamenangan iku nemtokaké kakuwasaan Utsmaniyah ing Bulgaria; sajrone sak generasi ora bisa dianakaké ekspedisi Salib gedhé ing Éropah.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Perang Ankara — Mangsa Interregnum (Fetret) diwiwiti", "b4a99d96"], "d": ["Ing kekalahan abot nglawan wadyabala Timur ing Dhataran Cubuk, Bayezid Yildirim ditawan lan sawetara sasi sawisé séda ing tawanan. Timur nguripaké manèh kadipaten-kadipaten Anatolia; wilayah Utsmaniyah dipérang ing antarané para putrané Bayezid lan diwiwiti rebutan tahta sing lumaku 11 taun (Mangsa Interregnum). Mangsa iki, krisis paling abot sing dialami nagara wiwit ngadegé, ngukir wigatiné tatanan sing kapusat ing éling-élingané bangsa Utsmaniyah. Pamukiman liya sing ucul ing tanggal sing padha: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Bèntèng Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, Pulo İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, Iznik, Izmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zağra), Tatarpazarcığı, İhtiman, Kyustendil, Petriç, Nevrokop (Gotse Delchev), Drama, Gallipoli, Cimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Plovdiv, Sofia, Niš, Vidin, Tarnovo, Varna, Shumen, Silistra, Nikopolis, Ruse, Thessaloniki, Serres, Kavala, Skopje, Manastir, Ohrid, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Pleven, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Constanța, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Mehmed Celebi mbangun manèh manunggalé nagara", "03413dfd"], "d": ["Mehmed I, sing ngalahaké Musa Celebi ing Çamurlu ing paprangan pungkasan antarané para sedulur, manunggalaké wilayah nagara ing sangisoré siji pamaréntahan; mula saka iku panjenengané dianggep 'pangadeg nagara sing kapindho'. Ing mangsa pamaréntahané, susunan nagara sing wis rusak didandani, sesambungan karo kadipaten-kadipaten Anatolia diimbangaké, lan ing Rumelia ditindakaké kawicaksanan tentrem sing ngati-ati. Pamukiman liya ing peta sing ing tanggal sing padha bali saka mangsa Interregnum menyang pamaréntahan Utsmaniyah: Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Pambrontakan Syekh Bedreddin", "e0a072ca"], "d": ["Obahé agama lan masarakat sing tuwuh ing sakiwa-tengené Syekh Bedreddin, ahli fikih lan sufi gedhé sing naté dadi hakim militèr (kazasker) ing Mangsa Interregnum, mbledhos bebarengan karo pambrontakan Börklüce Mustafa ing Karaburun lan Torlak Kemal ing Manisa. Pambrontakan-pambrontakan iku dipadhemaké kanthi getih; Bedreddin dicekel ing Deliorman lan diukum pati ing Serres. Kedadéan iki ninggalaké tilas jero ing sastra lan panulisan sejarah minangka pambrontakan masarakat lan mahdiisme gedhé sing paling wiwitan ing sejarah Utsmaniyah.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Kamenangan Varna", "f739eedc"], "d": ["Wadyabala Salib Hungaria-Polandia, sing mudhun ngidul kanthi nyulayani prajanjèn Szeged, ditumpes ing Varna déning Murad II, sing bali mimpin wadyabala sawisé lèngsèr saka tahta; raja enom Ladislaus III séda ing papan perang. Kamenangan iku ngilangaké kalodhangan gedhé pungkasan kanggo campur tangan manca sing ditujokaké kanggo nyingkiraké anané Utsmaniyah ing Balkan, lan njamin dalan menyang penaklukan Istanbul.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Perang Kosovo II", "ebe0b662"], "d": ["Wadyabala John Hunyadi, sing péngin males kekalahan Varna, dikalahaké kanthi mesthi déning Murad II ing paprangan sengit sing lumaku telung dina. Iki perang gedhé pungkasan ing papan jembar sing ditindakaké para Salib nglawan Utsmaniyah ing Balkan; kanthi kamenangan iki, kakuwasaan Utsmaniyah ing kidul Kali Donau wis mapan lan ora bisa dibalèkaké manèh.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Penaklukan Istanbul", "583d5e3e"], "d": ["Sawisé pengepungan sing lumaku sèket papat dina (6 April–29 Mei 1453), ing ésuké tanggal 29 Mei wadyabala Utsmaniyah ngliwati témbok-témbok lan mlebu kutha; kaisar pungkasan, Konstantinus XI, tiwas ing peperangan, lan Kekaisaran Romawi Wétan sing umuré 1100 taun dadi sejarah. Sultan sing isih enom iku nampa gelar 'Sang Penakluk' (Fatih), ndadèkaké kutha iku ibu kutha lan ngowahi Hagia Sophia dadi mesjid; ora suwe kutha iku diuripaké manèh liwat panggonan pendhudhuk lan pambangunan. Miturut TDV, Silivri lan Vize lagi ditaklukaké kanthi mesthi ing taun 1453; miturut artikel TDV bab Limnos, pulo iku mlebu pamaréntahan Utsmaniyah sanalika sawisé penaklukan lan dipasrahaké marang kulawarga Gattilusio kanthi syarat mbayar upeti. Ing atlas, Silivri, Vize lan Limnos kacathet pindhah saka Bizantium menyang Utsmaniyah wiwit dina iki (Limnos minangka tanah sing mbayar upeti). Pangecoran mriyem raseksa, kapal-kapal sing dilakokaké liwat dharatan, lan tatanan pengepungan ing ngarep témbok dianggep minangka pucuking teknik militèr ing jaman iku. Ing panulisan sejarah Éropah, penaklukan iki kaétung minangka salah siji tanggal lambang pungkasané Abad Pertengahan.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Penaklukan Trebizond", "15f52403"], "d": ["Ing pungkasané ekspedisi Segara Ireng sing abot, sing ditindakaké Sang Penakluk bebarengan nganggo wadyabala dharat lan armada, Kekaisaran Yunani Trebizond nyerah; kanthi disingkiraké sisa pungkasan donya Bizantium iki ing Anatolia, kabeh pesisir kidul Segara Ireng mlebu ing kakuwasaan Utsmaniyah. Dipungkasiné wangsa Komnenos nguwataké pengakuné Sang Penakluk minangka 'panguwasa rong segara lan rong dharatan'. Panggonan liya sing digabungake ing tanggal sing padha: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Penaklukan pungkasan Silifke — pecahé perlawanan pungkasan Karaman", "d988bee4"], "d": ["Bèntèng Silifke ing taun 1472 wis sapisan nyerah marang Gedik Ahmed Pasya, nanging ing taun sing padha Kasim Bey saka Karaman, kanthi pitulungan armada Salib ing Segara Tengah, ngrebut manèh bèntèng iku. Sawisé kamenangan Otlukbeli, Sang Penakluk menehi tugas marang putrané lan Gedik Ahmed Pasya supaya nguwasani tlatah iku kanthi mesthi; kanthi pitulungané para tukang mriyem sing biyèn melu Utsmaniyah, gudhang mesiu diobong lan bèntèng iku cepet dirubuhaké. Kanthi mangkono perlawanan pungkasan wong Karaman ing pagunungan Taşeli-İçel dipecah; panyingkiran kadipaten iku bakal rampung ing taun 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Perang Otlukbeli", "42c7194e"], "d": ["Panguwasa Aq Qoyunlu, Uzun Hasan, sing wis dadi kakuwatan gedhé ing Wétan lan sekutu karo Venesia, ngalami kekalahan abot ing Otlukbeli nglawan wadyabala Sang Penakluk sing nganggo gegaman geni. Kamenangan iku nemtokaké unggulé Utsmaniyah ing Anatolia; uga dadi bukti wiwitan unggulé wadyabala pusat sing nganggo mriyem lan bedhil nglawan wadyabala klasik. Miturut artikel TDV bab Gümüşhane, kutha iku wiwit taun 1467 ana ing kakuwasaan Aq Qoyunlu; kakuwasaan iku rampung amarga kekalahan Otlukbeli lan Gümüşhane pindhah kanthi mesthi menyang kakuwasaan Utsmaniyah.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krimea mlebu ing pangayoman Utsmaniyah", "44e3f7c8"], "d": ["Armada sing dipimpin Gedik Ahmed Pasya naklukaké kutha-kutha pesisir kidul Krimea, kawitan Kaffa sing ana ing tangané wong Genoa; pesisir iku didadèkaké sanjak Utsmaniyah langsung. Déné Kasultanan (Khanat) Krimea ing sangisoré Mengli Giray dadi nagara bawahan sing oleh hak istiméwa lan ngakoni kakuwasaan dhuwur Utsmaniyah, banjur sajrone telung abad dadi watu dhasar politik ing sisih lor; Segara Ireng saiki sejatiné wis dadi segara jero Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Bakhchysarai, Kerch, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Sédané Sang Penakluk — prakara Sultan Cem", "190ecf01"], "d": ["Sawisé Sang Penakluk séda dumadakan ing tengah dalan ekspedisi, Bayezid II munggah tahta; sedulure, Sultan Cem, sing ngaku duwé hak ing kasultanan, ndhawuhaké khutbah diwaca lan dhuwit dicithak nganggo jenengé ing Bursa. Sawisé kalah, panjenengané ngungsi dhisik menyang Mamluk, banjur menyang para ksatria Rodhos; Cem, sing ing tangané para ksatria lan kapausan dadi alat tawar-tinawar diplomasi Éropah, séda ing Napoli ing taun 1495. Prakara iki meksa politik njaba Utsmaniyah tumindak ngati-ati suwéné limalas taun.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Kamenangan Chaldiran", "fea64ebb"], "d": ["Yavuz Sultan Selim, sing péngin mbrastha nganti oyodé ancaman saka propaganda Safawiyah ing Anatolia, ngalahaké wadyabala Syah Ismail kanthi abot ing Dhataran Chaldiran amarga unggul ing mriyem lan bedhil. Tabriz dilebeti; Anatolia Wétan lan Kidul-Wétan sarta jalur Mosul-Diyarbakır digabungaké ing pamaréntahan Utsmaniyah. Kanthi usahané Idris Bitlisi, para bey Kurdi manut marang Utsmaniyah, sing mbentuk kerangka tapel wates wétan sing bakal lumaku pirang-pirang abad.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Kamenangan Marj Dabiq", "07d254d3"], "d": ["Wadyabala Mamluk dibubaraké sajrone sawetara jam ing Marj Dabiq ing sisih lor Aleppo; sultan sepuh Qansuh al-Ghawri séda nalika perang. Kanthi kamenangan sing mbukak amba-amba gapura Aleppo lan Damaskus, Suriah, Libanon lan Palestina pindhah menyang pamaréntahan Utsmaniyah; dalan kanggo ekspedisi Mesir sing bakal mungkasi Nagara Mamluk wis kabukak.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniyah — penaklukan Mesir lan khilafah", "caf378d6"], "d": ["Wadyabala Utsmaniyah sing kanthi cepet nyabrang ara-ara samun Sinai njebol garis pertahanan Tumanbay ing Ridaniyah banjur mlebu Kairo; Tumanbay, sing isih nglawan, dicekel lan diukum pati, lan Nagara Mamluk dadi sejarah. Mesir, Hijaz lan kutha-kutha suci mlebu pamaréntahan Utsmaniyah; khalifah Abbasiyah lan barang-barang suci digawa menyang Istanbul. Kanthi pindhahé khilafah menyang wangsa Utsmaniyah, para sultan ngemban pengaku dadi pimpinan donya Islam; kontrol Dalan Rempah-rempah uga menehi kekaisaran bathi gedhé. Panggonan liya sing digabungake ing tanggal sing padha: Akko, Maan, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Sultan Sulaiman Sang Pembuat Undhang-undhang munggah tahta", "f6512269"], "d": ["Pamaréntahan 46 taun Sulaiman I, sing munggah tahta minangka siji-sijiné putra lanang sawisé sédané Yavuz, dianggep minangka pucuk politik, militèr, kukum lan budaya kekaisaran. Kitab-kitab undhang-undhang (kanunname) sing nata kukum adat ndadèkaké panjenengané oleh gelar 'Kanuni' (Sang Pembuat Undhang-undhang); ing Kulon panjenengané disebut 'sing Agung' (Magnificent). Karya-karyané arsitèk Sinan, jaman emas sastra divan, lan unggulé armada ing Segara Tengah dadi lambang jaman iki.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Penaklukan Beograd", "59ef5cec"], "d": ["Beograd, sing ora bisa direbut Sang Penakluk ing taun 1456 lan dianggep 'kunci Éropah Tengah', tiba ing ekspedisi kapisan Sang Pembuat Undhang-undhang liwat pengepungan ing tempuran Kali Donau lan Sava. Garis pertahanan kidul Hungaria ambruk; penaklukan iki mbukak lawang kanggo gerakan ing Éropah Tengah sing tekan Mohács limang taun candhaké lan tekan panggabungan Buda rong puluh taun candhaké.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Penaklukan Rodhos", "807bbb1e"], "d": ["Rodhos, pangkalan para Ksatria Santo Yohanes sing ngancam dalan laut Segara Tengah Wétan lan dalan kaji, sawisé pengepungan getih sing lumaku pirang-pirang sasi nyerah kanthi prajanjèn penyerahan; para ksatria diidinaké ninggalaké pulo kanthi bébas (sabanjuré padha manggon ing Malta). Keamanan pesisir Anatolia kajamin lan jalur laut Istanbul-Mesir mlebu ing kontrol Utsmaniyah tanpa pedhot.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Perang Mohács", "f3418b0d"], "d": ["Wadyabala Hungaria dirusak ing Dhataran Mohács sajrone kira-kira rong jam amarga tembakan mriyem lan unggulé gerakan; Raja Louis II séda ing rawa nalika mlayu. Mohács, salah siji perang gedhé ing papan jembar sing paling cepet dimenangaké ing sejarah Utsmaniyah, sejatiné mungkasi krajan Hungaria sing mardika lan mbukak jaman persaingan Utsmaniyah-Habsburg ing Éropah Tengah.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Pengepungan Wina I", "dc49ea4f"], "d": ["Ing ekspedisi sing dianakaké nglawan campur tangané wangsa Habsburg ing tahta Hungaria, wadyabala Utsmaniyah ngepung Wina; amarga mriyem abot ditinggal ing dalan, mangsa adhem teka luwih awal lan angelé pasokan, pengepungan dicabut sawisé telung minggu. Senajan kutha iku ora bisa direbut, pengaruh Utsmaniyah ing Hungaria tetep dijaga; ngarep Wina dadi tandha wates jangkauan logistik kekaisaran ing Éropah Tengah.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Penaklukan Baghdad — Ekspedisi Rong Irak", "897092c3"], "d": ["Ing ekspedisi marang 'Rong Irak' (Irak Arab lan Irak Persia), sing dilebeti dhisik Tabriz, banjur Baghdad tanpa perang; direbuté ibu kutha lawas Abbasiyah ndadèkaké panguwasa Utsmaniyah oleh kawibawan gedhé ing donya Islam. Makam Imam A'zham Abu Hanifah dipulihaké; kanthi digabungaké Baghdad lan Basra, wilayah Utsmaniyah tekan Teluk Persia. Panggonan liya sing digabungake ing tanggal sing padha: Kirkuk, Karbala.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Kamenangan Laut Preveza", "30dc0f97"], "d": ["Armada Salib sing dibentuk dipimpin Paus, senajan luwih akèh cacahé, dibubaraké ing lepas pesisir Preveza déning taktik Barbarossa sing pinter nggunakaké angin lan pesisir; Andrea Doria ninggalaké papan perang. Kamenangan iku ngadegaké unggulé laut Utsmaniyah ing Segara Tengah tanpa tandhingan sing bakal lumaku kira-kira 33 taun; ing tradhisi pelayaran Turki, iki tanggal lambang Dina Angkatan Laut. Panggonan liya sing digabungake ing tanggal sing padha: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Panggabungan Buda — Hungaria dadi provinsi Utsmaniyah", "db53b244"], "d": ["Sang Pembuat Undhang-undhang, sing budhal ekspedisi amarga wangsa Habsburg ngepung Buda, sawisé nylametaké kutha iku njupuk Hungaria Tengah ing pamaréntahan Utsmaniyah langsung lan ngadegaké Beylerbeylik Buda; déné Transylvania didadèkaké kapangéranan otonom sing manut marang Utsmaniyah. Tatanan Hungaria sing dipérang telu iki lumaku kira-kira 150 taun lan mbentuk rerangkèn pamaréntahan Utsmaniyah sing tetep ing Éropah Tengah.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Prajanjèn Amasya", "a5afe0d1"], "d": ["Iki prajanjèn tentrem resmi kapisan sing mungkasi perang Utsmaniyah-Safawiyah sing wis lumaku pirang-pirang taun. Baghdad lan Irak tetep ing Utsmaniyah, tapel wates Anatolia Wétan diakoni bebarengan kanggo kaping pisan; Safawiyah saguh ngendheg propaganda Syiah ing wilayah Utsmaniyah, lan Utsmaniyah saguh njamin keamanan lelungané para kaji Iran. Prajanjèn iku dadi conto kapisan kerangka kukum sesambungan antarané rong nagara.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — sédané Sang Pembuat Undhang-undhang", "e2917ed2"], "d": ["Sang Pembuat Undhang-undhang, sing umuré 72 taun, séda ing kémahé sawetara jam sadurungé tibané Bèntèng Szigetvár, sing dikepung ing ekspedisiné kaping telulas; Sokollu Mehmed Pasya ndhelikaké sédané pirang-pirang minggu supaya wadyabala ora bubar. Bèntèng direbut, nanging nagara wis kelangan sultan sing paling suwé mréntah lan paling gemilang; putrané, Selim II, munggah tahta, lan bobot para wazir agung ing pamaréntahan nagara wiwit tambah.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Penaklukan Siprus", "e364a2b3"], "d": ["Ing taun 1570 wadyabala ndharat ing Siprus sing diprentah Venesia; Nikosia cepet tiba, déné Famagusta lagi nyerah sawisé pengepungan sewelas sasi ing Agustus 1571. Pulo iku, sing wigati banget kanggo keamanan dalan dagang lan kaji ing Segara Tengah Wétan, ditata dadi beylerbeylik lan pendhudhuk saka Anatolia dipanggonaké ing kono; penaklukan iku uga dadi alesan persekutuan Salib gedhé sing bakal pungkasané ing Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Kekalahan Lepanto", "6a1d44a9"], "d": ["Armada Salib sing manunggal sawisé penaklukan Siprus nyekel armada Utsmaniyah ing Teluk Lepanto lan ngrusak perangan gedhéné; laksamana agung (kaptan-ı deryâ) Müezzinzade Ali Pasya gugur syahid, mung eskadroné Uluç Ali sing slamet. Sawisé bilai iku, Wazir Agung Sokollu Mehmed Pasya ngangkat Uluç Ali Pasya dadi laksamana agung kanthi tugas nglumpukaké armada sing buyar, lan miwiti mbangun armada anyar ing kabeh galangan kapal saka Istanbul nganti Alanya; nanging unggul mutlak ing Segara Tengah wis goyah sacara psikologis.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Perang Mezőkeresztes", "da308ec5"], "d": ["Ing perang papan jembar paling gedhé ing Perang Dawa (1593–1606), wadyabala sing dipimpin dhéwé déning Mehmed III, nalika wis arep buyar, pulih manèh amarga piwulangé Hoca Sadeddin Efendi banjur mbubaraké wadyabala Habsburg. Perang iki dianggep perang klasik gedhé pungkasan sing dimenangaké Utsmaniyah; nanging amarga ora ngowahi lakuné perang sacara umum, iku uga dianggep tandha ausé sistem militèr.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Prajanjèn Zsitvatorok", "39c01142"], "d": ["Liwat prajanjèn sing mungkasi perang ngentèkaké tenaga telulas taun, panguwasa Habsburg kanggo kaping pisan dianggep padha drajat karo sultan kanthi sebutan 'Kaisar Romawi' lan upeti taunan dibusak. Kelangan wilayah mèh ora ana; nanging owahé basa diplomasi iki diwaca minangka lambang pungkasané pengaku Utsmaniyah bab unggul mutlak ngadhepi Éropah.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Prajanjèn Qasr-i Shirin", "c1acf3af"], "d": ["Prajanjèn sing ditandhatangani sawisé Murad IV ngrebut manèh Baghdad (1638) mungkasi perang Utsmaniyah-Safawiyah sing luwih saka satus taun. Baghdad lan Irak tetep mesthi ing Utsmaniyah, Revan dipasrahaké marang Safawiyah; garis sing digambar, kanthi owah-owahan cilik, dadi dhasar tapel wates Turki-Iran saiki lan dianggep salah siji tapel wates sing paling dawa umuré ing donya. Prajanjèn iku masrahaké Bedre, Cessan, Mendeli, Derteng lan Derne marang Utsmaniyah; Bèntèng Zencir ing tapel wates kudu dirubuhaké, désa-désa ing kulonané dadi duwèké Utsmaniyah, sing ing wétané dadi duwèké Iran. Sakiwa-tengené Bèntèng Zalim cedhak Shahrizor lan Kızılca Kale tetep ing Utsmaniyah, Avroman lan Mihriban ing Iran; bèntèng Kotur, Mâkû lan Mağazberd bakal dirubuhaké déning kaloro pihak.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Penaklukan Kréta rampung", "e0d85604"], "d": ["Pengepungan Kandia, babak pungkasan perang Kréta sing diwiwiti ing taun 1645, rampung amarga operasi mantep telung taun saka Fazil Ahmed Pasya; komandan Venesia, Morosini, masrahaké kutha iku liwat prajanjèn. Perjuangan sing lumaku kira-kira seprapat abad iku kacathet minangka pengepungan paling dawa ing sejarah Utsmaniyah; bèntèng Latin gedhé pungkasan ing Segara Tengah Wétan uga mlebu pamaréntahan Utsmaniyah. Telung bèntèng karang cilik ing pesisir lor pulo — Suda, Spinalonga lan Grambousa — isih tetep ing Venesia; amarga diadegaké ing pulo-pulo cilik sing kapisah, bèntèng-bèntèng iku ora bisa dituduhaké ing peta kapisah saka sisa Kréta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Prajanjèn Buchach — tapel wates paling amba", "b17b6e5a"], "d": ["Kanthi Prajanjèn Buchach, sing ditandhatangani sawisé penaklukan Kamianets ing ekspedisi Polandia, Podolia digabungaké menyang Utsmaniyah lan sapérangan Ukraina dijupuk ing sangisoré pangayoman. Kanthi mangkono kekaisaran tekan tapel watesé sing paling amba ing Éropah; titik iki dianggep pucuk lan uga mata rantai pungkasan jaman ékspansi.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Bubrahé Pengepungan Wina II", "7d889252"], "d": ["Pengepungan Wina déning Merzifonlu Kara Mustafa Pasya sing lumaku rong sasi dadi bubrah amarga gebugan dumadakan sing diturunaké raja Polandia Jan Sobieski saka gumuk Kahlenberg; wadyabala mundur kanthi ninggalaké bekalané, lan Merzifonlu diukum pati ing Beograd. Perang karo Liga Suci sing dibentuk sawisé kamenangan iku lumaku 16 taun; bubrah iki dituduhaké minangka wiwitané kemunduran gedhé ing sejarah Utsmaniyah.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Penaklukan Bèntèng Grambousa — salah siji bèntèng karang Kréta sing isih ing Venesia", "3ddf9eeb"], "d": ["Senajan penaklukan Kréta dianggep wis akèh-akèhé rampung kanthi nyerahé Kandia ing taun 1669, pulo-bèntèng karang Grambousa ing pucuk lor-kulon pulo isih ana ing tangané Venesia telulikur taun manèh. Kanthi direbuté ing taun 1692, salah siji saka telung sisa Venesia ing Kréta diresiki; déné Suda lan Spinalonga ngentèni ekspedisi Morea taun 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Prajanjèn Karlowitz — kelangan wilayah gedhé kapisan", "8f7e2546"], "d": ["Liwat Karlowitz, sing mungkasi perang Liga Suci nem belas taun, Hungaria lan Transylvania dipasrahaké marang Austria, Podolia marang Polandia, Morea lan pesisir Dalmasia marang Venesia. Kanggo kaping pisan ing sejarah Utsmaniyah, wilayah sak gedhé iki ucul ing meja rembugan lan kanggo salawasé; prajanjèn iku dianggep dokumèn wiwitan jaman anyar nalika kekaisaran pindhah dadi bertahan ngadhepi Éropah, lan uga dadi titik owah-owahan ing sejarah diplomasi Utsmaniyah. Pamukiman sing ing dina sing padha ganti tangan ing atlas: Kostajnica lan Jasenovac (saka Utsmaniyah menyang Habsburg; teks prajanjèn nglilakaké Castanoviz ing tangané kaisar, dina penyerahané Jasenovac ora ana ing sumber, ditulis dina prajanjèn) lan Preveza (saka Venesia menyang Utsmaniyah; TDV karlofca: miturut katetepan sing ditandhatangani 24 Rajab 1110 / 26 Januari 1699, panggonan sing didhudhuki Venesia ing sisih lor Teluk Lepanto dibalèkaké). Atlas uga nulis Kostajnica lan Jasenovac ing sisih Habsburg, Uman lan Vinnytsia ing Ukraina Pinggir Tengen saka Utsmaniyah menyang Polandia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: kakuwasaan Turki 1672-99) lan Nadin ing Dalmasia menyang Venesia (dina penyerahan sing khusus kanggo pamukiman iku ora ana ing sumber, ditulis dina prajanjèn; pucuk-pucuk periode Nadin durung diverifikasi karo sumber — perkiraan sing wis diumumaké). Vonitsa ing sisih lor Teluk Lepanto uga dibalèkaké saka Venesia menyang Utsmaniyah (TDV karlofca); ing Dalmasia Vrana (Urana) klebu panggonan sing tetep ing Venesia (pucuk periode durung diverifikasi — wis diumumaké).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Kamenangan Prut", "2583572f"], "d": ["Ing perang sing muncul amarga prakara raja Swédia sing ngungsi menyang Utsmaniyah sawisé kekalahan Poltava, wadyabala Tsar Peter I dikepung ing pinggir Kali Prut lan kepeksa nyerah. Liwat prajanjèn sing ditandhatangani, Azak direbut manèh; déné keputusan ora ngrusak wadyabala lan mbébasaké tsar kacathet ing sejarah minangka keputusan sing nganti saiki isih dadi rembugan.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Penaklukan bèntèng Suda lan Spinalonga — ilangé tilas pungkasan Venesia ing Kréta", "7261f7ba"], "d": ["Telulikur taun sawisé tibané Grambousa ing taun 1692, liwat cabang sisih saka ekspedisi Morea, Suda lan Spinalonga, loro benteng pungkasan Venesia ing Kréta, uga ditaklukaké. Kanthi mangkono penaklukan Kréta sing diwiwiti ing taun 1645 rampung nganti sak jengkal pungkasan pulo ing pungkasané patang puluh enem taun.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Pambrontakan Patrona Halil", "100941a4"], "d": ["Gagalé ing front Iran, pajeg lan nesuné marang kamewahan kalangan kraton dadi pambrontakan gedhé sing dipimpin Patrona Halil, tukang ngladèni ing pemandhian. Wazir Agung Ibrahim Pasya dipatèni, Ahmed III dilèngsèraké lan Jaman Tulip rampung; para pambrontak sing nguwasani kutha pirang-pirang sasi nuduhaké kanthi cetha ringkihé panguwasa pusat.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Prajanjèn Beograd — Beograd, Smederevo lan Serbia lor direbut manèh", "ba7f8e46"], "d": ["Ing pungkasané perang ing rong front (1736–1739) nglawan Austria lan Rusia, Beograd lan Serbia Lor direbut manèh; Rusia sarujuk nglucuti gegaman Azak lan ora nduwèni armada ing Segara Ireng. Prajanjèn iku, sing dianggep suksès gedhé pungkasan diplomasi lan wadyabala Utsmaniyah abad ka-18, menehi kekaisaran mangsa tentrem seprapat abad. Pamukiman liya sing ing dina sing padha bali saka Austria menyang Utsmaniyah ing atlas: Hisarcık (Grocka) (ranté pusat-induk Beograd; TDV belgrad), Craiova, Râmnicu Vâlcea lan Turnu Severin (baliné Wallachia Cilik menyang Utsmaniyah, minangka bawahan Wallachia). Déné Bosanski Brod lan Bosanska Dubica ing jalur Sava ing atlas bali menyang Utsmaniyah tanggal 28 September 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 September 1739). Târgu Jiu ing Wallachia Cilik uga bali menyang Utsmaniyah ing dina sing padha.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Serangan Çeşme", "840b30bd"], "d": ["Armada Rusia sing mlebu Segara Tengah kanthi dhukungan Inggris nyerang armada Utsmaniyah ing plabuhan Çeşme, papan pangungsené, nganggo kapal geni lan ngobong mèh kabeh. Rusia kanggo kaping pisan muncul minangka kakuwatan laut gedhé ing Segara Tengah; bilai iku dadi salah siji gebugan sing nemtokaké nasibé perang tumuju Küçük Kaynarca taun 1774, lan nuduhaké kanthi cetha perluné reformasi dhasar armada.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Prajanjèn Küçük Kaynarca", "2776dcdb"], "d": ["Liwat Küçük Kaynarca, sing mungkasi perang 1768–1774 lan dianggep salah siji prajanjèn paling abot ing sejarah Utsmaniyah, Kasultanan (Khanat) Krimea diwènèhi 'kamardikan' — sejatiné kagawé wewengkon pengaruh Rusia. Rusia manggon ing pesisir Segara Ireng, oleh hak liwat Selat kanggo kapal dagang lan kedutaan tetep ing Istanbul; klausul pangayoman sing ora cetha marang kawula Ortodoks mbukak lawang kanggo alesan campur tangan ing abad sabanjuré. Kanggo kaping pisan tanah sing rakyaté Muslim dicopot saka kakuwasaan Utsmaniyah.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Panggabungan Krimea menyang Rusia", "bdf6faa8"], "d": ["Krimea 'mardika' sing digawé Küçük Kaynarca, kanthi alesan kekisruhan ing mangsa khan pungkasan, Şahin Giray, digabungaké menyang Rusia liwat manifèsto Katerina II. Kerja bareng Utsmaniyah-Krimea sing wis telung abad rampung; kelangan stèp lor ngilangaké jeroné pertahanan Istanbul lan miwiti gelombang gedhé kapisan migrasi puluhan èwu wong Tatar Krimea menyang wilayah Utsmaniyah. Ing dina iki semenanjung Krimea (Alushta, Kefe/Kaffa, Sudak, Yalta, Balaklava, Inkerman, Mangup, Arabat) mlebu Rusia; Taman lan Kuban uga pindhah menyang Rusia ing panggabungan sing padha (TDV Kırım: 8 April 1783 Julian = 19 April Gregorian).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III lan Nizam-i Cedid", "d53aec21"], "d": ["Selim III, sing munggah tahta ing tengah perang, weruh yen kekalahan-kekalahan iku sipaté struktural, banjur miwiti program reformasi jembar kanthi jeneng 'Nizam-i Cedid' (Tatanan Anyar): wadyabala anyar sing dilatih cara Éropah, kas kapisah sing mbandhani (Irad-i Cedid), nguwataké sekolah teknik, lan kedutaan tetep kapisan ing ibu kutha-ibu kutha Éropah. Program iku dianggep wiwitan tradhisi reformasi Turki modhèrn; nanging amarga perlawanan korps-korps lan para ayan (tokoh provinsi), bakal digulingaké ing taun 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Dipungkasiné para Ksatria Malta — panggonan mampiré armada Prancis ing dalan", "d62f901d"], "d": ["Armada Prancis sing tumuju Mesir mampir ing Malta sing ana ing dalané; para Ksatria Santo Yohanes (Malta) masrahaké pulo iku tanpa akèh perlawanan. Kanthi mangkono rampung bèntèng pungkasan ordho ksatria sing diusir saka Rodhos ing taun 1522 lan banjur manggon ing kene. Rong taun sabanjuré Malta bakal tiba ing tangané Inggris, déné Napoleon saka pulo iku langsung tumuju Iskandariyah.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Pendhudhukan Mesir déning Napoleon", "93fede5f"], "d": ["Wadyabala Jenderal Bonaparte ndharat ing Iskandariyah lan ndhudhuki Mesir; ekspedisi iki, sing ngincer dalan Inggris menyang India, minangka serangan langsung kapisan saka kakuwatan Éropah marang tanah pusat Utsmaniyah. Serangan Nelson ing Abukir lan pertahanan Akko déning Cezzar Ahmed Pasya medhotaké lakuné Prancis; pendhudhukan rampung ing taun 1801, nanging ing kekosongan sing ditinggalaké diwiwiti munggahé Mehmed Ali Pasya saka Kavala lan jaman 'Prakara Wétan'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i Ittifak (Akta Persekutuan)", "cce49ef5"], "d": ["Dokumèn sing ditandhatangani antarané kraton lan kulawarga-kulawarga ayan sing kuwat ing dhaérah, dipimpin Alemdar Mustafa Pasya, ayan Rusçuk sing ndadèkaké Mahmud II munggah tahta; para ayan saguh setya marang sultan lan menehi pitulungan prajurit, déné nagara ngakoni anané lan hak-haké. Amarga iki conto kapisan ing sejarah Utsmaniyah nalika kakuwasaané sultan diwatesi nganggo dokumèn, sawetara sejarawan nganggepé wiwitan adoh saka tradhisi konstitusi; sejatiné ora ana daya manèh sajrone sawetara sasi.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Pambrontakan Yunani diwiwiti", "a7293715"], "d": ["Pambrontakan sing disiapaké organisasi Filiki Eteria mbledhos dhisik ing Wallachia, banjur kanthi kakuwatan utama ing Morea; nagara, sing sibuk karo prakara Ali Pasya saka Tepelena, kasèp ing tumindak kapisan. Amarga rasa simpati gedhé marang Yunani (filhelenisme) ing panemuné masarakat Éropah, pambrontakan iku cepet dadi prakara internasional; kanthi mangkono sumbu gerakan kamardikan kapisan sing kasil ing jaman nasionalisme ing tanah Utsmaniyah disumet. Pamukiman liya sing ucul ing tanggal sing padha: Athena, Patras (Balyabadra), Thebes, Livadeia, Eleusis (Attika), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Pambrontakan bersenjata kapisan ing Morea", "77e6250f"], "d": ["Sawisé nyabrang Prut, pambrontakan mlumpat menyang Morea: tumindak bersenjata sing diwiwiti ing Kalavryta (21 Maret Julian) disusul gerakan ing Patras, Kalamata lan Mani; ora suwe Morea dadi pambrontakan umum lan pamaréntahan Utsmaniyah kelangan sapérangan gedhé semenanjung. Pamukiman liya sing ucul ing tanggal sing padha: Athena, Patras (Balyabadra), Thebes, Livadeia, Eleusis (Attika), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vaka-i Hayriyye — Korps Yenisari dibubaraké", "08c9372a"], "d": ["Para yenisari, sing mbalikaké kuali minangka tandha mbrontak nglawan latihan Korps Eşkinci sing lagi diadegaké, ditumpes ing baraké ing Etmeydanı déning tembakan mriyem pasukan setya sing wis disiapaké Mahmud II; korps iku dibubaraké bebarengan karo kabeh cabangé lan pondhok tarékat Bektashi sing gegandhengan. Operasi iki, sing kacathet ing sejarah kanthi jeneng sing tegesé 'Kedadéan sing Becik', kanthi nyingkiraké lembaga sing umuré patang abad mbukak dalan kanggo wadyabala Asakir-i Mansure-i Muhammediyye lan kabeh reformasi pemusatan sabanjuré.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Serangan Navarino", "ee579e7f"], "d": ["Armada Utsmaniyah-Mesir, sing lagi madhemaké pambrontakan Yunani, diobong ing Navarino déning armada gabungan Inggris-Prancis-Rusia sing mlebu plabuhan tanpa ngumumaké perang; kira-kira sèket sewidak kapal lan èwuan pelaut ilang. Serangan iku, sing ing diplomasi Éropah diliwati kanthi sebutan 'kedadéan sing ora bejo', sejatiné njamin kamardikan Yunani lan mbukak dalan kanggo perang Utsmaniyah-Rusia 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Maklumat Tanzimat", "5042ce7b"], "d": ["Liwat Hatt-i Humayun sing diwaca ing Gülhane, keamanan nyawa, bandha lan kehormatan kabeh kawula tanpa mbédakaké agama dijamin nagara; prinsip keadilan pajeg, tatanan wajib militèr lan ora ngukum tanpa pengadilan diumumaké. Maklumat iku, karyané Mustafa Reşid Pasya, dianggep dokumèn gedhé kapisan modhernisasi Utsmaniyah sing sipaté konstitusional lan menehi jeneng marang 'Jaman Tanzimat' (1839–1876), jaman reformasi; penataan manèh sing jero ing pamaréntahan, kukum, pendhidhikan lan keuangan ditindakaké ing kerangka iki.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Perang Krimea diwiwiti", "3b9ca3c8"], "d": ["Krisis sing diwiwiti amarga prakara panggonan-panggonan suci lan pengaku Rusia bab pangayoman marang kawula Ortodoks dadi paprangan terang-terangan sawisé Utsmaniyah ngumumaké perang; sawisé serangan Sinop, Inggris lan Prancis (banjur Piedmont) mèlu perang ing pihak Utsmaniyah. Kanthi wadyabala Sekutu ndharat ing Krimea lan ngrebut Sevastopol, perang dimenangaké liwat Prajanjèn Paris 1856; nanging utang manca kapisan sing dijupuk ing taun-taun perang (1854) nglebokaké kekaisaran ing pusaran ketergantungan keuangan sing bakal lumaku setengah abad.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Maklumat Reformasi (Islahat Fermanı)", "78ff234d"], "d": ["Maklumat sing diumumaké sadurungé rembugan tentrem Paris ngambakaké prinsip-prinsip Tanzimat lan menehi kawula non-Muslim hak padha sing amba, kalebu dadi pegawé nagara, dadi prajurit lan mbukak sekolah; organisasi jamaah ditata manèh. Liwat Prajanjèn Paris sing ditandhatangani sabanjuré, Nagara Utsmaniyah resmi ditampa ing kulawarga kukum antarnagara Éropah lan wutuhé wilayah dijamin bebarengan déning nagara-nagara gedhé — jaminan iki, ing prakteké, bakal dadi lawang anyar kanggo campur tangan.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanun-i Esasi — Jaman Konstitusi I", "0fe052c1"], "d": ["Ing dina bukaané konferènsi internasional sing kumpul ing Istanbul kanggo ngrembug krisis Balkan, konstitusi Utsmaniyah kapisan diumumaké kanthi tembakan mriyem; liwat Kanun-i Esasi, karya gerakan 'Utsmaniyah Anyar' sing dipimpin Midhat Pasya, diadegaké parlemèn rong kamar. Meclis-i Meb'usan dibukak ing Maret 1877; nanging Abdülhamid II, kanthi alesan Perang '93, ing Februari 1878 nglèrènaké parlemèn tanpa wates, lan konstitusi digantung suwéné telung puluh taun.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Perang '93 (Perang Utsmaniyah-Rusia 1877–78)", "5bd96af7"], "d": ["Ing perang sing disebut 'Perang '93' amarga cocog karo taun Rumi 1293, wadyabala Rusia nyerang saka rong front; senajan pertahanan Plevna déning Gazi Osman Pasya lan paprangan Kaukasus Ahmed Muhtar Pasya dadi crita kepahlawanan, front iku ambruk lan wong Rusia maju nganti Yeşilköy (San Stefano). Perang iku miwiti gelombang gedhé migrasi Muslim saka Balkan lan Kaukasus tumuju Istanbul, sing akibaté isih krasa nganti saiki; struktur dhémografi lan keuangan kekaisaran ora bisa bali manèh kaya sadurungé.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Prajanjèn Berlin", "47f76a49"], "d": ["Kongres Berlin, sing ngrevisi 'Bulgaria Gedhé' sing digawé San Stefano atas jeneng imbangané nagara-nagara gedhé, tetep ninggalaké gambaran sing abot: Serbia, Montenegro lan Rumania dadi mardika; Kapangéranan Bulgaria otonom diadegaké; Bosnia-Hercegovina dipasrahaké marang pendhudhukan Austria, Siprus marang pamaréntahan Inggris, Kars-Ardahan-Batum marang Rusia. Tatanan Utsmaniyah sing umuré limang atus taun ing Rumelia akèh-akèhé bubrah; 'prakara Wétan' dadi agenda tetep diplomasi Éropah. Pamukiman liya sing ucul ing tanggal sing padha: Plovdiv, Vidin, Tarnovo, Varna, Shumen, Silistra, Ruse, Bukares, Iași, Constanța. Rumania, minangka gantiné nyerahaké Bessarabia marang Rusia, nampa Tulcea lan Dobruja: Tulcea, Babadag, Măcin, Isaccea, Hârșova lan Mangalia ing Dobruja Lor pindhah menyang Rumania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Pendhudhukan Tunisia lan Administrasi Utang Umum Utsmaniyah", "c7e25598"], "d": ["Prancis, kanthi alesan kedadéan ing tapel wates Aljazair, ndhudhuki Tunisia lan liwat Prajanjèn Bardo njupuk ing sangisoré pangayomané; anané Utsmaniyah ing Afrika Lor dadi mung Tripolitania. Liwat Dekret Muharram sing diwetokaké ing taun sing padha, kanggo ngurus utang manca sing bangkrut diadegaké Administrasi Utang Umum (Duyun-i Umumiyye), sing para kreditur diwakili ing njeroné: pamasukan pokok kaya uyah, mbako lan sutra langsung digandhèngaké karo administrasi manca iki lan kedaulatan keuangan diwatesi banget. Pamukiman liya sing ucul ing tanggal sing padha: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Pendhudhukan Inggris ing Mesir", "f1269768"], "d": ["Gerakan Urabi Pasya, sing muncul ing Mesir nglawan kebangkrutan keuangan lan kontrol manca, diremuk déning kamenangan Tel el-Kebir wadyabala Inggris sing ndharat sawisé Iskandariyah dibom, lan Kairo didhudhuki. Senajan sacara kukum Mesir tetep manut marang Utsmaniyah, sejatiné mlebu pamaréntahan Inggris; kontrol Terusan Suez manggon ing tengahé strategi kekaisaran Britania.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Pengumuman Jaman Konstitusi II", "95ee2fd2"], "d": ["Ngadhepi gerakan sing saya gedhé amarga para perwira anggota Komite Persatuan lan Kemajuan munggah gunung ing Makedonia, Abdülhamid II nglakokaké manèh Kanun-i Esasi; 'pengumuman kamardikan' ditampa kanthi gembira lan pemilu dianakaké. Nanging stabilitas ora teka: sawisé Kedadéan 31 Maret (April 1909) dipadhemaké, Abdülhamid dilèngsèraké; kamardikan Bulgaria, panggabungan Bosnia lan Kréta sing nyedhak menyang Yunani uga kedadéan ing sasi-sasi sing gonjang-ganjing iki.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Perang Tripolitania", "ed441994"], "d": ["Italia, sing lagi golek tanah jajahan, ngumumaké perang marang Tripolitania, tanah pungkasan Utsmaniyah ing Afrika Lor, lan ndhudhuki pesisiré; amarga nagara sing ora duwé armada ora bisa ngirim wadyabala reguler, para perwira enom kaya Mustafa Kemal lan Enver Bey kanthi dhelik-dhelik nyabrang menyang tlatah iku lan nata perlawanan sing èfèktif bebarengan karo suku-suku Senussi. Liwat Prajanjèn Ouchy sing ditandhatangani amarga mbledhosé Perang Balkan (18 Oktober 1912), Libia dipasrahaké marang Italia; Italia uga ndhudhuki Rodhos lan Dodekanesa.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Prajanjèn London — kelangan Rumelia", "f3f976df"], "d": ["Liwat Prajanjèn London sing mungkasi Perang Balkan I, kabeh tanah ing kulon garis Midye-Enez lan pulo-pulo Aegea ilang; Albania dadi mardika. Saka Rumelia, sing luwih saka limang atus taun dadi pusat bobot dhémografi, ékonomi lan budaya kekaisaran, mung Trakia Wétan sing bakal kari (Edirne direbut manèh ing Perang Balkan II); kelangan iku ndadèkaké kawicaksanan perang lan pamapanan pamaréntahan Ittihad dadi luwih keras sacara jero. Panggonan-panggonan ing kulon garis Midye-Enez sing ucul: Skopje, Veles, Štip, Strumica, Doiran, Gevgelija, Manastir, Ohrid, Debar (Dibra), Prizren, Pristina, Peć, Novi Pazar, Kosovo Polje; Serres, Drama, Kavala, Petrich, Nevrokop, Xanthi, Komotini, Dedeağaç, Didymoteicho, Çirmen, Feres, Soufli, Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); ing Kréta Chania, Kandia, Rethymno, Sitia lan Sfakia.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Mlebu Perang Donya I", "05a0252e"], "d": ["Kapal perang Goeben lan Breslau, sing mlayu saka Inggris, dilebokaké liwat Selat kanthi digawé kaya wis dituku, narik nagara sethithik mbaka sethithik menyang pihak Jerman; perang sejatiné diwiwiti nalika armada sing dipimpin Laksamana Souchon ngebom plabuhan-plabuhan Rusia (29 Oktober), lan pengumuman perang saka kaloro pihak teka ing awal November. Senajan Jihad Agung (Cihad-i Ekber) diumumaké, pengaruh sing diarep-arep ora muncul; sajrone patang taun kekaisaran mlebu perang kanggo urip ing limang front sing béda, saka Kaukasus nganti Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Kamenangan Çanakkale", "95d888e8"], "d": ["Armada Sekutu, sing arep ngrubuhaké Istanbul lan tekan Rusia, ing 18 Maret dipukul mundur saka Selat déning tembakan garis ranjau lan bèntèng; garis ranjau sing dipasang kapal ranjau Nusret nemtokaké nasibé perang. Operasi dharatan Gallipoli sing diwiwiti ing April uga diendheg ing Anafartalar lan Conkbayırı; Sekutu ngosongaké semenanjung iku kabeh ing Januari 1916. Jenengé Letnan Kolonel Mustafa Kemal misuwur ing front iki; kamenangan sing dimenangaké kanthi kira-kira seprapat yuta syuhada lan korban dianggep minangka papan laire kader lan semangaté Perjuangan Nasional.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Pambrontakan Syarif Husain", "75f7c58c"], "d": ["Amir Mekah Syarif Husain, sawisé surat-suratan rahasia karo Inggris, mbrontak kanthi janji krajan Arab sing mardika; sepur Hijaz dadi sasaran serangan. Senajan pertahanan Madinah sing misuwur déning Fahreddin Pasya, sing lumaku nganti sawisé gencatan senjata, tetep dadi lambang perlawanan, pambrontakan iku, bebarengan karo majuné Inggris ing front Palestina, nyepetaké bubrahé kakuwasaan Utsmaniyah ing provinsi-provinsi Arab. Pamukiman liya sing ucul ing tanggal sing padha: Hurma, Turaba.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Gencatan Senjata Mudros", "9e87c767"], "d": ["Nagara Utsmaniyah, sing front-fronté pedhot siji lan sijiné amarga ambruké Bulgaria, mundur saka perang liwat gencatan senjata sing ditandhatangani ing kapal perang Agamemnon. Dibukaké Selat lan utamané Pasal 7, sing ngidinaké ndhudhuki panggonan sing keamanané kaancam, ora suwe didadèkaké sarung kukum kanggo pambagèan sing nyata: Mosul, Iskandarun, banjur Izmir lan Istanbul didhudhuki. Gencatan senjata iku dianggep dokumèn pungkasané kekaisaran sacara nyata. Pamukiman liya sing ucul ing tanggal sing padha: Hama, Damaskus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal ing Samsun — Perjuangan Nasional", "09a8f784"], "d": ["Ing swasana nesu amarga pendhudhukan Izmir, Mustafa Kemal Pasya, sing ndharat ing Samsun minangka inspektur Wadyabala IX, ngowahi tugas resminé dadi nata perlawanan ing Anatolia. Surat Edaran Amasya sarta kongres Erzurum lan Sivas minangka terusané tumindak iku; prinsip 'kamardikané bangsa bakal dislametaké déning tekad lan keputusané bangsa dhéwé' dadi inti program politik Perjuangan Nasional.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Bukaané Majelis Agung Nasional (TBMM) lan Sèvres", "2008feec"], "d": ["Amarga Istanbul didhudhuki sacara resmi lan Meclis-i Meb'usan dibubaraké, ing 23 April 1920 Majelis Agung Nasional dibukak ing Ankara; majelis sing nglumpukaké wewenang luar biasa ing awaké dhéwé dadi inti nagara anyar sing adhedhasar karsané bangsa. Prajanjèn Sèvres sing ditandhatangani pamaréntah Istanbul ing Agustus mbagi-bagi Anatolia; TBMM ngumumaké sing nandhatangani prajanjèn iku pengkhianat tanah air, lan Sèvres ora tau bisa ditindakaké.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Perang Sakarya", "f2f970a6"], "d": ["Serangan Yunani, sing wis nyedhak nganti 50 kilomèter saka Ankara, dipecah ing perang 22 dina 22 bengi sing ditindakaké miturut dhawuhé Mustafa Kemal Pasya, sing wis nampa wewenang panglima tertinggi: 'Ora ana garis pertahanan, sing ana bidang pertahanan.' Wadyabala Yunani kanggo kaping pisan pindhah menyang pertahanan stratégis; kamenangan iku nggawa gelar Gazi lan pangkat marsekal (müşir) kanggo Mustafa Kemal, lan mbukak lawang kanggo Persetujuan Ankara karo Prancis sarta pangakuan saka njaba.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Serangan Gedhé lan kamardikané Izmir", "172a50c4"], "d": ["Serangan sing diwiwiti saka Kocatepe ing ésuk 26 Agustus tekan ditumpesé pasukan utama Yunani ing 30 Agustus ing Dumlupınar liwat Perang Panglima Tertinggi; ing pangoyakan sing diterusaké kanthi dhawuh 'Para wadyabala, tujuan kapisan kowé yaiku Segara Tengah, maju!', Izmir dimardikakaké ing 9 September. Liwat Gencatan Senjata Mudanya (11 Oktober) Trakia Wétan direbut manèh tanpa perang; kamenangan militèr iku nemtokaké kakuwatan nagara anyar sing bakal diadegaké ing Lausanne ing meja rembugan.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Dibusaké kasultanan", "9f36a9f6"], "d": ["Amarga pamaréntah Istanbul uga diundang menyang rembugan Lausanne, TBMM ing 1 November 1922 misahaké kasultanan saka khilafah lan mbusak kasultanan; pamaréntahan wangsa Utsmaniyah sing umuré 623 taun rampung sacara kukum. Mehmed VI Vahideddin ninggalaké nagara ing 17 November numpak kapal perang Inggris; Abdülmecid Efendi diangkat ing kalungguhan khalifah miturut keputusan TBMM, lan kalungguhan iku uga bakal dibusak ing 3 Maret 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Prajanjèn Lausanne", "38c27f7d"], "d": ["Liwat Prajanjèn Tentrem Lausanne, sing ditandhatangani ing pungkasané rembugan abot wolung sasi, tapel wates, kamardikan kebak lan kedaulatan nagara Turki anyar diakoni sacara internasional; kapitulasi dibusak, Administrasi Utang Umum dilebokaké ing prosès likuidasi, lan ijol-ijolan pendhudhuk diatur. Lausanne, sing sejatiné mbatalaké Sèvres, dianggep kamenangan diplomasi Perjuangan Nasional lan dokumèn njaba sing ngadegaké Republik.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Pengumuman Republik", "d5bfcdfb"], "d": ["Republik diumumaké nalika TBMM, liwat owah-owahan konstitusi, nampa katetepan yen 'wujud pamaréntahan Nagara Turki iku republik'; Mustafa Kemal Pasya kapilih dadi presidhèn kapisan. Kanthi mangkono lelampahan Utsmaniyah 624 taun, sing diwiwiti ing 1299 minangka kadipaten tapel wates, ditutup, lan nagara anyar sing kedaulatané tanpa syarat kagungané bangsa diadegaké ing ndhuwur warisan kekaisaran.", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Jaghbub, pusat ara-ara samun Sanusiyah, digandhèngaké karo tatanan Utsmaniyah — firman bébas pajeg Abdülmecid", "039fce6d"], "d": ["Muhammad bin Ali as-Sanusi, sing pirang-pirang taun ana ing Mekah, sawisé bali menyang Tripoli manggon ing oasis Jaghbub ing wates Mesir lan ndhawuhaké mbangun zawiyah gedhé ing watu dhuwur sing nguwasani tlatah; panggonan sing mung sawetara gubug iku cepet dadi kutha. Ing 1856, kanthi firman Sultan Abdülmecid, bandha duwèké anggota tarékat dibébasaké saka pajeg lan para murid diwènèhi wewenang nglumpukaké zakat. Firman iki ndadèkaké oasis ing dalan kafilah sing nyambungaké Afrika Kulon lan Sudan menyang Kairo dadi pérangan saka tatanan keuangan lan administrasi Utsmaniyah lan nguwataké Jaghbub minangka pusat dagang. Kasetyan warga tlatah marang khalifah uga dikuwataké déning crita lelungané kolonel Sadiq al-Mu'ayyad sing nekani panggonan iku ing 1884 lan 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Wiwitan pangedhukan Terusan Suez lan adegé Port Said", "cef0be8d"], "d": ["Pagawéan pangedhukan proyèk Lesseps, sing disarujuki Bab-i Ali tanggal 5 Januari 1856, diwiwiti tanggal 25 April 1859; terusan iku bakal rampung sepuluh taun sabanjuré, tanggal 16 November 1869. Ing pucuk Segara Tengah pangedhukan, ing gisik antarané tlaga Manzala lan segara, désa gubug limang omah sing didegaké kanggo buruh dadi wiji Port Said. Ing 1860 jeneng iku, tegesé 'plabuhan Said', diwènèhaké marang kutha déning pejabat maskapé terusan kanggo ngurmati gubernur Mesir jaman iku, Said Pasya. Kanthi mangkono ing peta Utsmaniyah lair plabuhan anyar ing gisik sing sadurungé ora ana panggonan apa waé.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Lawatan Sultan Abdülaziz menyang Mesir lan adegé Ismailia ing Tanah Genting Suez", "bcfacf38"], "d": ["Kanthi dorongan Wazir Agung Yusuf Kamil Pasya, Sultan Abdülaziz tindak menyang Mesir tanggal 3 April 1863 lan disambut surak gedhé; tujuané yaiku nguwataké kasetyan marang pusat saka provinsi sing wiwit pambrontakan Kavalalı Mehmed Ali Pasya kanyatané wiwit dadi nagara kapisah. Ing taun sing padha, ing tanah genting, ing punthuk Tell el-Gisr ing pinggir tlaga Timsah, diadegaké pusat administrasi maskapé terusan: dhisik désa Qaryat al-Timsah kanggo insinyur, banjur désa Qaryat al-Arab kanggo buruh. Nalika Khedive Ismail Pasya nggatèkaké terusan banyu tawa lan ndhawuhaké mbangun pesanggrahan kanggo awaké ing punthuk iku, panggonan iku dijenengi Ismailia miturut jenengé. Adegé kutha dititimangsani taun 1863; dina persisé ora dingertèni.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Midhat Pasya dadi gubernur Bagdad lan manggonaké suku — adegé Ramadi lan Nasiriyah", "0fa98f06"], "d": ["Midhat Pasya, sing dicopot saka pimpinan Dhéwan Nagara lan didohaké saka Istanbul, mréntah vilayet Bagdad, sing uga nyakup Mosul lan Basra, kanthi wewenang amba antarané 1869-1872, kalebu jabatan komandhan Wadyabala Kaenem. Ing kono dhèwèké ngetrapaké Undhang-undhang Tanah lan undhang-undhang vilayet anyar, mbagi tanah kanthi sertipikat, lan ngiket suku-suku sing ngumbara ing urip netep lan wewenang nagara. Minangka asil pulitik pamukiman iki, ing 1869 Ramadi diadegaké ing pinggir Kali Efrat kanggo suku Dulaym, lan ing sisih kidul Nasiriyah diadegaké déning mutasarrif Muntafiq, Nasir Pasya as-Sa'dun; loroné lair ing panggonan sing nganti wektu iku ora ana pamukiman lan mlebu peta kanggo sepisanan ing tanggal iki.", "7babb36f"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdinand ngrebut Buda — Szapolyai diusir saka kutha krajan", "99f77c29"], "d": ["Sawisé Mohács, ana raja loro ing dhampar Hungaria: sapérangan bangsawan milih János Szapolyai, sapérangan liyané milih Ferdinand saka Habsburg. Ing taun 1527 Ferdinand ngrebut Buda lan ngusir Szapolyai saka kutha krajan; Szapolyai njaluk pitulung marang Sultan Suleyman. Iki sebabé sasaran kapisan ekspedisi Wina 1529 yaiku Buda.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Ekspedisi Barbaros menyang pulo-pulo Aegea — Kadipatèn Naxos mlebu kendhali Utsmaniyah", "722b2fea"], "d": ["Kadipatèn Naxos, sing wiwit 1207 diprentah para adipati Latin ing sangisoré perwalian Venesia, mlebu ing sangisoré kendhali Utsmaniyah liwat ekspedisi pulo-pulo Barbaros Hayreddin Pasya. Status pulo iku ora diowahi; kadipatèn terus lumaku minangka bawahané Utsmaniyah, lan liwat prajanjian Utsmaniyah-Venesia taun 1540 hak kadhaulatan resmi dipasrahaké marang Utsmaniyah.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Armada Salib ngenggoni Djerba — pangkalané Turgut Pasya ucul saka tangan", "f41b3f2a"], "d": ["Armada Salib sing kasusun saka kapal-kapal Spanyol, Kapausan, Malta, Genoa lan Florence ngincer Djerba, sing wiwit 1551 digunakaké Turgut Reis minangka pangkalan panggrebegan. Amarga prahara lan pageblug, armada iku lagi bisa tekan ngarep pulo ing wiwitan taun 1560; tanggal 12 Maret 1560 pulo iku dienggoni lan dibangun sawijining bèntèng. Piyale Pasya sing nampa kabar iku mangkat saka Istanbul tanggal 28 Maret karo armada 120 kapal galèi. Pendhudhukan iku ora suwé: armada Utsmaniyah ngalahaké para sekutu ing ngarep Djerba ing sasi Mèi, lan bèntèng direbut manèh ing pungkasan Juli. Ekspedisi iki dadi wiwitan operasi segara gedhé kapindho, sawisé Preveza, sing nguwataké kaunggulan Utsmaniyah ing Segara Tengah.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Tibané bèntèng Djerba — pulo pindhah menyang pamaréntahan Utsmaniyah", "f1efc0df"], "d": ["Sawisé kamenangan segara Piyale Pasya tanggal 14 Mèi 1560, pasukan Salib ngunci awak ing bèntèng sing dibangun ing pulo iku; pasukan beylerbeyi Tripolitania, Turgut Pasya, ngepung saka dharatan. Pengepungan sing suwéné rong sasi rampung tanggal 30 Juli 1560 kanthi tibané bèntèng, lan pulo iku digandhèngaké menyang beylerbeyilik Tripolitania. Antarané kamenangan segara lan direbuté bèntèng ana pitung puluh pitu dina; pulo iku sanyatané pindhah tangan ora tanggal 14 Mèi nanging 30 Juli.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Kakuwasan loro Rusia-Prusia ing Danzig rampung — kutha bébas Napoleon bali menyang Prusia", "1ccda4d2"], "d": ["Danzig, sing liwat tentrem Tilsit (9 Juli 1807) dipisahaké saka Prusia lan didadèkaké kutha bébas ing sangisoré pangayoman Prancis, ditinggal pasukan Napoleon sawisé pengepungan 1813. Antarané 2 Januari – 4 Februari 1814 ing kutha iku lumaku kakuwasan loro Rusia-Prusia; nalika Tsar Aleksandr mbatalaké rencanané ngrebut Danzig lan muara Vistula, kutha iku pindhah menyang pamaréntahan Prusia.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Ing Wina Krakow diwartakaké minangka kutha bébas, mardika lan nétral", "19eea839"], "d": ["Ing Kongres Wina, Rusia, Austria lan Prusia ndadèkaké kutha Krakow sawewengkoné minangka nagara bébas ing sangisoré pangayoman nagara telu; Akta Pungkasan Wina ngesahaké tatanan iki.", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Bornu mlebu ing sangisoré kakuwasan Rabih b. Zubayr", "8be4ca96"], "d": ["Panglima perang saka Sudan, Rabih b. Zubayr, sing wis nggoncang Bagirmi lan Wadai, ngrebut Bornu; nganti 1896 dhèwèké nguwasani sakabèhé nagara iku lan ndadèkaké Dikwa minangka puseré.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Rabih b. Zubayr dikalahaké lan dipatèni wong Prancis — kakuwasané ing Bornu bubar", "fb5a3ace"], "d": ["Rabih, sing kalah déning wadyabala kolonial Prancis, dipatèni; sanajan anaké péngin nerusaké kakuwasan, dhèwèké ora bisa tahan, lan Bornu ing taun 1902 dipérang antarané Prancis, Inggris lan Jerman.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Pamaréntahan Sauntara Thrace Kulon sing puseré ing Gümülcine diwartakaké", "974b2e28"], "d": ["Nalika Prajanjèn Bukares (10 Agustus 1913) masrahaké Thrace Kulon marang Bulgaria, wong Turki ing wilayah iku martakaké pamaréntahan sauntara sing puseré ing Gümülcine; sawisé Dedeağaç direbut, pamaréntahan iku ngumumaké kamardikané kanthi jeneng 'Pamaréntahan Mardika Thrace Kulon'. Amarga campur tangané nagara-nagara gedhé, pamaréntah Utsmaniyah ora nyengkuyung; Prajanjèn Istanbul 29 September 1913 masrahaké Thrace Kulon marang wong Bulgaria, lan pamaréntahan iku mung urip sèket pitu dina, nganti 25 Oktober 1913.", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Sédané Orhan Ghazi — pungkasané patang puluh taun owah-owahan saka kadipaten dadi nagara", "62c59cfd"], "d": ["Orhan Ghazi, sing mimpin kadipaten sawisé Osman Ghazi séda ing 1324, sajroné telung puluh wolu taun mréntah ngowahi Utsmaniyah saka kadipaten tapel wates dadi nagara sing lungguh ing loro pinggiré Marmara: Bursa (1326), Iznik (1331) lan Izmit (1337) direbut, Kadipaten Karesi digabungaké, akçe kapisan dicithak (1327), madrasah kapisan diadegaké ing Iznik (1331), lan panyabrangan menyang Rumelia dadi langgeng liwat Cimpe (1352) lan Gallipoli (1354). Ing 1357 dhèwèké kélangan putra pambarepé, Suleyman Pasya, sing mimpin panaklukan Rumelia, amarga kacilakan nalika mbebedhag; dhèwèké dhéwé séda ing Bursa ing Maret 1362 lan diganti déning putrané, Murad I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Pulo-pulo Bahrain pindhah menyang tangané wangsa Jabriyah", "6a242b16"], "d": ["Artikel Bahrain ing TDV nyathet yèn pulo iku \"turut-turut tetep ing sangisoré pamaréntahan Uyuniyah, Salghuriyah, Tabiyah, Jabriyah, lan ing jaman Jabriyah mayoritas pindhah saka Syiah dadi Sunni\"; ora siji-sijia diwènèhi tanggal. Ing literatur umum, wangsa Jabriyah diadegaké ing wiwitan abad kaping 15 kanthi nggulingaké panguwasa Jarwaniyah pungkasan ing Qatif, lan ing jaman paling gemilangé (Ajwad b. Zamil, séda 1496) ngawasi kabèh pasisir Arab ing teluk Basra, al-Ahsa, Qatif lan pulo-pulo Bahrain. Sawisé Ajwad, pulo-pulo Awal pindhah menyang Muqrin b. Zamil — yaiku panguwasa sing bakal kalah déning Portugal ing 1521.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Arzila direbut Portugal — tumpuan kapindho ing pasisir Maroko", "83444a11"], "d": ["Afonso V dhéwé ndharat ing pasisir Maroko karo kakuwatan 30.000 wong lan armada 400 kapal, banjur tanggal 24 Agustus 1471 ngrebut Arzila sing ana ing sangisoré pamaréntahan Wattasiyah. Tibané kutha iku matahaké perlawanan Tanger; Tanger pasrah tanpa perang patang dina sabanjuré, tanggal 28 Agustus. Kanthi mangkono, sawisé Ceuta (1415) lan Ksar es-Seghir (1458), Portugal madegaké pos katelu lan kapapat ing pasisir Atlantik Maroko; sawisé ekspedisi iki raja nambahaké tetembungan \"panguwasa Afrika\" ing gelaré.", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Safi mlebu ing pangaribawa Portugal", "765e703e"], "d": ["Safi, plabuhan gandum lan iwak sing paling ramé ing pasisir Atlantik, mlebu ing pangaribawa Portugal ing taun 1488; sauntara wektu kutha iku diprentah lumantar para panguwasa lokal ing sangisoré pangayoman Portugal, lan ing 1508 dienggoni langsung. Amarga sumber-sumber menehi bobot béda marang rong tahap iki, tanggal wiwitané béda antarané 1488 lan 1508; loro-loroné iku pucuk saka proses sing padha. Safi ana ing tangan Portugal sèket telu taun lan dikosongaké ing 1541 sawisé tibané Agadir.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Madegé Santa Cruz do Cabo de Gué — bèntèng Portugal ing Agadir", "cc22c433"], "d": ["Bèntèng Santa Cruz do Cabo de Gué, sing diadegaké liwat usaha swasta ing pasisir Sous, ing panggonan sing nganti wektu iku durung diambah Portugal, dibangun ing 1505 lan ing 1513 dipasrahaké marang makutha Portugal. Bèntèng iku ngawasi dagang gula lan emas ing lembah Sous sarta nutup dalan metu Marrakesh sisih kidul-kulon; mulané dadi sasaran gedhé kapisan gerakan Saadi. Pengepungan 1533 bisa dipukul mundur, déné pengepungan 1541 kasil lan miwiti ambruké Portugal ing Maroko.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Direbuté Azemmour — pengawasan muara Oum Er-Rbia", "232acd4b"], "d": ["Wadyabala Portugal ing sangisoré komando Jaime, Adipati Braganza, tanggal 3 September 1513 mlebu Azemmour ing muara kali Oum Er-Rbia tanpa nemoni perlawanan. Direbuté kutha iku menehi kendhali tumrap muara kali lan uga dalan gandum menyang tlatah pedalaman, sarta ing taun sabanjuré mbukak dalan kanggo madegé bèntèng Mazagan, 12 km ing sisih kidul-kuloné. Azemmour ana ing tangan Portugal wolulikur taun.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Madegé bèntèng Mazagan — pos Portugal sing bakal paling suwé ana ing Maroko", "786cdb40"], "d": ["Setaun sawisé Azemmour direbut, ing mangsa panas 1514 bèntèng Mazagan dibangun ing pasisir. Sawisé ambruk umum 1541, nalika Portugal ninggal kabèh posé ing Maroko, Mazagan ora ditinggal; malah bèntèngé dibangun manèh saka wiwitan nganggo bastion gaya Italia lan kutha iku dicekel suwéné rong atus sèket lima taun. Pengepungan gedhé 1562 uga bisa dipukul mundur. Mazagan, minangka pos pungkasan Portugal ing Maroko, bakal dikosongaké ing 1769.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Pasrahé bèntèng Mardin — pungkasané perlawanan Safawiyah ing sakidulé Diyarbekir", "e6226de5"], "d": ["Nalika Bıyıklı Mehmed Pasya, sing mlaku menyang wilayah Diyarbekir sawisé Chaldiran, ngepung Mardin, pasukan Safawiyah ing Oktober 1515 mundur mlebu bèntèng; sanajan kuthané wis ing tangan Utsmaniyah, bèntèngé tetep nglawan. Serangan walesan gubernur Safawiyah, Qara Khan, kanthi bala bantuan dipungkasi ing Perang Koçhisar (Kızıltepe) ing Mèi 1516 — ing peperangan sedina muput ing ara-ara Dede Garkın, sirahé Qara Khan ditugel lan wadyabalané bubar. Déné bèntèngé, miturut tembungé TDV, pasrah \"lagi sangang sasi sabanjuré\".", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Portugal ngrebut Bahrain — pungkasané kakuwasan Jabriyah", "315a435a"], "d": ["Nalika panguwasa Jabriyah Muqrin b. Zamil ora gelem mbayar upeti marang Hormuz, armada Portugal lan pasukan Karajan Hormuz sing dadi bawahané Portugal ndharat ing pulo iku; Muqrin kalah ing perang lan Bahrain ing 1521 mlebu ing sangisoré pamaréntahan Portugal. Wiwit iku, suwéné wolung puluh taun, pulo iku diprentah lumantar Hormuz, umumé déning gubernur-gubernur Iran sing Sunni. Mutiara lan papan stratégis Bahrain bakal ndadèkaké pulo iku sasaran langsung rebutan Utsmaniyah-Portugal ing teluk.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Tibané Agadir — wangsa Saadi wiwit njebol Portugal saka Maroko", "bb1568f6"], "d": ["Sultan Saadi Muhammad al-Syekh ngepung bèntèng Santa Cruz tanggal 16 Februari 1541 lan ngrebuté tanggal 12 Maret; watara enem atus wong Portugal, kalebu gubernur Guterre de Monroy, dadi tawanan.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Dikosongaké Safi lan Azemmour — Portugal mundur saka pasisir Atlantik", "4cb6099a"], "d": ["Sawisé Agadir tiba tanggal 12 Maret 1541 lan sekutu sing diarep-arep karo sultan Maroko ora bisa diwujudaké, João III mréntahaké ngosongaké rong pos gedhé ing pasisir Atlantik; pangungsian Safi lan Azemmour rampung ing mangsa rontok 1541, ing sasi September-Oktober. Kanthi mangkono sajroné setaun telung pos ucul saka tangan lan ékspansi Portugal sing wis lumaku sèket taun ing pasisir Maroko walik; sing kari yaiku Ceuta, Tanger, Arzila, Ksar es-Seghir lan Mazagan sing nembé dikuwataké.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Dikosongaké Arzila — Portugal nyempitaké pasisiré sisih lor", "b5d18373"], "d": ["Amarga krisis kauangan lan tekanan Saadi dadi siji, João III ngosongaké Arzila sing dicekel wiwit 1471. Kanthi mangkono anané Portugal ing Maroko mung kari Ceuta, Tanger lan Mazagan. Arzila bakal dienggoni manèh sedhéla ing 1577 lan ditinggal babar pisan ing 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Ekspedisi Utsmaniyah menyang Bahrain — gebrakan gedhé pungkasan nglawan Portugal ing teluk", "14501df3"], "d": ["Nagara Utsmaniyah, sing wis manggon ing pasisir Arab teluk kanthi nggabungaké Basra ing 1546 lan madegaké eyalet al-Ahsa, nglurug Bahrain ing sangisoré komando beylerbeyi al-Ahsa Mustafa Pasya, kanthi ngincer dagang mutiara pulo iku lan jalur Hormuz duwèké Portugal. Asil ekspedisi iku béda-béda ing sumber: Ènsiklopedhia Islam TDV nulis yèn wong Utsmaniyah \"ing taun 1559 ngrebut Bahrain lan madegaké pangkalan ing kono\", lan pulo-pulo iku \"sabanjuré mlebu manèh ing pamaréntahan Portugal\"; déné literatur Kulon nyathet yèn pengepungan iku gagal, bala bantuan Portugal sing teka liwat segara saka Hormuz mukul mundur pasukan Utsmaniyah, lan sawisé pageblug pes sing nyuda loro pihak, wong Utsmaniyah njaluk sarat-sarat pasrah. Loro crita iku béda ing asilé dhéwé; sing padha yaiku Bahrain ora langgeng ana ing tangan Utsmaniyah.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Uluç Ali Pasya ngrebut Tunis — pungkasané tatanan Hafsiyah-Spanyol", "d4498698"], "d": ["Nalika Charles V ngrebut Tunis ing taun 1535, dhèwèké ora mréntah kutha iku dhéwé, nanging mbalèkaké sultan Hafsiyah Maulay Hasan ing dhampar; miturut tembungé TDV, kutha Tunis tetep \"ing sangisoré pangayoman Spanyol lan pamaréntahan Maulay Ahmad III nganti campur tangan kapindho Utsmaniyah ing 1569\". Uluç Ali, sing tanggal 27 Juni 1568 diangkat mimpin beylerbeyilik Aljir, mlaku liwat dharatan nglurug Tunis, ngalahaké sultan Hafsiyah ing Béja lan mlebu kutha; Maulay Ahmad ngungsi menyang presidio Spanyol ing La Goulette. Kanthi mangkono teluk iku kapérang dadi loro — kuthané duwèké Utsmaniyah, bèntèng plabuhané duwèké Spanyol — lan pérangan iki lumaku patang taun.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Don Juan de Austria ngrebut manèh Tunis — siji-sijiné imbangan Lepanto ing dharatan", "a6f044ee"], "d": ["Sanajan Liga Suci bubar sawisé Lepanto (1571), Spanyol dhéwékan neken Afrika Lor: miturut tembungé TDV, \"tanggal 10 Oktober 1573 wong Spanyol miwiti operasi anyar kanggo ngrebut kendhali ing Tunis. Wong-wong iku ngrebut Tunis lan ninggal 8000 prajurit ing kono.\" Operasi ing sangisoré komando Don Juan de Austria iki dadi siji-sijiné panggonan ing ngendi kamenangan Lepanto oleh imbangan ing dharatan; nanging ora langgeng lan kutha iku direbut manèh sewelas sasi sabanjuré. Sing digulingaké pendhudhukan iku yaiku pamaréntahan Utsmaniyah sing wis madeg: tanggal 2 Dzulhijjah 980 (5 April 1573) komandan Tunis yaiku Kılıç Ali Pasya, kaymakamé Ramazan Pasya, beylerbeyiné Haydar Pasya.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Wangsa Safawiyah ngrebut Bahrain saka Portugal", "c37d982c"], "d": ["Pasukan sing dikirim Syah Abbas I nggabung karo para pambrontak ing pulo iku lan ngetokaké garnisun Portugal saka bèntèng; miturut tembungé TDV, pulo-pulo iku direbut saka wong Portugal \"ing 1602 déning pasukan sing mèlu Iran\". Kanthi mangkono Bahrain ucul saka wolung puluh siji taun pamaréntahan Portugal, mlebu ing kakuwasan Safawiyah lan tetep gandhèng karo Iran suwéné satus limalas taun. Iki mata rantai kapisan bubaré Portugal ing teluk; rong puluh taun sabanjuré Hormuz dhéwé uga bakal tiba amarga operasi bebarengan Inggris-Iran.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Wong Oman nyerbu Bahrain — pungkasané kakuwasan Safawiyah", "c9be5820"], "d": ["Nalika Nagara Safawiyah bubrah ing taun-taun pungkasané, armada Oman ing sangisoré pamaréntahan wangsa Ya'rubi nyerbu pulo iku lan kakuwasan Safawiyah rampung. Telung puluh lima taun sabanjuré iku jaman sing paling ruwet ing teluk: pulo iku ganti tangan ping pirang-pirang antarané Oman, Iran lan kakuwatan Arab lokal.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Bahrain pindhah menyang pamaréntahan Al Mazkur saka Bushehr", "610e2f9d"], "d": ["Kulawarga Al Mazkur, sing asalé saka Oman, manggon ing Bushehr lan kaétung golongan Huwala, ing 1753 obah saka pangkalané ing Bushehr lan nglebokaké Bahrain ing pamaréntahané. Kulawarga iku mimpin masarakat Arab ing pasisir teluk Iran lan mréntah pulo iku atas jenengé Iran; wakilé sing pungkasan, Nasr Al Mazkur, diangkat dadi gubernur Bahrain déning pamaréntahan Zand. Iki pamaréntahan pungkasan pulo iku sadurungé Al Khalifa.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Dikosongaké Mazagan — pos pungkasan Portugal ing Maroko tiba", "f9e9749d"], "d": ["Garnisun 592 wong ora kuwat nadhahi pengepungan sing diwiwiti sultan Alawi Muhammad III b. Abdullah ing wiwitan 1769; armada pangungsian sing mangkat saka Lisboa tanggal 1 Februari ngangkut prajurit pungkasan tanggal 11 Maret 1769, lan gubernur Dinis Gregório dadi wong pungkasan sing ninggal kutha. Kanthi mangkono anané Portugal ing Maroko, sing diwiwiti kanthi direbuté Ceuta ing 1415, rampung sawisé telung abad setengah. Mazagan iku siji-sijiné pos ing pasisir Atlantik sing tetep dicekel sawisé ambruk umum 1541, lan kanthi rong atus sèket lima taun dadi panggonan sing paling suwé dicekel Portugal ing Maroko.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Al Khalifa naklukaké Bahrain — madegé wangsa sing lumaku nganti saiki", "8773b011"], "d": ["Nasr Al Mazkur, gubernur Bahrain saka pamaréntahan Zand, ngepung Zubarah ing semenanjung Qatar; pasukan Utub ing sangisoré komando Ahmad b. Muhammad b. Khalifa njebol pengepungan, banjur males nyerang lan ing taun sing padha ngrebut Bahrain. Cathetané TDV cekak: \"Ing taun 1783 Bahrain mlebu ing kakuwasan Al Khalifa saka suku Utub.\" Sawisé kamenangan iki Ahmad b. Muhammad disebut kanthi julukan \"al-Fatih\" (Sang Penakluk), lan wangsa sing diadegaké mréntah ing pulo iku nganti saiki.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Prajanjèn Bahrain karo Inggris — mlebu tatanan protektorat ing teluk", "576796b2"], "d": ["Miturut cathetan TDV, \"tanggal 21 Mèi 1861 Inggris lan Ali, seduluré Syekh Muhammad, sing makili Bahrain, nandhatangani prajanjian sing nglarang dagang budhak lan bajak laut ing wilayah iku\"; ing dokumèn Inggris, prajanjian sing padha (Perpetual Truce of Friendship and Peace) tinanggalan 31 Mèi 1861. Prajanjian iku mata rantai kapisan tatanan protektorat sing ngiket hubungan njaba Bahrain marang Inggris, lan pulo iku tetep ana ing sanjabané tatanan iki malah sawisé Utsmaniyah manggon manèh ing al-Ahsa lan Qatif ing 1871.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahi Evran — pepundhèn pangadeg organisasi ahi", "3392e100"], "d": ["Ahi Evran dianggep salah siji pangadeg organisasi ahi ing Anatolia lan pepundhèné para tukang samak kulit. Zawiyahé ing Kırşehir, ing jaman Utsmaniyah, tetep dadi puser karohanèn organisasi para sudagar lan gildhe nganti wiwitan abad kaping 20; nagara resmi negesaké kalungguhan iki ing 1780, 1782, 1822-23 lan 1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Syekh Edebali — tali adeg antarané organisasi ahi lan dinasti Utsmaniyah", "c1186059"], "d": ["Edebali, sing madegaké zawiyah ing Bilecik lan uga dadi syekh ing organisasi ahi, miturut riwayat nafsiraké impèn misuwuré Osman Ghazi; sawisé iku Osman Ghazi nikah karo putriné Edebali, Malhun Hatun. Edebali uga dianggep kadi lan mufti Utsmaniyah kapisan.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Orhan Ghazi mewakafaké lemah kanggo dolanan cirit sawisé naklukaké Bursa", "da1becbd"], "d": ["Miturut artikel Cirit ing TDV, sawisé Bursa ditaklukaké, Orhan Ghazi mewakafaké papan ing sakiwa-tengené kanggo balapan jaran lan dolanan cirit — iki salah siji tuladha kapisan sing kacathet bab dolanan cirit sing wis dadi lembaga ing Utsmaniyah.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Wiwitané gulat Kırkpınar miturut riwayat", "2d93fa65"], "d": ["Miturut riwayat, tradhisi gulat Kırkpınar diwiwiti saka lomba gulat antarané patang puluh ghazi sing nyabrang bebarengan karo Suleyman Pasya, panakluk Rumelia. Artikel Güreş lan Kırkpınar ing TDV nyritakaké riwayat iki nanging ora menehi tanggal adeg sing mesthi.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Madegé Korps Janissary", "f4206dce"], "d": ["Sistem sing diwiwiti kanthi nglatih para nom-noman non-Muslim sing dijupuk saka tawanan perang miturut undhang-undhang pencik, atas pituduhé Çandarlı Kara Halil lan Molla Rüstem, oleh wujud lembaga ing jaman Murad I liwat Korps Acemi sing diadegaké ing Gallipoli.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Wiwitané pambangunan Masjid Lawas Edirne (Masjid Agung)", "da7a22ac"], "d": ["Pambangunan Masjid Eski, sing ing antarané rakyat uga dikenal kanthi jeneng Ulucami (Jami Atiq), diwiwiti déning Emir Suleyman Celebi ing 1402-1403.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Wiwitané pambangunan Komplèk Masjid Ijo Bursa", "280b8a21"], "d": ["Mehmed I, sing nyawijèkaké manèh dhampar sawisé Mangsa Interregnum, miwiti pambangunan komplèk iku ing 1414 lan mapanaké ing titik tengah Bursa, kanthi cara sing bisa dibédakaké saka komplèk-komplèk duwèké éyang lan ramané. Kepala arsitèké yaiku Hacı İvaz Pasya.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Rampungé Komplèk Masjid Ijo Bursa", "bc82821f"], "d": ["Komplèk Masjid Ijo, sing dikenal amarga program tegel lan rerenggané sing uga disengkuyung tukang-tukang ahli saka Tabriz, rampung ing Désèmber 1419. Komplèk iku dumadi saka masjid, makam (Makam Ijo), madrasah, imaret lan pasiraman; iki salah siji tuladha sing paling sugih saka arsitèktur Utsmaniyah wiwitan.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Sistem devshirme wiwit ditrapaké ing kanyatan", "fa835172"], "d": ["Cara devshirme, sing ora ditemoni ing nagara-nagara Islam sadurungé, wiwitané arupa migunakaké para nom-noman non-Muslim saka tawanan perang miturut undhang-undhang pencik. Miturut TDV, \"dingertèni yèn iku ditrapaké ing jaman Celebi Mehmed, nanging lagi dadi undhang-undhang ing jaman putrané, Murad II.\"", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Diadegaké jabatan syekhul Islam — Molla Fenari dadi mufti Bursa", "2a8ee2b9"], "d": ["Diangkaté ulama Molla Fenari, sing wis suwé dadi kadi Bursa, dadi mufti Bursa ing 1425 dianggep, miturut tembungé TDV, \"wiwitané jabatan mufti lan syekhul Islam ing Utsmaniyah\". Nanging TDV nerangaké yèn iki ora padha karo jabatan syekhul Islam sing wis dadi lembaga kanthi wutuh ing abad kaping 16 lan makili kabèh organisasi ilmiye.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Sistem timar dadi lembaga", "dc267780"], "d": ["Panyebutan timar kapisan sing adhedhasar dokumèn tekan jaman Orhan Bey; déné pangundhangan sacara sistematis kelakon ing jaman Murad II. Buku daftar icmal timar sing disusun ing jaman iki nuduhaké yèn kabèh asas dhasar sistem iku wis kawangun; dokumèn saka watara 1432 mbuktèkaké yèn undhang-undhangé wis lumaku kanthi wutuh.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Rampungé Masjid lan Komplèk Üç Şerefeli", "cde6993e"], "d": ["Masjid Üç Şerefeli, sing dibangun atas dhawuhé Murad II déning tukang ahli Muslihuddin lan Syihabuddin sajroné sepuluh taun (1437-1447), dianggep minangka tuladha kapisan masjid kanthi dénah terpusat ing arsitèktur Utsmaniyah lan dadi salah siji titik wigati arsitèktur peralihan sadurungé jaman klasik.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Divan-i Hümayun dadi lembaga liwat undhang-undhang Sang Penakluk", "e8443e77"], "d": ["Divan wiwit oleh ciri \"Divan-i Hümayun\" ing jaman Murad II nalika ditata nganggo aturan sing ajeg ing Edirne. Owah-owahan sing satenané teka liwat undhang-undhang Mehmed Sang Penakluk: pambaharuan paling gedhé yaiku kalungguhané sultan minangka pimpinan divan dibusak babar pisan lan dipasrahaké marang wazir agung.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Mehmed Sang Penakluk nyawisaké Okmeydanı kanggo para pemanah", "342a9fd5"], "d": ["Mehmed Sang Penakluk, sing sajroné naklukaké Konstantinopel madegaké markas ing gigir Kasımpaşa, uga nggunakaké panggonan iku minangka papan latihan para pemanah; sawisé kutha direbut, dhèwèké nyawisaké papan iku kanggo para pemanah kanthi tetep. Panyawisan iki dadi wiwitané Okmeydanı dadi puser tradhisi manah Utsmaniyah sing lumaku atusan taun.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Bursa tekan pucuké ing dagang sutra Iran", "f1324cdf"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Bayezid II maringi hadiah gedhé marang para pegulat Kırkpınar", "d745b882"], "d": ["Miturut artikel Güreş ing TDV, Bayezid II ing taun 1504 maringi hadiah 3.000 lan 1.500 kuruş marang para pegulat; iki salah siji tuladha wiwitan sing kacathet saka pangayoman karaton Utsmaniyah marang olahraga gulat.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Rampungé Masjid lan Komplèk Bayezid", "eb9ab65b"], "d": ["Miturut dokumèn arsip, pambangunan Masjid lan Komplèk Bayezid sing digawé kanggo Bayezid II diwiwiti ing taun 906 (1500) lan rampung tanggal 14 Jumadilawal 911 (13 Oktober 1505). Arsitèké isih dadi bahan padudon: adhedhasar cathetané Ayvansarayi, suwé dianggep karyané Mimar Hayreddin, banjur digandhèngaké karo Mimar Kemaleddin, lan miturut sapérangan wong loro-loroné nyambut gawé bebarengan; nanging dokumèn sing padha nuduhaké yèn tukang ahliné yaiku Yakub Syah b. Sultan Syah. Masjid iki kaétung salah siji monumèn wigati peralihan saka arsitèktur Utsmaniyah pra-klasik menyang jaman klasik.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Tersane-i Amire (Galangan Kapal Kakaisaran) dipindhah menyang Istanbul (Kasımpaşa/Tandhuk Emas)", "f36e3675"], "d": ["Galangan anyar sing wiwit dibangun ing jaman Yavuz Sultan Selim ing teluk sisih kuloné bèntèng Galata rampung ing 1515 kanthi 160 petak; kanthi mangkono kagiyatan galangan sing puseré ing Gallipoli dipindhah menyang Istanbul. Lembaga iku sabanjuré, ing jaman Barbaros Hayreddin Pasya, resmi oleh jeneng \"Tersane-i Amire\".", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Sédané Syekh Hamdullah lan warisan aliran kaligrafiné", "f5ed4d09"], "d": ["Syekh Hamdullah saka Amasya, minangka guru kaligrafiné Bayezid II, nggawa aliran aqlam-i sitte (enem jinis aksara) nganti tekan mangsa diwasa lan dadi pangadeg gaya kaligrafi Utsmaniyah sing bakal nguwasani sakabèhé donya Islam. Nalika séda ing 1520, dhèwèké ninggal bunderan murid sing jembar.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Piri Reis ngrampungaké vèrsi kapisan Kitab-i Bahriye", "fd6cc1ff"], "d": ["Vèrsi kapisan (gancaran) Kitab-i Bahriye, sing nglumpukaké katrangan bab pasisir, plabuhan lan lelayaran Segara Tengah, dirampungaké Piri Reis ing 1521. Vèrsi kapisan iki durung diaturaké marang sultan lan isih arupa rancangan sing bakal dijembaraké ing taun-taun sabanjuré.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Piri Reis njembaraké Kitab-i Bahriye lan ngaturaké marang Sultan Suleyman", "d4abf0b7"], "d": ["Piri Reis njembaraké Kitab-i Bahriye, sapérangan awujud geguritan, lan ing 1526 ngaturaké marang Sultan Suleyman Sang Pembuat Undhang-undhang. Ing wujud iki karya kasebut sumebar minangka pandhuan lelayaran sing paling jangkep ing donya kalautan Utsmaniyah.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçı Nasuh nggambar rute ekspedisi Irak Loro ing Beyan-i Menazil", "aa012278"], "d": ["Matrakçı Nasuh, sing mèlu ekspedisi Iran kapisan (Irak Loro) Sultan Suleyman Sang Pembuat Undhang-undhang ing 1534, nggambar saben papan pangaso ing rute wadyabala saka Istanbul menyang Tabriz lan saka kono menyang Bagdad nganggo tèknik miniatur-peta. Karya iki dikumpulaké ing buku Beyan-i Menazil-i Sefer-i Iraqayn lan dadi tuladha sing paling asli saka jinis menzilname ing Utsmaniyah.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Fuzuli ngaturaké kasidah marang Sultan Suleyman sawisé Bagdad ditaklukaké", "1ef0653f"], "d": ["Sawisé Sultan Suleyman Sang Pembuat Undhang-undhang naklukaké Bagdad ing 1534, Fuzuli ngaturaké lima kasidah marang sultan Utsmaniyah, kalebu kasidah misuwur sing diwiwiti nganggo larik \"Geldi burc-ı evliyâya pâdişâh-ı nâmdâr\"; kanthi mangkono dhèwèké metu saka pangayoman Safawiyah lan golèk pangayomané para pejabat nagara Utsmaniyah.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Fuzuli ngrampungaké masnawi Layla lan Majnun", "e3ef4085"], "d": ["Layla lan Majnun, sing kaétung salah siji masnawi paling éndah ing sastra klasik Turki, ditulis lan dirampungaké Fuzuli ing 1535, atas panyuwuné para pujangga Istanbul sing mèlu ekspedisi Bagdad Sultan Suleyman.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Mimar Sinan diangkat dadi kepala arsitek karaton", "7a753f0e"], "d": ["Miturut artikel Sinan ing Ènsiklopedhia Islam TDV, nalika kepala arsitek karaton Acem Alisi séda ing 1537, Sinan, sing narik kawigatèn amarga kreteg sing dibangun ing dhuwur kali Prut sajroné ekspedisi Moldavia, diangkat ing kalungguhan iki merga pangaji-ajiné Wazir Agung Lutfi Pasya. Kanthi mangkono diwiwiti mangsa Sinan dadi kepala arsitek, sing bakal lumaku luwih saka sèket taun.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Wiwitané pambangunan Masjid lan Komplèk Şehzade", "1a70ddfd"], "d": ["Sultan Suleyman Sang Pembuat Undhang-undhang mréntahaké mbangun komplèk atas jenengé putrané, Şehzade Mehmed, sing séda amarga pageblug pes ing 1543; pambangunan diwiwiti ing Juni 1543, dhisik makamé dirampungaké banjur diterusaké mbangun masjidé. Bangunan iki, miturut tembungé Mimar Sinan dhéwé, yaiku \"karyaku nalika isih magang\".", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Rampungé Komplèk Üsküdar İskele (Mihrimah Sultan)", "3769007f"], "d": ["Pambangunan komplèk ing Alun-alun İskele Üsküdar diwiwiti ing taun-taun wiwitan 1540-an lan rampung ing 1547. Saka rong masjid gedhé sing digawé Mimar Sinan atas dhawuhé Mihrimah Sultan, sacara kronologis iki sing kapisan; sing kapindho (Edirnekapı) bakal rampung watara rong puluh taun sabanjuré.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Venesia mbukak konsulat ing Aleppo", "3aad8b9e"], "d": ["Ing abad kaping 16 puser dagang wong Éropah pindhah saka Damaskus menyang Aleppo. Minangka pratandha nyata owah-owahan iki, Venesia mbukak konsulat ing Aleppo ing 1548; Prancis nyusul ing 1557 lan Inggris ing 1586. Kutha iku dadi pasar utama papan kain wol lan perak Éropah diijolaké karo bumbon India lan, ing pungkasan abad, sutra Iran.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Masjid Şehzade dibukak kanggo ngibadah", "2bb3f4b2"], "d": ["Sawisé dibangun watara limang taun, Masjid Şehzade dibukak kanggo ngibadah ing Agustus 1548. Kanthi dénah sing nganggo menara kembar lan kubah tengah, masjid iki dianggep dadi pratandha karya-karya gedhé Mimar Sinan sabanjuré; komplèké dumadi saka masjid, makam, madrasah, imaret, tabhane lan karavanserai.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Wiwitané pambangunan saluran banyu Kırkçeşme", "14124b59"], "d": ["Atas dhawuhé Sultan Suleyman Sang Pembuat Undhang-undhang, Mimar Sinan nliti kamungkinan nggawa banyu saka alas Beograd menyang Istanbul lan nglaporaké yèn iku bisa ditindakaké; pambangunan instalasi banyu gedhé iku diwiwiti ing 1554 lan rampung sadurungé 1563. TDV njlèntrèhaké bangunan iki minangka karyané Sinan \"sing paling wigati saka sisi rékayasa, lan uga sing paling gedhé saka sisi volume\".", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Dibukaké warung kopi kapisan ing Istanbul", "85c12f9f"], "d": ["Mlebuné kopi ing urip kutha Utsmaniyah diwiwiti saka warung kopi sing dibukak ing Tahtakale déning sudagar saka Aleppo aran Hakem lan wong saka Damaskus aran Syams. Ora suwé lair ruang umum anyar papan wong saka saben lapisan masarakat padha nglumpuk; ing mangsa pungkasan Sultan Suleyman ana sèket warung kopi ing Istanbul.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ebussuud Efendi nliti perkara gedik (hak monopoli sudagar) saka sisi hukum", "5d4e2930"], "d": ["Perkara \"gedik\", yaiku hak monopoli lan hak istimewa sing diwènèhaké marang cacah wong tartamtu ing pakaryan dagang, muncul manèh ing jaman Sultan Suleyman; Syekhul Islam Ebussuud Efendi nliti perkara iku kanthi jero ing 1555-56 lan ngaturaké sahé praktik iku marang sultan.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Seydi Ali Reis ngrampungaké Mir'atul-Mamalik ing Istanbul", "ee8640e1"], "d": ["Karya lelampahan sing aran Mir'atul-Mamalik, sing ditulis sajroné lelampahan mulih wiwit saka Bagdad, dirampungaké Seydi Ali Reis ing Istanbul ing Januari 1557. Karya iki sumber tangan kapisan sing nyritakaké baliné sawijining pelaut Utsmaniyah menyang tanah wutah getihé liwat dharatan, saka Samudra Hindia ngliwati Asia Tengah.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Pambangunan Komplèk (Masjid) Rüstem Pasya", "02e30725"], "d": ["Komplèk sing digawé Mimar Sinan atas dhawuhé Rüstem Pasya, mantu lan wazir agungé Sultan Suleyman Sang Pembuat Undhang-undhang, dibangun antarané 1555-1561. Bangunan iki dikenal amarga arsitèkturé sing asli, madeg ing dhuwur panggung sing diunggahaké kanthi toko-toko lengkung ing ngisoré, lan amarga tegel Iznik sing sugih.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Rampungé Kreteg Mostar", "e7f434af"], "d": ["Kreteg Mostar sing misuwur ing dhuwur kali Neretva dibangun watara taun 1566-67 déning Mimar Hayreddin; disebuté kreteg iku ing dokumèn resmi tinanggalan 1568 mbuktèkaké yèn pancèn wis rampung. Bangunan iki salah siji tuladha sing paling dikenal saka arsitèktur kreteg klasik Utsmaniyah kanthi lengkung lancip bentang siji.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Rampungé Masjid Edirnekapı (Mihrimah Sultan)", "f2d21a82"], "d": ["Pambangunan masjid kanggo Mihrimah Sultan, putriné Sultan Suleyman Sang Pembuat Undhang-undhang, diwiwiti sawisé idin mbangun sing dipesthèkaké ing 1563 lan rampung ing 1566; piagam wakaf komplèké disusun ing 1570-71. Bangunan iki salah siji karya gedhé Mimar Sinan sing paling cedhak karo bèntèng kutha Istanbul.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Baki nulis geguritan lelayu kanggo Sultan Suleyman", "7aa6665f"], "d": ["Nalika kabar sédané Sultan Suleyman Sang Pembuat Undhang-undhang saka Szigetvár tekan, Baki, \"sultané para pujangga\" ing jaman iku, nulis salah siji geguritan lelayu sing paling misuwur ing sastra Utsmaniyah.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Baki ngaturaké geguritan jumenengan marang Selim II", "6027f034"], "d": ["Sanalika sawisé Selim II jumeneng, Baki ngaturaké marang sultan anyar sawijining \"culusiye\" (geguritan jumenengan) — miturut TDV, langsung sawisé geguritan lelayu sing ditulis bab sédané Sultan Suleyman.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Rampungé Kreteg Büyükçekmece", "5f49b3c5"], "d": ["Kreteg sing diwiwiti atas dhawuhé Sultan Suleyman Sang Pembuat Undhang-undhang dirampungaké ing 1567-68 déning putrané, Selim II, sawisé sultan séda sajroné ekspedisi Szigetvár. Mimar Sinan dhéwé uga ndandani pérangan-pérangan kreteg sing rusak amarga banjir; kreteg iku dibangun ing panggonan tlaga Büyükçekmece ketemu segara.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Wiwitané pambangunan Masjid Selimiye (Edirne)", "07e18c9e"], "d": ["Pambangunan Selimiye, sing diarani Mimar Sinan \"karya kaprigelanku\", diwiwiti atas jenengé Selim II ing 1568, lumaku enem taun lan rampung ing 1574 (rampungé wis kacathet ing kronologi). Déné toko-toko sisih kulon arasta lan sekolah dhasar bocah dirampungaké déning Davud Agha sawisé sédané Selim II, ing jaman Murad III.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Sédané Kınalızade Ali Celebi — pangripta Akhlaq-i Alai, naskah klasik filsafat budi pekerti Utsmaniyah", "dd921873"], "d": ["Kınalızade Ali Celebi, pangripta Akhlaq-i Alai, naskah klasik filsafat budi pekerti Utsmaniyah sing paling dikenal, séda tanggal 22 Januari 1572 nalika dadi kazasker Anatolia. Karyané duwé luwih saka pitung puluh salinan ing perpustakaan-perpustakaan Istanbul.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Digawéné Komplèk Piyale Pasya", "75411278"], "d": ["Kaptan-ı Deryâ Piyale Pasya, salah siji mantuné Selim II, tuku lemah kanggo komplèk iku ing 1573 banjur nyuruh Mimar Sinan mbangun. Komplèk iku dirancang minangka tatanan bangunan sing jembar, dumadi saka masjid, madrasah, tekke, makam, kuburan, sekolah dhasar bocah, pancuran, pasar lan pasiraman.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Rampungé Kreteg Drina (Sokollu Mehmed Pasya)", "1d668c73"], "d": ["Kreteg sing dibangun Mimar Sinan kanthi pangayomané Wazir Agung Sokollu Mehmed Pasya iki, miturut tanggal ing prasastiné, rampung ing 1577-78; sapérangan panaliti ngajokaké panemu yèn pambangunan diwiwiti ing 1571-72. Kreteg iki dadi lambang katresnané Sokollu marang Višegrad, papan kelairané.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Digawéné Masjid Azapkapı (Sokollu Mehmed Pasya)", "f7b57feb"], "d": ["Masjid sing mapan ing sandhing tiang Kreteg Unkapanı sisih Şişhane iki digawé déning Mimar Sinan atas dhawuhé Wazir Agung Sokollu Mehmed Pasya. Bangunan iki salah siji saka rong masjid karya Sinan sing dibangun atas jenengé Sokollu (sijiné manèh masjid ing Kadırga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Murad III ngetokaké firman supaya Hünername ditulis", "b125710d"], "d": ["Liwat firman tinanggalan 2 Januari 1578, Murad III mréntahaké Seyyid Lokman nulis Hünername, sing isiné urip para sultan wiwit Osman Ghazi nganti jamané; miniatur karya iku digarap déning Nakkaş Osman lan timé.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Rampungé Masjid Zal Mahmud Pasya", "732f75bc"], "d": ["Ing pambangunan komplèk sing diwiwiti sawisé Zal Mahmud Pasya lan Syah Sultan omah-omah ing 1574, pambangunan masjidé rampung ing 1580; madrasahé lumaku nganti 1582, déné pancurané nganti 1590. Komplèk iku narik kawigatèn amarga dénahé sing asli kanthi rong menara simetris ing lèrèng Eyüp.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Rampungé jilid kapindho Hünername", "70a1e741"], "d": ["Jilid kapindho Hünername rampung ing Januari 1588; kanthi 65 miniatur, jilid iki dadi salah siji karya historiografi Utsmaniyah sing paling aji saka sisi dokumèntèr. Loro jilid iku digambari ing bèngkèlé Nakkaş Osman.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Davud Agha dadi kepala arsitek karaton", "8cdc7f53"], "d": ["Sawisé sela cendhak sasédané Mimar Sinan ing 1588, wiwit 1592 Davud Agha disebut ing dokumèn resmi minangka kepala arsitek karaton. Davud Agha, sing nanggung sapérangan unsur panyampurna Komplèk Selimiye lan pambangunan wiwitan Masjid Anyar, iku salah siji arsitèk sing paling wigati ing jaman iku.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Pondhasi Masjid Anyar (Eminönü) dipasang", "d3cddc01"], "d": ["Kanthi Safiye Sultan, ibuné Mehmed III, minangka sing ngedegaké, pondhasi masjid iku dipasang nganggo blok watu sawisé lemahé dikuwataké nganggo cerucuk. Rong artikel TDV sing béda menehi tanggal sing béda kanggo kadadéan iki (artikel Komplèk Yenicami 9 April 1598, artikel Davud Agha 23 Agustus 1597); ing kéné sing dianggo dhasar yaiku tanggal ing artikel khusus bab bangunan iku dhéwé.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Davud Agha séda amarga pes lan pambangunan Masjid Anyar mandheg setengah dalan", "81f2cd04"], "d": ["Dalgıç Ahmed Çavuş diangkat dadi kepala arsitek nggantèni Davud Agha, sing séda amarga pageblug pes ing September 1598 nalika lagi ngunggahaké Masjid Anyar kira-kira sak zira' saka lemah. TDV nerangaké yèn ing riwayat liya sing adhedhasar geguritan kronogram, taun sédané uga katulis 1599-1600, lan tanggal sing mesthi ora bisa ditetepaké.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Èkspor akèh kain sof Ankara menyang Éropah", "3f37018d"], "d": ["Kain sof lan syali sing ditenun ing Ankara ora mung didol ing pasar njero kaya Istanbul, Bursa, Damaskus lan Aleppo, nanging uga diékspor menyang Venesia, Polandia, Inggris lan Prancis. Ing tuladha sing diwènèhaké TDV, ing 1599 sudagar wolulas wong tuku 162 momotan kain sof ajiné 5.700.000 akçe banjur dikirim menyang Aleppo lan Venesia.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Pambangunan Masjid Anyar mandheg amarga sédané Mehmed III", "5acef053"], "d": ["Sawisé Mehmed III, putrané Safiye Sultan sing ngedegaké masjid, séda ing 1603, Safiye Sultan dikirim menyang Karaton Lawas lan pambangunan Masjid Anyar mandheg setengah dalan; bangunan iku ngentèni kaya mangkono, durung rampung, watara sewidak taun.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Katib Celebi wiwit nliti ing Aleppo kanggo Kasyfuz-Zunun", "094e6870"], "d": ["Katib Celebi ing 1633 ing Aleppo wiwit nglumpukaké bahan Kasyfuz-Zunun, sing sabanjuré dadi karya agung bibliografiné. Sajroné panggawéan iki, sing lumaku rong puluh taun, dhèwèké nyisir siji-siji perpustakaan lan toko buku ing kutha-kutha sing diparani.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Nef'i diukum pati amarga geguritan sindirané", "5e459c60"], "d": ["Pujangga diwan Nef'i, sing dikenal amarga geguritan sindirané, ing 1635 diukum pati atas dhawuhé Murad IV amarga kumpulan sindiran sing aran Siham-i Qaza. Wazir Agung Bayram Pasya masrahaké dhèwèké; Nef'i dicekik nganti mati ing gudhang kayu karaton lan jisimé diguwang menyang segara.", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Disusuné buku narh sing jangkep", "6c1e231b"], "d": ["Sanajan praktik narh (wates rega paling dhuwur) ing Utsmaniyah wis lawas banget, buku narh sing paling jangkep sing isih tinemu saiki tinanggalan 1640; buku iki ngemot pangan, sandhangan, jasa, standar lan sarat karesikan, lan miturut tembungé TDV \"lumaku kaya undhang-undhang pranatan pasar sing wutuh.\"", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Katib Celebi sepisanan wiwit nulis Cihannüma", "554c6734"], "d": ["Katib Celebi, kanggo ngisi bolongan ing kawruh géografi Utsmaniyah ngadhepi panemon géografi Kulon, wiwit nyusun Cihannüma kapisan ing 1648. Vèrsi kapisan iki ora rampung amarga ora bisa nemokaké sumber sing cukup bab sapérangan nagara Éropah.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Sistem iltizam dadi mateng nalika mlebu monopoli golongan militèr", "2c587934"], "d": ["Cara iltizam (nglélang panariké pajeg marang wong pribadi kanthi pambayaran tartamtu) wis ditrapaké wiwit paro kapindho abad kaping 15, nanging wiwit awal abad kaping 16 sumebar kanthi cepet. Miturut TDV, prosès sektor iki mlebu kabèh ing monopoli anggota golongan militèr rampung ing 1650; kanthi mangkono iltizam dadi cara kauangan utama sing nggantèni sistem timar.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Katib Celebi wiwit nulis manèh Cihannüma saka wiwitan", "e9c68110"], "d": ["Katib Celebi, sing ninggal susunan kapisané durung rampung, ing pungkasan 1654 wiwit nulis manèh Cihannüma saka wiwitan. Vèrsi kapindho iki uga ora bisa dirampungaké; nalika karya iku wis tekan Van, penulisé séda ing 1657 saéngga karyané mandheg, lan lagi dicithak ing wujud iku ing 1732 déning Ibrahim Müteferrika.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Masjid Anyar rampung lan dibukak kanggo ngibadah", "d6d86c82"], "d": ["Pambangunan Masjid Anyar sing mandheg luwih saka sewidak taun dirampungaké ing sangisoré pimpinan Kepala Arsitek Meremetçi Mustafa Agha, sing diangkat Hatice Turhan Valide Sultan ing 1661, lan dibukak kanggo ngibadah kanthi salat Jumuah tanggal 30 Oktober 1665.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Mehmed IV nganakaké cirit nganti pirang-pirang dina ing pahargyan sunat ing Edirne", "3638a5b6"], "d": ["Mehmed IV, ing pahargyan sunat para pangéran putrané sing dianakaké ing Edirne ing 1675, nggelar lomba cirit nganti pirang-pirang dina; iki kasebut mligi ing artikel Cirit TDV minangka salah siji tuladha paling gemerlap saka panyengkuyung karaton Utsmaniyah marang olahraga cirit.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hafiz Osman ngrembakakaké gaya kaligrafiné dhéwé", "93081cb3"], "d": ["Hafiz Osman, sing nerusaké garis Syekh Hamdullah, ing 1679 ngrembakakaké ing aqlam-i sitte gaya anyar sing khas, sing sabanjuré disebut \"aliran Hafiz Osman\". Gaya iki lumaku nganti saiki kanthi rong cabang sing misah.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Hafiz Osman diangkat dadi guru kaligrafiné Mustafa II", "d976cda4"], "d": ["Hafiz Osman, sing dianggep ahli kaligrafi paling pinter ing jamané, ing 1695 diangkat dadi guru kaligrafi Mustafa II sing lagi waé jumeneng. Sajroné uripé dhèwèké nggulawenthah watara sèket ahli kaligrafi lan nyalin 25 Al-Qur'an.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Sédané Itri", "62750526"], "d": ["Buhurizade Mustafa Itri Efendi, salah siji komponis paling gedhé ing musik Turki, miturut sumber sing cedhak karo jamané, séda ing 1711. Kanthi karya kaya takbir Segah lan na't Rast, dhèwèké ninggal karya agung musik masjid lan tekke.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedim katon minangka pelopor geguritan Jaman Tulip", "d3c40dbb"], "d": ["Sajroné Jaman Tulip antarané 1718-1730, Nedim ngrembakakaké gaya geguritan anyar sing katon amarga kasampurnané ungkapan, golèk kasederhanaan lan gayané sing kebak lelucon alus. Gaya iki, sing ngrembaka ing sakiwa-tengené Nevşehirli Damad Ibrahim Pasya, dianggep wakil paling gedhé aliran pribumisasi ing geguritan diwan.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levni nggambari Surname-i Vehbi", "8c127866"], "d": ["Pelukis karaton Levni nggambari Surname-i Vehbi nganggo 137 miniatur; karya iku nyritakaké pahargyan sunat para pangéran putrané Ahmed III ing 1720. Béda karo tuladha sadurungé, dhèwèké ora mung ngurung rerameyan ing Hippodrome, nanging nggambaraké ing pirang-pirang pojok kutha, saéngga miwiti pamawas anyar ing seni miniatur Utsmaniyah.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Sistem gedik resmi mapan dadi tatanan sudagar adhedhasar monopoli", "cd0f79a7"], "d": ["Miturut TDV, owah-owahan sistematis nalika hak gedik oleh teges \"monopoli, hak istimewa lan jinis patèn\" bisa ditlusur wiwit 1727; tatanan iki, sing menehi hak nyambut gawé marang cacah wong tartamtu ing pakaryan dagang, mapan kanthi jeneng \"hak gedik\" ing toko-toko, sing akèhé duwèké wakaf.", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Sa'dabad dirusak sajroné pambrontakan Patrona Halil", "8a30f9a0"], "d": ["Sajroné pambrontakan Patrona Halil sing njebluk tanggal 25 September 1730, atusan paviliun lan bangunan ing Sa'dabad dirusak; komplèk sing dadi lambang Jaman Tulip iki ora tau bali menyang kamulyané biyèn.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Sédané Nedim sajroné pambrontakan Patrona Halil", "06bf909e"], "d": ["Nedim, sing nalika Pambrontakan Patrona Halil njebluk lagi dadi mudarris ing Madrasah Sekban Ali Pasya, séda ing dina-dina sawisé pambrontakan. Dina sédané ora dingertèni; nanging amarga akta qassam bab warisané digawé tanggal 15 Rabiulakir 1143 (28 Oktober 1730), dhèwèké séda sadurungé tanggal iku. Bab sebab sédané ana riwayat sing béda-béda: sapérangan sumber nulis yèn dhèwèké séda amarga lara wedi (illet-i vehime) utawa lara ndhredheg amarga ombèn-ombèn lan opium, déné Müstakimzade nulis yèn nalika geger dhèwèké, amarga wedi, munggah menyang payon omahé banjur tiba lan séda. Kanthi sédané, gemebyaré kabudayan Jaman Tulip uga sanyatané rampung.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Sédané Levni", "dd48b56e"], "d": ["Levni, sing dianggep wakil gedhé pungkasan seni miniatur Utsmaniyah, séda ing 1732. Pérangan gedhé karya-karyané saiki ana ing Museum Karaton Topkapı.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Pondhasi Masjid lan Komplèk Nuruosmaniye dipasang", "397ec798"], "d": ["Pondhasi Komplèk Nuruosmaniye dipasang déning Mahmud I tanggal 19 Januari 1749. Bangunan iki dianggep minangka panrapan gedhé kapisan gaya Barok Éropah ing arsitèktur Utsmaniyah lan cetha béda saka pola komplèk klasik.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Pambukaan Masjid lan Komplèk Nuruosmaniye", "15d83731"], "d": ["Pambukaan komplèk sing diwiwiti Mahmud I nanging ora kober dideleng rampungé, katindakaké tanggal 5 Desember 1755 ing jaman seduluré, Osman III. Masjid iku oleh jeneng kanthi teges \"Cahyané Osman\", ngrujuk marang Osman III sing mbukak.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Pambukaan Mühendishane-i Bahri-i Hümayun (Sekolah Tèknik Segara Kakaisaran)", "a2fab1cd"], "d": ["Mühendishane-i Bahri-i Hümayun, sekolah tèknik segara modhèrn kapisan ing Utsmaniyah, miturut dokumèn arsip Prancis dibukak tanggal 29 April 1775 ing jaman Abdulhamid I, nalika Wazir Agung Derviş Mehmed Pasya njabat.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Diadegaké sistem esham", "eabd8ece"], "d": ["Ngadhepi abotan ganti rugi 7,5 yuta kuruş sing digawa Prajanjèn Küçük Kaynarca, sistem esham diadegaké ing 1775. Ing cara iki, sing dirancang kanggo ngliwati watesané malikane, asil mukataa dipérang dadi andhil, lan béda karo malikane, wong wadon, wong non-Muslim lan rakyat lumrah uga bisa duwé andhil.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Laire Hammamizade Ismail Dede Efendi", "c033f039"], "d": ["Hammamizade Ismail Dede Efendi, salah siji komponis paling produktif ing musik Turki, lair tanggal 9 Januari 1778 ing kampung Şehzadebaşı, Istanbul. Sajroné uripé dhèwèké nganggit luwih saka 500 karya; udakara 294 saka cacah iku isih tinemu nganti saiki.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Wiwitané pambangunan Mühendishane-i Berri-i Hümayun (Sekolah Tèknik Militèr Dharatan Kakaisaran)", "4f5d521a"], "d": ["Pambangunan Mühendishane-i Berri-i Hümayun, salah siji lembaga paling wigati saka réformasi Nizam-i Cedid Selim III, diwiwiti tanggal 14 Juli 1793. Gedhungé rampung ing September 1795 lan dibukak kanggo piwulangan; lembaga iku sekolah tèknik militèr kapindho ing Utsmaniyah, sing nulad akademi militèr ing Éropah.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Selim III wiwit mbusak monopoli sapérangan gildhe sudagar", "008f4a7d"], "d": ["Miturut artikel Esnaf ing TDV, ing tatanan gildhe Utsmaniyah, sing wiwit adegé wis raket karo organisasi ahi, para pejabat kaya \"ahi baba\" lan \"syekh\" mimpin gildhe nganti wiwitan abad kaping 19; nalika ing abad kaping 18 gildhe nganggo monopoli ngunggahaké rega ngluwihi narh lan nuwuhaké tekanan ékonomi, Selim III wiwit 1794 mbusak monopoli gildhe pangan pokok.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendi ditampa ing karaton minangka musahib-i syehriyari", "0cb99ac3"], "d": ["Dede Efendi, sing ing jaman Selim III narik kawigatèné sultan liwat gubahan ing makam Buselik, ing 1812 dilebokaké Mahmud II ing golongan \"musahib-i syehriyari\" (kanca pasamuwan pribadiné sultan), lan ora suwé banjur munggah dadi kepala muadzin.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Sensus pendhudhuk ajeg kapisan ing Utsmaniyah", "4f004c6c"], "d": ["Mahmud II, kanggo nemtokaké pendhudhuk sing bakal dijupuk dadi prajurit, sepisanan nganakaké sensus ajeg ing pungkasan 1830; mung pendhudhuk lanang sing dicathet, lan ing Anatolia-Rumelia ketemu watara 7,5 yuta jiwa. Ing sapérangan wilayah kaya Erzurum lan Van sensus lagi bisa rampung ing 1836.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Madegé Feshane-i Amire", "971ab85a"], "d": ["Kanggo nyukupi kabutuhan pèci fez wadyabala Asakir-i Mansure-i Muhammediyye sing diadegaké sawisé Korps Janissary dibubaraké ing 1826, ing 1833 kanthi modhal 1,5 yuta kuruş wiwit digawé fez ing Alun-alun Cündi ing Kadırga. Pabriké ing 1839 dipindhah menyang Karaton Hatice Sultan ing Eyüp; Feshane dadi dhasar industri tèkstil Utsmaniyah.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Sekolah kedhokteran oleh jeneng Mekteb-i Tibbiyye-i Adliyye-i Syahane", "187d60f3"], "d": ["Sekolah kedhokteran sing pindhah menyang gedhung Sekolah Agha Enderun ing Galatasaray, tanggal 14 Mèi 1839 kanthi rawuhé Mahmud II oleh jeneng \"Mekteb-i Tibbiyye-i Adliyye-i Syahane\"; kanthi mangkono lembaga iku resmi kacathet nganggo ciri sekolah militèr-administratif.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Sédané Dede Efendi ing Mina nalika haji", "c3e613a2"], "d": ["Hammamizade Ismail Dede Efendi, sing kena kolera ing Mina nalika nindakaké kuwajiban haji, séda tanggal 29 November 1846. Kanthi sédané seniman iki, sing antarané 1824-1839 wis nganggit pitu ayin Mevlevi, sawijining jaman musik klasik Utsmaniyah katutup.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Ditampané Kitab Undhang-undhang Dagang 1850", "8ac085fd"], "d": ["Ing rangka réformasi hukum jaman Tanzimat, undhang-undhang anyar dijupuk saka nagara-nagara Kulon liwat terjemahan lan pangutipan: undhang-undhang pidana lumaku ing 1840, undhang-undhang dagang ing 1850, undhang-undhang lemah ing 1857. Kitab Undhang-undhang Dagang iku kodifikasi modhèrn kapisan hukum dagang Utsmaniyah.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Wiwitané pangungsian gedhé wong Tatar Krimea lan bangsa-bangsa Kaukasus menyang tanah Utsmaniyah", "8832c06d"], "d": ["Sawisé Syekh Syamil ditawan wong Rusia ing 1859, akèh muhajir Sirkasia lan Nogai saka Kaukasus, bebarengan karo wong Tatar Krimea, wiwit ngungsi menyang tanah Utsmaniyah. Ombak pangungsian iki lumaku kanthi kakuwatan sing béda-béda nganti sawisé Perang Utsmaniyah-Rusia 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Madegé Komisi Muhajirin", "9717e77e"], "d": ["Kanggo ngatur ombak pangungsian saka Kaukasus sing saya gedhé, pamaréntah Utsmaniyah ngedegaké Komisi Muhajirin tanggal 16 Januari 1860. Komisi iku ngoordinasi panggawéan panggonan manggon ing Anatolia, Balkan lan Suriah, lan lumaku nganti 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Bank-i Osmani ditata manèh dadi Bank-i Osmani-i Syahane (Bank Utsmaniyah)", "c3530456"], "d": ["Ing 1856, sawisé Perang Krimea, kanggo ngatur pambayaran utang njaba, diadegaké Bank-i Osmani sing puseré ing London lan modhalé saka Inggris. Ing 1863 klompok gabungan Prancis-Inggris diidini ngedegaké bank anyar kanthi jeneng Bank-i Osmani-i Syahane (Bank Utsmaniyah); sabanjuré lembaga iku uga oleh wewenang ngetokaké dhuwit kertas.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Madegé Cemiyet-i Tedrisiyye-i Islamiyye", "77ad553a"], "d": ["Kanggo nanggung pendhidhikan para magang Muslim sing mlarat, tanggal 30 Maret 1864 diadegaké Cemiyet-i Tedrisiyye-i Islamiyye; usaha paguyuban sipil iki tuladha pelopor tradhisi amal sing owah dadi proyèk sekolah modhèrn. Sangang taun sabanjuré paguyuban iku bakal mbukak Darüşşafaka.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Pranatan sistem muhtar lan dhéwan sesepuh liwat Pranatan Vilayet 1864", "1a2e8cf2"], "d": ["Liwat Pranatan Vilayet 1864, pamaréntahan désa ditata manèh; ing désa sing wong Muslim lan non-Muslim urip bebarengan, ditampa yèn saben jamaah milih muhtar lan dhéwan sesepuhé dhéwé. Kanthi mangkono dhéwan sesepuh sepisanan oleh panggonan resmi ing pamaréntahan désa/kampung.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Pucuké Pambuwangan Gedhé Sirkasia", "b2ab1874"], "d": ["Amarga Rusia ngenggoni Kaukasus antarané 1858-1878, paling abot ing 1861-1864, 1,2-1,5 yuta wong Sirkasia dipeksa ngungsi menyang tanah Utsmaniyah. Miturut TDV, akèh panaliti nyebut kadadéan iki \"gerakan pembersihan ètnis kapisan ing sajarah modhèrn.\"", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Diterbitaké Pranatan Pendhidhikan Umum (Maarif-i Umumiyye) 1869", "787f6022"], "d": ["Pranatan Maarif-i Umumiyye sing diterbitaké tanggal 1 September 1869 dadi naskah jangkep kapisan sing ngatur pendhidhikan umum ing dhaérah lan puser. Liwat pranatan iki Meclis-i Kebir-i Maarif diadegaké; kanthi pranatan iki uga diwiwiti nata manèh sekolah sibyan, supaya ora mung dadi tahap pendhidhikan agama nanging diarahaké marang piwulang maca-nulis.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Sekolah Darüşşafaka miwiti piwulangan", "525c457c"], "d": ["Darüşşafaka, sing diadegaké Cemiyet-i Tedrisiyye-i Islamiyye, sanyatané miwiti piwulangan tanggal 28 Juni 1873 kanggo ndhidhik bocah Muslim yatim lan mlarat kanthi gratis lan manggon ing asrama; umur panampan paling dhuwur ditetepaké sepuluh taun.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Lindhu Istanbul 1894", "7ae7f648"], "d": ["Lindhu sing kedadéan ing segara ngarep Teluk Izmit tanggal 10 Juli 1894 ngantem Istanbul kanthi abot; akèh masjid lan bangunan sajarah, kalebu bèntèng kutha Istanbul, rusak. Artikel bab lindhu ing TDV ngétung lindhu iki, bebarengan karo lindhu 1509, 1719 lan 1766, minangka lindhu sing nyebabaké akèh korban jiwa lan karugèn bandha ing wilayah Marmara.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Pambukaan Darülaceze", "a30baf31"], "d": ["Darülaceze, sing disiapaké miturut dhawuh Abdulhamid II wiwit 1890, dibukak tanggal 2 Februari 1896 déning Wazir Agung Halil Rifat Pasya. Lembaga iki ngiyupi bocah lola, wong tuwa lan wong sing mbutuhaké; kanthi griya sakit 200 amben, bèngkèl-bèngkèlé lan papan ngibadah sing dhéwé-dhéwé kaya masjid, gréja lan sinagoga, iki komplèk pitulungan sosial paling gedhé ing jamané.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Darulfunun-i Syahane diadegaké manèh minangka lembaga tetep", "7d6d8fc4"], "d": ["Sawisé rong usaha sadurungé sing gagal (1863 lan 1870), Darulfunun diadegaké manèh tanggal 31 Agustus 1900 minangka lembaga tetep kanthi jeneng Darulfunun-i Syahane; TDV nyebut tanggal iki minangka dhasar langsung sistem universitas Turki saiki.", "7d7fd7ca"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Kakuwasan Daju ing Darfur pindhah menyang wong Tunjur", "6eb22a2a"], "d": ["Miturut artikel Darfur ing Ènsiklopedhia Islam TDV, sing sepisanan manggon ing wilayah iku lan ngedegaké nagara kapisan yaiku suku Daju; wong Daju, sing nguwasani kono sajroné abad kaping 13 lan 14, kélangan dhominasi dagang marang wong Tunjur, lan ing abad kaping 15 kahanan, mligi ing wilayah tengah, walik babar pisan nguntungaké wong Tunjur.", "2709880c"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Madegé Kasultanan Darfur — wangsa Keira lan Sulaiman Solong", "0fc1c112"], "d": ["Miturut TDV, madegé Kasultanan Darfur kedadéan sawisé kekacauan sing nyusul serbuané Bumu al-Qasir ing wilayah iku ing pungkasan abad kaping 17. Wong Fur, ing sangisoré pimpinan wangsa Kira (Keira) sing dipimpin Sulaiman Solong, ngrebut kakuwasan saka tangané wong Daju lan Tunjur lan ngedegaké pamaréntahan sing kukuh. Sulaiman Solong mréntah antarané 1695-1715. Para sultan Darfur ing abad-abad sabanjuré surat-suratan karo Bab-i Ali; Abdulmajid lan Abdulaziz ngesahaké pamaréntahané.", "58155fc4"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Tashkent pindhah menyang pamaréntahané Yunus Khan, khan Moghulistan", "a37ee010"], "d": ["Nalika ana rebutan dhampar antarané para pangéran Timuriyah, Tashkent sawewengkoné tiba ing tangané Yunus Khan, khan Chagatai Wétan (Moghulistan). Rong taun sabanjuré Yunus Khan séda lan digantèni putrané, Mahmud Khan; kutha iku tetep ing tangané para khan Mughal nganti wong Uzbek pimpinan Syaibani Khan ngrebuté ing taun 1503.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Babur ninggalaké Fergana marang wong Uzbek lan lunga menyang Kabul", "69df593c"], "d": ["Babur saka wangsa Timuriyah, putrané Umar Syekh Mirza, sawisé perang-perang nglawan Muhammad Syaibani Khan, ninggalaké Fergana sing diprentah wiwit 1494 marang wong Uzbek, banjur nyabrang Hindu Kush lan manggon ing Kabul.", "21d1ed8c"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Panyawijiné tlatah sakiwa-tengené Kars: Şüregel, Arpaçay lan Digor mlebu pamaréntahan Utsmaniyah", "10f16b5c"], "d": ["Nalika Ekspedisi Irak Loro, bèntèng Pasin, Şüregel lan Oltu tiba ing tangané wong Utsmaniyah; kamungkinan gedhé Bèntèng Kars uga digandhèngaké ing wektu iku. Tlatah Arpaçay lan Digor ing sisih lor lan wétan Kars mlebu kendhali Utsmaniyah liwat operasi sing padha.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Pungkasané Para Syirwansyah: Elqas Mirza nawan Syahrukh, Syirwan dadi provinsi Safawiyah", "e6d64114"], "d": ["Elqas Mirza, sing dikirim Syah Tahmasb, njarah Syirwan, ngrebut Bèntèng Baykurd, lan nawan Syirwansyah Syahrukh sing umuré limalas taun banjur nggawa dhèwèké menyang Tabriz. Kanthi mangkono pamaréntahan Para Syirwansyah sing suwé nguwasani tlatah iku rampung; Syirwan dadi provinsi Nagara Safawiyah.", "47532c27"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Ilangé Anabolu (Nauplion) menyang Venesia — titik owah-owahan Perang Morea", "9d400557"], "d": ["Miturut artikel TDV babagan Anabolu, nalika pengepungan, warga muslim kutha sing isih urip mlayu menyang pulo-pulo sakiwa-tengené lan Anatolia (1686). Miturut sumber akademik baku (Setton, Venice, Austria, and the Turks in the Seventeenth Century), wadyabala Königsmarck sajroné rong minggu nolak serangané tentara bantuan Utsmaniyah; nalika serbuan İsmail Pasya tanggal 29 Agustus rampung kanthi kekalahan abot, bèntèng nungkul sajroné sawetara dina. Anabolu iku tanah Utsmaniyah sing ditampa liwat prajanjian ing taun 1540; ilangé kutha iki nyepetaké pindhahé semenanjung Morea menyang Venesia.", "592908a0"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Bèntèng Munkács (Mukacheve) nungkul marang Austria sawisé pengepungan telung taun", "ca2efc3d"], "d": ["Bèntèng Munkács, sing dikepung wadyabala kakaisaran ing pungkasan 1685, tahan sajroné telung taun ing sangisoré pimpinan İlona Zrínyi, garwané Thököly İmre; miturut akèh buku rujukan sing wis diterbitaké, bèntèng iku dipasrahaké marang Jenderal Antonio Caraffa tanggal 17 Januari 1688. Iki tibané salah siji bèntèng gedhé pungkasan saka perlawanan pro-Utsmaniyah ing Hungaria ing garis ngarep Utsmaniyah-Habsburg.", "d72ac109"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Semendire (Smederevo) direbut manèh saka tangané Habsburg (makutha Karajan Hungaria) — Perang 1737-39", "63dcf604"], "d": ["Miturut artikel TDV babagan Semendire, bèntèng sing dipasrahaké marang Austria liwat Passarowitz ing taun 1717 iku direbut manèh kanthi majuné Utsmaniyah ing garis ngarep Donau-Sava sajroné Perang Utsmaniyah-Austria sing diwiwiti ing taun 1737; wadyabala Habsburg (makutha Karajan Hungaria) bisa tahan ing tlatah iku nganti Agustus 1738, lan sawisé wektu iku Semendire mlebu manèh ing pamaréntahan Utsmaniyah. Prajanjèn Beograd (1739-09-18), sing ditandhatangani setaun sabanjuré, bakal ngesahaké kauntungan iki — bebarengan karo Beograd lan Serbia sisih lor.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Lembah Morava bali menyang pamaréntahan Utsmaniyah — Jagodina, Kragujevac lan Čačak", "b219d3c9"], "d": ["Kanthi direbuté manèh Semendire ing Agustus 1738, lembah Morava sing ana ing antarané Semendire lan awak utama Utsmaniyah uga bali menyang pamaréntahan Utsmaniyah: Jagodina, Kragujevac lan Čačak wiwit tanggal iki dianggep duwèké Utsmaniyah. Sumber-sumber ora nyebut baliné papan telu iki kanthi tanggal dhéwé; peta nggunakaké dinané Semendire. Prajanjèn Beograd (1739-09-18) ngesahaké kahanan iki.", "4b38fa55"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Sekuthu Pertahanan Utsmaniyah-Rusia — pertahanan bebarengan nglawan Prancis", "c87079d1"], "d": ["Amarga Napoleon ngenggoni Mesir, Selim III lan Tsar Rusia Pavel I mbentuk sekuthu pertahanan wolung taun sing isiné patbelas pasal. Para pihak janji nduwèni kanca lan mungsuh bebarengan, tulung-tinulung lan ora gawé tentrem dhéwé-dhéwé.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Sekuthu Pertahanan Utsmaniyah-Sisilia Loro (Napoli) — perjuangan bebarengan nglawan Prancis", "1d2be816"], "d": ["Ngadhepi pendhudhukan Prancis ing Italia, Malta lan Mesir, Nagara Utsmaniyah lan Karajan Sisilia Loro nganakaké sekuthu pertahanan sangang pasal. Para pihak janji perang bebarengan, ora gawé tentrem dhéwé-dhéwé, lan awèh pitulung dharat lan segara siji lan sijiné.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Républik Pitung Pulo diadegaké — pulo-pulo Ionia ing sangisoré pangayoman Rusia-Utsmaniyah", "08839694"], "d": ["Ing taun 1799 armada gabungan Rusia-Utsmaniyah wis ngusir wong Prancis saka pulo-pulo Ionia (bèntèng Korfu tiba tanggal 5 Maret 1799); liwat kasepakatan rolas pasal tanggal 21 Maret 1800, pulo-pulo iku diadegaké minangka Cezâyir-i Seb'a-i Müctemia Cumhuru (Républik Pitung Pulo), otonom ing urusan njero lan gumantung marang Utsmaniyah ing urusan njaba. Mangsa antarané 1799-03-05 nganti dina iki iku mangsa pendhudhukan bebarengan.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — hak-hak Rusia tumrap Républik Pitung Pulo dipasrahaké marang Prancis", "98a78beb"], "d": ["Liwat kasepakatan antarané Rusia lan Prancis ing Tilsit, Rusia masrahaké hak-haké tumrap Pitung Pulo marang Prancis; pasukan Prancis manggon ing pulo-pulo iku ing mangsa panas 1807 lan Républik Pitung Pulo sirna.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Santa Maura (Ayamavra) lan Pulo-pulo Ionia pindhah menyang pangayoman Inggris — tatanan sawisé Napoleon", "0af821dc"], "d": ["Santa Maura lan pulo-pulo Ionia liyané, sing pindhah menyang Prancis ing taun 1797, sawisé kekalahan pungkasan Napoleon dipasrahaké marang pangayoman Inggris kanthi jeneng 'Nagara Sarékat Pitung Pulo' liwat prajanjian khusus sing ditandhatangani ing Paris tanggal 5 November 1815 antarané Inggris, Rusia, Austria lan Prusia — iki dhokumèn sing béda karo Prajanjèn Paris umum tanggal 20 November 1815. Pangayoman iku bakal lumaku nganti 1864, banjur pulo-pulo iku bakal dipasrahaké marang Yunani.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Panaklukan Prizren — puser sanjak Utsmaniyah ing Kosovo", "f84c220f"], "d": ["Tanggal 4 Rajab 859 (20 Juni 1455) tentara Utsmaniyah sing dipimpin Mehmed Sang Penakluk ngrebut Prizren sawisé perang nglawan despot Serbia Đurađ Branković — ing sumber Utsmaniyah disebut Vılkoğlu. Kutha iku ing tengah abad kaping-13 pindhah saka Bizantium menyang Karajan Serbia, lan nalika jaman Raja Milutin, Tsar Dušan lan Raja Uroš dadi papan dalemé raja; sawisé Dušan séda, wigatiné suda. Sawisé ditaklukaké, kutha iku didadèkaké puseré sawijining sanjak lan nyekel kalungguhan iku suwéné patang abad setengah nganti 1912. Sadurungé Yugoslavia pecah, Prizren iku siji-sijiné kutha ing Balkan sing telung basa — Albania, Turki lan Serbia — dienggo bebarengan.", "82ab4141"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Tentara Mamluk mlebu Malatya — kutha iku pindhah saka pamaréntahan Ilkhaniyah menyang Mamluk", "2540363d"], "d": ["Wong Mamluk ngirim tentara sing dipimpin naib Damaskus, Saifuddin Tengiz, menyang Malatya; tentara iku mlebu kutha tanggal 22 Muharram 715 (28 April 1315). Nganti dina iku Malatya ana ing sangisoré kakuwasan Ilkhaniyah lan dadi titik kunci garis ing sisih kuloné Kali Efrat, papan wilayah pengaruh Ilkhaniyah lan Mamluk gepukan. Pindhah tangané kutha iki nuduhaké majuné wong Mamluk menyang Efrat Ndhuwur sajroné rebutan dawa antarané nagara loro iku. Sawisé tanggal iki Malatya sawetara wektu bakal mlebu pamaréntahan Wangsa Eretna, lan wiwit 1338 bali manèh menyang kakuwasan Mamluk.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Pungkasané Kabèylikan Esref — Beyşehir lan Seydişehir pindhah menyang Wangsa Hamid", "e4e70846"], "d": ["Demirtaş, putrané Emir Chupan, gubernur jenderal Ilkhaniyah ing Anatolia, tumindak nglawan kabèylikan-kabèylikan Turkmen sing ngumumaké kamardikané, mlebu Beyşehir lan ndhawuhi matèni Esrefoğlu Suleyman Syah, sing biyèn naté ngadukaké dhèwèké (9 Oktober 1326). Kanthi mangkono Kabèylikan Esref, sing diadegaké ing pungkasan abad kaping-13 ing tlatah Beyşehir lan Seydişehir, rampung. Artikel TDV babagan Wangsa Hamid nyaritakaké lanjutané: Beyşehir, Seydişehir, Akşehir lan Doğanhisar, duwèké Wangsa Esref sing disingkiraké Demirtaş, digandhèngaké menyang wates kabèylikan Hamid. Ing taun sing padha, Dündar Bey saka Wangsa Hamid uga dipasrahaké marang Demirtaş lan dipatèni. Tanah-tanah iki ing taun 1381 bakal didol marang Murad I kanthi rega 80.000 dhuwit emas lan mlebu pamaréntahan Utsmaniyah.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya mlebu manèh ing kakuwasan Mamluk — pungkasané pamaréntahan Wangsa Eretna", "08b80aa2"], "d": ["Malatya, sing mlebu pamaréntahan Mamluk ing taun 1315, ing taun-taun ajuré Nagara Ilkhaniyah sawetara wektu tiba ing tangané Wangsa Eretna. Artikel TDV babagan Malatya nyaritakaké baliné mung ing saukara: wiwit 1338 wong Mamluk nguwasani manèh kutha iku. Iki irisan saka taun-taun nalika kekosongan sawisé Ilkhaniyah ing Anatolia kidul-wétan dibagi antarané Mamluk lan Eretna.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Pelabuhan Izmir ilang menyang armada Salib — kakuwatan segara Wangsa Aydin remuk", "775c65fe"], "d": ["Armada Salib sing kasusun saka kapal-kapal Venesia, Genoa, Karajan Siprus, para Ksatria Rhodes lan Adipati Naxos, kanthi pangajaké Paus Clement VI, ngrebut Pelabuhan Izmir saka tangané Wangsa Aydin (28 Oktober 1344). Pelabuhan iku ing 1328-1329 direbut saka wong Genoa Martino Zaccaria déning Mehmed Bey, ramané Umur Bey, lan dadi pangkalan kakuwatan segara Aydin ing Aegea. Armada Salib sing teka kanthi tujuan sing padha ing September 1334 kepeksa mundur; ekspedisi kaping pindho iki kasil. Umur Bey nerusaké perlawanan lan, nyawiji karo kabèylikan Turki liyané, ngalahaké armada Salib tanggal 17 Januari 1345, nanging pelabuhan iku ora bisa direbut manèh.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Alaeddin Bey saka Wangsa Karaman nggandhèngaké Konya, Aksaray lan Niğde menyang tanah Karaman", "2b8b0f70"], "d": ["Alaeddin Bey saka Wangsa Karaman, sing péngin njupuk kauntungan saka Kasultanan Mamluk sing mungkasi Karajan Armenia lan nggandhèngaké sakabèhé Cilicia menyang tanahé, sarta saka kerusuhan sing njeblug ing Nagara Eretna ing Anatolia Tengah, nggandhèngaké menyang tanah Karaman utamané Konya (1366-1367), uga Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı lan Kayseri. Amarga bobote minangka kutha krajan Seljuk, Konya kanggo Wangsa Karaman ora mung sawijining kutha nanging pratandha klaim kaabsahan.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan mungkasi Nagara Qara Qoyunlu — cekungan Tlaga Van pindhah menyang Aq Qoyunlu", "d8d6c2e8"], "d": ["Panguwasa Aq Qoyunlu, Uzun Hasan, ing taun 1467 nggerebeg kanthi dadakan mungsuhé sing tanpa welas, panguwasa Qara Qoyunlu Jahan Syah, sing lagi mlaku nyerang dhèwèké, lan mungkasi Nagara Qara Qoyunlu. Kanthi sirnané Jahan Syah, sing mréntah wiwit 1438, cekungan Tlaga Van — Van, Bitlis, Bargiri (Muradiye), Hoşap lan Kotur — pindhah saka pamaréntahan Qara Qoyunlu menyang Aq Qoyunlu. Kamenangan iki ndadèkaké Nagara Aq Qoyunlu siji-sijiné kakuwatan gedhé ing Anatolia Wétan lan Iran, lan nuntun Uzun Hasan menyang dalan sing sagenerasi sabanjuré bakal ngadhepaké dhèwèké karo Utsmaniyah.", "4d0ea428"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Karajan Géorgia pecah dadi telu — Kartli, Kakheti lan Imereti sing puseré ing Kutaisi", "f9c5f798"], "d": ["Karajan Géorgia sing manunggal, sing diprentah wangsa Bagratid, sawisé perang njero sing dawa resmi pecah dadi karajan telu: Kartli sing puseré ing Tiflis ing sisih wétan, Kakheti ing wétan-lor, lan Imereti sing puseré ing Kutaisi ing sisih kulon. Artikel TDV babagan Géorgia negesaké pecahan iku — 'Géorgia pecah dadi karajan telu (Kartli, Kakheti, Imereti) lan kapangéranan lima'. Pecahan iki nemtokaké ing rebutan Utsmaniyah-Safawiyah abad sabanjuré: miturut Prajanjèn Amasya 1555, Imereti, Dadiani, Guria lan Daveli dipasrahaké marang Utsmaniyah; Kartli, Kakheti lan Mosuk marang Safawiyah. Tegesé, anggoné atlas nyambungaké Géorgia kulon lan wétan menyang bendara sing béda iku asalé saka pecahan iki. Yavuz Sultan Selim, nalika isih dadi gubernur Trebizond, ing taun 1508 wis nundhukaké Karajan Imereti (Açıkbaş) supaya manut lan mbayar upeti.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Tripolitania dienggoni wong Spanyol — pungkasané kakuwasan Hafsiyah", "de319d23"], "d": ["Sawisé Bani Ammar, kakuwasan Hafsiyah ing Tripoli lumaku nganti taun 1510. Ing taun iku kutha dienggoni wong Spanyol sing dipimpin Don Pedro Navarro, Count Oliveto; wong muslim sing slamet saka pembantaian ninggalaké kutha. Pendhudhukan iki pucuk wétan saka ranté bèntèng Spanyol ing pesisir Afrika Lor sing mbentang saka Melilla nganti Tripoli. Warga Tripoli ing 925 (1519) bakal ngirim delegasi menyang Istanbul njaluk pitulungan Utsmaniyah nglawan serbuan Spanyol, lan kutha iku ing 1551 bakal direbut Turgut Reis lan Sinan Pasya banjur mlebu pamaréntahan Utsmaniyah.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta lan Tripoli diwènèhaké marang Ksatria Santo Yohanes — pangkalan anyar ordo sing diusir saka Rhodes", "2595729e"], "d": ["Para Ksatria Santo Yohanes (Hospitalier), sing diusir Sultan Suleyman Sang Pembuat Undhang-undhang saka Rhodes ing 928 (1522), sawisé wolung taun tanpa omah, dipapanaké ing Malta déning Charles V, Raja Spanyol lan Jerman; bareng karo paringan iku, pertahanan Tripoli uga dipasrahaké marang ordo. Malta, kanthi pelabuhané sing becik banget, dadi pangkalan sing cocog kanggo para ksatria sing duwé pengaruh ing segara: wiwitané padha manggon ing Birgu, nguwataké Bèntèng Santo Angelo, lan mbangun Bèntèng Santo Michel ing pucuk Senglea. Panggonan iki ngasilaké pangkalan mungsuh sing langgeng ing tengah Segara Tengah sing medhot dalan segara Utsmaniyah; bentrokan, sing diwiwiti kanthi penggrebegané Turgut Reis menyang Gozo ing 947 (1540), bakal terus nganti pengepungan Malta 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Korsika didol Genoa marang Prancis — Prajanjèn Versailles", "770343df"], "d": ["Républik Genoa masrahaké Korsika marang Prancis, pulo sing wis atusan taun dicekel nanging nyatané ora bisa dikendhalèni amarga pambrontakan. Artikel TDV babagan Korsika nyaritakaké prastawa iku mung ing saukara: Genoa, sing ora patiya bisa nguwasani pulo iki, ngedol marang Prancis ing 1768. Pamasrahan iki dadi tandha mundhuré Genoa saka duwèk tanah gedhé pungkasané ing Segara Tengah; pulo iku ing 1796 sawetara wektu bakal pindhah menyang tangané Inggris, banjur dibalèkaké manèh marang Prancis. Dadiné pulo iku tanah Prancis ndadèkaké Napoleon Bonaparte, sing bakal lair ing Ajaccio setaun sabanjuré, dadi kawula Prancis. Ing taun iki (1768) Korsika, kalebu Bastia, didol Genoa marang Prancis (TDV Korsika; dina durung dikonfirmasi).", "c6214397"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Perang Chelenko — pungkasané Kaamiran Harar lan pendhudhukan Abesinia", "5671a0d9"], "d": ["Nalika Dawud dadi imam Aussa, Harar sing ana ing tengah tanah-tanah sing diprentah wong Oromo dadi manèh kaamiran mardika, lan kahanan iku lestari nganti pendhudhukan Abesinia ing 1887. Emir Abdullah, sing ngumumaké jihad, tanggal 7 Januari 1887 karo wong 5.000 ngadhepi wong Abesinia ing Chelenko (Şeleneko); nalika ngerti bakal kalah, dhèwèké mlayu menyang tlatah Ogaden ing Harar kidul. Perang iki nuduhaké ora imbangé tentara Abesinia sing nganggo gaman geni karo wadyabala kaamiran, lan nyirnakaké salah siji kaamiran muslim mardika pungkasan ing sabrangé Segara Abang. Kanthi mangkono Harar, Jijiga lan Dagahbur digandhèngaké menyang Abesinia.", "73175130"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Nyithak akce Utsmaniyah kapisan", "38d2d638"], "d": ["Akce perak kapisan sing dicithak nganggo jenengé Orhan Ghazi minangka pengumuman moneter kedaulatan mardika kadipaten; akce tetep dadi satuan dhuwit pokok sajrone limang abad.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Beylerbeylik Rumelia diadegaké", "ffa16089"], "d": ["Penaklukan ing sisih Éropah diklumpukaké ing sangisoré siji payon militèr-administratif; tatanan beylerbeylik dadi balung geger organisasi provinsi kekaisaran.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Kramané Bayezid Yildirim lan Despina Hatun", "4b10dc6c"], "d": ["Hubungan bawahan sing diadegaké karo Despotat Serbia sawisé Kosovo dicap kanthi kramané Olivera, putriné Lazar, karo Bayezid — conto tipikal diplomasi kraman ing mangsa wiwitan.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Beylerbeylik Anatolia diadegaké", "5ef8d3a7"], "d": ["Beylerbeylik Anatolia ditata kanggo ngurus tanah kadipaten sing digabungaké; tatanan administrasi sing duwé suwiwi loro, Rumelia-Anatolia, rampung.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Mesjid Agung Bursa rampung", "27bcc4a5"], "d": ["Mesjid agung kanthi rong puluh kubah, sing dibangun nganggo jarahan Nikopolis, dadi conto monumental arsitektur Utsmaniyah wiwitan lan museum mbukak seni kaligrafi.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Dipecat lan diukum patiné Çandarlı Halil Pasya", "5e19438f"], "d": ["Sawisé penaklukan, wazir agung saka kulawarga lawas Çandarlı, sing njaga jarak saka pengepungan, diukum pati; kanggo kaping pisan wazir agung dipatèni miturut dhawuh sultan, lan jaman wazir asal devşirme kabukak.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Moldavia dadi pambayar upeti", "25bd3693"], "d": ["Voivodat Moldavia sarujuk mbayar upeti; bebarengan karo Wallachia lan Transylvania, sabuk bawahan telu ing lor Donau dadi panyangga lor kekaisaran. Panggonan liya sing digabungake ing tanggal sing padha: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Upeti Dubrovnik (Ragusa)", "d127c78a"], "d": ["Republik sudagar Ragusa njamin otonomi lan hak dagangé kanthi mbayar upeti; dadi sugih minangka jendhéla Utsmaniyah ing Adriatik. Pulo Mljet (Mliyet), tanahé republik iku, uga mèlu status iki.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Ekspedisi Wallachia: Vlad sang Panyunduk", "fd4530bb"], "d": ["Liwat ekspedisi nglawan Vlad Țepeș, sing nolak mbayar upeti lan matèni utusan, Wallachia dibalèkaké dadi bawahan; serangan wengi lan adegan medèni wong sing disunduk dadi legendha ing Éropah. Panggonan liya sing digabungake ing tanggal sing padha: Bukares.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Komplèks Fatih dibukak", "a150ea55"], "d": ["Komplèks iku, karo wolung madrasahé (Sahn-i Seman), minangka langkah gedhé kapisan program ngowahi Istanbul dadi pusat ilmu donya Islam.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu ing Istanbul", "8508229d"], "d": ["Ali Kuşçu, wakil gedhé pungkasan observatorium Samarkand, amarga diundang Sang Penakluk dadi profesor (müderris) ing Madrasah Hagia Sophia; panjenengané ngadegaké tradhisi matematika-astronomi ing Istanbul.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kitab Undhang-undhang Sang Penakluk", "b08944c9"], "d": ["Kitab undhang-undhang adat jangkep kapisan sing nglumpukaké organisasi nagara, protokol lan paukuman; wis suwé dadi pasulayan amarga pasalé sing misuwur sing ngidinaké matèni sedulur 'kanggo tatanan donya' (nizam-i alem).", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Dhuwit emas Utsmaniyah kapisan (sultani) dicithak", "2fd5c0dd"], "d": ["Dhuwit emas Utsmaniyah kapisan, sing padha ajiné karo dukat Venesia, dicithak; keuangan kekaisaran mlebu tatanan dhuwit internasional.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Pindhah menyang Kraton Topkapı", "b9cd6a5e"], "d": ["Kanthi rampungé Kraton Anyar (Topkapı), pusat pamaréntahan nagara dipindhah mrana; kraton iku tetep dadi uteké kekaisaran sajrone patang abad.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Republik Firenze dadi kadipaten — Alessandro de' Medici", "c08764e1"], "d": ["Amarga tekanan Paus Clemens VII, komisi pamaréntah Firenze (Balìa) nampa konstitusi anyar; rezim republik sing umuré limang abad dibusak lan Alessandro de' Medici diproklamasikaké adipati turun-temurun, lan ing 1 Mei sejatiné munggah kakuwasaan. Kanthi mangkono Firenze malih saka republik kutha mardika dadi kadipaten turun-temurun wangsa Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Nikahé Sang Pembuat Undhang-undhang lan Sultanah Hürrem", "abc05f26"], "d": ["Nikah resmi Sang Pembuat Undhang-undhang karo Hürrem ngowahi tradhisi kraton nganti oyodé; lair lembaga 'Haseki Sultan' lan kabukak lawang jaman para wanita ing politik wangsa.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Kapitulasi jangkep kapisan kanggo Prancis", "e2264e48"], "d": ["Minangka péranganing persekutuan karo Prancis nglawan kepungan Habsburg, hak istiméwa dagang ditandhatangani antarané Jean de la Forest lan Makbul Ibrahim Pasya; kapitulasi sing ing dina iku dadi alat diplomasi, sajrone pirang-pirang abad bakal dadi lawang ketergantungan keuangan.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Ekspedisi Samudra Hindia: pengepungan Diu", "fcd1217a"], "d": ["Armada sing budhal saka Suez nyabrang Segara Abang lan ngepung Diu ing Gujarat; senajan bèntèng ora bisa direbut, kakuwatan Utsmaniyah kanggo kaping pisan tekan Samudra Hindia lan monopoli Portugis goyah.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Lelungané Seydi Ali Reis menyang Hindhia", "e5da3b2c"], "d": ["Seydi Ali Reis, sing ditugasi nggawa armada ing Basra menyang Mesir, kabuncang prahara nganti tekan Hindhia; Mir'atü'l-memalik, sing nyritakaké lelampahan baliné, klebu salah siji buku lelungan Utsmaniyah kapisan.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Piri Reis diukum pati", "63026444"], "d": ["Pelaut lan tukang gawé peta gedhé iku, sing bali saka ekspedisi Hormuz kanthi ninggalaké armada ing Basra, diukum pati nalika umuré 84 taun — salah siji keputusan paling kontroversial ing sejarah ilmu kita.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Komplèks Süleymaniye dibukak", "1c6458b2"], "d": ["Komplèks sing disebut arsitèk Sinan 'karya tukang madyaku'; karo madrasah, griya sakit (dârüşşifâ) lan perpustakaané, dadi komplèks pendhidhikan lan amal paling gedhé ing mangsa klasik.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Pengepungan Malta", "f57f6a85"], "d": ["Malta, kunci Segara Tengah, dikepung patang sasi; Turgut Reis gugur syahid lan pengepungan dicabut. Iki dadi kemunduran gedhé kapisan pelayaran ing jaman Sang Pembuat Undhang-undhang.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Mesjid Selimiye rampung", "3b0484e1"], "d": ["Selimiye, sing disebut Sinan 'karya masteré' lan siji kubah nguwasani ruangé, dianggep pucuk arsitektur klasik Utsmaniyah (Warisan Donya UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Observatorium Istanbul diadegaké", "169bdf5d"], "d": ["Observatorium Takiyyüddin, salah siji observatorium paling jangkep piranti ing jamané, dirubuhaké ing 1580 amarga pasulayan sing muncul sawisé komèt 1577; astronomi lembaga kasèp telung abad.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Kamenangan Çıldır — perang wétan diwiwiti", "13125a54"], "d": ["Kanthi kalahé wadyabala Safawiyah ing Çıldır, gapura Kaukasus kabukak; Tbilisi direbut lan Georgia mlebu ing kakuwasaan Utsmaniyah.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Perang Obor — Shirvan mesthi dadi duwèké Utsmaniyah", "3bbc23bc"], "d": ["Ing perang sing dijenengi mangkono amarga lumaku nganti bengi ing sangisoré pepadhang obor, wong Safawiyah dikalahaké kanthi mesthi; kakuwasaan Utsmaniyah ing Shirvan lan Baku dikukuhaké.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Pangurangan gedhé aji dhuwit — krisis akce", "9205c3d4"], "d": ["Amarga tekanan perang dawa lan perak Amerika, isi peraké akce dikurangi dadi separo; revolusi rega nyuburaké bubrahé tatanan sipahi lan kekisruhan Celali.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Penaklukan Tabriz", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Pasya mlebu Tabriz; ibu kutha lawas Safawiyah dijupuk ing pamaréntahan Utsmaniyah. Osman Pasya séda ing pakemahan sawetara minggu sabanjuré.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Prajanjèn Ferhad Pasya — tapel wates paling amba ing wétan", "c429972f"], "d": ["Sawisé utusané Syah Abbas, Haydar Mirza, teka ing Istanbul (18 Januari 1590), liwat prajanjèn sing digawé kanthi syarat panggonan sing ditaklukaké tetep dadi duwèké Utsmaniyah lan mungkasi perang 12 taun, Tabriz, Karabakh, Shirvan, Georgia lan Luristan tetep ing Utsmaniyah; kekaisaran tekan tapel wates paling amba ing sejarahé ing sisih wétan.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Perang Utsmaniyah-Safawiyah (1603-1612) diwiwiti — serangan walesan Syah Abbas, Tabriz ucul", "abf27dd8"], "d": ["Syah Abbas, sing wis nata manèh wadyabalané, kanthi nggunakaké kekisruhan Celali miwiti serangan; Tabriz tiba, lan asil sing diolèhaké ing Kaukasus ucul sajrone sawetara taun. Pamukiman liya sing ucul ing ekspedisi sing padha lan sawisé: Nakhchivan, Khoy, Marand, Salmas; para bey Karadagh (Ahar) lan Mukri uga pindhah menyang pihak Safawiyah.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Evliya Celebi lair", "2b6051ff"], "d": ["Evliya Celebi, sing nglumpukaké lelungané luwih saka sèket taun ing Seyahatname sepuluh jilid, ninggalaké gambaran donya Utsmaniyah abad ka-17 sing ora ana tandhingané.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Prajanjèn Nasuh Pasya", "bb69e388"], "d": ["Liwat prajanjèn sing mungkasi perang sing lumaku wiwit 1603, asil 1590 ditinggalaké lan tapel wates bali menyang tapel wates Amasya 1555; imbangan ing front wétan diadegaké manèh.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Mesjid Sultan Ahmed dibukak", "e39dfd43"], "d": ["Karo enem menara lan tegel Iznik birué, 'Mesjid Biru' dadi komplèks gedhé sultan pungkasan ing mangsa klasik.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Sultan Ibrahim dipatèni", "bc4eb452"], "d": ["Kanthi alesan boros lan krisis pamaréntahan, persekutuan korps lan ulama nglèngsèraké Ibrahim; sepuluh dina sabanjuré panjenengané dijiret miturut fatwa. Mehmed IV sing umuré pitung taun munggah tahta; kakuwasaan sejatiné pindhah menyang tangané Valide Agung Sultanah Kösem.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Sédané Katib Celebi", "e167e89d"], "d": ["Jeneng paling dhuwur ing sejarah ilmu Utsmaniyah amarga bibliografi Keşfü'z-zunun lan geografi Cihannüma; misuwur amarga pendekatan pelopor sing nggunakaké sumber-sumber Éropah.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Kedadéan Edirne — dilèngsèraké Mustafa II", "0291c1cd"], "d": ["Nesu amarga sultan manggon ing Edirne lan amarga pengaruhé Feyzullah Efendi dadi pambrontakan gedhé prajurit lan tukang dagang; syaikhul Islam dikroyok nganti mati, sultan dilèngsèraké lan kraton bali menyang Istanbul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Duta gedhé menyang Paris: Yirmisekiz Mehmed Celebi", "26312a3f"], "d": ["Kedutaan gedhé sing dikirim menyang Prancis dadi pengamatan sistematis kapisan marang Kulon ing panggonané; Sefaretname-né menehi inspirasi pambaharuan Jaman Tulip.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Percétakan Utsmaniyah kapisan diadegaké", "4943f7e5"], "d": ["Idin nyithak buku basa Turki diwènèhaké; karya kapisan, Bausastra Vankulu, dicithak ing 1729. Percétakan iku warisan pambaharuan Jaman Tulip sing paling langgeng.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitulasi didadèkaké langgeng", "d044a79e"], "d": ["Hak istiméwa sing diwènèhaké marang Prancis ora manèh diwatesi mangsa sultan lan digandhèngaké karo prajanjèn sing tetep; rezim kapitulasi sing ora bisa dibatalaké sapihak lagi bisa dibusak ing Lausanne.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Sekolah Teknik Angkatan Laut Kekaisaran (Mühendishâne-i Bahrî-i Hümâyun) diadegaké", "9bf3f439"], "d": ["Sekolah teknik sing diadegaké sawisé bilai Çeşme kanggo ndhidhik perwira laut modhèrn iku lembaga tetep kapisan pendhidhikan teknik gaya Kulon; sekolah teknik dharat nyusul ing 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Kedutaan tetep kapisan ing London", "6b5630eb"], "d": ["Minangka péranganing program Nizam-i Cedid, kedutaan tetep dibukak ing ibu kutha-ibu kutha Éropah; diplomasi Utsmaniyah pindhah menyang dhasar timbal-walik.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Sédané Alemdar Mustafa Pasya", "4426534e"], "d": ["Ing pambrontakan yenisari sing diwiwiti ing wengi 15 November 1808, wazir agung reformis sing dikepung ing Bab-i Ali, amarga pitulungan sing diarep-arep ora teka, ing dina candhaké ngobong gudhang gegaman lan séda bebarengan karo atusan panyerang; tatanan Sened-i Ittifak lan upaya reformasi kapisan dikubur bebarengan karo panjenengané.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Koran resmi kapisan: Takvim-i Vekayi", "c637f623"], "d": ["Koran resmi nagara wiwit diterbitaké; iki wiwitan tradhisi panemuné masarakat modhèrn lan pengumuman resmi.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Prajanjèn Dagang Balta Limanı", "e790b383"], "d": ["Inggris diwènèhi kalungguhan paling istiméwa malah ing dagang njero nagara, lan sistem yed-i vahit (monopoli) dibusak; produksi dhaérah ditinggal tanpa pangayoman, lan prajanjèn iku dadi dokumèn bukaé pasar Utsmaniyah kanthi kebak marang dagang bébas.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Pungkasané Emirat Libanon — Bashir Shihab III dipecat", "f85ae454"], "d": ["Emir Bashir II (III), sing ora bisa ngontrol pasulayan Kristen-Druze lan imbangan njero ing tlatah Shuf, dipecat ing Januari 1842; tatanan emirat lokal sing lumaku wiwit 1516 (liwat wangsa Ma'an banjur Shihab) rampung, lan tlatah iku pindhah menyang pamaréntahan Utsmaniyah langsung, banjur menyang sistem kaymakam rangkep.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashih-i sikke: tatanan Mecidiye", "c77be809"], "d": ["Liwat reformasi dhuwit, dhuwit logam sing wis rusak kadharé diklumpukaké; tatanan bimetal sing stabil adhedhasar lira emas (Mecidiye) diadegaké.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Pungkasané kakuwasaan lokal kulawarga Harfush ing Baalbek", "8438f4ae"], "d": ["Pengaruh kulawarga Harfush, sing wiwit 1521 (sawisé pambrontakan Janbirdi al-Ghazali) mréntah Baalbek minangka wangsa lokal cilik, rampung amarga tatanan administrasi anyar Bab-i Ali; kutha iku didadèkaké pusat kaza (distrik) lumrah ing ngisor Vilayet Damaskus.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Şirket-i Hayriyye diadegaké", "462830e7"], "d": ["Perusahaan sing diadegaké kanggo nglakokaké kapal uap ing Bosporus dianggep perséroan terbatas Utsmaniyah kapisan; dermaga kapal uap menehi tandha ing uripé kutha.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Kontrak utang manca kapisan", "9017c579"], "d": ["Utang manca kapisan dijupuk saka pasar London kanggo mbandhani Perang Krimea; pungkasané sawisé 15 utang sajrone 21 taun yaiku moratorium 1875 lan Duyun-i Umumiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Garis telegraf ing Istanbul", "d320f39f"], "d": ["Garis telegraf kapisan sing diadegaké amarga kabutuhan Perang Krimea dibukak kanggo layanan; sajrone sawetara dasawarsa kekaisaran nduwé salah siji jaringan telegraf paling amba ing donya.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Undhang-undhang Tanah", "6bae243a"], "d": ["Undhang-undhang sing ngmodhèrnaké kukum tanah iku nggandhèngaké panguwasaan nyata tanah nagara (miri) karo sertifikat (tapu); iki salah siji dokumèn dhasar tatanan hak milik Timur Tengah saiki.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Kuliah kapisan ing Darülfünun", "08f74066"], "d": ["Darülfünun, sing bakal menehi pendhidhikan tingkat universitas, wiwit makarya kanthi kuliah umum; lembaga sing lumaku karo pedhot-pedhot iku dibukak tetep ing 1900 lan dadi inti Universitas Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Peraturan Vilayet", "ad20853b"], "d": ["Gantiné tatanan eyalet, diadegaké organisasi vilayet modèl Prancis; kanthi njupuk conto pratikélé Midhat Pasya ing Vilayet Donau, disebaraké ing kabeh nagara.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Lelungané Abdülaziz menyang Éropah", "9ff0fa1e"], "d": ["Lelungan kapisan sultan Utsmaniyah menyang Éropah kanthi tujuan tentrem; paméran Paris lan lawatan London dadi etalase diplomasi lan uga modhernisasi.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Lyceum Kekaisaran Galatasaray (Mekteb-i Sultani) dibukak", "f9688524"], "d": ["Lyceum sing mulang nganggo basa Prancis iku, karo susunan murid sing ora mbédakaké agama lan millet, dadi lambang idéal Tanzimat bab padha drajat ing pendhidhikan.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Kitab kapisan Mecelle lumaku", "6475461c"], "d": ["Mecelle, sing nglumpukaké bidang utang-piutang lan barang ing kukum Islam nganggo teknik undhang-undhang modhèrn, dianggep kitab kukum sipil Islam kapisan; panitia sing dipimpin Cevdet Pasya ngrampungaké 16 kitab ing 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Dilèngsèraké Abdülaziz", "eb7397ea"], "d": ["Para negarawan konstitusional lan pimpinan militèr nglèngsèraké Abdülaziz liwat kudéta meneng; sédané sing nyujanani limang dina sabanjuré, lan kedadéan Çırağan sing nyusul, nglairaké etung-etungan sing lumaku pirang-pirang taun.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Serangan Çırağan (prakara Ali Suavi)", "d2a9ac87"], "d": ["Wartawan Ali Suavi nyerang Çırağan arep ngunggahaké manèh Murad V ing tahta; serangan dipadhemaké kanthi getih, lan rezim Abdülhamid ngencengaké bunderan keamanan sacara tetep.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Administrasi Régie diadegaké (monopoli mbako)", "bad9b030"], "d": ["Pamasukan mbako dialihaké marang perusahaan Régie sing modalé saka manca, ing ngisor Duyun-i Umumiyye; bentrokan 'penyelundupan Régie' antarané wong tani lan para penjaga lumaku pirang-pirang dasawarsa. Pamukiman liya sing ucul ing tanggal sing padha: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Lawatan Kaisar Wilhelm II menyang Istanbul lan Yerusalem", "2988cd06"], "d": ["Lawatan kapindho kaisar Jerman nguwataké sesambungan raket Utsmaniyah-Jerman; dalan konsèsi sepur Baghdad kabukak, lan ing Damaskus diucapaké pidhato 'kanca telung atus yuta wong Muslim'.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Sepur Hijaz tekan Madinah", "95009b9c"], "d": ["Garis 1464 km sing dibangun mung nganggo sumbangan wong Muslim lan teknik jero nagara tekan Madinah; lelungan kaji saka pirang-pirang minggu dadi pirang-pirang dina. Iki karya infrastruktur paling gedhé ing jaman Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Kedadéan 31 Maret", "1d7c2bb2"], "d": ["Pambrontakan gedhé anti-konstitusi nguwasani Istanbul; Wadyabala Gerakan sing teka saka Thessaloniki madhemaké pambrontakan lan Abdülhamid II dilèngsèraké.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Pengepungan Edirne diwiwiti", "234d9b28"], "d": ["Pertahanan limang sasi Şükrü Pasya dadi crita kepahlawanan perlawanan ing tengah bilai Balkan; kutha tiba amarga keluwèn, lan direbut manèh ing Juli 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Serangan Bab-i Ali", "b304d02d"], "d": ["Pamaréntah sing nyiapaké nyerahaké Edirne dirubuhaké liwat serangan bersenjata wong Ittihad; Menteri Perang Nazım Pasya dipatèni. Mangsa kakuwasaan kebak Komite Persatuan lan Kemajuan diwiwiti.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Mutasarrifat Gunung Libanon dibusak", "b5639051"], "d": ["Tatanan mutasarrifat otonom, sing diadegaké liwat Règlement Organique 1861 lan adhedhasar protokol internasional sing dianyaraké ing 1864, dibatalaké sapihak déning Nagara Utsmaniyah nalika Perang Donya I; Kementerian Urusan Njero wiwit ngangkat mutasarrif Muslim langsung menyang tlatah iku. Kanthi mangkono mangsa otonomi, nalika wolung mutasarrif makarya antarané 1861-1915, ditutup.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Nagara dipérang antarané para pangéran", "82f26bfb"], "d": ["Sawisé bilai Ankara, Suleyman Celebi nyabrang menyang Rumelia lan ngumumaké kasultanané ing Edirne; Isa Celebi nyekel Bursa, déné Mehmed Celebi nyekel tlatah Amasya-Tokat-Sivas. Ing peta bagéan telu iki dituduhaké nganggo warna sing béda.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Prajanjèn Gallipoli: pesisir Segara Ireng nganti Mesembria dipasrahaké marang Bizantium", "a4164eca"], "d": ["Amir Suleyman, sing sawisé bilai Ankara péngin tahan ing Rumelia, nandhatangani prajanjèn karo Kaisar Bizantium Manuel ing Gallipoli. Panjenengané masrahaké marang Bizantium Kartal, Pendik lan Gebze sarta sawetara pulo, Thessaloniki lan Tesalia ing Rumelia, lan jalur pesisir Segara Ireng sing tekan Mesembria; pajeg sing dibayar Bizantium marang Utsmaniyah uga dibusak. Kanthi mangkono Agathopolis, İğneada lan Rezve ing pesisir Istranca tetep ing pamaréntahan Bizantium suwéné selikur taun; Murad II ngrebut manèh akèh-akèhé panggonan iki liwat tentrem 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Sédané Bayezid Yildirim ing tawanan", "7e968d83"], "d": ["Sultan, sing ditawan Timur, séda ing Akşehir; layoné digawa menyang Bursa lan disarèkaké ing kono. Sédané ndadèkaké rebutan tahta antarané para pangéran ora bisa dibalèkaké manèh.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Prajanjèn Gallipoli — konsèsi marang Bizantium", "dfacbd00"], "d": ["Suleyman Celebi, sing péngin njamin kalungguhané ing Rumelia, kanthi sarujuk karo Bizantium lan nagara-nagara Latin mbalèkaké Thessaloniki, pesisir Marmara lan sawetara pulo; malah sarujuk mbayar upeti.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Paprangan Ulubat — kekalahan Isa Celebi", "500c5d24"], "d": ["Isa Celebi, sing nyekel Bursa, kalah ing Ulubat nglawan sedulure, Mehmed; upayané pulih sawetara kaping uga ora ana asilé.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Ilangé Isa Celebi", "0effa11e"], "d": ["Isa Celebi, sing kanthi dhukungan Suleyman Celebi bali menyang Anatolia sawetara kaping, ilang sawisé kekalahané sing pungkasan; bagéané pindhah menyang Mehmed Celebi, lan ing peta wilayahé Mehmed mekar ngulon.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Celebi nyabrang menyang Wallachia", "8441267a"], "d": ["Mehmed Celebi, sing kelangan Bursa lan Ankara menyang Suleyman Celebi lan mundur menyang Tokat-Amasya, nyurung sedulure, Musa, supaya lunga menyang Rumelia. Musa, sing nampa undangané voivoda Wallachia Mircea, tekan Wallachia liwat segara; saka kono panjenengané bakal mlebu ing perjuangan sing ndadèkaké Suleyman ana ing antarané rong front.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Mehmed Celebi ngrebut manèh Bursa lan Ankara — bagéan Anatolia ucul saka Suleyman Celebi", "bfb69f12"], "d": ["Amarga suksèsé Musa Celebi ing Rumelia (Yambol, 13 Februari 1410), Amir Suleyman Celebi, sing ana ing Anatolia, nyabrang menyang Rumelia. Sawisé Suleyman ninggalaké Anatolia, Mehmed Celebi ngrebut manèh tlatah Bursa, kalebu Ankara, lan minangka tandha wis munggah tahta ndhawuhaké nyithak dhuwit mawa taun 813. Ing peta, sisih Anatolia Marmara pindhah saka bagéan Amir Suleyman dadi warnané Mehmed Celebi.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Perang Kosmidion", "0efc2caa"], "d": ["Ing perang sing kedadéan ing ngarep témbok Istanbul kanthi dhukungan Bizantium, Suleyman Celebi ngalahaké sedulure, Musa; nanging dhukungané ing Rumelia wis wiwit cepet leleh. Pamukiman liya sing ucul ing tanggal sing padha: Elassona, Aytos, Bolayır (panggonan ing Rumelia sing ing peta pindhah saka Musa menyang Suleyman).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Pengepungan Istanbul déning Musa Celebi", "4932f586"], "d": ["Musa Celebi, sing péngin ngukum Bizantium amarga nyengkuyung Suleyman, ngepung Istanbul; pengepungan iki nyurung Bizantium sekutu karo Mehmed Celebi.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Sédané Amir Suleyman — Musa nguwasani Rumelia", "325c1549"], "d": ["Suleyman Celebi, sing kacekel nalika mlayu saka Edirne, dipatèni; kabeh Rumelia pindhah menyang tangané Musa Celebi. Ing peta Rumelia malih saka warna biru dadi wungu.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Perang Çamurlu — manunggalé diadegaké manèh", "0b23173e"], "d": ["Mehmed Celebi, sing oleh dhukungan Bizantium, Despotat Serbia lan para bey tapel wates Rumelia, ngalahaké sedulure, Musa, kanthi mesthi ing Çamurlu; Musa dipatèni nalika mlayu. Rumelia, sing dicekel Musa, pindhah menyang Mehmed bebarengan karo Edirne, lan Mehmed Celebi ngumumaké awaké ing Edirne dadi siji-sijiné panguwasa Nagara Utsmaniyah. Mangsa Interregnum sewelas taun rampung, lan bagéan para pangéran ing peta manunggal dadi siji awak.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Keputusan ekspedisi Wina — tentrem Vasvár ora dianyaraké, sasaran dialihaké saka Győr menyang Wina", "1bf278f2"], "d": ["Kaisar Leopold I péngin Prajanjèn Vasvár, sing wektuné durung entèk, dianyaraké, lan Mehmed IV uga katoné milih tentrem. Nanging Wazir Agung Merzifonlu Kara Mustafa Pasya, kanthi alesan pangaduané Imre Thököly, sing wis didadèkaké raja Hungaria Tengah miturut karsané, ora nganyaraké tentrem; kanthi ngobahaké para pendakwah, utamané Vani Mehmed Efendi, panjenengané ngyakinaké sultan supaya perang. Ing musyawarah diputusaké yen sultan tetep ing Beograd lan serdar-i ekrem (panglima tertinggi) maju kanggo ngrebut Győr; nanging ing musyawarah ing Székesfehérvár, senajan khan Krimea Murad Giray lan gubernur Buda Uzun Ibrahim Pasya ora sarujuk, sasaran diowahi dadi ngepung Wina.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Pengepungan Wina II diwiwiti — wadyabala ing ngarep Wina", "bb542e49"], "d": ["Wadyabala Utsmaniyah sing dipimpin Wazir Agung Kara Mustafa Pasya tekan ngarep Wina ing 14 Juli 1683. Kaisar Leopold I ninggalaké tanggung jawab njaga kutha marang Starhemberg lan mundur menyang pedalaman Austria. Pengepungan kapindho iki, sing béda karo sing kapisan, disiapaké kanthi Wina langsung dadi sasaran, bakal lumaku nganti 12 September.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Bubrah Párkány lan kelangan Esztergom", "a7366740"], "d": ["Wadyabala sing mundur saka Wina bubrah kaping pindho ing Párkány; sabanjuré Esztergom, salah siji bèntèng kunci Hungaria, tiba. Mundur iku wiwit dadi ambruk.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Merzifonlu Kara Mustafa Pasya diukum pati", "ce8b10ac"], "d": ["Wazir agung, sing dianggep tanggung jawab marang bilai Wina, dijiret nganti mati ing Beograd; nanging paukuman patiné ora mbeneraké front lan ora mbalèkaké kawibawan nagara sing goyah.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Liga Suci diadegaké", "060280d0"], "d": ["Dipimpin kapausan, Liga Suci (Mukaddes İttifak) nglawan Utsmaniyah diadegaké antarané Austria, Polandia lan Venesia; ing 1686 Rusia uga gabung. Kanthi mangkono kekaisaran mlebu perang akèh front sing bakal lumaku nem belas taun.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Pertahanan Buda kapisan", "ccc43630"], "d": ["Pengepungan Buda kapisan déning wadyabala Liga Suci dipukul mundur déning pertahanan bèntèng sing ngotot suwéné patang sasi; nanging bèntèng-bèntèng ing Hungaria isih terus tiba siji mbaka siji.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Kelangan Uyvar", "689ab78c"], "d": ["Bèntèng Uyvar (Nové Zámky), sing rong puluh loro taun ana ing tangané Utsmaniyah lan wis dadi paribasan ing Éropah, tiba; anané Utsmaniyah ing Hungaria Ndhuwur bubrah.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Thököly dicekel ing Várad — Krajan Hungaria Tengah bubar, bèntèng-bèntèng Hungaria Ndhuwur nyerah", "1741aaaf"], "d": ["Sawisé bilai Wina, Utsmaniyah wiwit nganggep Thököly uga klebu sing njalari perang lan kekalahan. Ing 15 Oktober 1685, miturut dhawuh Serdar Melek Ibrahim Pasya, Ahmed Pasya, beylerbey Várad, ndhawuhaké nyekel Thököly sing teka arep nulungi; diarep-arep kanthi masrahaké marang Habsburg bisa oleh syarat tentrem sing luwih apik. Nalika kabar penangkepan sumebar, kabeh bèntèng lan kutha Krajan Hungaria Tengah, kejaba Munkács sing dibéla garwané, Ilona Zrínyi, nyerah marang Habsburg; akèh-akèhé prajurit Kuruc pindhah menyang wadyabala Habsburg. Nalika Thököly dibébasaké ing Beograd ing 2 Januari 1686, krajan iku wis ora ana manèh.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Kelangan Buda — ibu kutha Hungaria 145 taun", "70800e2b"], "d": ["Ing pungkasané pengepungan sing lumaku pitung puluh wolu dina, Buda tiba; beylerbey pungkasan, Abdurrahman Abdi Pasya, gugur syahid ing ndhuwur témbok. Kelangan kutha, sing wiwit 1541 ana ing pamaréntahan Utsmaniyah, dianggep lambang uculé Hungaria. Pamukiman liya sing ucul ing tanggal sing padha: Pest.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Bilai Mohács Kapindho (Harsány) — kelangan Transylvania lan Mohács", "a7922681"], "d": ["Ing dhataran panggonan kamenangan gedhé dimenangaké ing 1526, saiki diolèhi kekalahan abot; wadyabala bubar, lan prajurit sing mbrontak meksa wazir agung dipecat. Kekalahan iku uga njalari Transylvania ucul.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Kelangan Athena lan mbledhosé Parthenon", "b6691730"], "d": ["Bom sing ditembakaké mriyem Venesia mbledhosaké Parthenon, sing digunakaké Utsmaniyah dadi gudhang mesiu; candhi sing umuré rong èwu taun dadi reruntuhan. Kutha iku tiba ing tangané Venesia (bakal direbut manèh ing 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Dilèngsèraké Mehmed IV lan munggah tahtané Suleyman II", "9f53037c"], "d": ["Amarga bilai ing front lan pambrontakan wadyabala, sawisé mréntah 39 taun Mehmed IV dilèngsèraké; gantiné, sedulure, Suleyman II, sing patang puluh taun disimpen ing kandhang (kafes), diunggahaké.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Beograd ucul kanggo kaping pisan — pengepungan Liga Suci", "c6b9b19a"], "d": ["Beograd, sing wiwit 1521 ana ing tangané Utsmaniyah, nyerah marang wadyabala Liga Suci; lawang Serbia kabukak kanggo mungsuh lan bebaya tekan jalur Niš-Sofia. Pamukiman liya sing ing atlas ing dina sing padha pindhah saka Utsmaniyah menyang Habsburg: Hisarcık (Grocka) — nuruti ranté pusat-induk Beograd (TDV belgrad; perkiraan sing wis diumumaké).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden nyabrang Morava ing Pasarofça — Pasarofça tiba menyang Austria", "bcf3fc59"], "d": ["Margrave Ludwig von Baden ing Agustus 1689 nyabrang Morava ing Pasarofça lan maju tumuju Niš; kutha iku tetep ing tangané Austria nganti musim panas 1690 (TDV suleyman-ii nyebut yen Pasarofça direbut manèh ing 1690). Dinané lan wacan Röder durung diverifikasi manèh.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Kelangan Niš — majuné Habsburg (mahkota Krajan Hungaria), taun paling genting", "c5e27b3f"], "d": ["Majuné Habsburg (mahkota Krajan Hungaria) uga ngrebut Niš saka pamaréntahan Utsmaniyah; serangan-serangan tekan Skopje lan Pristina. Déné Vidin lagi tiba sabanjuré, ing Oktober 1689 (artikel kapisah). Ing taun paling peteng perang iki, nagara rumangsa malah ibu kuthané kaancam.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova lan Fethülislâm dilebokaké garnisun Austria", "ee8dd875"], "d": ["Sawisé Vidin direbut tanpa perang (Oktober 1689, TDV vidin), ing 25 Oktober 1689 Baden ndandani lan menehi garnisun Orsova lan Fethülislâm; Orsova tetep duwèké Austria nganti musim gugur 1690. Dinané adhedhasar Bánlaky/Röder lan durung diverifikasi manèh.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš manèh dadi duwèké Utsmaniyah", "0c4f44eb"], "d": ["Fazil Mustafa Pasya budhal ekspedisi ing Juli 1690; sawisé Şehirköy (Pirot), Pasarofça lan Güvercinlik direbut, Niš sing dikepung tiba ing tangané Utsmaniyah ing 27 September 1690 (TDV semendire). Ing wektu sing padha Vidin uga wis direbut manèh. Pamukiman liya sing ing atlas ing tanggal sing padha bali saka Habsburg menyang Utsmaniyah: Yagodina (Jagodina) lan Ürküp (Prokuplje) — amarga dina ing tingkat panggonan ora ketemu, dijupuk dina Niš (TDV semendire; perkiraan sing wis diumumaké; Röder 1842 nulis yen wazir ngliwati Yagodina ing 8-24 September, pasulayan iki durung dirampungaké).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Pasukan Austria nyerah ing Smederevo", "90da20c4"], "d": ["Sawisé Niš direbut ing 27 September 1690, pasukan Austria ing Smederevo nyerah sawisé pengepungan patang dina (TDV semendire). Bánlaky/Röder nyebut 24 September; sumber-sumber pasulayan, TDV didadèkaké dhasar.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Beograd direbut manèh", "ab435838"], "d": ["Wazir Agung Köprülüzade Fazil Mustafa Pasya ing 8 Oktober 1690 ngrebut manèh Beograd saka Austria; kutha sing ucul ing 1688 kanthi mangkono bali menyang Utsmaniyah (TDV suleyman-ii). Pamukiman liya sing ing atlas ing tanggal sing padha bali saka Habsburg menyang Utsmaniyah: Hisarcık (Grocka) — nuruti ranté pusat-induk Beograd (TDV suleyman-ii; perkiraan sing wis diumumaké).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Bubrah Slankamen — Fazil Mustafa Pasya gugur syahid", "10d626f1"], "d": ["Ing salah siji perang papan jembar paling getih ing abad iku, wazir agung gugur syahid amarga ditembak ing bathuk; wadyabala bubar. Pangarep-arep pulih mati bebarengan karo perang iki.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Kelangan pulo Khios", "07c084f8"], "d": ["Armada Venesia ndhudhuki Khios; kakuwasaan Utsmaniyah ing Segara Aegea kaancam. Pulo iku bakal direbut manèh taun candhaké.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Keputusané Mustafa II budhal ekspedisi dhéwé", "61c3ba9c"], "d": ["Sultan anyar, nurut dalané para leluhuré, ngumumaké bakal budhal ekspedisi mimpin wadyabala; keputusan iki ngangkat semangat wadyabala lan miwiti mangsa ekspedisi pribadi sing lumaku rong taun.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Khios direbut manèh", "6b496fca"], "d": ["Mezzomorto Hüseyin Pasya, sing ngalahaké armada Venesia ing perang laut Kapuloan Oinousses (Koyun Adaları), ngrebut manèh Khios; iki dadi tandha tangi sedhéla ing pelayaran Utsmaniyah.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Kamenangan Lugoj — ekspedisi Austria kapisan Mustafa II", "d5ee9b34"], "d": ["Ing ekspedisi kapisan sing dimèlu dhéwé déning sultan, Lipova direbut manèh lan pasukan Austria dikalahaké ing Lugoj; ing ranté kekalahan sing wis pirang-pirang taun kedadéan pedhotan kapisan. Atlas uga nganggep Caransebeș ing ekspedisi iki bali saka Habsburg menyang Utsmaniyah; sumber mung menehi September 1695 (TDV mustafa-ii), dina atlas dijupuk saka cathetan Lugoj (perkiraan sing wis diumumaké).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Kelangan Bèntèng Azak", "2b78b5cd"], "d": ["Peter I, sing péngin tekan Segara Ireng, ing pengepungan kaping pindho ngrebut Azak (Azov); Rusia kanggo kaping pisan manggon tetep ing bèntèng Utsmaniyah lan njupuk langkah kapisan dadi kakuwatan laut.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Kamenangan Ulaş (Olašin)", "02ac9ca8"], "d": ["Kamenangan sing diolèhi ing pinggir Donau ing ekspedisi kapindho sultan ngrusak rencana Austria arep ngrebut Temeşvar; nanging ora ngowahi imbangan umum perang.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Bubrah Zenta — nasibé perang wis ditemtokaké", "475c4a7b"], "d": ["Nalika nyabrang Kali Tisza, wadyabala kena serangan dumadakan Pangeran Eugene; pasukan sing kapisah ing pinggir loro kali ditumpes sajrone sawetara jam, lan èwuan prajurit lan negarawan tiwas, kalebu Wazir Agung Elmas Mehmed Pasya. Zenta, salah siji kekalahan paling abot ing sejarah Utsmaniyah, ndadèkaké meja tentrem ora bisa diendhani.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Rembugan tentrem Karlowitz diwiwiti", "1f395cf3"], "d": ["Ing rembugan sing diwiwiti kanthi perantara Inggris lan Walanda, delegasi Utsmaniyah kanggo kaping pisan kepeksa nampa prinsip 'uti possidetis' (apa sing dicekel tetep dicekel); rembugan sing lumaku pitung puluh loro sidhang dianggep laire diplomasi Utsmaniyah modhèrn.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali saka Kavala ndharat ing Mesir", "514c943f"], "d": ["Ing wadyabala Utsmaniyah sing dikirim kanggo ngrebut manèh Mesir sing didhudhuki Prancis uga ana pasukan sukarelawan sing diklumpukaké saka Kavala. Mehmed Ali, sing umuré telung puluhan, dadi komandan kapindho pasukan iku; panjenengané ngidak Mesir ora minangka gubernur, nanging minangka perwira kompi.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Prajurit Albania nggulingaké gubernur Mesir", "c76a0ec2"], "d": ["Pasukan Albania sing ulufe (gajihé) ora dibayar mbrontak lan meksa gubernur Husrev Pasya mlayu saka bèntèng. Ing kekosongan sing tuwuh amarga mundure wong Prancis, para bey Mamluk, korps Albania, lan para gubernur sing diangkat déning Bab-i Ali mlebu ing perjuangan telung pojok; Mehmed Ali dadi misuwur kanthi ngatur kasetimbangan ing segitiga iki. Papan liyané sing ucul ing tanggal sing padha: Thaif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulama Kairo ngumumaké Mehmed Ali dadi gubernur", "a16752f2"], "d": ["Para pedagang lan ulama Kairo sing kabotan déning tekanan pajeg, dipimpin naqib al-asyraf Umar Makram, mbrontak, nyatakaké ora ngakoni gubernur Hurşid Pasya, lan nglungguhaké Mehmed Ali ing kalungguhan gubernur. Ing sajarah Utsmaniyah, gubernur sing dipilih déning rakyat iku prastawa sing arang banget ana tandhingané.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Bab-i Ali nampa kasunyatan sing wis kelakon: firman gubernur Mesir", "b86736a3"], "d": ["Bab-i Ali, sing ora duwé kakuwatan kanggo njejegaké calone dhéwé ing Mesir, ngirim firman gubernur Mesir marang Mehmed Ali kanthi pangkat wazir. Ing peta, wiwit tanggal iki Mesir pindhah menyang lapisan bawahan (werna enom): sacara hukum tlatah Utsmaniyah, nanging kasunyatané negarané wangsa Kavalalı. Papan liyané sing pindhah menyang lapisan bawahan ing tanggal sing padha: Kairo, Iskandariyah, Damietta, Asyut, Aswan, Ibrim, Suez, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Ekspedisi Inggris Fraser ndharat ing Iskandariyah", "4d6c31be"], "d": ["Minangka wangsulan marang Utsmaniyah sing nyedhak menyang Prancis, Inggris ngirim pasukan pendharatan menyang Mesir. Nalika iku Mehmed Ali lagi ngadhepi para Mamluk ing Mesir Hulu; dhèwèké énggal bali lan nata pertahanan.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Kakalahan ing Reşid (Rosetta) — Inggris dipukul mundur", "3636004c"], "d": ["Barisan Inggris sing mlebu kutha cilik Reşid nandhang karugèn abot ing perang dalan; ing sasi September pasukan kuwi ninggalaké Mesir kabèh. Kamenangan iki ngukuhaké wibawané Mehmed Ali, ing Mesir uga ing Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Prastawa Bèntèng: panumpesan para bey Mamluk", "84030b97"], "d": ["Para bey Mamluk sing diundang menyang arak-arakan upacara kanggo ekspedisi Hijaz kejebak ing lorong ciyut Bèntèng Kairo lan ditumpes. Kanthi mangkono pengaruh Mamluk sing wis limang abad rampung, lan Mehmed Ali ora duwé saingan manèh ing Mesir.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Ekspedisi Hijaz diwiwiti — wadyabala maju menyang Yanbu liwat segara saka Suez lan liwat dharatan ing dalan kaji", "1c05c159"], "d": ["Ngrebut manèh Haramain, sing wiwit taun 1803 ana ing pamaréntahan Saudi-Wahabi, iku prakara legitimasi paling gedhé tumrap Mahmud II; amarga kakuwatan Bab-i Ali ora nyukupi, tugas iku dipasrahaké marang gubernur Mesir. Mehmed Ali ngutus putrané sing umur nem belas taun, Tosun, dadi pangarepé wadyabala.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu ditampa nyerah — pangkalan pesisir kapisan ing ekspedisi Hijaz", "179bc78d"], "d": ["Watara rong èwu prajurit infantri Albania, sing mangkat saka Suez nganggo kapal-kapal sing anyar digawé, ndharat cedhak Yanbu ing Oktober 1811; kutha cilik iku nyerah sawisé nglawan kanthi lemah suwéné rong dina. Pasukan jaranan ing pangwasané Tosun ngetutaké dalan kaji liwat dharatan lan lagi tekan Yanbu rong minggu sawisé, ngliwati Aqaba lan al-Wajh. Yanbu dadi pangkalan kapisan ing Hijaz tumrap wadyabala Mesir sing bakal maju menyang Madinah lan Makkah.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Kakalahan kapisan ing selat gunung Safra-Jadida", "99ef804d"], "d": ["Pasukan pangarep Mesir sing dicegat ing lorong-lorong gunung sing ciyut dadi buyar. Kakalahan iki dadi piwulang taktik ing ekspedisi kasebut: dimangertèni manawa maju ing Hijaz ora bisa tanpa panyengkuyung suku-suku Badui.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Madinah direbut manèh", "6f6a5d55"], "d": ["Sawisé dikepung suwé, Madinah nyerah. Direbuté manèh kuthané Kanjeng Nabi dirayakaké ing Istanbul kanthi pésta tembakan mriyem; minangka ganjaran, Mehmed Ali uga diparingi kalungguhan gubernur Jeddah.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Makkah direbut manèh — dalan kaji kabukak", "3d6d66a0"], "d": ["Pasukan Mesir sing mlebu Makkah ndadèkaké khutbah ing Ka'bah diwaca manèh atas asmané sultan Utsmaniyah. Kafilah kaji sing wis sepuluh taun kepedhot bisa mangkat manèh. Ing peta, Hijaz bali menyang pangwasa Utsmaniyah, nanging amarga pamaréntahané ana ing Kairo, ditampilaké nganggo werna bawahan. Papan liyané sing pindhah menyang pamaréntahan bawahan ing tanggal sing padha: Jeddah.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Direbuté manèh Thaif — rampungé ekspedisi Hijaz", "6315fb31"], "d": ["Sawisé Madinah (Desember 1812) lan Makkah (Januari 1813), wadyabala Mesir ing pangwasané Tosun Pasya pungkasané ngrebut manèh Thaif saka wong Wahabi. Pangwasa Saudi sing suwéné sepuluh taun rampung, lan telu pusat suci ing Hijaz bali ana ing pangawasan Utsmaniyah-Mesir.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali dhéwé tindak menyang Hijaz", "fda0ea2d"], "d": ["Weruh ekspedisi mlaku alon, gubernur iku njupuk pamaréntahan langsung ing tangané; kanthi tawar-tinawar karo para pangarsa suku, dhèwèké nyoba ngudhari garis ngarep Saudi saka njero. Bagéané Mesir ing dagang Segara Abang uga tambah gedhé amarga ekspedisi iki.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Perang Bisel: pasukan Saudi dikalahaké mutlak", "9c9ab91f"], "d": ["Wong Saudi sing kalah abot ing perang ara-ara mundur menyang tlatah pedalaman. Gencatan senjata sing digawé ora langgeng; rong taun sawisé, operasi bakal digawa menyang jantung Najd. Sawisé kamenangan iki, atlas nganggep Turaba lan Hurma ing sisih wétan Thaif wis ucul saka tangan Saudi (sumber prastawa Lorimer, Gazetteer; kasaksèn mligi tumrap papan-papan kuwi lan tanggal 13 Januari iku kira-kira sing wis diterangaké).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasya mangkat ing ekspedisi Najd", "d5ed80d1"], "d": ["Ibrahim Pasya, sing nampa komando sawisé sedané sadulure, Tosun, miwiti lelampahan abot ing ara-ara samun suwéné rong taun. Wadyabala sing maju saka sumur siji menyang sumur sijiné, karo nyingkiraké suku-suku siji mbaka siji, pungkasané tekan ing ngarep kutha krajan Saudi.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Diriyah tiba — Nagara Saudi Kapisan rampung", "aa96206d"], "d": ["Sawisé dikepung suwéné nem sasi, Diriyah nyerah lan dirusak. Emir Abdullah bin Saud dikirim menyang Istanbul lan diukum pati. Kanggo sepisanan, gendéra Utsmaniyah tekan semono jeroné ing pedalaman Arab; garnisun Najd tetep ana nganti taun 1824. Papan liyané sing gabung ing tanggal sing padha: Diriyah (Najd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Ekspedisi Sudan diwiwiti", "b1fc6905"], "d": ["Tujuané Mehmed Ali ana telu: nglumpukaké prajurit kanggo wadyabalané, ngranggèh emas Sennar, lan numpes sisa-sisa Mamluk sing mlayu. Pasukan ing pangwasané putrané, Ismail Pasya, mudhun ngidul ngetutaké Kali Nil.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola pindhah menyang wadyabala Mesir tanpa kekerasan (para Mamluk wis ninggalaké ing Juni 1820)", "bc5942c0"], "d": ["Dongola ing tikungan gedhé Kali Nil, sawisé ditinggal para Mamluk ing Juni 1820, tiba ing tangané wadyabala Mesir sing dipimpin Ismail Pasya tanpa kekerasan. Ing peta, wiwit tanggal iki Sudan katon ing lapisan bawahan: sing nelukaké iku Kairo, lan sing bakal mréntah uga Kairo.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Perang Jabal al-Dayqa — konfederasi Syayqiya dikalahaké mutlak déning wadyabala Mesir", "befc9539"], "d": ["Sasasi sawisé tempuran kapisan ing Kurti, wadyabalané Ismail Pasya, putrané Muhammad Ali Pasya, ngalahaké Syayqiya ing perang kapindho sing nemtokaké cedhak Jabal al-Dayqa. Pangarsa Syayqiya, Makk Subayr, nyerah; Makk Syawisy terus nglawan. Wiwit iku pangwasa Mesir ing tikungan Kali Nil dadi tetep.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Kasultanan Sennar (Funj) nyerah", "3cac7dd2"], "d": ["Wangsa Funj sing wis telung abad nyerah tanpa perang. Pakémahan sing diadegaké ing taun sing padha ing papan patemoné rong cabang Kali Nil énggal dadi Khartoum, pusat pamaréntahan Sudan. Papan liyané sing gabung ing tanggal sing padha: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan direbut", "06440602"], "d": ["Barisan kapindho sing dikirim mangulon ngalahaké pasukan Darfur ing Bara (Bâra) lan ngrebut Kordofan bebarengan karo tlatah sakiwa-tengené Nuhud. Kanthi mangkono pangwasa Mesir ing Sudan jembar saka lembah Nil menyang stépa sisih kulon.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Pasukan Mesir ndharat ing Kreta", "835aee90"], "d": ["Nalika pambrontakan Yunani nular menyang Kreta, Bab-i Ali njaluk supaya pasukan Mesir dikirim menyang pulo iku. Pengaruhé Mehmed Ali ing pulo kuwi diwiwiti saka campur tangan iki, lan wolung taun sawisé dipungkasi kanthi diparingaké kalungguhan gubernur Kreta marang dhèwèké.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Ismail Pasya dipatèni ing Shendi", "223860c9"], "d": ["Emir lokal Nimr, sing nesu amarga panjaluk pajeg abot lan prajurit, ngobong omah sing dienggoni Ismail Pasya nginep, nganti Ismail Pasya sakpandhèrèké kobong. Ekspedisi piwales ndadèkaké tlatah iku banjir getih; wiwit iku pamaréntahan Sudan diadegaké adhedhasar kekerasan.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II njaluk pitulung marang Mehmed Ali kanggo Morea", "03594a42"], "d": ["Kanggo pambrontakan Morea sing sajroné telung taun ora bisa ditumpes déning wadyabala Janissari, sultan nyuwun pitulung marang wadyabala Mesir sing dilatih cara Éropah. Minangka piwales, dijanjèkaké kalungguhan gubernur Morea lan Kreta. Panjaluk iki dadi pangakuan terbuka kapisan manawa kakaisaran wis gumantung marang provinsiné dhéwé.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasya ndharat ing Modon", "9c993dba"], "d": ["Pasukan pendharatan sing direksa déning armada Mesir ngancik pucuk kidul-kulon Morea. Wadyabala iki, sing nduwé infantri reguler (nizami) lan artileri lapangan, kanthi cepet unggul ngadhepi gerombolan pambrontak.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa direbut manèh — puseré Morea tiba", "8a478c11"], "d": ["Kanthi tibané Tripolitsa, pusat pamaréntahan pambrontakan, pérangan gedhé Morea bali ana ing pangawasan. Ing peta, semenanjung iku katon nganggo werna bawahan amarga ana ing tangané pasukan Mesir.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) tiba", "07257f87"], "d": ["Sawisé dikepung suwéné setaun, kutha iku direbut. Nanging kumandhangé pertahanan kutha kuwi ing koran-koran Éropah njunjung simpati marang perjuangan Yunani nganti pucuké lan nyawisaké dalan kanggo campur tangané nagara-nagara gedhé.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Akropolis Athena ditampa nyerah", "3b19f946"], "d": ["Kanthi tibané Akropolis, pambrontakan Yunani sacara militèr meh rampung. Pas ing titik iki, prakara kuwi ora manèh dadi pambrontakan njero nagara, nanging dadi bab diplomasi Éropah.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Prajanjian London: telung nagara meksakaké otonomi Yunani", "7ce46fd8"], "d": ["Inggris, Prancis, lan Rusia mutusaké tumindak bebarengan supaya Utsmaniyah lan wong Yunani nampa gencatan senjata lan sarat otonomi; diumumaké yèn tawaran iku ditolak, armadané bakal campur tangan. Bab-i Ali nolak usulan kasebut.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Prajanjian Iskandariyah: keputusané Mesir mundur saka Morea", "cc978f37"], "d": ["Mehmed Ali, sing kélangan armadané ing Navarino, rembugan langsung karo laksamana Inggris tanpa takon marang Istanbul lan sarujuk narik pasukané saka Morea. Gubernur sing gawé prajanjian dhéwé karo nagara-nagara gedhé iku dadi pratandha krisis sing bakal teka.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Pasukan Mesir ninggalaké Morea", "8fb742dd"], "d": ["Pasukan pungkasan diunggahaké menyang kapal; semenanjung iku kasunyatané ucul saka tangan lan, miturut Protokol London 1830, dadi intiné Yunani sing mardika. Mehmed Ali dhéwé ora nampa kalungguhan gubernur Morea sing dijanjèkaké, malah kélangan armada lan wadyabala sing gedhé. Papan liyané sing ucul ing tanggal sing padha: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Pamaréntahan Kreta dipasrahaké marang Mehmed Ali", "7f76396d"], "d": ["Minangka ganti ruginé kélangan Morea, kalungguhan gubernur Kreta diparingaké marang Mehmed Ali. Pulo iku diprentah saka Kairo suwéné sepuluh taun; ing peta, sajroné wektu iki katon nganggo werna bawahan. Papan liyané sing gabung ing tanggal sing padha: Kandia (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasya mlebu Suriah — krisis kapisan diwiwiti", "1a5cc386"], "d": ["Alesan lahiré yaiku gubernur Akko sing ora gelem mbalèkaké para fellah sing mlayu saka Mesir; sebab sing sejati yaiku kabutuhané Mehmed Ali marang kayu, plabuhan, lan tenaga manungsa saka Suriah. Wadyabala nyabrang Sinai lan cepet ngrebut pesisir Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Pengepungan Akko diwiwiti", "b211d96d"], "d": ["Bèntèng sing ngendheg Napoleon ing taun 1799 iku nglawan suwéné nem sasi. Pengepungan iki dadi ujian gedhé kapisan tumrap artileri modèren wadyabala Mesir.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akko tiba", "0f47917b"], "d": ["Nalika batere mriyem sing nggebugi témbok gawé jebolan, bèntèng iku direbut. Gapurané Suriah wis menga; ing dina-dina kuwi uga, Bab-i Ali nyatakaké Mehmed Ali dadi pambrontak lan nyopot kalungguhané minangka gubernur.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damaskus nyerah", "48da3b62"], "d": ["Kutha iku nyerah tanpa perang. Ibrahim Pasya nyoba ngranggèh panyengkuyung warga lokal kanthi ngumumaké tatanan pajeg lan kasetaraan sing diparingaké marang wong non-Muslim; kawicaksanan sing padha kuwi sawetara taun sawisé uga bakal dadi sebabé pambrontakan nglawan dhèwèké. Papan liyané sing gabung ing dina-dina kuwi: Beirut, Tripoli Syam, Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Perang Homs", "867810ee"], "d": ["Wadyabala Utsmaniyah sing dikirim kanggo nylametaké Suriah dikalahaké mutlak ing ara-ara. Katon yèn wadyabala anyar, sing diadegaké nem taun sawisé Janissari dibubaraké, durung siyaga.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo direbut", "9c0ead76"], "d": ["Pusat dagang lan pamaréntahan Suriah sisih lor uga tiba. Kanthi mangkono wadyabala Mesir tekan sikilé Pagunungan Taurus lan nuju menyang lorong-lorong ing gapurané Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Kakalahan ing Lorong Belen (Beylan) — Çukurova kabukak", "4bae872b"], "d": ["Garis pertahanan dijebol ing lorong ciyut Pagunungan Amanos. Antiokhia, Adana, lan Tarsus pindhah menyang pasukan Mesir (dhudhukan Maraş, miturut TDV, dumadi ing 1833, dadi butir kapisah); ing peta Çukurova malih dadi werna bawahan. Dalan menyang pedalaman Anatolia saiki ora ana sing njaga.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Lorong Gülek tiba — pesisir Içil (Mersin, Silifke) mlebu pangawasan Mesir", "d9049b5b"], "d": ["Lorong Gülek, gapura Pagunungan Taurus menyang Çukurova, tiba ing tangané wadyabala Mesir. Ibrahim Pasya ngangkat mütesellimé dhéwé kanggo Sancak Içil, lan kabèh dhermaga ing pesisir mlebu pangawasan Mesir. Ing peta, Mersin lan Silifke ditampilaké dadi pérangané Mesir wiwit dina iki (wates ngisor; dina pangangkatan ora ana ing sumber); amarga ing keputusan Kütahya mung muhassıllık Adana sing dipasrahaké, pangawasan iki rampung bebarengan karo Anatolia dikosongaké.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereğli Konya didhudhuki Mesir — lawang Taurus ing dalan Konya–Adana", "fb908900"], "d": ["Ereğli, sing ana ing dalan menyang Konya tumrap wadyabala Mesir sing ngliwati Lorong Gülek, didhudhuki Ibrahim Pasya ing taun 1832, lan nalika dikosongaké miturut tatanan Kütahya 1833, bali digabungaké karo provinsi Karaman. Ing peta, papan iki dadi titik antara sing ana sumberé ing garis dhudhukan antarané Adana lan Konya; ora ditemokaké kasaksèn ing tingkat kutha kanggo Ulukışla lan Karapınar.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Wadyabala Mesir mlebu Konya", "13952a2d"], "d": ["Wadyabala sing nyabrang Pagunungan Taurus tekan Anatolia Tengah. Sepisanan, pasukané gubernur Utsmaniyah maju ing tlatah inti kakaisaran. Papan liyané sing gabung ing tanggal sing padha: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Perang Konya: wazir agung ditawan", "ec82cc9a"], "d": ["Wadyabala Utsmaniyah sing buyar ing hawa pedhut nandhang kakalahan abot, lan wazir agung Reşid Mehmed Pasya ditawan. Wadyabala pusat nagara wis ora ana manèh; ora ana kakuwatan sing isa ngadeg ing antarané Istanbul lan pasukan Mesir.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş didhudhuki Mesir", "f558e383"], "d": ["Miturut TDV, ing taun 1833 Maraş didhudhuki déning Ibrahim Pasya Kavalalı lan tetep ana ing pamaréntahané meh sangalas sasi. Amarga Maraş ana ing sanjabané wates provinsi miturut tatanan Kütahya, pamaréntahan iki mung sacara kasunyatan, dudu sacara hukum.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) didhudhuki Mesir — dalan Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, sing ana ing dalané wadyabala Mesir nalika maju menyang Kütahya sawisé Perang Konya, ing taun 1833 sawetara wektu ana ing tangané Ibrahim Pasya. Ing peta, papan iki dadi titik antara sing ana sumberé ing garis dhudhukan antarané Konya lan Kütahya; ora ditemokaké kasaksèn ing tingkat kutha kanggo Akşehir, Ilgın, lan Ishaklı, mula padha ana ing werna Utsmaniyah.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Wadyabala Mesir tekan Kütahya", "214f8df6"], "d": ["Ibrahim Pasya mandheg ing Kütahya, sing adohé telung pos lelampahan saka Istanbul. Anggoné ora maju manèh iku alesan pulitik, dudu militèr: campur tangan Rusia lan réaksi Éropah wis diétung.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Armada Rusia ing ngarep Büyükdere", "6f836d61"], "d": ["Mahmud II, sing ora bisa éntuk pitulung saka Inggris lan Prancis, njaluk pitulung marang Rusia, mungsuhé wingi. Keputusan iki, sing dièlingi liwat tembungé sultan \"wong sing klelep ing segara bakal nyekel ula\", njalari prajurit Rusia ndharat ing Selat-Selat lan ngunèkaké lonceng tandha bebaya ing Éropah.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Kesepakatan Kütahya (lisan) — Suriah lan Adana kanggo Kavalalı", "25fe9985"], "d": ["Saliyané Mesir, Kreta, lan Hijaz, Bab-i Ali masrahaké kalungguhan gubernur Damaskus, Aleppo, Tripoli (Syam), lan Sidon marang Mehmed Ali; dene muhassıllık Adana marang Ibrahim Pasya. Minangka gantiné, wadyabala mundur menyang sisih kidulé Pagunungan Taurus. Iki dudu prajanjian, nanging awujud firman sing diparingaké sultan marang gubernur — prakarané durung rampung, mung ditundha.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Munduré wadyabala Mesir saka Anatolia rampung liwat Gülek", "a53ac2a3"], "d": ["Sawisé tatanan Kütahya, pasukan Mesir ninggalaké Anatolia; nyedhaki tengah sasi Juni, kabèh wadyabala wis nyabrang saka Lorong Gülek menyang Çukurova. Pesisir Içil (Mersin, Silifke) bali menyang pamaréntahan Utsmaniyah; muhassıllık Adana lan Suriah tetep ana ing Mesir.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Prajanjian Hünkâr Iskelesi", "da741d5c"], "d": ["Persekutuan pertahanan bebarengan suwéné wolung taun ditandhatangani karo Rusia. Miturut pasal wadi, yèn Rusia diserang, Utsmaniyah bakal nutup Selat-Selat tumrap kapal perang. Iki dadi salah siji keputusan diplomasi Utsmaniyah sing paling akèh dipadu lan ndadèkaké Inggris aktif ing prakara Mesir.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Pambrontakan Palestina-Nablus nglawan pamaréntahan Mesir", "4fe43e27"], "d": ["Wajib militèr, panglumpukan gaman, lan pajeg anyar njalari pambrontakan sing amba ing Palestina. Pambrontakan iku ditumpes kanthi keras; panyengkuyungé warga lokal marang pamaréntahan Mesir cepet luntur.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Pungkasané pamaréntahan Mesir ing Maraş (kira-kira)", "bb46ca42"], "d": ["Yèn ukara TDV bab suwéné 'meh sangalas sasi' diétung wiwit dhudhukan 1833, pamaréntahan Mesir rampung watara mangsa panas 1834. Mustafa Bey saka Küçükalioğulları, sing ing taun 1834 ora kuwat nglawan wadyabala Mesir lan mundur menyang arah Maraş, uga nuduhaké yèn nalika iku Maraş dadi papan pangungsèn ing sanjabané pangawasan Mesir.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Pambrontakan Jabal al-Druz", "12e74626"], "d": ["Perlawanan sing tuwuh ing tlatah Druz lumaku suwéné rong taun. Rasa ora marem sing nglumpuk ing Suriah, ing taun 1840, nalika armada sekutu ndharat ing pesisir, bakal ndadèkaké buriné wadyabala Mesir kothong tanpa pangayoman.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali ngabaraké niyaté mardika", "48633bbd"], "d": ["Gubernur iku mratélakaké marang para konsul nagara gedhé yèn dhèwèké nimbang arep ngumumaké kamardikané Mesir lan Suriah. Inggris nolak kanthi tegas: laire nagara kuwat ing Segara Tengah sing cedhak karo Prancis bakal ngancam dalan menyang Hindia.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Wadyabala Utsmaniyah nyabrang Kali Efrat", "9af1ea69"], "d": ["Mahmud II ngerahaké wadyabalané menyang tapel wates Suriah kanggo ngrebut manèh apa sing ilang ing Kütahya. Perwira Prusia Moltke, sing ana ing wadyabala minangka penasihat, mbantah pamilihé papan pertahanan lan serangan sing kesusu; bantahané ora digagas.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Perang Nizip — wadyabala Utsmaniyah buyar", "156b3cdf"], "d": ["Wadyabala Utsmaniyah sing diatur papané kanthi ala dikalahaké mutlak mung sajroné sawetara jam. Sultan séda sadurungé kabar kakalahan tekan Istanbul; sajroné sawetara dina, nagara bakal kélangan wadyabala, rajané, banjur armadané.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Sédané Mahmud II", "07eccfff"], "d": ["Sultan sing sajroné kuwasa telung puluh siji taun mbubaraké Janissari lan ngedegaké manèh pamaréntahan pusat iku séda tanpa bisa ngalahaké mungsuhé sing paling gedhé. Lelarané ora didiagnosis kanthi trep. Sédané didhelikaké nganti 30 Juni, nganti tindakan militèr dijupuk ing kutha amarga kuwatir manawa semangat Janissari bakal obah manèh.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Jumenengé Abdülmecid lan layon Mahmud II", "d0f3d2cc"], "d": ["Sawisé ramané séda, Abdülmecid sing umur nem belas taun jumeneng. Ing dina sing padha, layon Mahmud II digawa menyang Kraton Topkapı; karusuhan sing dikuwatiraké ora kedadéan, lan wong akèh, Muslim uga non-Muslim, mèlu arak-arakan layon.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Armada dipasrahaké ing Iskandariyah", "a53e6103"], "d": ["Kaptan-ı derya (laksamana agung) Ahmed Fevzi Pasya, sing nyujanani yèn wazir agung Koca Husrev Pasya bakal masrahaké armada marang Rusia, nggawa armada menyang Iskandariyah lan masrahaké marang Mehmed Ali. Ing sasi sing padha, Nagara Utsmaniyah tanpa wadyabala, tanpa sultan, lan tanpa armada.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota bebarengan saka nagara-nagara gedhé", "2a3b8316"], "d": ["Lima nagara ngaturaké nota marang Bab-i Ali supaya ora gawé sarujukan dhéwé ing prakara Mesir. Kanthi mangkono, prakara njero nagara resmi dadi \"prakara Éropah\"; nagara Utsmaniyah kasunyatané kélangan wewenang mutusaké bab provinsiné dhéwé.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Prajanjian London: patang nagara ing pihak Utsmaniyah", "a517f775"], "d": ["Prajanjian sing ditandhatangani kanthi ninggalaké Prancis iku menèhi ultimatum marang Mehmed Ali: yèn nampa sajroné sepuluh dina, éntuk kalungguhan gubernur Mesir turun-temurun lan Akko saumur urip; yèn sajroné rong puluh dina, mung Mesir; yèn nolak, ora éntuk apa-apa. Gubernur iku nolak.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Pamboman Beirut lan pendharatan sekutu", "0905ce92"], "d": ["Armada Inggris-Austria nembaki Beirut nganggo mriyem; gaman diedum marang rakyat sing mbrontak nglawan pamaréntahan Mesir ing pagunungan Libanon. Pangawasané Ibrahim Pasya ing Suriah ambruk, kejepit antarané pambrontakan njero lan campur tangan njaba.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut lan kutha-kutha pesisir ucul saka tangan", "09bdaf23"], "d": ["Sawisé tempuran ing arah Baalbek, pasukan Mesir mundur saka pesisir. Ing peta, pesisir Libanon metu saka werna bawahan lan bali menyang pamaréntahan Utsmaniyah langsung.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akko tiba sajroné rong jam", "5aec21f0"], "d": ["Ing pamboman armada sekutu, gudhang amunisi bèntèng mbledhos lan Akko nyerah sajroné sawetara jam. Bèntèng sing wolung taun sadurungé mung bisa direbut Ibrahim Pasya sajroné nem sasi iku nuduhaké unggulé artileri segara.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konvènsi Iskandariyah", "85cb47b0"], "d": ["Mehmed Ali sarujuk ngeculaké Suriah, Adana, Kreta, lan Hijaz, mbalèkaké armada Utsmaniyah, lan ngakoni pangwasa sultan; minangka gantiné, kalungguhan gubernur Mesir sing turun-temurun dijamin.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Wadyabala Mesir ninggalaké Suriah lan Çukurova", "719a28dc"], "d": ["Dhudhukan suwéné sangang taun rampung; wadyabala Ibrahim Pasya bali menyang Mesir liwat Sinai. Ing peta, sabuk amba sing mbentang saka Aleppo nganti Gaza lan saka Adana nganti Kreta bali menyang pamaréntahan Utsmaniyah langsung. Papan liyané sing ucul ing tanggal sing padha: Urfa, Maraş, Tarsus, Antiokhia, Kandia (Kreta), Hama, Damaskus, Yerusalem, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman: kalungguhan gubernur Mesir dipasrahaké turun-temurun marang kulawarga Kavalalı", "87b89ff8"], "d": ["Firmané sultan ngakoni kalungguhan gubernur lumintu saka bapak menyang anak ing njero wangsa; minangka gantiné, cacahé wadyabala dikurangi dadi wolulas èwu, pajeg diiket karo Istanbul, lan wewenang nyithak dhuwit sarta gawé prajanjian dicabut. Mesir tetep dadi provinsi, nanging saiki wis dadi negarané wangsa dhéwé. Pamaréntahan Hijaz lan Haramain bali menyang Bab-i Ali. Papan liyané sing bali saka lapisan bawahan menyang lapisan langsung ing tanggal sing padha: Makkah, Madinah, Jeddah, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konvènsi Selat London", "0e95a1ea"], "d": ["Konvènsi sing ngganti Hünkâr Iskelesi iki netepaké yèn ing jaman tentrem Selat-Selat katutup tumrap kabèh kapal perang. Kanthi mangkono hak mirunggan sing dimenangaké Rusia dhéwé malih dadi jaminan bebarengan Éropah; prakara Selat éntuk status internasional.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasya kasunyatané dadi gubernur Mesir", "9e14f5d9"], "d": ["Ngganti Mehmed Ali sing saya sepuh lan kélangan kawarasan pikirané, putrané, Ibrahim Pasya, diangkat dadi gubernur. Nanging sawetara sasi sawisé, ing November 1848, dhèwèké séda ndhisiki ramané.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Sédané Kavalalı Mehmed Ali Pasya", "871310e0"], "d": ["Gubernur sing lair ing Kavala, ngedegaké wangsa ing Mesir, lan kaping pindho nggawa kakaisaran menyang pinggiré jurang iku séda ing umur wolung puluh taun. Wangsa sing diadegaké mréntah Mesir nganti taun 1953; nagara, sing weruh manawa tatu sing digawéné mung bisa ditutup kanthi campur tangan Éropah, banjur maju ing dalan Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Sédané Ertuğrul Gazi lan jumenengé Osman Bey ing kabèylikan — warisan Söğüt lan Domaniç", "395fb9fa"], "d": ["Miturut TDV, Ertuğrul Gazi séda ing taun 680 (1281-82); butir kasebut nyathet yèn tanggal 1288 lan 1289 uga disebutaké. Saka ramané, Osman Bey ora marisi kutha sing wis ditelukaké, nanging rong paringan sing diwènèhaké sultan Seljuk marang Ertuğrul, sing dipapanaké ing garis paling ngarep tlatah tapel watesé: papan mangsa adhem (yurtluk) ing Söğüt lan pangonan mangsa panas (yaylak) ing Domaniç. Tegesé, kabèylikan iku miwiti uripé ora nganggo warisan penaklukan, nanging nganggo rong paringan pangonan; ing peta, rong papan iki ditampilaké minangka 'warisan', dudu 'penaklukan'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vespers Sisilia — wangsa Anjou kélangan pulo Sisilia", "547db635"], "d": ["Pambrontakan sing mbledhos ing Palermo ing wayah sembahyang soré Senin Paskah nglawan pamaréntahan Charles I saka Anjou misahaké pulo Sisilia saka wangsa Anjou. Karajan Sisilia pecah dadi loro: pulo iku milih Aragon, déné wangsa Anjou tetep tahan ing karajan dharatan sing puseré ing Napoli. Duwèké wangsa kuwi ing njaba negara, ing Segara Adriatik lan Segara Tengah, uga tetep mèlu karajan iki: Korfu, sing wiwit 1267 ana ing tangané, lan Durazzo, sing wiwit taun 1270-an dicekel, lumaku terus minangka pérangan Karajan Napoli; bèntèng Valona, Kanina, lan Himara ing pesisir Albania uga tetep ana ing karajan sing puseré ing Napoli (komandan Valona, John of Taxis, nglawan Bizantium sajroné taun 1282; Durazzo, Valona, lan Kanina mbokmenawa banget pindhah menyang Bizantium ing wiwitan 1285). Déné Malta lagi tiba ing tangané wong Aragon ing taun 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Serbuan menyang Kulacahisar — operasi militèr kapisané Osman Bey", "79b00b14"], "d": ["TDV, butir Osman I: 'Dhèwèké njarah lan ngobong Bèntèng Kulaca sing cilik cedhak Inegöl (684/1285).' Iki tumindak militèr kapisané Osman Bey sing bisa ditemtokaké tanggalé ing sumber. Ora ana papan dunung sing direbut kanthi tetep; bèntèng iku dijarah lan diobong, mula iki luwih pas diarani serbuan tapel wates klasik tinimbang penaklukan. Kedadéan iki dianggep titik wiwitané kagiyatan militèr kabèylikan.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Direbuté Karacahisar — kutha kapisan sing diduwèni lan pangwasa marang Eskişehir", "178ae619"], "d": ["TDV, butir Osman I: ing taun 687 (1288) Osman Bey 'nelukaké Karacahisar lan dadi sing nguwasani Eskişehir'. Iki kutha sejati kapisan sing diduwèni kabèylikan, lan miturut crita turun-temurun, amarga kasil iki Osman Bey munggah dadi sancak beyi ing tapel wates; dicritakaké yèn khutbah Jemuwah kapisan atas asmané diwaca ing Karacahisar lan kadi kapisan diangkat ing kono. Butir TDV Eskişehir nyathet yèn tradisi Utsmaniyah nyebut tanggal 1291, nanging benere isih diragokaké.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Akko tiba ing tangané wangsa Mamluk — panumpesan pasukan Salib saka pesisir Suriah: Sidon lan Beirut", "3ca7a464"], "d": ["Akko, sing suwé dadi puseré Karajan Salib Yerusalem, ditelukaké Sultan Mamluk al-Malik al-Asyraf Khalil, lan pangwasané pasukan Salib ing Palestina rampung. Ksatria Templar sing mundur saka Akko ngungsi menyang Sidon; nalika wadyabala Mamluk nyedhak, para ksatria ninggalaké bèntèng segara lan mlayu menyang Siprus, lan ing mangsa panas sing padha kutha iku pindhah menyang wangsa Mamluk. Beirut, sing wiwit 1197 ana ing tangané pasukan Salib, uga direbut ing taun 1291 déning gubernur Damaskus, Sanjar al-Syuja'i. Kanthi mangkono anané pasukan Salib suwéné rong abad dibusak saka pesisir Suriah-Palestina.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Direbuté Bilecik lan Yarhisar kanthi serbuan wengi", "f461b0af"], "d": ["TDV, butir Bilecik: 'Sanajan para tekfur liyané ing tlatah iku, klebu tekfur Bilecik, nyusun rancangan arep matèni Osman Gazi, bareng rancangan iku kawruhan, pasukan Utsmaniyah nelukaké Yarhisar lan Bilecik kanthi serbuan dadakan (1299).' Rong bèntèng iku direbut ing siji operasi, ing serbuan wengi sing padha. Tanggal iki dadi titik owah sing ditampa minangka taun adegé Nagara Utsmaniyah. Papan liyané sing gabung ing tanggal sing padha: Inegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Perang Koyunhisar (Bapheus) — kamenangan gedhé kapisan nglawan wadyabala Bizantium", "584a9512"], "d": ["TDV, butir Osman I: tanggal 27 Juli 1302 Osman Bey perang lawan wadyabala Bizantium ing Bapheus (Koyunhisar) lan ngalahaké. Kamenangan iki dadi titik owah sing ngunggahaké Osman Bey saka mung pangarsa tapel wates dhaérah dadi pangadeg wangsa. Sawisé perang, dhataran Bursa mlebu pangawasan Utsmaniyah lan blokadé marang Iznik diwiwiti.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Kamenangan ing Dimbos lan sawisé iku direbuté Kite sarta Ulubat", "e168ab64"], "d": ["TDV, butir Osman I: ing taun 702 (1303) persekutuan sing diadegaké para tekfur Bursa, Kestel, Kite, lan Adranos dikalahaké ing lorong Dimbos; mungsuh dipeksa mundur karo perang nganti lorong sing ciyut, lan tekfur Kestel tiwas ing paprangan. Sanalika sawisé kamenangan, bèntèng Kite lan Ulubat direbut, saéngga sesambungan dharatané Bursa pedhot lan blokadené saya kenceng. Orhan sing isih enom uga mèlu perang iki.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Ekspedisi Sakarya: direbuté Leblebicihisar, Lefke, Mekece, lan Geyve", "a51ba4d3"], "d": ["TDV, butir Osman I menèhi urut-urutané ekspedisi Sakarya taun 704 (1304): 'Nalika tekan Bèntèng Leblebüci, tekfuré tundhuk... Dhèwèké tekan Lefke... Dhèwèké tekan Mekece... Dhèwèké menyang Geyve lan ngrebut bèntèng sing ditemoni kothong.' Lefke iku gapurané lembah Sakarya sing menga menyang Bilecik. Ekspedisi siji iki, kanthi nglebokaké ranté bèntèng sauruté lembah menyang pangawasan Utsmaniyah, nutup suwiwi wétan cekungan Iznik.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Direbuté bèntèng-bèntèng Lorong Geyve: Karaçepüş, Karatigin, lan Absu", "76907c78"], "d": ["TDV, butir Orhan: ing ekspedisi Sakarya taun 705 (1305), Orhan 'nelukaké bèntèng Karaçepüş (Katoikia), Karatigin ing ngarep Iznik, lan Absu (Hypsu: ing Lorong Geyve)'. Telu bèntèng iki, kanthi nutup liwatan antarané lembah Sakarya lan cekungan Iznik, medhot babar pisan pitulungan dharatan menyang Iznik. Gazi Abdurrahman dipapanaké ing Karaçepüş lan Absu ing lorong Geyve; saiki kutha iku mung bisa ditibakaké lumantar keluwèn.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Ekspedisi Adranos (Orhaneli) — ekspedisi pungkasané Osman Bey", "4811546c"], "d": ["TDV, butir Orhan nyathet ekspedisi menyang Bèntèng Adranos ing mangsa gugur 1323 minangka ekspedisi pungkasané Osman Bey. Tekfur Adranos biyèn dadi anggota persekutuan tekfur sing diadegaké nglawan Utsmaniyah ing Dimbos rong puluh taun sadurungé; ekspedisi iki ateges nutup étungan lawas kuwi. Dina pasti direbuté bèntèng ora dingertèni; operasi iki diterusaké déning Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Sédané Osman Gazi lan jumenengé Orhan Bey ing kabèylikan", "021487cd"], "d": ["Osman Gazi, sing menèhi jeneng marang kabèylikan, séda ing taun 724 (1324), miturut paseksèné layang wakaf (vakfiye) Asporça Hatun lan Mekece. Putrané, Orhan, sing wiwit 1305 dadi pangarsa wadyabala ing ekspedisi, nalika ramané séda lungguh dadi pangarsa kabèylikan tanpa ana rebutan dhampar babar pisan. Anggoné generasi pangadeg masrahaké panji tanpa gonjang-ganjing nuduhaké yèn wangsa iku ngliwati ujian gedhé kapisan, ing dalan saka kabèylikan tapel wates dadi nagara, kanthi tentrem.", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Perang Pelekanon (Maltepe) lan direbuté kabèh Kocaeli", "389e7bd4"], "d": ["TDV, butir Orhan: ing dina kapisan perang, Orhan Gazi ngirim pasukan telung atus wong kanggo mancing wadyabala Bizantium nyedhak; ing dina kapindho, perang dadi gedhé nalika pasukan ing pangwasané Pazarlu mudhun menyang dhataran, lan nalika kaisar tatu kena panah, wadyabala Bizantium dadi geger. Asilé cetha: 'Orhan ngrebut kabèh Kocaeli; sawisé kamenangan, wong Iznik wis ora duwé pangarep-arep.' Kutha-kutha pesisir saka Hereke nganti Üsküdar mlebu pamaréntahan Utsmaniyah, lan Gebze didadèkaké pusat tlatah. Iki wadyabala kekaisaran Bizantium pungkasan sing teka kanggo nylametaké Istanbul.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Adegé madrasah Utsmaniyah kapisan ing Iznik", "c85fb625"], "d": ["Sanalika sawisé ngrebut Iznik, Orhan Bey ngangkat Çandarlı Kara Halil dadi kadi ing kono, ngowahi siji basilika dadi masjid, lan miwiti mbangun kutha kanthi ngedegaké imaret lan madrasah ing sandhingé. Miturut butir TDV Dâvûd-i Kayserî, pambangunan madrasah rampung ing taun 1336, lan Orhan Gazi ngundang Dâvûd-i Kayserî dadi mudarrisé kanthi bayaran 30 akçe saben dina. Madrasah iki langkah kelembagaan kapisan ing uripé ngèlmu Utsmaniyah; kanthi mangkono kabèylikan nambahaké tradhisi ngèlmu ing sandhing kakuwatan penaklukané. Malihé krajan Bizantium sing direbut dadi puser ngèlmu Islam iku tandha nyata kapisan saka pangaku Utsmaniyah minangka nagara sing mapan.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizantium kudu mbayar upeti — pengepungan Izmit lan prajanjian", "0c1ec8d3"], "d": ["TDV, butir Orhan: ing mangsa panas 733 (1333), Orhan ngepung Izmit nganggo wadyabala gedhé lan manjanik, lan kaisar gelem gawé prajanjian. Minangka gantiné Orhan ngendheg pengepungan, Bizantium sarujuk mbayar 12.000 dhuwit emas (hyperpyra) saben taun marang Orhan; 'kanthi mangkono, ing paningalé emir Utsmaniyah, Bizantium tiba ing kalungguhan nagara sing mbayar upeti'. Minangka timbal balik, Orhan bakal dadi kancané kaisar lan ora nyerang kutha-kutha bawahan Bizantium. Kabèylikan tapel wates sing bisa meksa Romawi Wétan mbayar upeti iku dadi pangumuman sepira adohé imbangan kakuwatan wis malik.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Panggabungan Kabèylikan Karesi: Balıkesir, Bergama, Biga, Edremit, lan Erdek", "c7cb0511"], "d": ["TDV, butir Orhan (Inalcık) nempataké panggabungan iki ing taun 735 (1334-35): sawisé sedané Demirhan Bey, para gazi Karesi lan Hacı Ilbey ngundang Dursun Bey menyang dhampar lan njaluk pitulungan marang Orhan. Orhan luwih dhisik maju menyang Balıkesir; nalika Dursun Bey, sing lunga rembugan tentrem, mati kena panah saka bèntèng Bergama, kabèylikan iku sakabèhé digabungaké karo tlatah Utsmaniyah. Ing operasi sing padha, Kirmasti lan Mihaliç tundhuk, Gölyazı direbut, lan Ulubat, sing sadurungé ditinggal kanthi jaminan kaslametan (eman), direbut kanthi tetep. Orhan ngangkat Suleyman Pasya ing sancak Karesi lan ndadèkaké Biga pusat tapel wates — kanthi mangkono kader pelaut kanggo nyabrang menyang Rumeli bisa diduwèni. Cathetan: butir TDV Karesioğulları nyebut taun 746 (1345) kanggo prastawa sing padha; ensiklopedi iku ora cocog karo awaké dhéwé. Papan liyané sing gabung ing tanggal sing padha: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Kapitulasi kapisané Orhan Gazi karo wong Genoa", "e64cb196"], "d": ["Orhan Gazi, sing sarujukan karo wong Genoa nalika perang Venesia-Genoa, sawisé perang Selat Bosporus ing Februari 1352 ngirim 1000 prajurit panah kanggo mbélani Pera lan nyawisaké 60.000 dhuwit emas kanggo ngangkut prajurit; minangka timbal balik, dhèwèké maringi kapitulasi kapisan marang wong Genoa. Tèks lengkap prajanjian iku ora tekan jaman saiki. Iki prajanjian resmi kapisan sing digawé Utsmaniyah karo kakuwatan segara Éropah, lan bakal dianyaraké telung puluh limang taun sawisé, ing taun 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Direbuté Gallipoli — pangkalan pandhegan sing tetep ing Rumeli", "ba51a160"], "d": ["Wong Utsmaniyah ngrebut Gallipoli ing taun 1354, papan sing sakiwa-tengené wis ditepungi ing antarané 1349-1352 nalika dadi sekutuné Kantakouzenos; lindhu gedhé sing ngrubuhaké témbok kutha mènèhi kalodhangan. Kanthi mangkono pangkalan pandhegan ciyut ing Çimpe malih dadi pangkalan nyata ing sisih Rumeli Selat-Selat, lan gapura menyang Thrace menga amba. Gallipoli bakal ucul ing taun 1366 amarga Perang Salib Savoy, nanging lumantar penaklukan kapindho ing taun 1376 bakal tetep mlebu pangwasa Utsmaniyah. Papan liyané sing gabung ing tanggal sing padha: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Sédané Suleyman Pasya, sang penakluk Rumeli", "2dc98228"], "d": ["Suleyman Pasya, putra mbarepé Orhan Bey lan arsitèk penaklukan Rumeli, séda amarga tiba saka jaran nalika bebedhag, ing mangsa gugur 1357, yaiku tanggal sing paling akèh ditampa saka tanggal-tanggal ing sumber: 758 (1357), 759, lan 760 (1359). Sédané pangéran sing, lumantar panyabrangané ing antarané 1352-1354, ngedegaké anané Utsmaniyah sing tetep ing Rumeli iku ninggalaké urutan putra mahkota marang adhiné, Murad. Pasaréané Suleyman Pasya, sing disarèkaké ing Bolayır, tetep dadi monumen wangsa Utsmaniyah sing paling tuwa ing Éropah.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Undhang-undhang Pencik — dipasangé dhasar Korps Janissari", "e5877c2d"], "d": ["Sawisé penaklukan ing Rumeli, miturut saran Karamanlı Kara Rüstem saka kalangan ulama, dileksanakaké sistem pencik, sing netepaké yèn saprelima tawanan perang utawa regané ing dhuwit disisihaké kanggo nagara. Lumantar wong-wong sing dipilih saka tawanan iki, digulawenthah ing kulawarga Turk banjur dilebokaké dadi prajurit, kawangun intiné pasukan infantri tetep sing langsung ana ing sangisoré sultan — Korps Janissari. Malihé kabèylikan tapel wates sing adhedhasar pasukan jaranan suku dadi nagara sing duwé wadyabala pusat diwiwiti kanthi tatanan iki.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Mudhun menyang Thrace Kulon: direbuté Gümülcine", "9ef69221"], "d": ["Sawisé Edirne direbut, pasukan tapel wates sing nuju ing sisih kulon Kali Maritsa, ing pangwasané Gazi Evrenos Bey, ngrebut Gümülcine (Komotini), puseré Thrace Kulon. Kutha iku dadi markas ngarep, saka kono Evrenos Bey bakal nggawa serbuané menyang Makedonia. Kanthi mangkono pérangan Thrace sing mbentang nganti pesisir Aegea mlebu pangawasan Utsmaniyah lan dalan menyang Thessalonika kabukak.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna pindhah menyang Kepangéranan Dobruja lan dadi krajané", "2bfe73f9"], "d": ["Nalika Ketsaran Bulgaria pecah, Varna ing pesisir Segara Ireng gabung karo Kepangéranan Dobruja sing diadegaké Dobrotitsa lan didadèkaké krajan nagara cilik iku.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Sisih kuloné Plovdiv: digabungaké Tatarpazarcığı lan Ihtiman", "1664d0e1"], "d": ["Sawisé Plovdiv (Filibe) direbut ing taun 1372, Tatarpazarcığı ing pucuk ndhuwur lembah Maritsa lan Ihtiman (Ihtiman), sing nyekel lorong menga menyang Sofia, digabungaké karo pamaréntahan Utsmaniyah. Garis iki, sing ana ing tangané para panggedhé lokal sing dadi vasal sawisé Perang Chirmen, dipindhah menyang pamaréntahan langsung, saéngga dalan Plovdiv-Sofia dadi tanpa pedhot. Kemajuan iki minangka persiapan dalan menyang direbuté Sofia rolas taun sawisé.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Pambrontakan Savcı Bey — pambrontakan bebarengan pangéran lan putra mahkota Bizantium", "75198c33"], "d": ["Savcı Bey, putrané Murad I, lan Andronikos Palaiologos, putrané Kaisar Bizantium Ioannes V, mbrontak nglawan ramané dhéwé-dhéwé bebarengan ing Bursa lan Istanbul ing wiwitan Mei 1373. Persekutuan sing nyawijèkaké putra mahkota saka rong wangsa iki cepet ditumpes; Savcı Bey dicekel, mripaté diwutakaké, lan diukum pati. Tanggal 787 (1385) sing disebut tradisi Utsmaniyah kanggo pambrontakan iki salah; prastawané tiba pas sawisé taun-taun nalika Bizantium dadi vasal Utsmaniyah lan nuduhaké sepira raketé rong kraton kuwi.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Lembah Struma lan Mesta: digabungaké Kyustendil, Petrich, Nevrokop, lan Drama", "8c0980c4"], "d": ["Lembah Struma lan Mesta, sing ana ing tangané para panggedhé lokal Serbia lan Bulgaria sing wiwit mbayar upeti marang Utsmaniyah sawisé kamenangan Chirmen, dijupuk menyang pamaréntahan Utsmaniyah langsung lumantar majuné para bey tapel wates. Kanthi digabungaké Kyustendil, Petrich, Nevrokop, lan Drama, separo sisih wétan Makedonia kabukak, lan Thessalonika sarta Serres mlebu kalung pengepungan. Jembaré Rumeli ngidul-ngulon ing peta iku asil saka operasi iki.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Pungkasané Kabèylikan Eretna lan adegé Nagara Kadı Burhâneddin", "60dcaf57"], "d": ["Wangsa Eretna, sing lair ing taun 1335 saka kalungguhan gubernur Ilkhaniyah lan mréntah Anatolia Tengah, puseré ing Sivas lan Kayseri, suwéné patang puluh nem taun, bubar amarga padudon ing njero kraton. Kadı Burhâneddin, sing dadi wazir ing Mei 1378, sawisé nyingkiraké saingan-saingané, Kılıcarslan lan Hacı Şadgeldi, ngumumaké kasultanané ing mangsa gugur 1381, mungkasi kabèylikan iku, lan ngedegaké nagara sing dikenal nganggo jenengé. Kanthi mangkono tanggané Utsmaniyah ing wétan ganti tangan; garis Sivas-Kayseri sawisé iku bakal ana ing tangané Kadı Burhâneddin suwéné pitulas taun.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur ngrebut Herat: pungkasané wangsa Kart lan pindhahé Khurasan menyang Timuriyah", "15f6019e"], "d": ["Ing taun 1380, Khurasan pecah-belah amarga perebutan antarané Sarbadar, wangsa Kart, lan wangsa Muzaffariyah. Sawisé ngutus putrané, Miran Syah, menyang tlatah iku, Timur dhéwé maju menyang Herat lan, sawisé ngepung sawetara wektu, nampa kutha iku saka malik Kart, Ghiyath al-Din Pir Ali. Pambrontakan sing tuwuh sawisé dhèwèké lunga ditumpes kanthi banjir getih déning Miran Syah, lan wangsa Kart, sing mréntah ing Herat wiwit 1255, dipungkasi. Kabèh Khurasan, saka Mashhad nganti Nishapur, mlebu pamaréntahan Timuriyah ing tanggal iki.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Maju menyang jeroning Makedonia: direbuté Monastir lan Ohrid", "63bb7838"], "d": ["Monastir (Bitola) ing Via Egnatia lan Ohrid ing pinggir tlaga mlebu pamaréntahan Utsmaniyah nalika serbuan menyang arah Albania. Loro-loroné titik kunci ing dalan sing nuju Segara Adriatik; Ohrid uga puseré keuskupan agung Ortodoks sing paling tuwa ing Balkan. TDV nyathet yèn ora ana katrangan pasti bab tanggal direbuté Ohrid, lan diusulaké tanggal 787 (1385) sarta 797 (1395), sawisé sedané Marko Kraljević; ing kéné taun 1385 dadi dhasar. Ing abad-abad sabanjuré, Monastir bakal dadi salah siji puser militèr sing paling wigati ing Rumeli.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Perang Savra — kabukaké gapura Albania", "dda6671b"], "d": ["Amarga panggedhé Albania Karlo Thopia, sing kepepet nglawan wangsa Balšić, njaluk pitulungan, pasukan Utsmaniyah ngalahaké mutlak wadyabala Balša II ing dhataran Savra; Balša tiwas ing paprangan. Perang iki, sing dilakoni amarga diundang panggedhé pribumi, menèhi Utsmaniyah pengaruh tetep kapisan ing lemah Albania sing mbentang nganti pesisir Adriatik. Pulitik sing nggunakaké padudoné para panggedhé tlatah iku minangka kalodhangan bakal dadi cara sing ora owah ing penaklukan Balkan sajroné abad sabanjuré.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Ekspedisi Telung Taun' Timur: direbuté Azerbaijan lan Iran sisih lor", "2a98ec51"], "d": ["Timur, sing nalika ekspedisi Khurasan weruh saka cedhak kahanan Iran sing pecah-belah, maju mangulon ing taun 788 (1386). Ing operasi 1386-1388, sing kondhang minangka 'Ekspedisi Telung Taun', dhèwèké liwat Mazandaran, Luristan, lan Georgia mlebu Azerbaijan lan tekan Karabakh; Tabriz, Ardabil, Urmia, lan Nakhchivan mlebu pamaréntahan Timuriyah. Direbuté Iran sisih lor lan Azerbaijan uga dadi wiwitané padudon dawa karo Horde Emas, kaya sing biyèn dumadi antarané ulus Jochi lan wangsa Ilkhaniyah.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Perang Frenkyazısı lan pengepungan Konya — ekspedisi Karaman kapisan", "af4e5d77"], "d": ["Murad I dhéwé mangkat ing ekspedisi nglawan Karamanoğlu Alaeddin Ali Bey, sing sanajan dadi mantuné, ora seneng marang jembaré Utsmaniyah ing Anatolia Kulon; ing perang sing dumadi ing papan aran Frenk Yazısı, wadyabala Utsmaniyah sing kalatih lan kawentar pengalaman ngalahaké pasukan Karaman. Banjur bèntèng Konya dikepung, nanging kanthi diapurané Alaeddin Bey, kabèylikan iku ora diilangi kabèh. Ekspedisi iki babak pambuka saka étung-étungan dawa antarané Utsmaniyah lan Karaman, sing bakal suwéné seabad lan lagi rampung ing panggabungan pungkasan ing 1468.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Adegé Galangan Kapal Gallipoli — lairé armada Utsmaniyah", "47546241"], "d": ["Galangan kapal Nagara Utsmaniyah sing ditata kanthi bener sepisanan diadegaké ing 1390 déning Bayezid Yildirim ing Gallipoli, ing papan galangan tinggalan Bizantium. Utsmaniyah, sing nampa warisan pelayaran kabèylikan-kabèylikan Anatolia Kulon, kanthi mangkono sepisanan dadi kakuwatan segara sing gawé kapalé dhéwé. Galangan kapal iki, sing ana ing titik kunci Selat Dardanelles, dadi pangkalan utama armada Utsmaniyah suwéné siji setengah abad, wiwit pengepungan Istanbul nganti ekspedisi Segara Aegea.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamid-ili gabung karo Utsmaniyah: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Bayezid Yildirim, sing mangkat ing ekspedisi sawisé Karamanoğlu Alaeddin Bey nyerang Hamid-ili lan rakyaté sambat, ngrebut kabèh sisa lemah wangsa Hamid lan masrahaké pamaréntahané marang putrané, Isa Celebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Pungkasané wangsa Muzaffariyah: Syah Mansur kalah ing ngarep Shiraz", "5fd14eb8"], "d": ["Syah Mansur, panguwasa kuwat pungkasan saka wangsa Muzaffariyah sing wiwit 1318 mréntah ing Yazd, Fars, Isfahan, lan Kerman, sekutu karo sanak-sedulure lan obah nglawan Timur. Ing perang cedhak Shiraz, nalika salah siji emiré mbalik menyang pihak mungsuh, dhèwèké kélangan akèh-akèhé pasukané, kalah, lan dipatèni. Sawisé Timur uga matèni kabèh anggota wangsa, pangwasa Muzaffariyah rampung, lan Fars sarta Kerman digabungaké karo pamaréntahan Timuriyah.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Amasya digabungaké karo tlatah Utsmaniyah", "fe2860cf"], "d": ["Nalika operasi Bayezid Yildirim ing Anatolia Tengah, emir Amasya sing dikepung masrahaké kutha marang Utsmaniyah, lan Bayezid mlebu kutha ing taun 1393. Sultan masrahaké pamaréntahané marang putrané, Mehmed Celebi; minangka sancak pangéran, wiwit iku Amasya dadi salah siji papan pendhidhikan sing paling wigati tumrap wangsa Utsmaniyah. Papan liyané sing ucul ing tanggal sing padha: Ladik (Amasya), Merzifon, Osmancık, Çorum. Pilihan iki bakal nemtokaké ing Mangsa Interregnum sawisé, nalika Celebi Mehmed nindakaké perjuangan nyawijèkaké manèh nagara saka dhasar Amasya iki.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur ngrebut Baghdad — wangsa Jalayiriyah mlayu menyang Anatolia", "4d5602b3"], "d": ["Timur ngrebut Baghdad sawisé ngepung suwé; panguwasa kutha iku, Sultan Ahmed saka Jalayiriyah, mlayu mangulon lan ngungsi dhisik menyang wangsa Mamluk, banjur menyang kraton Utsmaniyah. Kanthi mangkono jembaré Timur mangulon sepisanan sesambungan langsung karo laladan pengaruh Utsmaniyah. Mata ranté kapisan saka memungsuhan antarané rong panguwasa iku diwiwiti saka kéné.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Direbuté Varna ing pesisir Segara Ireng", "a84b2abf"], "d": ["Nalika tlatah Ketsaran Bulgaria ing antarané Kali Donau lan Segara Ireng dipepet, Varna, plabuhan paling gedhé ing pesisir, mlebu pamaréntahan Utsmaniyah. Direbuté plabuhan iki mbukak dalan kanggo maju menyang arah Dobruja lan menèhi Utsmaniyah dhermaga gedhé kapisan ing pesisir kulon Segara Ireng. Varna uga bakal dadi papan kamenangan taun 1444, sèket siji taun sawisé, nalika wadyabala Salib diancuraké.", "2e425501"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Runtuhé Nagara Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, sing ditawan déning panguwasa Aq Qoyunlu Qarayuluk Osman Bey, nawakaké supaya diculaké kanthi gantiné Sivas dipasrahaké, nanging rakyat kutha nglawan lan sultan diukum pati ing ngarep témbok bèntèng. Sanajan para pinisepuh Sivas nglungguhaké putrané, Alaeddin Ali Celebi, dadi pangarsa, ngadhepi tekanan Aq Qoyunlu para pinisepuh njaluk pitulungan marang Bayezid Yildirim; pasukan Utsmaniyah ing pangwasané Suleyman Celebi ngalahaké Qarayuluk lan nguwasani kutha. Kanthi mangkono Nagara Kadı Burhâneddin dadi sajarah, lan Sivas, Tokat, Niksar, sarta Kayseri digabungaké karo tlatah Utsmaniyah. Papan liyané sing gabung ing tanggal sing padha: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Tantangané Timur: panjaluk mbalèkaké buronan ditolak", "33790bc8"], "d": ["Amarga ditekan Timur, Sultan Ahmed saka Jalayiriyah lan pangarsa Qara Qoyunlu, Qara Yusuf, ngungsi menyang tlatah Utsmaniyah; Timur njaluk supaya buronan loro iku dibalèkaké, lan Bayezid Yildirim nolak. Banjur rong panguwasa iku wiwit ijol-ijolan layang sing isiné pangasoran abot saka loro-loroné. Dhasar idhéologi perang diadegaké lumantar surat-suratan iki, sadurungé ana siji prajurit waé sing obah.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Darusyifa Yildirim ing Bursa — rumah sakit Utsmaniyah kapisan", "5f0dc59a"], "d": ["Ing taun-taun nalika Bayezid Yildirim ngedegaké Masjid Agung (Ulucami) sing éndah ing Bursa, dhèwèké uga menèhi kutha iku siji darusyifa (rumah sakit); iki mata ranté kanggo ngèlmu kedhokteran saka program wakaf amba sing dumadi saka imaret, madrasah, han, lan jembatan. Bangunan iki, rumah sakit kapisan sing diadegaké nagara, uga dadi sekolah kedhokteran sing nggulawenthah dhokter, lan nemtokaké modhèlé lembaga kasarasan Utsmaniyah. Karya iki, sing rampung mung rong taun sadurungé bencana Ankara, klebu mata ranté pungkasan saka gegayuhané Yildirim ndadèkaké Bursa krajan kakaisaran.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur ngremuk Sivas nganti rata", "f4d79de6"], "d": ["Timur, sing maju menyang Sivas kanthi dituntun Qarayuluk Osman Bey saka Aq Qoyunlu lan emir Erzincan, Mutahharten, ngepung kutha iku suwéné wolulas dina lan, sawisé nampa nyerahé kanthi janji ora bakal ana getih sapa waé sing diwutahaké, banjur nindakaké pambantaian gedhé; para pambela diuncalaké menyang paritan lan diurug urip-urip. Bangunan-bangunan wigati kutha, wiwit saka témbok bèntèng, dirusak, lan Sivas ambruk sacara demografi. Iki gebugan gedhé kapisan sing ditibakaké Timur marang tlatah Utsmaniyah, rong taun sadurungé Perang Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid Yildirim ngrebut manèh Erzincan lan Kemah", "7047ca08"], "d": ["Nggunakaké kalodhangan nalika Timur mangkat ing ekspedisi Suriah, Bayezid Yildirim ngrebut Erzincan lan Kemah saka tangané emir Erzincan, Mutahharten, sing dadi bawahané Timur. Sanajan ora campur tangan nalika Sivas dirusak, tumindak iki ateges tantangan langsung marang laladan pengaruhé Timur ing Anatolia Wétan. Wiwit iku sesambungané rong panguwasa kuwi ora bisa didandani manèh.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum saka Timur sing dikirim saka Tabriz — patang sarat", "3e1ac50e"], "d": ["Lumantar utusan sing dikirim saka Tabriz, Timur ngabaraké patang sarat: Kemah dibalèkaké marang Mutahharten, lemah sing dijupuk saka para bey Anatolia dibalèkaké marang sing duwé, siji pangéran Utsmaniyah dikirim dadi sandera sarta topi (külah) lan sabuk ditampa minangka tandha tundhuk, lan Qara Yusuf dipasrahaké. Bayezid ora nampa siji-sijia; sanajan para pangarsa nagara meksa lan Mutahharten dadi perantara, rembugan iku gagal. Timur wis mantep arep mungkasi prakara Anatolia kanthi cetha sadurungé mangkat ing ekspedisi menyang Cina.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Kabèylikan Saruhanoğulları diadegaké manèh — Manisa ucul saka Utsmaniyah", "ac747b05"], "d": ["Telung minggu sawisé kakalahan ing Ankara, kanthi panyengkuyungé Timur, Orhan Bey dadi pangarsa kabèylikan lan tlatah Saruhan mardika manèh. Tlatah sing puseré ing Manisa ilang saka peta rolas taun sawisé digabungaké karo Utsmaniyah ing taun 1390. Iki salah siji penerapan kapisan, sing tanggalé dingertèni kanthi cetha, saka pulitik Timur nguripaké manèh para kabèylikan.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Suleyman mlayu menyang Rumeli nggawa bandha nagara", "0a2b7363"], "d": ["Emir Suleyman, sing nggawa bandha nagara ing Bursa, arsip, kulawarga, lan sadulur-sadulure, nyabrang nganggo kapal saka Gemlik menyang Güzelcehisar (Anadoluhisarı), saka kono tekan Gallipoli lan ngumumaké pangwasané ing Edirne. Pamindhahé arsip lan bandha nagara menyang Rumeli iku wiwitané pusat abot Utsmaniyah geser menyang Balkan sajroné sak generasi. Ing peta, wiwit tanggal iki Rumeli digambar nganggo wernané Emir Suleyman dhéwé.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur ngadegaké manèh kabèylikan-kabèylikan Anatolia — manunggalé bangsa Turk pecah", "15187774"], "d": ["Sawisé menang ing Ankara, Timur mbalèkaké para bey sing ana ing sandhingé menyang tlatah lawasé. Mehmed Bey lan Ali Bey saka Karamanoğlu diparingi tlatah Karaman bebarengan karo Kayseri, Kırşehir, Sivrihisar, lan Beyşehir; Yakub Bey II saka Germiyanoğlu nampa Kütahya lan tlatah Germiyan; Isfendiyar Bey saka Candaroğlu nampa Çankırı lan Kalecik, minangka tambahan saka garis Kastamonu-Sinop. Tlatah Aydın, Menteşe, lan Teke uga bali menyang wangsa lawasé. Manunggalé Turk ing Anatolia sing dibangun Bayezid Yildirim sajroné sepuluh taun pecah mung sajroné siji mangsa panas; ing peta, kabèylikan-kabèylikan iki katon manèh nganggo wernané dhéwé-dhéwé. Papan liyané sing ganti tangan ing proses sing padha: Aksaray, Denizli, Ereğli (Konya), Ermenek, Ilgın, Karapınar, Kayseri, Konya, Kırşehir, Kütahya, Sivrihisar, Söke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur ngrebut Izmir saka ksatria Santo Yohanes", "66dd1dd4"], "d": ["Timur, sing mudhun mangulon liwat Kütahya, Denizli, Aydın, Ayasuluk, lan Tire, ngepung lan ngrebut kutha pesisir Izmir, sing wiwit taun 1344 ana ing tangané wong Kristen. Sawisé kanthi cepet ngrebut bèntèng iki, sing wis pirang-pirang taun ora bisa direbut Bayezid Yildirim, lan uga ngrebut bèntèng-bèntèng sakiwa-tengené, Timur ninggalaké tlatah Aydın marang sing duwé lawasé lan bali mangétan. Sawisé iku kutha kuwi mlebu pamaréntahan Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Celebi ngrebut Bursa — lair bagéan Anatolia", "955128c1"], "d": ["Isa Celebi, sing sawisé kakalahan ing Ankara mundur menyang tlatah Karesi, ngrebut Bursa nalika Timur ana ing Izmir. Ing krajan lawas sing dijarah lan diobong prajurité Timur, dhèwèké ngumumaké pangwasané lan nyithak dhuwit atas asmané dhéwé; ing Januari 1403 ing Anatolia dhèwèké diakoni kanthi sesebutan 'panguwasa wong Turk'. Ing peta, bagéan iki, sing mbentang sauruté pesisir Asia Segara Marmara, katon nganggo wernané Isa Celebi dhéwé.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Munduré Timur saka Anatolia", "93a98839"], "d": ["Nalika nampa kabar yèn Bayezid Yildirim séda ing Akşehir, Timur nganggep urusané ing Anatolia wis rampung lan mangétan. Sing ditinggal yaiku para kabèylikan sing wis nyatakaké setya marang dhèwèké lan para pangéran Utsmaniyah sing padha memungsuhan; sawetara kutha, kayata Sivas, dipasrahaké ing tangané emir bawahané Timur, kayata Mezid Bey. Timur ora tau bali manèh menyang Anatolia, nanging tatanan pecah-belah sing diadegaké lumaku suwéné sepuluh taun.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Suleyman nyabrang menyang Anatolia: Bursa tiba ing tangané", "9b27aa5f"], "d": ["Krungu kakalahané Îsâ Celebi, Emir Suleyman nyabrang menyang Anatolia bebarengan karo Çandarlı Ali Pasya kanthi wadyabala sing kuwat lan ngrebut Bursa; cathetan Maret 1404 nuduhaké yèn Karadeniz Ereğli uga ana ing pamaréntahané. Celebi Mehmed ora kuwat nglawan Suleyman, sing énggal nguwasani Rumeli lan akèh-akèhé Anatolia. Papan liyané sing pindhah saka Celebi Mehmed menyang Emir Suleyman ing proses sing padha: Akyazı, Anadolu Hisarı, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, Bèntèng Aydos, Ayvalık, Balıkesir, Behramkale (Assos), Bergama, Beykoz, Biga. Ing peta, wiwit tanggal iki nganti Celebi Mehmed ngrebut manèh Bursa (1410), pesisir loro iku katon nganggo siji werna, ing bagéané Emir Suleyman.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Perang Dhataran Yenişehir — Celebi Mehmed mundur menyang Amasya", "f1568288"], "d": ["Celebi Mehmed, sing wis kélangan Bursa lan Ankara, dikalahaké Emir Suleyman ing dhataran Yenişehir, kélangan kabèh asil sing wis diranggèh ing Anatolia Kulon, lan mundur menyang pangkalané ing Tokat-Amasya. Sawisé kakalahan iki, dhèwèké ngéndhani tempuran langsung lan nguwataké wibawané ing pedalaman Anatolia. Kanthi mangkono diwiwiti babak sepi sing paling dawa ing Mangsa Interregnum.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Suleyman ngrebut Ankara saka Celebi Mehmed", "d6a2acd6"], "d": ["Ing taun 1406, Emir Suleyman ngepung Ankara, sing sawisé Timur mundur saka Anatolia tetep ana ing tangané Celebi Mehmed. Panjaga bèntèng, Yakub Bey, nahan sawetara wektu, nanging amarga akal-akalané wazir agung Çandarlı Ali Pasya, dhèwèké masrahaké bèntèng marang Suleyman. Banjur Celebi Mehmed sarujukan karo Mehmed Bey saka Karamanoğlu lan obah nglawan Suleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Celebi Mehmed ngrebut manèh Sivas saka Mezid Bey bawahané Timuriyah", "90079b0c"], "d": ["Sawisé serbuan Timuriyah, pamaréntahan Sivas dipasrahaké marang Mezid Bey, bawahané Timur. Celebi Mehmed ing Amasya ngutus panglimané, Bayezid Pasya, kanggo ngrebut kutha iku, lan sawisé perlawanan sing sengit, Sivas kaping pindho tiba ing tangané wangsa Utsmaniyah. Kanthi mangkono bagéané Mehmed tekan tapel wates lawasé ing wétan, nem taun sawisé Perang Ankara.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Pungkasané wangsa Artuqiyah: Mardin dipasrahaké marang Qara Qoyunlu", "15b06f33"], "d": ["Wangsa Artuqiyah, sing wiwit 1106 mréntah ing Mardin lan dadi cabang wangsa sing paling dawa umuré, ora bisa tahan ngadhepi tekanan Aq Qoyunlu. Malik Ahmed, sing weruh yèn ora bisa mbélani kutha, sarujukan karo panguwasa Qara Qoyunlu Qara Yusuf lan masrahaké Mardin marang dhèwèké. Kanthi mangkono pangwasa Artuqiyah sing luwih saka telung abad rampung; Mardin lan sakiwa-tengené dadi gelanggang perjuangan Qara Qoyunlu-Aq Qoyunlu nganti pindhah menyang Utsmaniyah seabad sawisé.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Perang Yambol — Musa Celebi mlebu Edirne", "8f978408"], "d": ["Musa Celebi, sing nyabrang menyang Rumeli liwat Wallachia, kanthi panyengkuyungé Wallachia lan Serbia ngalahaké mutlak pasukané Emir Suleyman ing Yambol lan mlebu Edirne. Ing Mangsa Interregnum, sepisanan Rumeli ucul saka tangané Emir Suleyman. Nanging pangwasané ora langgeng; patang sasi sawisé dhèwèké kalah ing Kosmidion lan mundur menyang pedalaman Balkan.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Perang Inceğiz — kakalahan kapisané Celebi Mehmed ing Rumeli", "3c35cd43"], "d": ["Celebi Mehmed, sing nyabrang menyang Rumeli nganggo kapal-kapal Bizantium, perang lawan Musa Celebi ing Inceğiz; Musa, kanthi pitung èwu Janissari ing pangwasané, ngalahaké Mehmed, lan Mehmed kepeksa bali menyang Anatolia. Kakalahan iki ndadèkaké Mehmed ora manèh milih perang langsung, nanging strategi narik para bey tapel wates Rumeli lan despotat Serbia menyang pihaké. Dhasar kamenangan Çamurlu sangang sasi sawisé disiapaké lumantar diplomasi iki.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Pengepungan Konya lan prajanjian karo wangsa Karaman — Hamid-ili, Said-ili, Beyşehir, Seydişehir, lan Akşehir direbut manèh", "0996257e"], "d": ["Celebi Mehmed nganakaké ekspedisi gedhé nglawan wangsa Karamanoğlu, sing ing Mangsa Interregnum nyerang tlatah Utsmaniyah sarta ngepung lan ngobong Bursa, banjur ngepung Konya ing sasi Muharam 818. Karamanoğlu Mehmed Bey II kepeksa njaluk tentrem; asilé prajanjian, Hamid-ili (tlatah Isparta) lan Said-ili gabung manèh karo tlatah Utsmaniyah, Beyşehir, Seydişehir, lan Akşehir uga dibalèkaké; Sivrihisar, sing ing 1402 diparingaké Timur marang wangsa Karaman, uga bali menyang Utsmaniyah. Ekspedisi iki, nalika manunggalé Anatolia sing pecah amarga Perang Ankara wiwit ditambal, klebu alesan nyata kenapa Celebi Mehmed dianggep 'pangadeg kapindho'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Direbuté Izmir saka Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["Izmir, puseré Aydınoğlu Cüneyd Bey, sing sajroné Mangsa Interregnum bola-bali ganti pihak ing antarané para pangéran, direbut Celebi Mehmed sawisé dikepung sepuluh dina; Cüneyd diapura lan dikirim dadi sancak beyi ing Nikopolis. Kanthi mangkono kutha sing dibalèkaké Timur marang wangsa Aydın ing taun 1402 bali menyang Utsmaniyah sawisé telulas taun. Cüneyd bakal ngrebut manèh kutha iku ing taun 1422, lan prakarané lagi dipungkasi déning Murad II ing 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Torlak Kemal diukum pati — Saruhan tetep dadi duwèké Utsmaniyah", "8a09dbf1"], "d": ["Torlak Kemal, sing mimpin sayap Anatolia Kulon saka gerakan Sheikh Bedreddin, dikalahaké ing tlatah Manisa lan diukum pati. Sawisé tanggal iki, tlatah Saruhan tetep mlebu pangawasan Utsmaniyah, lan kabèylikan sing diuripaké manèh déning Timur ing taun 1402 dadi sajarah. Kanthi mangkono sisa-sisa pulitik pungkasan Mangsa Interregnum ing Anatolia Kulon diresiki.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Direbuté Valona, Berat, lan Kanina", "1e1949b8"], "d": ["Ing taun 1417, Utsmaniyah nglebokaké Valona (Avlonya) ing pesisir Adriatik, bebarengan karo kutha Berat lan Bèntèng Kanina ing pedalaman negara, ing sangisoré pangwasané. Setaun sawisé, usahané Venesia ngrebut manèh kutha iku gagal, lan kanthi diadegaké tatanan sancak ing kono, wibawa Utsmaniyah dadi tetep. Direbuté Valona ndadèkaké Utsmaniyah sepisanan duwé plabuhan langsung ing Adriatik, saéngga nduwèni batu loncatan nyabrang segara ngadhepi Italia.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Direbuté manèh Anatolia Tengah: Kayseri lan Kırşehir", "204eacb3"], "d": ["Kutha-kutha Anatolia Tengah sing ing Mangsa Interregnum tiba ing tangané wangsa Karamanoğlu bali menyang pamaréntahan Utsmaniyah nalika ekspedisi Celebi Mehmed kanggo nata manèh nagara. Kanthi digabungaké Kayseri lan Kırşehir, cekungan Kızılırmak sing ilang ing Perang Ankara sebagéan gedhé direbut manèh. Kemajuan iki terusané kawicaksanan nuju mangétan sing diwiwiti kanthi pengepungan Konya patang taun sadurungé.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Wangsa Mamluk maringaké Kayseri marang Nasir al-Din Muhammad saka Dulkadir", "aad4b00c"], "d": ["Wadyabala Mamluk sing mangkat nglawan Karamanoğlu Mehmed Bey ndhudhuki Kayseri; panglima Mamluk ninggalaké kutha iku sakiwa-tengené marang Nasir al-Din Muhammad saka Dulkadir banjur bali menyang negarané.", "8cd84dc4"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Panumpesan pungkasan wangsa Teke: direbuté Antalya", "e65565b2"], "d": ["Kabèylikan Tekeoğulları, sing sawisé Perang Ankara diadegaké manèh amarga diuripaké Timur, rampung nalika pasukan Utsmaniyah ing pangwasané Hamza Bey ngepung Antalya; Osman Celebi, wong wigati pungkasan saka kabèylikan iku, disingkiraké. Kanthi mangkono tlatah Teke ing pesisir Segara Tengah tetep gabung karo Utsmaniyah sawisé pisah selikur taun. Kabèylikan iku, minangka cabang sing misah saka wangsa Hamid, wis mréntah ing Antalya wiwit 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Ekspedisi Morea déning Turahan Bey lan dirubuhaké Témbok Hexamilion", "c6c2706d"], "d": ["Nalika Bizantium nyengkuyung Mustafa Celebi, sing dadi saingan pangaku dhampar, Murad II ngutus Turahan Bey menyang Morea. Turahan Bey ngrubuhaké témbok Hexamilion sing nutup Tanah Genting Korintus saka pucuk nganti pucuk, mlebu semenanjung, lan nuwuhaké karusakan gedhé. Tentrem diraih kanthi sarat témbok ora bakal dibangun manèh lan pajeg taunan dibayar; kanthi mangkono Despotat Morea ditinggal tanpa pertahanan sacara militèr, lan dhasar penaklukan pungkasan ing 1460 disiapaké telung puluh pitu taun sadurungé.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Biara-biara Athos mlebu pangayoman Utsmaniyah", "562de5ea"], "d": ["Ing taun-taun nalika Thessalonika dikepung, républik biara Athos (Aynaroz) ing semenanjung wétané Chalkidiki sowan marang Murad II, njaluk pangayoman, lan nampa pangwasa Utsmaniyah. Hak milik lan hak ibadahé para biarawan dijamin; minangka gantiné pajeg, biara-biara diparingi kamardikan ing urusan njeroné. Tatanan iki dadi conto sesambungan pangayoman sing paling dawa umuré antarané Utsmaniyah lan lembaga Ortodoks, lan lumaku limang abad.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Panggabungan Kabèylikan Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Amarga ditekan beylerbeyi Amasya, Yörgüç Pasya, Taceddinoğlu Hüsameddin Hasan Bey masrahaké kunci-kunci negarané, sing puseré ing Niksar, ing taun 830 (1427); dhèwèké diparingi siji sancak ing Rumeli. Kanthi mangkono rampung kabèylikan sing diadegaké ing paroan kapindho abad kaping patbelas lan sing tapel watesé kala-kala tekan Kelkit, Amasya, Samsun, Ordu, lan Giresun. Ing taun sing padha, lemah duwèké wangsa Hacıemiroğulları uga didaftar (tahrir) lan digabungaké karo sancak Canik; jaman kabèylikan ing Segara Ireng sisih tengah rampung.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Beograd dipasrahaké marang Hungaria — Prajanjèn Tata", "62481183"], "d": ["Sawisé sédané despot Serbia Stefan Lazarević, miturut Prajanjèn Tata sing digawé antarané raja Hungaria Sigismund lan ahli waris Đurađ Branković, bèntèng Beograd dipasrahaké marang Hungaria. Bèntèng sing ngadeg ing panggonan Kali Donau lan Sava ketemu iki nganti wektu iku ana ing tangan despotat Serbia lan kanggo Utsmaniyah minangka kunciné lawang sing mbukak menyang Éropah Tengah. Pasrah iki ndadèkaké Beograd sajrone satus taun dadi alangan paling atos ing ngarep majuné Utsmaniyah: pengepungan 1440 lan 1456 gagal, lan bèntèng iku lagi tiba ing 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin pindhah saka panjaga Qara Qoyunlu menyang Qarayuluk Osman Bey saka Aq Qoyunlu", "d82bc97f"], "d": ["Mardin, sing direbut Qara Yusuf ing taun 1409, diprentah Qara Qoyunlu lumantar para gubernur; Emir Nasir, sing ditinggal dadi panjaga, masrahaké kutha iku marang Qarayuluk Osman Bey saka Aq Qoyunlu ing taun 835 (1432). Pamaréntahan Aq Qoyunlu lumaku nganti wiwitan abad kaping nembelas.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Wangsa Karamanoğlu ngrebut Kayseri saka wangsa Dulkadir", "2b09e8e8"], "d": ["Kanthi kamenangan nglawan wangsa Dulkadir, bey Karaman nambahaké Kayseri, Ürgüp, Develi Karahisarı, lan Uçhisar menyang tlatahé.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Prastawa Buçuktepe — pambrontakan Janissari kapisan lan baliné Murad II menyang dhampar", "6388dda1"], "d": ["Prastawa Buçuktepe, sing mbledhos ing Edirne lan dadi pambrontakan Janissari kapisan sing dingertèni sajarah, diwiwiti saka panjaluk supaya ulufe (bayaran) ditambah setengah akçe lan dipungkasi kanthi dilèngsèraké Mehmed II sing isih enom saka dhampar. Murad II mangkat kesusu saka Manisa tanggal 8 Safar 850 lan miwiti pangwasané kapindho. Prastawa iki dadi tandha kapisan yèn korps kapıkulu wis dadi kakuwatan sing duwé swara ngenani dhampar, lan mbentuk sikap ati-ati Sang Penakluk marang Janissari sing lumaku sauripé.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Digabungaké pesisir Epirus: Arta lan Preveza", "796f7ecf"], "d": ["Sangalas taun sawisé Ioannina nyerah ing taun 1430, Arta lan Preveza ing pérangan pesisir Despotat Epirus uga mlebu pamaréntahan Utsmaniyah. Kanthi mangkono Teluk Ambrakia sing menga menyang Segara Ionia bisa diawasi lan sesambungan segarané Ioannina dadi jangkep. Preveza iku titik kunci teluk sing sangang puluh taun sawisé bakal menèhi jeneng marang kamenangané Barbarossa sing kondhang.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Sédané Murad II lan jumenengé Mehmed II kaping pindho", "8f8256ad"], "d": ["Murad II, sing lara sawisé palakramané putrané, séda ing Edirne tanggal 1 Muharam 855 (3 Februari 1451). Mehmed II sing umur sangalas taun jumeneng ing dhampar Utsmaniyah kaping pindho tanggal 16 Muharam 855 (18 Februari 1451) — wektu iki tetep. Baliné panguwasa enom, sing limang taun sadurungé dilèngsèraké saka dhampar ing Buçuktepe, iku wiwitané pamaréntahan sing, rong taun sawisé, bakal dimakuthani kanthi penaklukan Istanbul lan ngowahi Kabèylikan Utsmaniyah dadi kakaisaran donya.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Pengepungan Kefe kapisan déning pasukan gabungan Utsmaniyah-Krimea", "e346d163"], "d": ["Khan Krimea Hacı Giray, sing sarujukan karo Mehmed Sang Penakluk ing Juni 1454, ngepung Kefe saka dharatan nganggo 7000 prajurit jaranan; armada Utsmaniyah sing dumadi saka sèket nganti sawidak kapal galley uga njupuk papan ing tengah segara. Kefe, sing ana ing tangané Genoa, bisa ndadèkaké pengepungan diudhari kanthi mbayar upeti, lan penaklukan pungkasan ditundha nganti selikur taun sawisé, ing 1475. Operasi bebarengan kapisan iki dadi conto kapisan gotong royong militèr Utsmaniyah-Krimea, sing bakal dibalèni ing penaklukan pungkasan Kefe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Direbuté pulo-pulo Aegea sisih lor: Bozcaada, Imbros, lan Thasos", "76575895"], "d": ["Sanalika sawisé penaklukan Istanbul, Mehmed Sang Penakluk nuju pulo-pulo ing cangkem Aegea Selat Dardanelles kanggo ngamanaké dalan segarané krajan anyar; Bozcaada (Tenedos) lan Imbros (Imroz) direbut saka Bizantium, lan Thasos saka kulawarga Gattilusio sing asalé saka Genoa. Pulo-pulo iki, sing ngunci loro pinggiré Selat, sawisé iku dadi mata ranté kapisan garis pasokan pangan lan pertahanan Istanbul. Amarga campur tangané armada Kepausan lan Venesia, pangwasa sawetara wektu bola-bali ganti lan lagi tetep ing taun 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Penaklukan Kosovo: direbuté Pristina lan Novi Pazar", "d7ed2345"], "d": ["Wadyabala Utsmaniyah sing maju nglawan Despotat Serbia ngrebut Pristina ing dhataran Kosovo lan Novi Pazar (Yenipazar), puseré tlatah Raška; ing operasi sing padha, Novo Brdo, sing kondhang amarga tambang slakané, uga direbut. Kanthi mangkono separo sisih kidul Serbia digabungaké langsung karo pamaréntahan Utsmaniyah, lan despotat ing Smederevo dipedhot saka tlatah puseré. Penaklukan iki langkah sing nemtokaké ing dalan menyang panggabungan kabèh Serbia patang taun sawisé.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Ipek (Peć) mlebu pamaréntahan Utsmaniyah — salah siji puser sancak Dukakin", "19511588"], "d": ["Sanalika sawisé ekspedisi Serbia déning Mehmed Sang Penakluk ing taun 1455, Ipek, puseré kapatriarkan Serbia, pindhah menyang pamaréntahan Utsmaniyah; ing sumber Utsmaniyah ora ana cathetan bab pamindhahan iki. Kutha cilik iku suwé-suwé dadi kutha cilik Muslim lan dadi salah siji papan dunungé sancak beyi ing sancak Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Direbuté Enez lan Samothrace — jangkepé pesisir Thrace Kulon", "106e723b"], "d": ["Enez (Ainos), ing papan Kali Maritsa mili menyang segara, direbut saka kulawarga Gattilusio sing asalé saka Genoa, sing wis wolung puluh taun nyekel papan iku; pulo Samothrace sing mèlu Enez uga direbut ing operasi sing padha. Kanthi tibané Enez, sabuk pesisir Thrace Kulon dadi lemah Utsmaniyah sing tanpa pedhot saka Thessalonika nganti Gallipoli. Sing isih ana ing tangané kulawarga Gattilusio mung Lesbos (Midilli); pulo iku uga bakal direbut nem taun sawisé.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Gagalé pengepungan Beograd", "3d53a604"], "d": ["Sawisé penaklukan Istanbul, Mehmed Sang Penakluk ngepung Beograd, sing dianggep kuncine Éropah Tengah; nanging bala bantuan sing digawa John Hunyadi saka Kali Donau lan para relawan sing diklumpukaké juru khotbah Perang Salib Capistrano nyegah bèntèng tiba. Sultan, sanajan nuduhaké kawanènan pribadiné ing ngarep pengepungan, kapeksa mundur amarga tatu. Kagagalan iki bakal nutup tapel wates Hungaria marang majuné Utsmaniyah suwéné sawidak limang taun; Beograd lagi bisa direbut ing taun 1521 déning Suleyman Sang Pembuat Undhang-undhang.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Direbuté Morea sisih lor: Balyabadra (Patras)", "c08a8509"], "d": ["Pasukané Mehmed Sang Penakluk, sing ing taun-taun sing padha karo panggabungan Serbia nuju Despotat Morea, ngrebut Balyabadra (Patras) ing sisih lor-kulon semenanjung. Plabuhan sing nyekel cangkemé Teluk Korintus iki minangka kunci mlebu Morea liwat dharatan; direbuté nyiapaké dhasar penaklukan pungkasan rong taun sawisé. Kutha iku dhermaga gedhé pungkasan sing dienggo para despot Bizantium sesambungan karo donya Latin.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Direbuté pesisir kulon Segara Ireng: Amasra", "f43608fc"], "d": ["Amasra, koloni Genoa sing dibèntèngi ing pesisir kulon Segara Ireng, nyerah tanpa nglawan amarga ditekan bebarengan déning armada lan pasukan dharatan Mehmed Sang Penakluk. Plabuhan ing pesisir Bartın-Zonguldak iki ngadeg minangka kanthong Latin ing antarané tlatah wangsa Candar lan Utsmaniyah; kanthi direbuté, pesisir dadi manunggal. Tibané Amasra iku langkah kapisan ekspedisi gedhé Segara Ireng sing rong taun sawisé (1461) bakal diarahaké menyang Sinop lan Trebizond.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Penaklukan pulo Lesbos (Midilli)", "fe17aeba"], "d": ["Wadyabala Utsmaniyah ing pangwasané Mehmed Sang Penakluk ngrebut Lesbos ing sasi Zulhijah 866, sawisé pengepungan sing cendhak nanging sengit, saka kulawarga Gattilusio sing asalé saka Genoa, lan nggabungaké. Tibané pulo paling gedhé ing Aegea sisih lor uga numpes pangkalan wigati pungkasané wong Genoa ing tlatah kuwi. Amarga cedhak karo pesisir Anatolia, wiwit iku pulo kuwi bakal dadi pos ngarep armada Utsmaniyah, lan uga mlebu sajarah pelayaran minangka papan tuwuhé para sadulur Barbarossa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Wiwitané Perang Utsmaniyah-Venesia sing suwéné nem belas taun", "563ddb68"], "d": ["Kanggo ngendheg majuné Utsmaniyah ing Morea lan Aegea, wong Venesia miwiti perang ing 1463 kanthi sekutu karo para panguwasa Karaman lan Aq Qoyunlu. Strategi ngepung iki, sing disusun karo Uzun Hasan ing wétan, Venesia ing kulon, lan Karaman ing tengahé, meksa Sang Penakluk perang ing pirang-pirang front bebarengan. Perjuangan sing suwéné nem belas taun iki bakal ngemot kabèh operasi gedhé jaman iku, saka Otlukbeli nganti ekspedisi Albania, lan lagi rampung karo Prajanjian Istanbul 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Penaklukan sebagéan gedhé Herzegovina: Trebinje lan Mostar", "f54c0100"], "d": ["Lemah duwèké Adipati Herzegovina Stjepan Vukčić-Kosača, sing ngedegaké pamaréntahan sing misah saka Bosnia, telung taun sawisé runtuhé Karajan Bosnia sebagéan gedhé pindhah menyang pamaréntahan Utsmaniyah: ing sisih kidul, Trebinje direbut ing 1466 \"bebarengan karo meh kabèh tlatah Herzegovina\". Mostar, sing tuwuh ing sakiwa-tengené rong bèntèng cilik ing jembatan Kali Neretva, mesthiné uga direbut sadhéla sadurungé penaklukan Blagaj, puseré Herzegovina, ing 1466-1468; ing daftar ringkes (icmal tahrir) Bosnia taun 1468-1469, papan iku kacathet kanthi jeneng \"Köprülü Hisar\". Penaklukan Herzegovina, kalebu sisa bèntèng-bèntèngé kadipatèn, rampung ing 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Ekspedisi Albania kapindho — Sang Penakluk dhéwé maju nglawan Skanderbeg", "9cdd2bfa"], "d": ["Kanggo mecah perlawanané Skanderbeg, sing wis luwih saka seprapat abad, Mehmed Sang Penakluk ing 1466-1467 nganakaké ekspedisi gedhé sing dipimpin dhéwé. Wadyabala Utsmaniyah ngepung Akçahisar (Kruja) lan mbangun Bèntèng Ilbasan (Elbasan) supaya tlatah iku bisa diawasi. Ekspedisi iki, sanajan matahaké geger perlawanan Albania, ora kasil ngrubuhaké bèntèng; tundhuké tlatah iku sakabèhé bakal mbutuhaké sepuluh taun sawisé sedané Skanderbeg.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Runtuhé Nagara Qara Qoyunlu: Jahan Syah dipatèni", "30bc6358"], "d": ["Panguwasa Qara Qoyunlu Jahan Syah, sing diserbu nalika bali saka ekspedisi nglawan Uzun Hasan amarga mangsa adhem wis teka, dipatèni nalika mlayu ing antarané Bingöl lan Kiğı. Sawisé gebugan iki nagara ora bisa pulih; panguwasa pungkasan, Hasan Ali, ditawan lan dipatèni ing 1469 déning Uğurlu Mehmed, putrané Uzun Hasan. Kanthi mangkono pangwasa Qara Qoyunlu, sing meh seabad ana ing Anatolia Wétan, Azerbaijan, lan Irak, pindhah menyang Aq Qoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Sédané Skanderbeg — sirnané perlawanan Albania", "9158c35f"], "d": ["Skanderbeg, sing sanajan digulawenthah ing kraton Utsmaniyah, mbrontak ing taun 1444 sawisé kakalahan Izladi lan nglawan ing Albania luwih saka seprapat abad, séda ing Lezhë (Leş), papan pangungsèné. Perlawanan iki, sing ing jaman Murad II lan Sang Penakluk bola-bali ngrepotaké wadyabala Utsmaniyah, kélangan pimpinan pusat amarga sedané. Kanthi ambruké front Albania sing disengkuyung Kepausan lan Venesia, sajroné sepuluh taun Utsmaniyah ngrebut Akçahisar lan Shkodër sarta nggabungaké tlatah iku kanthi tetep menyang lemahé.", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Kakalahan ing Racova (Vaslui) ing Moldavia", "a1a74bf7"], "d": ["Voivode Moldavia, Stefan Agung (Stefan cel Mare), mancing pasukan Utsmaniyah ing pangwasané beylerbeyi Rumeli, Hadım Suleyman Pasya, menyang lemah rawa lan ngalahaké kanthi abot. Kakalahan iki, salah siji kakalahan dharatan paling abot ing jaman Sang Penakluk, nuwuhaké kumandhang gedhé ing Éropah lan ndadèkaké Stefan kondhang ing donya Salib. Taun sabanjuré sultan bakal mangkat dhéwé ing ekspedisi kanggo males.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Kamenangan Akdere (Valea Albă) — ekspedisi Moldavia", "45a66791"], "d": ["Mehmed Sang Penakluk, sing mangkat dhéwé ing ekspedisi kanggo males kakalahan Racova setaun sadurungé, kanthi wadyabala Utsmaniyah ngalahaké mutlak pasukan Moldavia ing papan aran Akdere lan mlebu Suceava, puseré kepangéranan. Nanging bèntèng-bèntèng ora bisa direbut; amarga kurang pasokan, pageblug pes sing tuwuh ing antarané Janissari, lan persiapané Hungaria, wadyabala kepeksa mundur. Tundhuké Moldavia kanthi tetep lagi bisa diraih ing taun-taun sabanjuré lan kanthi direbuté Kili (Chilia) lan Akkirman (Cetatea Albă) ing 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Penaklukan Akçahisar (Kruja) lan jangkepé Albania", "559a79b4"], "d": ["Sepuluh taun sawisé sedané Skanderbeg, kanthi direbuté Akçahisar, Drivasto, Lezhë, lan Jabyak ing taun 1478, penaklukan Albania sebagéan gedhé rampung. Tibané Bèntèng Kruja, sing pirang-pirang taun nglawan wadyabala Utsmaniyah lan dadi lambang perlawanané Skanderbeg, ateges pungkasané persekutuan Venesia-Albania ing tlatah iku. Shkodër, sing isih kari, bakal dipasrahaké marang Utsmaniyah miturut Prajanjian Istanbul sing ditandhatangani taun sabanjuré.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Digabungaké Semenanjung Taman", "4ef917b8"], "d": ["Sawisé Kefe lan Kerch direbut ing taun 1475, armada sing dikirim Mehmed Sang Penakluk menyang pesisir Kaukasus ngrebut, bebarengan karo Anapa lan Kopa, Matrega (Tamatarkhan) duwèké Genoa ing Semenanjung Taman. Kanthi mangkono loro pinggiré selat bisa diawasi lan lawang mlebu Segara Azov sakabèhé ana ing pangawasan. Taman, minangka gapura menyang Kaukasus Lor, digabungaké karo sancak Kefe.", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Gagalé pengepungan Rhodes", "35a85c28"], "d": ["Miturut dhawuhé Mehmed Sang Penakluk, armada 160 kapal ing pangwasané Mesih Pasya ngepung Rhodes ing mangsa semi 885 (1480), lan pulo iku diblokade suwéné telung sasi. Ksatria Santo Yohanes sing dipimpin grand master Pierre d'Aubusson nglawan kanthi sengit sanajan akèh korban; nalika serbuan gedhé pungkasan ing 20 Jumadilawal 885 uga ditolak, armada mundur tanggal 3 Agustus. Sawisé kagagalan iki, témbok kutha dianyaraké saka pondhasiné lan didadèkaké pertahanan paling kuwat ing Éropah, lan pulo iku lagi bisa direbut ing 1522 déning Suleyman Sang Pembuat Undhang-undhang.", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Perang Yenişehir — kakalahané Cem Sultan", "c35abee2"], "d": ["Sadulur loro sing obah ngrebut dhampar sawisé sedané Sang Penakluk padha adu arep ing dhataran Yenişehir, lan Cem Sultan nandhang kakalahan mutlak. Pangéran sing mréntah ing Bursa suwéné wolulas dina lan ndadèkaké khutbah diwaca atas asmané iku, sawisé kalah, kepeksa ngungsi dhisik menyang Konya, banjur menyang tlatah Mamluk. Yenişehir miwiti krisis wangsa sing paling dawa ing sajarah Utsmaniyah: suwéné patbelas taun prakara Cem bakal nglumpuhaké pulitik njaba Utsmaniyah ngadhepi Éropah.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Panggabungan Herzegovina", "bf247891"], "d": ["Sawisé penaklukan Bosnia ing 1463, lemah Kadipatèn Herzegovina sing isih ngadeg pindhah sethithik-sethithik menyang pamaréntahan Utsmaniyah: Trebinje lan Mostar direbut ing 1466, sancak Herzegovina diadegaké ing 1470, lan lemah pungkasan kadipatèn ing pesisir Adriatik, bebarengan karo Herseknovi (Herceg Novi), ditelukaké ing wiwitan 1482 lan digabungaké karo sancak. Kanthi mangkono tlatah pagunungan ing mburiné Adriatik sakabèhé dadi duwèké Utsmaniyah, lan Bosnia sarta Herzegovina dadi siji wilayah administrasi. Putrané adipati pungkasan, sing mlebu kraton Utsmaniyah, yaiku Hersekzâde Ahmed Pasya, sing ing mbésuk munggah nganti dadi wazir agung.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Zakynthos dipasrahaké marang Venesia kanthi imbalan upeti taunan", "268a691a"], "d": ["Zakynthos, salah siji pulo Ionia sing dijupuk saka kulawarga Tocco ing pungkasan mangsa Mehmed Sang Penakluk, diwènèhaké marang Venesia déning sultan anyar, sing sibuk karo perkara Cem Sultan lan golèk tentrem ing Kulon. Pulo iku dipasrahaké marang pamaréntahan Venesia sing ngakoni kedaulatan Utsmaniyah lan mbayar upeti taunan limang atus dukat. Kanthi mangkono ing Segara Ionia pamaréntahan langsung Utsmaniyah mung kari ing Santa Maura (Lefkada).", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultan ngungsi menyang Rhodes", "2228d6da"], "d": ["Cem Sultan, sing usahané ngepung Konya uga ora ana asilé, mlayu saka Anatolia karo watara telung puluh wong lan tekan Rhodes, ing kono ditampa kanthi upacara déning Ksatria Santo Yohanes. Nanging dhayohan iku énggal malih dadi tawanan; pangéran dipasrahaké dhisik marang Prancis, banjur marang Kepausan, lan dadi kertu truf ing tangané pulitik Éropah. Bayezid II kepeksa mbayar saben taun minangka gantiné sadulure ditahan, lan tumindak militèr Utsmaniyah menyang Kulon ditundha nganti sedané Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Wiwitané Perang Utsmaniyah-Mamluk (front Çukurova)", "3fe3f0c7"], "d": ["Rebutan pengaruh marang wangsa Dulkadir lan memungsuhan sing ditinggalaké amarga Cem Sultan ngungsi menyang tlatah Mamluk, ing taun 1485 miwiti perang antarané loro kakuwatan gedhé Sunni sing bakal suwéné nem taun. Ing tempuran ing Çukurova sakiwa-tengené Adana lan Tarsus, loro pihak ora bisa unggul siji saka sijiné; wadyabala Utsmaniyah nampa sawetara gebugan abot. Perang iki babak kapisan saka retaké sesambungan Utsmaniyah-Mamluk lan dadi pambuka proses sing, telung puluh taun sawisé, bakal dipungkasi karo ekspedisi Marj Dabiq lan Ridaniya déning Yavuz (Selim I).", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Tentrem Utsmaniyah-Mamluk — Tunis dadi perantara", "60dd6719"], "d": ["Ing perang Utsmaniyah-Mamluk sing diwiwiti ing 1485, loro pihak ora bisa nggayuh kamenangan sing nemtokaké; lumantar perantarané panguwasa Hafsiyah Tunis, Utsman, sarujukan diraih ing 1491. Prajanjian iku mbalèkaké tapel wates meh padha karo sadurungé perang, lan étung-étungan antarané rong nagara Islam ditundha suwéné sak generasi. Perjuangan nem taun sing ngentèkaké tenaga iku klebu sebab utama pulitik njaba Bayezid II sing ati-ati lan anggoné luwih mentingaké tatanan njero tinimbang nuju mangétan.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Wong Yahudi Sefardim sing diusir saka Spanyol ditampa ing Utsmaniyah", "5c2b5c24"], "d": ["Sawisé Granada tiba, sebagéan wong Yahudi sing mlayu saka panganiayané Inkuisisi ing Spanyol ngungsi menyang tlatah Utsmaniyah lan dipapanaké ing manéka kutha. Ing pamaréntahan Utsmaniyah, pasamuwan Sefardim iki éntuk kamardikan sing durung tau dialami: manggon ing ngendi waé sing dikarepaké, nglakoni kapercayané, mbukak lembaga pendhidhikan, lan mbangun sinagoga anyar. Migrasi iki, sing ngowahi urip ékonomi Thessalonika lan Istanbul lumantar ngèlmu percétakan, kedhokteran, lan keuangan sing digawa, dadi conto tatanan toleransi Utsmaniyah sing paling akèh dirembug ing Éropah.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Sédané Cem Sultan — pungkasané sandera patbelas taun", "f6588b70"], "d": ["Cem Sultan, sing dipasrahaké saka Kepausan marang Raja Prancis Charles VIII, séda ing papan aran Castel Capuana sawisé mangkat saka Roma tanggal 27 Januari 1495; sumber-sumber nyathet yèn mbokmenawa dhèwèké diracun déning kalangan Kepausan. Sédané pangéran sing suwéné patbelas taun dicekel nagara-nagara Éropah minangka kertu ancaman marang Utsmaniyah pungkasané ngluwari tangané Bayezid II. Nyatané, sawisé iku sultan ngumumaké perang marang Venesia lan nggawa armadané menyang kamenangan gedhé kapisan.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Kamenangan Segara Sapienza (Zonchio) — kasil gedhé kapisan armada ing Segara Tengah", "9754aaef"], "d": ["Bayezid II, sing tangané wis luwar amarga rampungé prakara Cem, ngumumaké perang marang Venesia ing 1499; armada Utsmaniyah ngalahaké armada Venesia ing segara cedhak Sapienza (Zonchio) lan nggayuh kamenangan segara gedhé kapisan ing Segara Tengah. Kanthi kamenangan iki, armada kaya-kaya ngumumaké yèn saiki wis bisa nglawan Venesia ing segara.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Ilangé Kefalonia lan Ithaka", "60f0f687"], "d": ["Venesia, sing goncang amarga Modon lan Koron direbut, nyawiji karo Spanyol lan nindakaké serangan wales, ngepung Kefalonia sing wiwit 1479 ana ing tangan Utsmaniyah. Sawisé perlawanan patang puluh pitu dina, bèntèng tiba, pulo iku bebarengan karo Ithaka pindhah menyang Venesia lan telung atus taun ora bali menyang pamaréntahan Utsmaniyah. Kélangan iki nggawé keseimbangan: sing diolèhi ing Morea dibalèkaké ing Ionia.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Runtuhé Kekhanan Horde Emas lan munggahé Krimea", "0d1dc515"], "d": ["Panguwasa pungkasané, Sheikh Ahmed Khan (1481-1502), ora bisa nylametaké negarané saka krisis sing dialami, lan Kekhanan Horde Emas dadi sajarah ing 1502 amarga gebugané Khan Krimea Mengli Giray. Amarga rebutan dhampar lan pecah-belah, ing lemah lawas Horde Emas muncul kekhanan Krimea, Kazan, Nogai, Astrakhan, lan Sibir. Kamenangané Krimea sing ana ing pangayoman Utsmaniyah iki ndadèkaké pengaruh Utsmaniyah ing sisih loré Segara Ireng ora bisa dibantah, déné kekosongan sing tuwuh ing tlatah iku bakal diisi Moskwa ing abad sabanjuré.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Pungkasané Perang Utsmaniyah-Venesia lan tentrem", "125b1526"], "d": ["Perang sing diwiwiti ing 1499 lan nggoncang Venesia amarga kélangan Sapienza, Lepanto (Inebahtı), Modon, lan Koron, rampung kanthi tentrem ing 1502. Venesia, sing kélangan pangkalan paling wigati ing Morea, kepeksa ngakoni unggulé Utsmaniyah minangka gantiné bisa njaga hak mirunggan dagangé ing Segara Tengah sisih wétan. Pamaréntahané Bayezid II, sing dianggep ati-ati, lumantar perang iki wis ngunggahaké Utsmaniyah sepisanan dadi kakuwatan segara sing serius ing Segara Tengah.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Pambrontakan Şahkulu — pambrontakan Qizilbash saka tlatah Teke nganti Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, sing kena pengaruh propaganda Safawiyah ing Anatolia lan mbukak pambrontakané ing 1510, wis nyerbu pasar Antalya ing Maret 1511 lan ing April ngalahaké pasukan Utsmaniyah ing Kütahya lan sakiwa-tengené. Ing tempuran pungkasan sing dilakoni cedhak Sivas karo wazir agung Hadım Ali Pasya, loro pihak nandhang karugèn abot; wazir agung lan pimpinan pambrontak loro-loroné tiwas. Pambrontakan iki, sing nggoncang wibawa nagara ing Anatolia, ngetokaké kekosongan pangwasa ing taun-taun pungkasané Bayezid II lan dadi alesan paling kuwat kanggo lelampahané Pangéran Selim menyang dhampar.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Bayezid II lèngsèr lan jumenengé Yavuz Sultan Selim", "c4cfab69"], "d": ["Amarga ditekan Pangéran Selim, sing ing perjuangan dhampar karo sadulur-sadulure disengkuyung Janissari, Bayezid II lèngsèr tanggal 24 April 1512, lan ing dina sing padha Selim I jumeneng dadi panguwasa Utsmaniyah kaping sanga. Sultan sepuh iku, nalika tindak menyang Dimetoka, papan lairé, séda ing dalan, ing désa Abalar cedhak Çorlu, tanggal 25 Rabiulawal 918 (10 Juni 1512). Pamaréntahan telung puluh siji taun sing ati-ati lan madhep njero diganti jaman Yavuz, sing sajroné wolung taun bakal nikelaké jembaré tapel wates kakaisaran.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Penaklukan Bèntèng Sinj", "83271ea5"], "d": ["Pasukan penyerbu Utsmaniyah ing tapel wates Bosnia ngrebut Bèntèng Sinj, sing tekan pedhalaman Dalmatia, saka Karajan Hungaria. Iki mata ranté wiwitan saka garis tapel wates Dalmatia sing sangang taun sabanjuré saya jembar kanthi penaklukan Knin lan sakiwa-tengené déning Gazi Husrev Bey; bèntèng iku bakal ilang menyang Venesia ing 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Perang Yenişehir lan disingkiraké Pangéran Ahmed", "e2ed15dd"], "d": ["Yavuz Sultan Selim ngalahaké mutlak kangmasé, Pangéran Ahmed, saingan dhampar sing paling kuwat, ing dhataran Yenişehir cedhak Bursa, lan nyingkiraké kanthi nawan. Kanthi mangkono padudon sadulur sing lumaku wiwit 1511 rampung, lan pecahé njero Anatolia wis tutug. Sawisé ngamanaké mburiné, Selim éntuk kamardikan kanggo nuju prakara Safawiyah.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Yavuz Sultan Selim mlebu Tabriz", "dad2e227"], "d": ["Sawisé kamenangan ing Chaldiran, wadyabala Utsmaniyah mlebu krajan Safawiyah, Tabriz, lan ing kutha iku khutbah diwaca atas asmané sultan. Selim manggon ing kono seminggu lan mrentahaké sebagéan tukang seni lan ulama Tabriz dipindhah menyang Istanbul; pamindhahan iki bakal duwé pengaruh jero marang seni kraton Utsmaniyah. Sanajan kutha ditinggal amarga mangsa adhem nyedhak lan Janissari ora marem, unggulé Safawiyah ing Wétan wis dipecah. Papan-papan sing ing peta dina iki pindhah menyang Utsmaniyah ora gandhèng siji karo sijiné, lan iki bener: Tabriz iku dhudhukan wadyabala sangang dina; dhataran Erzincan nyerah tanpa perang nalika ekspedisi, déné bèntèng Kemah ing tengahé tetep nglawan minangka duwèké Safawiyah nganti 19 Mei 1515; Siirt direbut manèh saka Safawiyah déning Halil Bey, malik Hasankeyf, sing luwar saka pakunjarané Syah Ismail ing Tabriz lan tundhuk marang Utsmaniyah — Diyarbakır ing sakiwa-tengené tetep Safawiyah nganti 1515, lan Hasankeyf nganti 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Penaklukan Bèntèng Kemah saka Safawiyah", "73fd8671"], "d": ["Yavuz Sultan Selim, sing bali saka Chaldiran ngliwati mangsa adhem ing Amasya, masrahaké marang Bıyıklı Mehmed Pasya penaklukan Bèntèng Kemah sing kuwat, sing nyekel papan panyabrangan Kali Efrat. Ing pungkasané pengepungan sing sultan dhéwé mèlu, bèntèng iku direbut saka tangané Safawiyah lan gapura Anatolia Wétan kabukak. Penaklukan iki langkah nyata kapisan sing ngowahi kamenangan Chaldiran dadi tambahan lemah sing langgeng.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Kamenangan Turnadağ — Kabèylikan Dulkadir dadi bawahan Utsmaniyah", "fd879145"], "d": ["Pasukan Utsmaniyah ngalahaké Bey Dulkadir Alâüddevle Bozkurt, sing nalika ekspedisi Chaldiran sikapé mangro, ing papan Ördekli antarané Göksun lan Andırın; Alâüddevle tiwas ing perang iki. Ing tanggal iki kabèylikan durung digabungaké: sawisé Alâüddevle, Yavuz Sultan Selim ngangkat Şehsuvaroğlu Ali Bey dadi pangarsa Kabèylikan Dulkadiroğulları, lan negara sing puseré ing Maraş-Elbistan lumaku terus minangka kabèylikan bawahan Utsmaniyah. Kanthi mangkono panyangga ing tapel wates Mamluk mlebu pangawasan Utsmaniyah lan dalan kanggo ekspedisi Mesir rong taun sawisé kabukak; panggabungan lagi bakal kelakon sawisé Ali Bey dipatèni.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Penaklukan Amid (Diyarbekir) lan adegé beylerbeyilik Diyarbekir", "a6867d5b"], "d": ["Sawisé Idris-i Bitlisi kasil narik para bey Kurdi Sunni ing tlatah iku menyang pihak Utsmaniyah, pasukan Safawiyah ora kuwat nahan pengepungan dawa, lan kunci-kunci Amid dipasrahaké marang Bıyıklı Mehmed Pasya. Kutha iku didadèkaké puseré beylerbeyilik Diyarbekir sing anyar diadegaké. Kanthi mangkono inti administrasi Mesopotamia Hulu tiba ing tangané Utsmaniyah.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Penaklukan Harput — kabukaké dalan Diyarbekir", "564eb269"], "d": ["Husrev Pasya, beylerbeyi Karaman, sing mangkat kanggo ngluwari Diyarbekir, sing direbut sawisé Chaldiran, saka pengepungan Safawiyah, ngrebut Bèntèng Harput, sing sakiwa-tengené wis direbut luwih dhisik déning Çerkez Hüseyin Bey, sawisé pengepungan telung dina. Kanthi mangkono dalan ing sisih wétan Kali Efrat sing mbentang menyang Diyarbekir dadi aman.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Perang Koçhisar (Kızıltepe) — kakalahané Kara Han", "9ea9e843"], "d": ["Wadyabala Utsmaniyah ing pangwasané Bıyıklı Mehmed Pasya ngalahaké gubernur Safawiyah Kara Han, ing perang ara-ara sing suwéné sedina muput ing papan aran Koruk ing ara-ara Dede Garkın cedhak Koçhisar; sirahé Kara Han sing dipenggal dikirim menyang pakémahané sultan. Banjur pasukan Utsmaniyah mlebu kutha Mardin, nanging mung manggon sawetara dina banjur lunga; Bèntèng Mardin sing dicekel panjaga Safawiyah lagi bisa ditampa nyerah setaun sawisé. Kamenangan iki ngamanaké tapel wates kidulé Yavuz lan ndadèkaké dhèwèké bisa nuju ekspedisi Mesir. Papan liyané sing gabung ing tanggal sing padha: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Mangkaté Yavuz Sultan Selim saka Istanbul kanggo ekspedisi Mesir", "ac258b4b"], "d": ["Yavuz Sultan Selim mangkat saka Istanbul, katoné nyawisaké ekspedisi wétan anyar nglawan Safawiyah, lan méngo ngidul liwat Akşehir. Amarga Sultan Mamluk Qansuh al-Ghawri nggawé sesambungan karo Syah Ismail lan ngancam suwiwi wétané Utsmaniyah, sasarané bakal énggal owah. Ekspedisi iki wiwitané operasi gedhé sing bakal suwéné rong taun lan ngowahi Utsmaniyah dadi kakaisaran Wétan Tengah.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Direbuté Zabid: sepisanan pelaut Utsmaniyah mlebu Segara Abang", "38740e0c"], "d": ["Ngadhepi tekanan Portugis ing Samudra Hindia, miturut panjaluké Sultan Mamluk Qansuh al-Ghawri, pelaut asal Utsmaniyah, Hüseyin Bey lan Selman Reis, dikirim menyang Segara Abang lan ngrebut Zabid nganggo armadané. Operasi iki, sing isih dilakoni ing pangabdèn marang Mamluk, iku anané nyata kapisan angkatan laut Utsmaniyah ing garis Segara Abang-Hindia. Setaun sawisé, nalika Mesir pindhah menyang Utsmaniyah, armada sing padha bakal digandhèng langsung karo Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Pangumuman resmi Mamluk lan Aleppo minangka sasaran ekspedisi", "689e310d"], "d": ["Nalika Qansuh al-Ghawri sarujukan karo Safawiyah lan ngerahaké wadyabalané menyang Aleppo, Yavuz Sultan Selim kanthi terbuka ngumumaké yèn sasaran ekspedisi yaiku sultan Mamluk lan Aleppo. Kanthi mangkono saingan sesidheman sing wis pirang-pirang taun antarané loro nagara Sunni malih dadi perang terbuka. Pangumuman iki miwiti étungan mundur patang minggu menyang Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Gagalé pengepungan Aden: usaha kapisan ing Segara Abang nglawan Portugis", "8ffd46f2"], "d": ["Selman Reis lan Hüseyin Bey nindakaké pengepungan suwéné wolung dina kanggo ngrebut Aden, gapurané Segara Abang menyang Samudra Hindia, nanging kepeksa mundur ngadhepi pertahanan kutha sing kuwat. Ora bisané Aden direbut bakal ngganggu strategi kidul nglawan Portugis sajroné pirang-pirang taun. Usaha iki ujian kapisan Utsmaniyah ing pulitik samudra.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Kabèylikan Ramazanoğulları digabungaké karo Utsmaniyah", "cfaa3754"], "d": ["Ing pamaringan kalungguhan (tevcih) sawisé kamenangan Marj Dabiq, Kabèylikan Ramazanoğulları sing puseré ing Adana diparingaké marang Mahmud Bey lan dilebokaké ing pangwasa Utsmaniyah. Kabèylikan sing metu saka status bawahan Mamluk iku ora diilangi, nanging ditinggal ing kulawarga kanthi status 'ocaklık'; wangsa Ramazan nerusaké pamaréntahan Çukurova minangka sancak beyi Utsmaniyah. Tatanan mirunggan iki lumaku nganti taun 1608, nalika Pîr Mansûr ninggalaké kabèylikan. Papan liyané sing gabung ing tanggal sing padha: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa, lan Deir ez-Zor mlebu pangwasa Utsmaniyah", "2088eb6a"], "d": ["Patang dina sawisé Marj Dabiq, Yavuz Sultan Selim mlebu Aleppo tanpa ditentang, lan khutbah ing masjid-masjid kutha diwaca atas asmané. Tibané Aleppo, sing dianggep krajan dagang lan administrasi Suriah, kanthi semono cepeté nuduhaké yèn wibawa Mamluk ing tlatah iku wis ambruk. Direbuté kutha iki sakala mbukak dalan menyang Damaskus lan saka kono menyang Mesir. Papan liyané sing gabung ing tanggal sing padha: Antiokhia, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Patemon karo Khalifah Abbasiyah al-Mutawakkil III ing Gökmeydan Aleppo", "22979f42"], "d": ["Khalifah Abbasiyah ing Kairo, al-Mutawakkil III, sing ditawan ing Marj Dabiq bebarengan karo wadyabala Mamluk, diadhepaké marang sultan ing Gökmeydan ing Aleppo, lan Yavuz Sultan Selim nuduhaké pakurmatan gedhé marang dhèwèké. Kekhalifahan Kairo, sing wiwit 1261 mung dadi kalungguhan simbolis ing sangisoré ayang-ayangé sultan-sultan Mamluk, lumantar patemon iki kasunyatané pindhah ing pangayoman Utsmaniyah. Ing tembé, khalifah bakal digawa menyang Istanbul bebarengan karo sultan.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli Syam lan Hama mlebu pamaréntahan Utsmaniyah", "a1e19a79"], "d": ["Sawisé Aleppo lan Hama, Tripoli Syam ing pesisir Suriah uga pindhah menyang pamaréntahan Utsmaniyah tanpa nglawan. Kutha iku, salah siji plabuhan paling ramé ing Segara Tengah sisih wétan, minangka gapurané Damaskus menyang segara lan puseré dagang sutra lan gula. Kanthi direbuté, sabuk pesisir Bilad al-Syam sakabèhé ganti tangan.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damaskus (Dimashq) mlebu pangwasa Utsmaniyah", "2b844d91"], "d": ["Yavuz Sultan Selim, sing dalané kabukak amarga Hama lan Homs nyerah sawisé Aleppo, tekan ngarep Damaskus tanggal 27 September; dhèwèké ora langsung mlebu kutha, nanging ngedegaké tarup ing njaba, ing papan Mastaba, lan ing dina kaping rolas sawisé teka dhèwèké mlebu kanthi upacara gedhé. Manggon rada suwé ing Damaskus, dhèwèké nata tatanan administrasi Suriah lan mbangun pasaréané Muhyiddin Ibnu Arabi. Kanthi mangkono kabèh Bilad al-Syam metu saka pamaréntahan Mamluk. Papan liyané sing gabung ing tanggal sing padha: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tumanbay diumumaké dadi sultan Mamluk ing Kairo", "6020d90d"], "d": ["Sawisé Qansuh al-Ghawri tiwas ing Marj Dabiq, para emir Mamluk ngangkat Tumanbay, sing bakal dadi sultan pungkasan nagara iku, menyang dhampar. Sultan anyar asal Sirkasia iku nampa nagara sing wis kélangan Suriah, bandhané entèk, lan ora duwé gaman geni. Sanajan mangkono, kanthi ngedegaké garis pertahanan ing ngarep Kairo, dhèwèké bakal nata perlawanan pungkasan marang majuné Utsmaniyah.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Perang Gaza (Khan Yunus): Janbirdi al-Ghazali kalah", "9f1eb8cb"], "d": ["Yavuz Sultan Selim ngutus wazir agung Hadım Sinan Pasya menyang Gaza nganggo pasukan pangarep patang èwu wong. Janbirdi al-Ghazali, sing diangkat Tumanbay dadi wakil gubernur Damaskus, nyoba ngendheg pasukan pangarep Utsmaniyah ing garis Gaza-Khan Yunus, nanging kalah abot lan mlayu menyang Mesir. Kanthi buyaré kakuwatan panyangga Mamluk pungkasan ing Palestina, dalan menyang ara-ara samun Sinai kabukak kabèh.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Sisih wétan Kali Yordan: Amman mlebu pamaréntahan Utsmaniyah", "9db62667"], "d": ["Nalika pasukan Utsmaniyah sing nyiapaké ekspedisi Mesir sawisé perang Gaza mudhun ngidul, Amman ing sisih wétan Kali Yordan uga mlebu pamaréntahan Utsmaniyah. Déné kutha-kutha pesisir lan pedalaman Palestina (Jaffa, Nablus, Sidon, Akko, Yerusalem) wis ganti tangan sawisé Marj Dabiq ing mangsa gugur 1516. Kutha-kutha iki diprentah suwéné patang abad minangka sancak provinsi Damaskus.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Rawuhé Yavuz Sultan Selim ing Yerusalem", "66d7bfad"], "d": ["Menyang Yerusalem, sing sawisé Marj Dabiq wis pindhah ing pamaréntahan Utsmaniyah tanpa nglawan, Yavuz Sultan Selim teka sawisé perang Gaza bebarengan karo para pinisepuh nagara lan wadyabala. Sultan ziarah menyang Kubah Batu lan Masjidil Aqsa lan ngukuhaké status suciné kutha iku. Yerusalem bakal ana ing pamaréntahan Utsmaniyah wiwit tanggal iki nganti Desember 1917, jangkep patang abad.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Yavuz Sultan Selim mlebu Gaza lan nuju ara-ara samun Sinai", "2106bfc7"], "d": ["Sawisé Janbirdi al-Ghazali kalah ing Khan Yunus (21 Desember 1516), Gaza ana ing tangané pasukan pangarep. Sultan mlebu Gaza tanggal 2 Januari 1517 lan ketemu ing kono karo Sinan Pasya, pangarepé pasukan pangarep, lan wadyabala nindakaké persiapan pungkasan kanggo nyabrang menyang Mesir. Wolung pos lelampahan kudu ditempuh ing ara-ara samun tanpa banyu Qatiya (Sinai) sing mbentang saka Gaza nganti Salihiyya, kanthi banyu diangkut nganggo unta. Panyabrangan iki babak ekspedisi sing paling bebayani lan paling angèl sacara logistik.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Direbuté Suez — gapura sing menga menyang Segara Abang", "05f3324e"], "d": ["Nalika pasukan Utsmaniyah mlebu Kairo sawisé kamenangan Ridaniya, Suez ing pucuk lor Segara Abang uga pindhah menyang pamaréntahan Utsmaniyah. Plabuhan-galangan kapal iki, saka kono wangsa Mamluk ngirim armada menyang Samudra Hindia, dadi pangkalan kawicaksanan sisih kidul sing bakal ditindakaké nglawan Portugis. Suez iku cangkem lor saka garis sing, telung abad sawisé, bakal dibukak terusan.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Sepisanan pasukan Utsmaniyah mlebu Kairo", "0a3f4f4d"], "d": ["Dina sawisé kamenangan Ridaniya, wadyabala Utsmaniyah diidinaké mlebu Kairo, lan tanggal 24 Januari pasukan manggon ing kutha. Nanging mlebuné iki durung ateges kutha diawasi kabèh; Tumanbay mundur menyang Mesir Hulu, lan perlawanan Mamluk durung dipecah. Penaklukan Kairo bakal rampung ora sajroné sedina, nanging lumantar proses sing kebak getih sajroné pirang-pirang minggu.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Serbuané Tumanbay menyang Kairo lan perang dalan telung dina", "b83b6ce6"], "d": ["Tumanbay, sing mundur menyang Mesir Hulu, ing wengi 27-28 Januari dumadakan mlebu Kairo karo watara pitung èwu wong, miwiti perlawanan ing njero kutha, lan ndadèkaké pasukan Utsmaniyah ana ing kahanan angèl banget. Ing tempuran dalan sing sengit suwéné telung dina, wong Mamluk sawetara wektu nyekel pérangan gedhé kutha. Perlawanan iku lagi bisa dipecah sawisé artileri Utsmaniyah lan bala bantuan mlebu gelanggang.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Janbirdi al-Ghazali mlebu pangabdèn Utsmaniyah", "a94ea459"], "d": ["Janbirdi al-Ghazali, emir Mamluk lawas sing sawisé Ridaniya mundur menyang Salihiyya, sowan marang sultan lan nyuwun pangapura (aman). Yavuz Sultan Selim, sing mikir yèn dhèwèké bakal ana gunané kanggo netepaké katentreman ing Mesir lan Suriah, nampa dhèwèké dadi abdiné. Pilihan iki conto gedhé kapisan pulitik Utsmaniyah nglebokaké kader Mamluk menyang sistem, dudu numpes.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Yavuz Sultan Selim mlebu Kairo kanthi upacara lan diwacané khutbah", "6d98080c"], "d": ["Sawisé perang dalan ditumpes, tanggal 15 Februari 1517 sultan mlebu Kairo kanthi upacara sing éndah banget, lan ing masjid-masjid khutbah diwaca atas asmané. Diwacané khutbah ing Kairo atas asmané sultan Utsmaniyah iku pangumuman yèn pangwasa Mamluk, sing lumaku wiwit 1250, sacara hukum wis rampung. Tanggal iki dianggep wektu simbolis jangkepé penaklukan nyata Mesir.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Dicekelé sultan Mamluk pungkasan Tumanbay ing Terrūja", "7058e6ad"], "d": ["Tumanbay, sing sawisé ninggalaké Kairo ndhelik ing delta Kali Nil, diwadulaké déning wong Badui sing mènèhi papan pangungsèn lan dicekel ing tlatah Terrūja. Dicekelé iki ngilangi puser perlawanan Mamluk sing katata. Sultan pungkasan sawisé iku bakal ana ing tangané Utsmaniyah suwéné patbelas dina.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Tumanbay diukum pati ing Bab Zuwayla lan pungkasané Nagara Mamluk", "ad9820be"], "d": ["Patbelas dina sawisé dicekel, Tumanbay digantung ing Bab Zuwayla, gapura Kairo sing kondhang; layoné banjur disarèkaké ing madrasah sing diadegaké pamané. Kanthi mangkono Nagara Mamluk, sing mréntah Mesir lan Suriah wiwit 1250, resmi dadi sajarah. Kanthi pecahé perlawanan, kutha-kutha ing Mesir Hulu (Said) kayata Asyut lan Aswan uga digabungaké karo pamaréntahan Utsmaniyah.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Serangan armada Portugis menyang Jeddah lan pertahanané Selman Reis", "52322cf5"], "d": ["Armada Portugis sing dumadi saka watara telung puluh kapal galley lan galleon nyerang Jeddah; Selman Reis mimpin pertahanan kutha, nyegah mungsuh ndharat, lan nggelemaké sawetara kapal Portugis. Pertahanan iki nyegah plabuhané Makkah, lan uga dalan kaji, tiba ing tangané nagara Kristen. Sawetara sasi sawisé, Jeddah bakal resmi mlebu pamaréntahan Utsmaniyah bebarengan karo baiaté Hijaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Iskandariyah ditampa nyerah lumantar armada — jangkepé penaklukan Mesir", "386878fe"], "d": ["Jangkep patang sasi sawisé Ridaniya lan telung puluh nem dina sawisé Tumanbay diukum pati, kanthi tekané armada Utsmaniyah ing pangwasané Cafer Bey menyang plabuhan, Iskandariyah pindhah ing pamaréntahan Utsmaniyah; plabuhan-plabuhan delta kayata Rosetta (Reşîd) lan Damietta uga digabungaké ing proses sing padha. Plabuhan gedhé Mesir ing Segara Tengah iki ditampa nyerah pirang-pirang sasi sawisé tibané Kairo, lan saka segara, dudu dharatan, nuduhaké kanthi cetha yèn penaklukan rampung dudu lumantar siji perang, nanging tlatah mbaka tlatah. Wiwit iku Iskandariyah bakal dadi plabuhan wigati sing nyambungaké Istanbul lan Kairo. Papan liyané sing gabung ing tanggal sing padha: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Hijaz gabung tanpa perang: baiaté Abu Numayy, putrané Syarif Makkah", "c13b98c7"], "d": ["Yavuz Sultan Selim wiwitané wis nimbang arep ngirim prajurit kanggo ngrebut Makkah lan sakiwa-tengené, nanging banjur ngurungaké nalika Emir Makkah, Syarif Barakat, nyatakaké tundhuk. Putrané Barakat sing umur rolas taun, Abu Numayy, teka ing Kairo nggawa pisungsungé ramané lan kunci-kunci Makkah lan ditampa ngadhep sultan. Kanthi mangkono Hijaz gabung karo Utsmaniyah dudu minangka asil otomatis saka Ridaniya, nanging limang setengah sasi sawisé, tanpa siji pelor ditembakaké, kanthi tentrem lan lumantar baiat. Papan liyané sing gabung ing tanggal sing padha: Thaif. Papan liyané sing ucul ing tanggal sing padha: Hurma (wétan Thaif), Rabigh, Badar.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Ditampané sesebutan Khadim al-Haramain lan khutbah ing Madinah", "63b32b59"], "d": ["Sawisé utusan Makkah ditampa kaping pindho, Yavuz Sultan Selim resmi nanggung pangayomané Haramain lan wiwit nganggo sesebutan 'hadimü'l-Haremeyni'ş-şerîfeyn' (abdi loro papan suci sing mulya). Syarif Barakat nganggo jubah kahurmatan (hil'at) sing dikirim marang dhèwèké lan ndadèkaké khutbah diwaca atas asmané sultan; kanthi utusan Madinah uga lunga menyang Istanbul, kalungguhan emiré Barakat dikukuhaké nganggo piagam (berat). Sultan ngirim rong atus èwu dhuwit emas lan pasokan pangan akèh marang warga Haramain, miwiti tradhisi surre sing bakal dibalèni saben taun. Papan liyané sing gabung ing tanggal sing padha: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis mlebu pangabdèn Utsmaniyah lan pamindhahan pulitik Segara Abang", "771da99a"], "d": ["Selman Reis, sing mbélani Jeddah nglawan Portugis, teka ing Kairo lan sowan marang Yavuz Sultan Selim; sanajan sawetara wektu ditahan, ing 1519 dhèwèké diundang menyang Istanbul lan nyanggupi nyawisaké telung puluh kapal galley lan sawetara kapal kalyata kanggo ngadhepi ancaman Portugis. Patemon iki wiwitané pulitik Segara Abang lan Samudra Hindia diwarisi saka Mamluk lan digandhèng langsung karo Istanbul. Saiki Utsmaniyah ora mung nagara Segara Tengah, nanging uga kakuwatan sing nindakaké pulitik samudra.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Mangkaté Yavuz Sultan Selim saka Kairo lan beylerbeyilik Hayır Bey", "8cd4fb23"], "d": ["Yavuz Sultan Selim, sing manggon ing Mesir watara wolung sasi lan nata tatanan administrasi, keuangan, lan militèr, mangkat saka Kairo; Hayır Bey, bekas wakil gubernur Aleppo sing kanthi narik suwiwi kiwa ing Marj Dabiq nyepetaké kakalahan Mamluk, miwiti pamaréntahan saka Bèntèng (Qal'at al-Jabal) minangka beylerbeyi Utsmaniyah kapisan ing Mesir. Milih gubernur asal Mamluk iku pulitik pralihan sing disengaja, supaya pamaréntahan anyar ora katon asing tumrap warga lokal. Ing lelampahan mulih, sultan nggawa menyang Istanbul khalifah Abbasiyah pungkasan, al-Mutawakkil III, sarta para tukang seni lan ulama pinunjul saka Mesir.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Pungkasané kekhalifahan Abbasiyah Kairo — crita 'upacara pasrah-pinampan'", "1d357640"], "d": ["Nalika Yavuz Sultan Selim ngrebut Mesir, dhèwèké nggawa menyang Istanbul khalifah pungkasan, al-Mutawakkil III 'Alallah, sing ditawan ing Marj Dabiq; kanthi mangkono kekhalifahan Abbasiyah Kairo, sing wiwit 1261 lumaku tanpa wewenang ing ayang-ayangé sultan Mamluk, rampung. Kosok baliné, crita kondhang yèn kekhalifahan dipasrahaké marang Yavuz ing upacara resmi ing Hagia Sophia iku sepisanan muncul ing karyané d'Ohsson ing pungkasan abad kaping wolulas, lan ora ana ing sumber jaman Yavuz siji waé. TDV İslâm Ansiklopedisi nganggep crita iku gawéan amarga ora ana sumber asli sing mbuktèkaké upacara kuwi; nanging uga nyathet yèn sacara syariat ora perlu upacara pasrah-pinampan kaya mangkono supaya kekhalifahan pindhah.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum gabung karo pamaréntahan Utsmaniyah — pengaruh Safawiyah ing Anatolia Wétan dipecah", "78d1be02"], "d": ["Sanajan sawisé kamenangan ing Çaldıran (1514) pengaruh Utsmaniyah ing tlatah iku tambah, direbuté Erzurum sakabèhé ketundha nganti pengaruh Iran dipecah; kutha iku lagi gabung karo pamaréntahan Utsmaniyah ing 1518-19, sawisé ekspedisi Mesir. Erzurum mlebu pangwasa Safawiyah ing 1502, nalika Syah Ismail mungkasi Kabèylikan Aq Qoyunlu; kanthi mangkono jaman nem belas taun iku rampung. Ing 1534, nalika Ekspedisi Irak Loro (Irakeyn), beylerbeyilik Erzurum bakal diadegaké. Antarané 1518 lan 1519, Aşkale bebarengan karo tlatah Erzurum gabung karo pamaréntahan Utsmaniyah (dina durung dikonfirmasi).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Wiwitané pambrontakan Celali: pambrontakané Şeyh Celâl saka Bozok", "99bd8a99"], "d": ["Ing tlatah Bozok, wong aran Şeyh Celâl ngumumaké awaké dadi Imam Mahdi lan mbrontak ing sakiwa-tengené Tokat; sanajan pambrontakan ditumpes, jenengé suwéné seabad dadi sebutan kanggo kabèh gerakan brandhal lan pambrontakan ing Anatolia. Gerakan Celali, sing ing pungkasan abad kaping nembelas manunggal karo bubrahé tatanan timar lan tekanan cacah jiwa, malih dadi prakara keamanan njero kakaisaran sing paling dawa umuré. Pambrontakan iku njalari ngungsi gedhé-gedhéan ing Anatolia sing diarani 'pangungsèn agung'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Aljir digabungaké karo Nagara Utsmaniyah", "b8eba4c1"], "d": ["Hayreddin Reis, sing nglawan tekanan Spanyol ing Afrika Lor, supaya bisa tahan sowan marang Istanbul lan ngaturaké Aljir marang sultan, lan khutbah diwaca atas asmané Yavuz Sultan Selim. Kanthi mangkono Aljir resmi digabungaké karo tlatah Utsmaniyah, lan prajurit sarta mriyem dikirim marang Hayreddin kanthi sesebutan beylerbeyi. Panggabungan iki masang dhasar pangwasa segara Utsmaniyah ing Segara Tengah sisih Kulon sing bakal suwéné pirang-pirang abad. Papan liyané sing gabung ing tanggal sing padha: Constantine, Cherchell (Şerşel), Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Sédané Yavuz Sultan Selim ing Çorlu", "9fe83744"], "d": ["Selim I, sing sajroné wolung taun njembaraké lemah nagara luwih saka kaping pindho, mangkat saka Istanbul tanggal 18 Juli 1520 kanggo ekspedisi anyar; amarga ana tumor gedhé sing tuwuh ing gegeré, dhèwèké ora bisa ngliwati Çorlu. Sanajan ditambani dhokter, lelarané saya abot, lan sawisé pangobatan tanpa pangarep-arep suwéné rong sasi, dhèwèké séda ing kono tanggal 8-9 Syawal 926 (21-22 September 1520). Lumantar Chaldiran, Marj Dabiq, lan Ridaniya, dhèwèké wis ngendheg Iran lan numpes Nagara Mamluk, sarta nggawa kekhalifahan lan kalungguhan pangayom Haramain menyang Utsmaniyah. Sing ditinggal mung siji putra lanang: Suleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Pulo Nikaria (Ikaria) mlebu pamaréntahan Utsmaniyah", "6afa972b"], "d": ["Nikaria, sing ana antarané Samos lan Khios, wiwit 1481 nganti 1521 ana ing pamaréntahan Ksatria Santo Yohanes saka Rhodes; mangsa Utsmaniyah kapisan ing pulo iku diwiwiti ing 1522 lan lumaku nganti 1822. Ing mangsa iki kaymakam tanggung jawab nglumpukaké lan mbayar pajeg; kaya ing pulo Aegea liyané, dhéwan pinituwa lokal (demogerontia) uga tetep ana lan kadhangkala padu karo pamaréntahan Utsmaniyah.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksasi tanah Dulkadir — eyalet Dulkadir sing pusaté Maraş", "595c3c30"], "d": ["Tanah Dulkadir, sing sawisé kekalahan Turna Dağı 1515 isih lumaku dadi kadipaten sing manut Utsmaniyah, digabungaké langsung menyang tanah Utsmaniyah sawisé Şehsuvaroğlu Ali Bey dipatèni bebarengan karo anak-anaké ing Artukova, lan didadèkaké eyalet sing pusaté Maraş. Tlatah Bozok ing kadipaten iku digandhèngaké menyang pamaréntahan Utsmaniyah dadi sanjak kapisah. Kanthi mangkono mangsa Dulkadir sing umuré watara rong abad ing Maraş, Elbistan, Göksun, Gürün, Zamantı lan Darende ditutup; kadipaten panyangga ing tapel wates Mamluk ilang babar pisan.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Penaklukan Knin", "a46d3117"], "d": ["Liwat serbuan sanjak-bèy Bosnia Gazi Husrev Bey ing taun 927-928 (1521-1522), rerangkèn bèntèng Venesia, utamané Knin, Skradin lan Ostrovica, pindhah menyang pamaréntahan Utsmaniyah; tapel wates disurung ngliwati deretan gunung kapindho. Ranté penaklukan iki masang dhasar sanjak Dalmatia, sing limalas taun sabanjuré bakal dirampungaké kanthi direbuté Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Para ksatria mundur: Bodrum, Kos lan Dodekanesa dipasrahaké", "ea01666e"], "d": ["Miturut sarat nyerahé Rhodes, Ksatria Santo Yohanes ngosongaké ora mung pusat pulo nanging uga kabèh pos sing dicekel sajrone rong atus taun. Bèntèng Bodrum (Santo Petrus) ing pesisir Anatolia sarta pulo Kos, Kalymnos lan Leros mangkono pindhah menyang pamaréntahan Utsmaniyah tanpa perang. Liwat pasrah iki, sing rampung rong minggu sawisé Rhodes tiba, anané wong Latin ing pojok kidul-wétan Aegea rampung babar pisan.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Pambrontakan Hain Ahmed Pasya ing Mesir", "b18bb805"], "d": ["Ahmed Pasya, sing dikirim dadi gubernur Mesir nalika ngarep-arep dadi wazir agung, ing Kairo ngumumaké awaké dadi 'al-Malik al-Mansur Sultan Ahmed' lan nyatakaké mardika. Pambrontakan énggal ditumpes lan pasya iku dipatèni, nanging prastawa iku nuduhaké ringkihé pangawasan pusat ing provinsi paling sugih ing kakaisaran. Amarga iku Ibrahim Pasya tindak menyang Mesir lan mrentahaké nyusun Kanunnâmé Mesir sing kondhang, sing nata manèh pamaréntahan provinsi.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksasi Bosnia Lor: Jajce lan Banja Luka", "8ec86cfa"], "d": ["Nalika garis pertahanan Hungaria ambruk sawisé Mohács, sanjak-bèy Bosnia Gazi Husrev Bey maju menyang lembah Vrbas lan ngrebut bèntèng Bosnia pungkasan sing isih ana ing tangan karajan Hungaria. Kanthi tibané Jajce lan Banja Luka, eyalet Bosnia ing lor tekan Kali Sava lan garis ngarep Kroasia lair. Ora suwé Banja Luka dadi pusat kapindho eyalet.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Direbuté Buda lan dipasrahaké marang Zápolya", "fba4f89b"], "d": ["Ing dalan ekspedisi Wina, wadyabala Utsmaniyah ngepung lan ngrebut manèh Buda, sing wis tiba ing tangané Ferdinand, lan masrahaké kutha iku marang János Szapolyai, raja Hungaria sing ana ing pangayoman Utsmaniyah. Kanthi mangkono, ing saingan Habsburg-Utsmaniyah ngenani Hungaria, diadegaké modhèl karajan vasal panyangga. Tatanan iki bakal lumaku nganti 1541; sawisé sedané Zápolya, Buda bakal didadèkaké provinsi Utsmaniyah langsung.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Suleyman Sang Pembuat Undhang-undhang mangkat ing ekspedisi Jerman — tantangan marang Charles V", "7c3d7055"], "d": ["Sawisé pengepungan Wina ora ana asilé lan Ferdinand ngepung manèh Buda, sultan mangkat saka Istanbul, wektu iki kanggo narik kaisar Charles V dhéwé menyang perang ara-ara. Ing Agustus wadyabala bakal ketahan amarga perlawanan bèntèng cilik Güns, lan amarga kaisar ora metu perang, ekspedisi mung winates ing serbuan. Ekspedisi iki nyiapaké dhasar tentrem kapisan karo Habsburg ing taun sabanjuré.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Ekspedisi Jerman lan pengepungan Güns (Kőszeg)", "8aec937a"], "d": ["Suleyman Sang Pembuat Undhang-undhang maju karo wadyabalané menyang Austria kanggo meksa Charles V perang ara-ara; bèntèng cilik Güns nglawan suwéné selawé dina lan ngrèndhèti majuné wadyabala. Amarga kaisar ora metu perang, prajurit penyerbu (akıncı) nggebugi sakiwa-tengené Wina, lan amarga mangsa saya mlaku, wadyabala bali. Ekspedisi iki ora nggawa tambahan lemah, nanging kanthi nglungguhaké Habsburg ing méja rembugan, nyiapaké dhasar tentrem taun sabanjuré.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Prajanjian Istanbul — tentrem kapisan karo Habsburg", "b085767a"], "d": ["Sultan, sing nampa Cornelius, utusané Ferdinand, sarujuk gencatan senjata, lan muncul tèks tentrem resmi kapisan antarané Utsmaniyah lan Austria. Miturut prajanjian, Ferdinand sarujuk mbayar upeti taunan kanggo lemah Hungaria sing dicekel, lan archduke Austria ing protokol dianggep sadrajat karo wazir agung. Status sing ora imbang iki pratélan cetha saka pangaku unggulé diplomasi Utsmaniyah ing abad kaping nembelas.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Direbuté Kars lan pambukaan tapel wates lor-wétan", "742e3101"], "d": ["Nalika pasukan ngarep Ekspedisi Irak Loro belok ngétan saka Erzurum, bèntèng Kars, sing dicekel kaatabegan Géorgia lan wiwit jaman Timur dadi reruntuhan, dipasrahaké tanpa nemoni perlawanan. Amarga kutha iku nyekel dalan antarané lengkungan Aras lan Çıldır, dianggep dadi kunciné lawang lor sing mbukak menyang Iran. Bathi iki dadi mata ranté kapisan beylerbeylik Kars, sing diadegaké telung puluh taun sabanjuré, lan garis Kaukasus.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Mlebu Tabriz kanggo kapisan — pambukaan Ekspedisi Irak Loro", "cf7ed4e3"], "d": ["Ibrahim Pasya, sing maju dhisik minangka serdar-ı ekrem, mlebu ibu kutha Safawiyah Tabriz tanpa nemoni perlawanan amarga Syah Tahmasp nyingkiri perang lapangan lan mundur menyang pedhalaman. Sultan Sulaiman Sang Pembuat Undhang-undhang uga tekan kutha iku ing September; nanging amarga mangsa adhem wis teka lan jalur bekal kedawan banget, wadyabala belok menyang arah Baghdad lan Tabriz ora bisa dicekel suwé. Kutha sing direbut kanggo kaping pindho sawisé Chaldiran iki dadi panggonan Utsmaniyah sinau yen ing wétan ngrebut iku gampang, nanging njaga iku angèl.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Barbarossa nelukaké Tunis", "d8754216"], "d": ["Laksamana agung (kaptan-ı deryâ) Barbarossa Hayreddin Pasya, sawisé nggebugi pesisir Italia nganggo armadané, banjur nuju Tunis, ndadèkaké panguwasa Hafsiyah Mulay Hasan mlayu, lan mlebu kutha. Direbuté Tunis, sing papané ngawasi Selat Sisilia, sakala malik imbangan kakuwatan ing Segara Tengah sisih Kulon dadi untung tumrap Utsmaniyah. Nanging pangwasa iki ora suwé, lan Charles V bakal males ing taun sabanjuré nganggo armada gedhé.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Tunis ilang direbut Charles V", "a691f0f8"], "d": ["Charles V, ing ekspedisi gedhé sing disengkuyung armada Genoa lan Kepausan, sawisé ngrubuhaké La Goulette (Halkulvâd), ngrebut Tunis lan nglungguhaké manèh Mulay Hasan ing dhampar ing pangayoman Spanyol. Garnisun Spanyol dipapanaké ing kutha, lan majuné Utsmaniyah ing Segara Tengah sisih tengah diendheg sawetara. Penaklukan pungkasan Tunis lagi bisa patang puluh taun sawisé, ing 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operasi Gazi Husrev Bey ing sadawané Sava: Bosanski Brod lan Jasenovac", "3740ec83"], "d": ["Sawisé Jajce lan Banja Luka direbut ing 1528, bèntèng ing sadawané Kali Sava sawetara wektu isih ana ing tapel wates Kroasia-Slavonia sing nggandhèng makutha Habsburg. Gazi Husrev Bey, sing ing 1536 kanggo kaping telu dadi sanjak-bèy Bosnia, ing taun sing padha ngrebut Požega lan sakiwa-tengené, uga nambahaké bèntèng Brod lan Jasenovac ing pesisir Sava menyang pamaréntahan Utsmaniyah. Kanthi mangkono tapel wates lor Bosnia tekan Sava; tlatah iku dirampungaké rong taun sabanjuré kanthi direbuté Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Makbul Ibrahim Pasya diukum pati", "348aa7b8"], "d": ["Ibrahim Pasya, sing telulas taun dadi wazir agung lan dadi kanca paling rakeré Suleyman sarta wong nomer loro kasunyatané ing nagara, diukum pati kanthi dicekik tanpa alesan apa waé ing kraton, ing ngendi dhèwèké diundang buka pasa. Sikapé ing ekspedisi Irak, anggoné nganggo sesebutan 'serasker sultan', lan imbangan ing njero kraton dianggep mèlu dadi sebabé sedané. Ukuman pati iki titik owah sing nuduhaké yèn wazir agung ora duwé kaslametan mutlak ing pamaréntahan pusat Utsmaniyah.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Penaklukan Bèntèng Klis lan adegé sancak Dalmatia", "6ffd4ebf"], "d": ["Murad Bey, kethüdâ-né Gazi Husrev Bey, wong mualaf asal Kroasia, ngrebut bèntèng strategis Klis, pas ing sisih loré Split, saka Venesia. Sanalika sawisé penaklukan, Klis didadèkaké puseré sancak lan kaza anyar sing nyakup sakiwa-tengené; tapel watesé sancak iki sebagéan gedhé nggambar rangkané Kroasia Utsmaniyah. Penaklukan iki, sing teka limalas taun sawisé Knin, njangkepi balung administrasi pedalaman Dalmatia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Pengepungan Korfu lan perang karo Venesia", "11af95bd"], "d": ["Sawisé ekspedisi Apulia (Pulya), wadyabala Utsmaniyah ndharataké prajurit ing Korfu lan ngepung bèntèng Venesia sing kuwat ing pulo iku. Amarga wujudé bèntèng sing curam, karugèn abot, lan kahanan mangsa, tanggal 6 September blokadé diudhari lan wadyabala mundur. Sanajan pengepungan ora ana asilé, perang sing kabukak karo Venesia dipungkasi kanthi akèh pulo ing Aegea lan Adriatik digabungaké karo Utsmaniyah lan kamenangan Preveza ing taun sabanjuré.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Ekspedisi Aegea Barbarossa: direbuté pulo-pulo sing langsung diprentah Venesia", "1b32ed96"], "d": ["Armada sing bali saka pengepungan Korfu, manfaataké pawartos perang marang Venesia, nampa siji-siji pulo ing Aegea sing ora kalebu kadipatèn nanging nggandhèng langsung karo Venesia. Aegina direbut sawisé perlawanan abot, Astypalaia sing dicekel kulawarga Querini bebarengan karo Karpathos lan Kasos nyerah, lan Patmos sing diprentah biara uga nampa pangayoman Utsmaniyah. Nanging Kadipatèn Naxos ditinggal ing panggonané kanthi diwajibaké mbayar upeti; aneksasiné kudu ngentèni 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Ekspedisi Aegea Lor Barbarossa: direbuté Skyros lan Sporades Lor", "20ab688e"], "d": ["Ing dalan menyang Preveza, armada nampa siji-siji pulo Aegea Lor sing sawisé penaklukan Istanbul ngungsi marang Venesia. Skyros ing sisih lor Eubea (Negroponte) lan Skiathos, Skopelos sarta Alonissos sing nyekel cangkeming Teluk Salonika mangkono mlebu pamaréntahan Utsmaniyah. Pulo-pulo iki nutup celah pungkasan ing Aegea Lor sing, sanajan Eubea wis direbut ing 1470, isih suwidak wolu taun manèh ana ing tangan Venesia.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Direbuté Aden lan aneksasi pesisir Yaman", "e7d46d8f"], "d": ["Armada sing budhal saka Suez kanggo ekspedisi India dhisik tumuju pesisir Yaman, amarga ora bisa metu menyang samodra tanpa ngamanaké Segara Abang. Hadım Suleyman Pasya mlebu plabuhan Aden ing 3 Agustus 1538; panguwasa Tahiriyah Amir bin Dawud, sing condhong marang Portugis, digawa menyang lawang kapten lan dipatèni, lan penjaga cacah 500 wong ditinggal ing kutha. Ing ekspedisi sing padha Mocha sarta pulo Kamaran lan Farasan sing nguwasani selat uga dipasrahaké, lan dhasar beylerbeylik Yaman dipasang. Kanthi mangkono Nagara Utsmaniyah kanggo kapisan nduwé kabèh pesisir lor Bab al-Mandab; déné Sana'a lan tlatah pedhalaman kudu ngentèni sangang taun manèh.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Ekspedisi Moldavia lan panggabungan tlatah Bucak (Bender)", "90a88a56"], "d": ["Ing ekspedisi nglawan voivode Moldavia Petru Rareş, sing ora netepi kuwajibané marang Utsmaniyah, Suceava direbut lan kutha Iași dijarah déning Khan Krimea Sahib Giray. Sultan ngangkat Stefan Walang (Çekirge Stefan) dadi voivode lan nggabungaké tlatah Bucak (Bessarabia Kidul) bebarengan karo Bender langsung menyang lemah Utsmaniyah. Panggabungan iki dadi salah siji mata ranté sing ngowahi pesisir lor-kulon Segara Ireng dadi segara njero Utsmaniyah. Moldavia pancèn wis dadi voivodat bawahan Utsmaniyah; ekspedisi iki ora ngrebut lemah saka nagara manca, mung njupuk pamaréntahan njero Bender lan Bucak saka voivode lan nggandhèngaké langsung karo sultan; sisané voivodat tetep nganggo status bawahan. Susunan sing padha bakal dibalèni ing 1484 ing Kili lan Akkirman, lan ing 1713 ing Hotin: bèntèng tapel wates langsung, lemah pedalaman bawahan.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Anabolu (Nafplion) dipasrahaké liwat prajanjèn", "104d0937"], "d": ["Perang Venesia sing lumaku telung taun sawisé Preveza rampung nalika republik iku sarujuk ngulungaké rong bèntèng pungkasané ing Morea. Anabolu lan Benefşe, sing ora bisa direbut lumantar pengepungan, dipasrahaké marang Utsmaniyah ing méja rembugan, saliyané ganti rugi perang telung atus èwu dukat. Semenanjung Morea mangkono dadi wutuh tanpa ana siji tapak sikil Venesia.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Szeged mlebu pamaréntahan Utsmaniyah lan liva Szeged dibentuk", "019aa000"], "d": ["Sawisé pamaréntahan Utsmaniyah diadegaké kanthi wutuh ing Buda ing 1541, para pinituwa Szeged ngakoni kedaulatan Ferdinand I lan nyiapaké pertahanan nganggo gaman. Beylerbeyi Buda Küçük Bâlî Pasya ing wiwitan 1543 nimbali para pimpinan kutha lan matèni wong-wong mau amarga dianggep ngkhianati, banjur ngirim pasukan kanggo ngrebut kutha. Ing wektu iku liva Szeged dibentuk lan Derviş Bey, putrané Bâlî Pasya, diangkat dadi sanjak-bèy kapisan; liva iku wiwitané dawa antarané Kali Donau lan Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Penaklukan Valpo, Šikloš lan Pécs", "2ca030a3"], "d": ["Tujuan kapisan ekspedisi Hungaria sing dianakaké rong taun sawisé aneksasi Buda yaiku ngamanaké sayap kidul eyalet anyar antarané Kali Drava lan Donau. Sawisé bèntèng Valpo lan Šikloš direbut, Pécs, pusaté Baranya, nyerah. Kutha iku bakal dadi pusat sing paling akèh pendhudhuké lan paling akèh dibangun ing Hungaria Utsmaniyah, lan sejarawan İbrahim Peçuylu njupuk jenengé saka kene.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Penaklukan Esztergom lan Székesfehérvár", "efca9e05"], "d": ["Ing ekspedisi Hungaria sing dipimpin Suleyman dhéwé, sawisé pengepungan rong setengah minggu, Esztergom, puser agama Karajan Hungaria lan kutha keuskupan agung, mlebu pamaréntahan Utsmaniyah. Banjur Székesfehérvár, kutha penobatan raja-raja Hungaria, uga direbut, lan sabuk pertahanan provinsi Buda dadi jangkep. Esztergom bakal tetep ana ing tangané Utsmaniyah nganti 1595 minangka bèntèng kunci garis Donau.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Sabuk pertahanan lor lan kulon Buda: Vác, Hatvan lan Simontornya", "733ee5ce"], "d": ["Sawisé Esztergom lan Székesfehérvár direbut, beylerbeyi Buda, tanpa ekspedisi sultan, obah kanggo ngrampungaké lingkaran bèntèng sing ngubengi ibu kutha. Vác ing tikungan Donau, Hatvan, lawangé Alföld, lan Simontornya ing garis Sió dipasrahaké siji-siji. Asil taun sing sepi iki ngowahi Buda saka kutha tapel wates dadi pusat eyalet sing bakal tahan satus patang puluh taun.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksasi Basrah lan metu menyang Teluk Persia", "02f87c11"], "d": ["Nalika penaklukan Baghdad (1534), panguwasa Basrah Râşid bin Megāmis wis nyatakaké manut marang Sultan Sulaiman Sang Pembuat Undhang-undhang lan ing 1538 ngirim kunci-kunci kutha. Gantiné, Syekh Yahyâ, njupuk sikap nglawan Utsmaniyah, mula beylerbeyi Baghdad Ayas Pasya maju liwat dharat, lan sanjak-bèy Mosul maju liwat Kali Efrat karo 120 kapal; Ayas Pasya mlebu Basrah ing 26 Desember 1545 lan kutha iku dadi pusat beylerbeylik. Plabuhan ing muara Shatt al-Arab iki dadi lawang Utsmaniyah mbukak menyang teluk sing dikuwasani Portugis saka Hormuz; liwat Prajanjèn Amasya 1555 Iran uga ngakoni kahanan iki.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Penaklukan Sana'a lan pedhalaman Yaman", "d31ded85"], "d": ["Sawisé Taiz, Sana'a uga direbut lan kabèh nagara iku digandhèngaké menyang beylerbeylik. Nanging amarga géografi sing curam lan beda madzhab, panguwasan iki ora tau kepénak; Yaman dadi garis ngarep sing terus-terusan nguntal prajurit Utsmaniyah.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Penaklukan Taiz", "d4509df9"], "d": ["Ing Yaman, panggonan sangang taun sadurungé Utsmaniyah wis marem mung nduwé jalur pesisir, para imam Zaidiyah saya kuwat ing pedhalaman pegunungan; mula pasukan Özdemir Pasya munggah menyang dhataran dhuwur lan ngrebut Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Prajanjian Istanbul — tentrem limang taun karo Habsburg", "41f81773"], "d": ["Tentrem suwéné limang taun ditandhatangani antarané Utsmaniyah lan Habsburg; Ferdinand sarujuk mbayar 30.000 dukat saben taun kanggo lemah Hungaria sing dicekel. Prajanjian iki ndhaftar sacara hukum kahanan nyata Hungaria sing kapérang telu. Kanthi front kulon diamanaké mangkono, Suleyman éntuk kalodhangan nata ekspedisi anyar nglawan Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Ekspedisi Iran Kapindho lan Tabriz direbut manèh", "e82365df"], "d": ["Ing ekspedisi sing dianakaké amarga dorongané Elqas Mirza, seduluré Syah Tahmasp sing mbrontak lan ngungsi menyang Istanbul, wadyabala mlebu Tabriz kanggo kaping pindho. Amarga Safawiyah manèh ora gelem perang lapangan lan mundur karo ngobong lemah, wadyabala mung bisa manggon ing kutha sawetara minggu. Ekspedisi iki nggawé mesthi yen Tabriz ora bisa dicekel lan ngarahaké stratégi Utsmaniyah kanggo gawé garis tapel wates sing tetep, yaiku nguwataké Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Penaklukan Van lan tapel wates wétan ditetepaké", "fc8f930b"], "d": ["Bèntèng Van, sing dikepung nalika bali saka Tabriz, kanthi panggonané ing ndhuwur gunung watu ing pesisir wétan tlaga, minangka kunci tlatah iku sing ora bisa disulayakaké, lan nyerah sawisé pengepungan cendhak. Kutha iku langsung didadèkaké pusat beylerbeylik; sanjak Erciş, Adilcevaz lan Hakkâri digandhèngaké menyang kene. Beda karo Tabriz, Van tetep dicekel lan sajrone patang atus taun dadi kalungguhan tetep Utsmaniyah paling ngarep ing wétan.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksasi Al-Ahsa lan Qatif — pesisir Arab ing Teluk", "f6701e60"], "d": ["Sawisé Basrah direbut, Qatif, sing wis dadi pos ngarep Portugis ing pesisir kulon teluk, direbut, lan bebarengan karo oasis Al-Ahsa ing pedhalaman beylerbeylik anyar diadegaké. Saka kene operasi tumuju Bahrain lan Hormuz diwiwiti. Kanthi mangkono Nagara Utsmaniyah bebarengan nduwé swara ing pesisir Segara Abang lan Teluk Persia ing semenanjung Arab.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Shahrizor ilang — Sührâb, bèy Erdelân, condhong marang Safawiyah", "5600efc9"], "d": ["Tlatah Shahrizor, sing wis ngakoni pamaréntahan Utsmaniyah nalika Ekspedisi Irak Loro (1535), diprentah emir Erdelân Bige Bey sing manggon ing Bèntèng Zalm. Sawisé Bige Bey séda ing 1550, seduluré Sührâb, sing ngrebut Bèntèng Zalm lan nguwasani kadipaten, ngalih menyang Safawiyah lan medhot manut marang Utsmaniyah; mula tlatah Shahrizor metu saka pangaribawa Utsmaniyah. Tlatah iku lagi bali nalika ekspedisi Nakhchivan, ing 1554, kanthi Bèntèng Zalm dikepung lan direbut.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Direbuté Ardahan lan cekungan Çıldır", "14c9eb76"], "d": ["Beylerbeyi Erzurum, nalika perang karo Safawiyah isih lumaku, ngarah tanah para atabeg Géorgia ing lengkungan Kali Kura lan nggandhèngaké Ardahan lan sakiwa-tengené Çıldır menyang pamaréntahan Utsmaniyah. Kanthi mangkono garis Kars-Ardahan dadi wutuh lan dhataran dhuwur ing lor-wétan sing mbukak menyang Géorgia dikuwasani. Tatanan administrasi pungkasan tlatah iku bakal dirampungaké liwat eyalet Çıldır sing diadegaké pitulikur taun sabanjuré.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pasya nyabrang Kali Donau — wiwité perang Transylvania", "38fde931"], "d": ["Amarga kekisruhan sing dijalari biarawan Martinuzzi, wali raja Transylvania cilik János Zsigmond, lan Transylvania masrahaké bèntèng Banat marang Ferdinand, ekspedisi anyar dianggep prelu; pimpinan diwènèhaké marang beylerbeyi Rumelia Sokollu Mehmed Pasya. Sanajan Martinuzzi nyoba ngulur wektu, wadyabala nyabrang Kali Donau lan ngrebut Becse, Becskerek, Csanád lan Lippa; nanging pengepungan Temeşvar dibatalaké ing 16 November amarga adhem. Kanthi mangkono perang anyar Utsmaniyah-Habsburg dibukak ing Hungaria.", "85071c5e"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Palanka-palanka Banat Kidul dikuwasani déning pasukan sing dikirim saka Temeşvar — Versec, Haram, Keve", "edca0921"], "d": ["Sawisé Temeşvar nyerah marang wadyabala Utsmaniyah, pasukan sing dipisahaké saka wadyabala pangepung tumuju menyang palanka-palanka cilik ing Banat; miturut critané Bánlaky, palanka Versec, Facset, Mehádia, Csákóvár, Haramvár lan Keve dikuwasani déning pasukan iki. Kanthi mangkono Haram ing pinggir Kali Donau uga tiba ing tangan Utsmaniyah.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Penaklukan Szolnok lan gagalé pengepungan Eger", "a7156e8f"], "d": ["Sawisé Temeşvar direbut, rong wadyabala Utsmaniyah sing nyawiji ngrebut Szolnok ing Kali Tisza meh tanpa perang, amarga penjaga bayaran ninggalaké bèntèng. Nanging bèntèng Eger, sing banjur dikepung, ora bisa direbut amarga perlawanan telung puluh wolu dina garnisun rong èwu wong kanthi pimpinan István Dobó, lan wadyabala mundur nalika mangsa adhem teka. Ing ekspedisi sing padha siji bèntèng tiba gampang déné sijiné tahan, iki dadi pratandha cetha kapisan yen tapel wates ing Hungaria wis ora maju dhéwé kanggo kauntungan Utsmaniyah.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Persekutuan Utsmaniyah-Prancis — armada Prancis ana ing sangisoré dhawuh Utsmaniyah", "a8e01b22"], "d": ["Miturut prajanjian tanggal 1 Februari 1553, armada Prancis dipasrahaké ing sangisoré dhawuh armada Utsmaniyah; operasi bebarengan nglawan Spanyol ing Segara Tengah sisih Kulon wis dirancang. Sawisé prajanjian, Turgut Reis tanggal 15 Juni 1553 mangkat karo patang puluh lima kapal galley kanggo nyengkuyung Prancis. Iki prajanjian persekutuan resmi kapisan sing ngowahi dhasar dagang kapitulasi 1536 dadi gotong royong militèr.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Pangéran Mustafa diukum pati ing Ereğli Konya", "dec36858"], "d": ["Pangéran Mustafa, sing mlebu tarupé ramané arep gabung karo wadyabala sing diklumpukaké kanggo ekspedisi Nakhchivan, pas arep ngadhep sultan kepethuk para algojo lan dipatèni kanthi dicekik. Matènané calon putra mahkota sing ditresnani banget ing wadyabala nuwuhaké nesu jero ing antarané Janissari, lan Rüstem Pasya dicopot saka kalungguhan wazir agung. Prastawa iki mlebu sastra lan ingatan rakyat minangka salah siji retakan sing paling akèh dipadu ing pulitik pangéran Utsmaniyah.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Tapel wates Ibrim lan Nubia dipindhah ngidul", "c57d5d77"], "d": ["Tapel wates kidul beylerbeylik Mesir dipindhah menyang sabrangé katarak kapindho nalika bèntèng Ibrim, sing ngadeg ing ndhuwur tanjung watu ing Kali Nil, dikuwataké déning Özdemir Bey lan Nubia Ngisor digabungaké kanthi wutuh menyang Mesir Utsmaniyah. (Tatanan administrasi Utsmaniyah ing Ibrim wis diadegaké sawisé penaklukan Mesir; ing péta Ibrim dituduhaké minangka Utsmaniyah wiwit 1517. Taun iki kira-kira, sumber ora mènèhi taun.) Bèntèng iku dadi tanggul nglawan serbuan saka Nubia uga titik pangawasan dalan emas lan budhak menyang Sennar. Pasukan penjaga Bosnia sing dipanggonaké ing kene dadi tetep banget nganti turuné isih ana ing bèntèng telung atus taun sabanjuré. Sumber-sumber mènèhi rong crita sing béda bab wektu Ibrim mlebu pamaréntahan Utsmaniyah: artikel TDV bab Sudan nyambungaké gabungé Nubia Ngisor menyang Mesir Utsmaniyah karo operasi Özdemir Pasya ing tengahé abad kaping 16, déné artikel Nubia nulis yen tlatah nganti lembah Wadi Halfa lan tatanan administrasi ing Ibrim diadegaké sanalika sawisé penaklukan 1517. Sanjak Ibrim digandhèngaké menyang eyalet Habeş ing 26 Juli 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Bijayah (Bougie) direbut saka Spanyol", "49691cda"], "d": ["Bijayah, sing wis patang puluh telu taun ana ing tangan Spanyol lan mbagi pesisir antarané Aljir lan Konstantinah dadi loro, nyerah sawisé dikepung saka dharat lan segara. Kanthi tibané bèntèng, pesisir ojak Aljir dadi sambung tanpa pedhot nganti Oran. Ing Spanyol, kélangan iki nuwuhaké nesu gedhé banget nganti panglima sing masrahaké bèntèng, Alonso de Peralta, dipatèni ing nagarané.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Zeila digabungaké menyang Eyalet Habeş", "7bbf369a"], "d": ["Plabuhan Zeila ing pesisir Afrika Teluk Aden, ing pucuk kidul eyalet Habeş, digandhèngaké menyang pamaréntahan Utsmaniyah. Kutha iki, lawang segara Kasultanan Adal, minangka titik bekal pungkasan kanggo kapal sing metu saka Bab al-Mandab. Kanthi gabungé Zeila, tapel wates Nagara Utsmaniyah ing Afrika tekan titik paling kidul.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Perang Para Pangéran ing Konya", "1c8de387"], "d": ["Pangéran Bayezid, sing mlebu perjuangan dhampar, teka ing ngarep Konya karo pasukan watara 30.000 wong lan, ing tempuran sing suwéné rong dina, kalah déning sadulure, Pangéran Selim. Bayezid sing kalah ngungsi menyang Iran, menyang Syah Tahmasb, liwat Amasya. Perang iki ngowahi krisis warisan tahta ing taun-taun pungkasané Suleyman Sang Pembuat Undhang-undhang dadi prakara pulitik njaba negara.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Kamenangan Segara Djerba", "c7b905c1"], "d": ["Armada Utsmaniyah ing pangwasané Piyâle Pasya mbuyaraké armada sekutu Spanyol-Genoa-Malta, sing diklumpukaké kanggo ngrebut manèh Tripoli, ing ngarep Djerba kanthi manuver pecah dadi loro. Sekutu kélangan pérangan gedhé armadané, lan bèntèng ing pulo kuwi uga énggal tiba. Djerba dianggep kamenangan segara gedhé kapindho, sawisé Preveza, sing ngukuhaké unggulé Utsmaniyah ing Segara Tengah.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Pangéran Bayezid diukum pati ing Qazvin", "a759de14"], "d": ["Pangéran Bayezid sing ngungsi menyang Iran, sawisé tawar-tinawar suwé, dipasrahaké déning Syah Tahmasb marang utusan Utsmaniyah lan dipatèni kanthi dicekik bebarengan karo patang putrané. Minangka gantiné pamasrahan, Safawiyah éntuk konsesi materi sing wigati lan jaminan tapel wates. Kanthi ukuman iki, alangan pungkasan kanggo Selim II jumeneng ilang, lan tatanan tentrem Prajanjian Amasya tetep dijaga.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Direbuté Khios saka wong Genoa", "a4559b96"], "d": ["Khios, sing sajrone rong atus taun diprentah minangka koloni dagang kulawarga Giustiniani saka Genoa lan mbayar upeti marang Utsmaniyah, dipasrahaké marang Piyâle Pasya tanpa sapeluru pun ditembakaké, kanthi alesan upetiné telat lan mènèhi plabuhan marang kapal mungsuh. Bebarengan karo Khios lan Psara, anané Genoa pungkasan ing pesisir wétan Aegea uga disingkiraké. Produksi mastik wong Khios lan hak istimewané dijaga, lan pulo iku digandhèngaké menyang eyalet Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Aneksasi Kadipatèn Naxos — kabèh Kapuloan Cyclades", "68f0ec0b"], "d": ["Kadipatèn Latin Naxos, sing lumaku wiwit 1207 lan wiwit 1537 mbayar upeti marang Utsmaniyah, dibubaraké kanthi alesan sambat bab duke pungkasan Giacomo Crispo sing nindhes rakyaté. Naxos, Paros, Antiparos, Andros, Syros, Mykonos, Ios, Amorgos lan kabèh pulo Cyclades ing sakiwa-tengené dilebokaké langsung ing pamaréntahan Utsmaniyah liwat siji keputusan. Sultan Sulaiman Sang Pembuat Undhang-undhang sawetara wektu masrahaké pamaréntahan pulo marang Joseph Nasi; panguwasan Latin telung abad setengah mangkono rampung ing tengah Aegea.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Pambrontakan Yaman lan ekspedisi Yamané Koca Sinan Pasya", "c8218d8e"], "d": ["Imam Zaidi al-Mutahhar mbrontak kanthi alesan pajeg dikumpulaké kanthi peksan lan nyabut pamaréntahan Utsmaniyah saka pérangan gedhé Yaman. Koca Sinan Pasya sing dikirim saka Istanbul, lumantar operasi ing antarané 1568-1570, ngrebut Kawkaban sawisé pengepungan suwé lan ngadegaké manèh pangwasa Utsmaniyah ing tlatah iku. Ekspedisi iki wigati banget kanggo njaga pangawasan marang gapura kidul Segara Abang lan dalan dagang Samudra Hindia.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Persekutuan pertahanan karo Kasultanan Aceh lan pitulungan ing Samudra Hindia", "8e835f24"], "d": ["Utusan Aceh, sing njaluk pitulungan marang Suleyman Sang Pembuat Undhang-undhang ngadhepi serangan Portugis, amarga sultan séda ing Szigetvár, ngaturaké kasetiané marang Selim II, lan prajanjian pertahanan ditandhatangani karo dhèwèké. Sultan dhawuh supaya mriyem, bedhil, amunisi, lan para tukang dikirim saka Iskandariyah; pitulas kapal perang disiapaké arep dikirim menyang perairan Hindia. Gedhéné pambrontakan Yaman ngalangi armada mangkat, nanging para ahli mriyem lan tukang Utsmaniyah sing tekan Aceh ninggalaké tilas sing langgeng ing tlatah iku.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Pendharatan ing Siprus: direbuté Limassol", "9074ccc9"], "d": ["Wadyabala Utsmaniyah sing mudhun ing pulo ngrebut Limassol tanpa nemoni perlawanan sing akèh lan dina sabanjuré tumuju Larnaka. Amarga pendhudhuk setempat ora marem karo pamaréntahan Venesia lan mbiyantu pasukan Utsmaniyah, ing Larnaka uga ora ana perlawanan serius; dermaga Tuzla didadèkaké pangkalan nurunaké prajurit lan piranti. Venesia numpuk pertahanané ing Nikosia lan Famagusta; gubernur Paphos lagi nyatakaké manut marang panglima sawisé Nikosia tiba.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Penaklukan Nikosia", "413d866b"], "d": ["Sawisé pengepungan sing diwiwiti tanggal 25 Juli 1570 lan suwéné patang puluh lima dina, Nikosia, krajan Siprus ing pamaréntahan Venesia, nyerah marang wadyabala Utsmaniyah. Tibané puser pulo meksa perlawanan Venesia kejepit ing bèntèng Famagusta. Penaklukan iki nuwuhaké kumandhang gedhé ing Kulon lan nyepetaké proses menyang adegé armada Liga Suci sing dipimpin Paus.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Pasrahé Kyrenia — pesisir lor Siprus", "39fdeea5"], "d": ["Tibané Nikosia ing 9 September, kanthi pembantaian nganggo pedhang, nugel perlawanan ing lor Siprus. Bèntèng Kyrenia, ing mburi pegunungan Pentadaktylos, nalika ngerti nasib ibu kutha, wolung dina sabanjuré nyerah kanthi sarat lan garnisuné diidinaké metu saka pulo. Ing pulo gendéra Venesia mung kari ing Famagusta; iku uga bakal tahan sewelas sasi manèh.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Pambangunan manèh armada sawisé Lepanto", "db51fe44"], "d": ["Pagawéan kapisan Kılıç Ali Pasya, sing diangkat dadi laksamana agung sawisé bencana Lepanto, yaiku mbangun manèh armada sing nandhang karugèn abot; galangan-galangan kapal kerja tanpa leren sajroné mangsa adhem 1571-1572. Ing Juni 1572, armada anyar sing dumadi saka watara 250 kapal galley lan 300 galley reis sukarela mlebu Segara Tengah. Pulihé sing cepet iki nuduhaké yèn Lepanto ora bisa matahaké kakuwatan segara Utsmaniyah kanthi tetep.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Prajanjian Istanbul karo Venesia — Siprus diakoni", "4d08ef50"], "d": ["Venesia, sing dadi dhéwékan amarga Liga Suci bubar, gawé tentrem dhéwé karo Utsmaniyah, resmi ngakoni yèn Siprus duwèké Utsmaniyah, lan nampa mbayar ganti rugi perang. Prajanjian iki nuduhaké kanthi cetha yèn kamenangan Lepanto ora nggawa untung pulitik tumrap donya Kristen. Wiwit iku, suwéné pitung puluh taun, Venesia bakal ngéndhani perang langsung karo Utsmaniyah.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Sédané Selim II", "c289f5ee"], "d": ["Selim II, sing watara rong sasi sawisé tiba ora bisa rawuh ing divan, banjur séda. Sédané didhelikaké ing kraton suwéné rolas dina nganti putra mbarepé, Murad, teka ing Istanbul saka Manisa. Sumber-sumber béda ngenani dina sédané: Selânikî nyebut 15 Desember; Gerlach, Mehmed b. Mehmed, lan Cenâbî nyebut 13 Desember.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Pangumuman sédané Selim II lan jumenengé Murad III", "84334d70"], "d": ["Sédané Selim II lan jumenengé Murad III, sing digawa saka Manisa, diumumaké resmi tanggal 22 Desember 1574. Sultan anyar bakal ana ing dhampar suwéné selikur taun, lan pamaréntahané bakal dièlingi amarga perang dawa karo Iran ing Wétan, wayah sadurungé Perang Dawa ing Kulon, lan ing njero negara amarga mudhuné kadar logam akçe. Nganti sedané Sokollu Mehmed Pasya ing 1579, tatanan lawas lumaku terus ing pamaréntahan nagara.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Perang Wadi al-Makhazin (Alcácer Quibir) — Abd al-Malik sing disengkuyung Utsmaniyah numpes wadyabala Portugis", "21280dac"], "d": ["Abd al-Malik, sing lungguh ing dhampar Maroko kanthi panyengkuyungé Utsmaniyah, numpes wadyabala gedhé Raja Portugis Sebastian ing Wadi al-Makhazin; amarga telu panguwasa mati bebarengan ing perang iku, ing sumber Kulon diarani 'Perang Telung Raja'. Kakuwatan militèr Portugis ambruk, lan ora suwé sawisé negara iku tiba ing tangané Spanyol. Abd al-Malik uga tiwas ing perang; sadulure sing ngganteni, Ahmad al-Mansur, ngabaraké kamenangan menyang Istanbul lumantar utusan. Sesambungané rong nagara tetep ing tataran ijol-ijolan utusan lan pisungsung, dudu upeti utawa status bawahan, lan ora suwé sawisé dadi tegang amarga prakara pisungsung.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Rakyat Derbent nyatakaké setya marang Lala Mustafa Pasya — Lawang Wesi ing pamaréntahan Utsmaniyah", "9c55aeff"], "d": ["Nalika ekspedisi Shirvan, utusan pitung wong saka rakyat Derbent teka marang Serdar Lala Mustafa Pasya sing ana ing Ereş lan nyatakaké setya. Derbent (Lawang Wesi), sing nutup dalan sempit antarané tembok Kaukasus lan Segara Kaspia, nduwé peran kunci kanggo njaga Shirvan, minangka dalan wajib kanggo dalan dharat saka lor. Panguwasan Utsmaniyah ing kene lumaku nganti 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Penaklukan Shirvan: direbuté Shamakhi", "9afae4c1"], "d": ["Wadyabala sing mbukak dalan menyang Kaukasus sawisé Kamenangan Çıldır mlebu Shirvan, provinsi paling sugih Safawiyah ing pesisir Kaspia, lan ngrebut kutha pusaté Shamakhi. Özdemiroğlu Osman Pasya diangkat dadi beylerbeyi ing kono, mula cabang lor Dalan Sutra mlebu ing pangawasan Utsmaniyah. Shirvan bakal dadi garis ngarep sing paling kerep ganti tangan lan paling larang ing perang wétan sing lumaku rolas taun.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Direbuté Baku — tekan pesisir Kaspia", "eb5adab8"], "d": ["Minangka mata ranté pungkasan operasi Shirvan, plabuhan Baku ing pesisir kulon Segara Kaspia direbut. Sumur lenga bumi ing sakiwa-tengené kutha, sanajan ing jaman iku, minangka sumber pametu sing wis dingertèni, lan plabuhan iku dadi titik metuné sutra Iran sing teka liwat Kaspia. Kanthi mangkono Nagara Utsmaniyah, kanggo kapisan lan siji-sijiné ing sajarahé, nduwé pesisir ing Segara Kaspia.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Penaklukan Erivan (Revan) lan pambangunan bèntèng", "7f623b7b"], "d": ["Ferhad Pasya, sing ing Kars nampa prentah supaya lunga menyang Erivan lan mbangun bèntèng ing kono, maju menyang Erivan, lan kutha iku mlebu ing pangawasan Utsmaniyah ing wiwitan Ramadhan 991 (tengahé September 1583). Ing Erivan, sing nyekel lawang lor lembah Aras, bèntèng anyar lan gedhé dibangun; kutha iku didadèkaké pusat beylerbeylik. Erivan sing ana ing tengah dalan wadyabala antarané Kars lan Tabriz minangka balung geger logistik garis ngarep wétan. Bèntèng iku dibangun kuwat banget nganti rong atus taun sabanjuré tetep dadi sasaran perang Utsmaniyah-Iran.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Aneksasi Karabakh lan Ganja", "29abaead"], "d": ["Minangka bathi pungkasan perang wétan sepuluh taun, Ferhad Pasya maju menyang Ganja ing 1588 lan mlebu kutha ing 1 September; tlatah Karabakh antarané Kali Kura lan Aras lan pusaté, Ganja, mlebu ing pamaréntahan Utsmaniyah. Kanthi mangkono Shirvan, Erivan lan Karabakh nyawiji dadi garis Utsmaniyah tanpa pedhot ing Kaukasus. Prajanjèn Ferhad Pasya sing ditandhatangani ing 1590 bakal ngesahaké tapel wates iki, nanging bathi iku mung bisa dicekel rong puluh taun.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Penaklukan Bihać", "651a7275"], "d": ["Beylerbeyi Bosnia Telli Hasan Pasya, sawisé ngrebut Ripač, bèntèng ngarep Bihać, ing November 1591, banjur ngrebut kutha lan bèntèngé dhéwé ing 1592; sawisé pengepungan sepuluh dina, komandan Lamberg nyerah. Penaklukan iki ndorong tapel wates Bosnia maju sauruté Kali Una lan dadi tambahan gedhé pungkasan Utsmaniyah sadurungé Perang Dawa, sing mbledhos setaun sawisé bebarengan karo Telli Hasan Pasya gugur ing ngarep Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Wiwitané 'Perang Dawa' Utsmaniyah-Austria", "bd22c392"], "d": ["Nalika beylerbeyi Bosnia Telli Hasan Pasya kalah lan gugur ing ngarep Kulpa (Sisak), Nagara Utsmaniyah ngumumaké perang marang Austria, lan diwiwiti Perang Dawa sing bakal suwéné telulas taun. Perang iki, ing ngendi infantri nganggo gaman geni dadi sing nemtokaké, nyepetaké panggunané sekban lan prajurit bedhil ing tatanan wadyabala Utsmaniyah lan njeronaké kamunduran sipahi sing nyekel timar. Perang bakal rampung ing 1606 kanthi Prajanjian Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pasya mangkat ing ekspedisi Austria — ekspedisi kapisan Perang Dawa", "d4a2f46d"], "d": ["Sawisé beylerbeyi Bosnia Hasan Pasya kalah lan gugur ing ngarep Sisak, wazir agung Koca Sinan Pasya mbujuk sultan supaya gelem perang lumantar tembung manis lan janji, banjur mangkat karo 12.000 Janissari lan pasukan liyané. Kanthi mangkono kabukak ekspedisi kapisan perang Utsmaniyah-Austria sing bakal suwéné telulas taun.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Penaklukan Yanıkkale (Győr)", "14b75207"], "d": ["Wazir agung Koca Sinan Pasya, sawisé pengepungan luwih saka sasasi, nampa nyerahé Yanıkkale, sing dianggep kuncine dalan menyang Wina. Tibané bèntèng nuwuhaké geger gedhé ing Éropah lan dadi tambahan paling gemilang Utsmaniyah ing Perang Dawa. Nanging bèntèng iku mung bisa dicekel suwéné patang taun.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Sédané Murad III", "1b62e886"], "d": ["Sawisé mréntah selikur taun, Murad III séda ing dina-dina nalika wadyabala Wallachia ngobong Brăila lan maju nganti Silistra, lan disarèkaké ing pasaréan Hagia Sophia. Putrané, Mehmed III, sing ditimbali saka Manisa, tekan Istanbul sepuluh dina sawisé lan jumeneng (27 Januari 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Esztergom ilang direbut Austria", "f420d333"], "d": ["Para panjaga Esztergom, sing ora éntuk pitulungan cekap ing pengepungan sing dipimpin Karl von Mansfeld, masrahaké bèntèng marang Archduke Matthias. Kanthi rampungé pangwasa Utsmaniyah sèket loro taun, ranté pertahanan ing garis Donau pecah lan Buda langsung kaancam. Bèntèng iku lagi bisa direbut manèh sepuluh taun sawisé, ing 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Penaklukan Bèntèng Eger", "3e511629"], "d": ["Sawisé perjuangan telung minggu, bèntèng kuwat Eger, sing sadurungé ora tau bisa direbut Utsmaniyah, tiba amarga para panjagané nyerah. Penaklukan iki, sing sultan dhéwé ana ing kono, sathithik ndandani semangat sing rusak amarga ilangé Esztergom, lan provinsi Eger diadegaké. Bebarengan karo kamenangan Mezőkeresztes sing diraih rong minggu sawisé, taun 1596 dadi taun Utsmaniyah sing paling kasil ing Perang Dawa.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Ilangé Yanıkkale (Győr)", "b4ccc679"], "d": ["Pasukan ing pangwasané Miklós Pálffy lan Adolf von Schwarzenberg ngrebut manèh Yanıkkale lumantar serbuan dadakan kanthi mbledhosaké gapura bèntèng. Ilangé bèntèng, sing patang taun sadurungé diranggèh Koca Sinan Pasya kanthi rekasa gedhé, ngambrukaké garis ngarep Utsmaniyah ing Hungaria. Sanajan ing taun sing padha pasukan mungsuh sing ngepung Buda dipukul mundur, imbangan perang saya malih dadi perang sing ngentèkaké tenaga.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Pambrontakan Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, sing nglumpukaké sekban lan levend sing minggat saka wadyabala ing Perang Dawa, nguwasani tlatah amba ing Anatolia Tengah, ngrebut Bèntèng Urfa (November 1599), ngumumaké awaké dadi sultan kanthi sesebutan 'Halim Syah', lan ngirim firman sing nganggo tughrané dhéwé. Karayazıcı, sing dianggep pimpinan kapisan ombak gedhé Celali, mati ing 1602, lan gerakané diterusaké sadulure, Deli Hasan. Pambrontakan iki wiwitané jaman 'pangungsèn agung', nalika wong tani Anatolia akèh-akèhan ninggalaké lemahé.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Pertahanan Kanizsa déning Tiryaki Hasan Pasya", "d56a5e6a"], "d": ["Archduke Ferdinand lan sekutuné, sing kepéngin ngrebut manèh Kanizsa sing ditelukaké setaun sadurungé, ngepung bèntèng iku luwih saka rong sasi; Tiryaki Hasan Pasya nglawan karo pasukan 9000 wong. Sanajan ora éntuk pitulungan saka njaba, dhèwèké nulak serbuan umum lan, lumantar serangan metu saka bèntèng, meksa mungsuh mundur kanthi nandhang karugèn abot. Pertahanan iki dadi crita kapahlawanan ing panulisan sajarah Utsmaniyah, lan 'Pengepungan Kanizsa' dadi genre sastra dhéwé.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Sédané Mehmed III lan jumenengé Ahmed I", "da735fde"], "d": ["Nalika Mehmed III séda tanggal 20 Desember, putrané sing umur patbelas taun, Ahmed I, jumeneng. Dhèwèké sultan kapisan sing lungguh ing dhampar nalika isih bocah lan tanpa tau dikirim mimpin sancak, lan iki nuduhaké yèn cara nggulawenthah para pangéran ing dhaérah kasunyatané wis rampung. Ing pamaréntahan Ahmed I, adat matèni sadulur bakal ditinggal lan diganti prinsip 'ekberiyet' (anggota lanang paling tuwa sing ngganteni dhampar).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Esztergom direbut manèh", "7330f273"], "d": ["Wazir agung Lala Mehmed Pasya ngepung Esztergom, sing ilang sepuluh taun sadurungé, lan nglebokaké manèh menyang pamaréntahan Utsmaniyah. Ing ekspedisi sing padha, Pest lan Vác uga diluwari, lan Utsmaniyah nata manèh garisé ing Hungaria. Kasil iki ndadèkaké ing taun sabanjuré Utsmaniyah bisa lungguh ing méja rembugan Zsitvatorok saka kalungguhan sing rada kuwat; Esztergom bakal tetep ana ing tangané Utsmaniyah nganti 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Kamenangan Dhataran Oruç lan ditumpesé pambrontakan Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Pasya, sing ngedegaké kabèylikan mardika ing Aleppo lan golek persekutuan karo Toscana, dikalahaké abot ing Dhataran Oruç déning wazir agung Kuyucu Murad Pasya. Kanthi ngedegaké manèh wibawa pusat ing Suriah, cabang ombak Celali sing paling mbebayani dipecah. Panumpesan tanpa welas déning Kuyucu Murad Pasya sing suwéné rong taun netepaké katentreman ing Anatolia, sanajan mung sawetara.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Kamenangan Alaçayır lan ditumpesé pambrontakan Kalenderoğlu", "55db0485"], "d": ["Pimpinan Celali Kalenderoğlu, sing meksa tlatah Manisa lan Bursa mbayar upeti, dikalahaké ing Alaçayır déning Kuyucu Murad Pasya lan kepeksa mlayu menyang Iran. Kanthi kamenangan iki, wadyabala Celali gedhé pungkasan ing Anatolia dibuyaraké. Panumpesan sing keras déning Kuyucu Murad Pasya, sing miturut crita ngisi sumur-sumur sing dikon didhudhuk nganggo para pambrontak sing dipatèni, sanajan sajroné wektu cendhak netepaké katentreman, ora bisa ngganti ilangé cacah jiwa lan asil produksi Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Ahidname kapisan diparingaké marang Walanda", "5d9d117e"], "d": ["Cornelis Haga, utusan Republik Persatuan Walanda, kasil éntuk saka Ahmed I ahidname sing cakupané padha karo sing diparingaké marang Prancis lan Inggris. Kanthi mangkono Walanda éntuk hak mbukak kedhutaan ing Istanbul, mbukak konsulat ing plabuhan-plabuhan Utsmaniyah, lan dagang nganggo gendérané dhéwé. Ahidname iki nglambangaké mlebuné kakuwatan segara saka lor, sing ngganti Venesia ing dagang Segara Tengah, menyang pasar Utsmaniyah.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Sédané Ahmed I lan jumenengé Mustafa I — cara ekberiyet", "9901c09e"], "d": ["Sawisé lara weteng suwéné sèket siji dina, Ahmed I sing umur wolulikur taun séda, lan sing didadèkaké raja dudu putrané, nanging sadulure, Mustafa I. Kanthi mangkono cara warisan saka bapak menyang anak ditinggal lan kasunyatané pindhah menyang sistem 'ekberiyet', yaiku anggota lanang paling tuwa saka wangsa sing jumeneng. Pamaréntahan kapisan sing suwéné sangang puluh nem dina iki uga wiwitané jaman para pangéran digulawenthah ing 'kafes' (kurungan).", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Lèngsèré Mustafa I lan jumenengé Osman Enom (Osman II)", "e0f552f2"], "d": ["Kanthi alesan kawarasan jiwané ora bener, Mustafa I dilèngsèraké sawisé sangang puluh nem dina, lan Osman II, putrané Ahmed I sing umur patbelas taun, dadi sultan. Miturut katrangan sing adhedhasar Hasanbeyzâde, Kızlar Ağası (kepala kasim) Mustafa Agha duwé pengaruh ing keputusan nglèngsèraké iki. Kanthi rancangan mbubaraké korps Janissari lan ngedegaké wadyabala anyar, Osman Enom dianggep tokoh radikal kapisan ing padudon réformasi Utsmaniyah. Rancangan iki patang taun sawisé bakal ngentèkaké nyawané dhéwé.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Prajanjian Serav — dianyaraké tentrem karo Iran", "e778aca8"], "d": ["Prajanjian Serav, sing diraih karo Iran sawisé kakalahan Pul-i Shikasta, sebagéan gedhé ngukuhaké sarat-sarat Prajanjian Nasuh Pasya 1612; cacahé sutra taunan sing kudu dikirim Safawiyah dikurangi saka rong atus momotan dadi satus momotan. Kanthi mangkono babak kapindho perang wétan sing lumaku wiwit 1603 rampung. Tentrem iku ora bakal suwé; kanthi ucule Baghdad ing 1623, perang bakal murub manèh.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Ekspedisi Khotin lan Prajanjian Khotin", "bc4c823c"], "d": ["Pakémahan sing dibèntèngi, sing diadegaké Chodkiewicz ing ngarep Khotin, ora bisa ditembus déning wadyabala gedhé sing dipimpin dhéwé déning Osman II, lan serbuan pirang-pirang sasi ora ana asilé. Miturut prajanjian sing ditandhatangani tanggal 9 Oktober, Kali Dniester ditampa dadi tapel wates, lan wong Polandia nyanggupi nyegah serbuan Cossack. Sanajan diaturaké kaya kamenangan, ekspedisi sing ora mènèhi asil iki nguwataké rasa ora percayané sultan enom marang Janissari lan niyaté numpes korps kuwi.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Lèngsèré Mustafa I kaping pindho lan jumenengé Murad IV", "1b3a9e74"], "d": ["Mustafa I, sing sawisé Osman II dipatèni didadèkaké raja kaping pindho, dilèngsèraké manèh sawisé setaun telung sasi, lan Murad IV sing umur sewelas taun diumumaké dadi sultan. Sangang taun kapisan, nagara kasunyatané diprentah ibuné, Kösem Sultan, lan para pinisepuh kraton. Wiwit 1632, Murad IV bakal nyekel pamaréntahan dhéwé lan miwiti jaman pemusatan sing keras.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Baghdad ilang direbut Safawiyah", "db81be0c"], "d": ["Asilé tawar-tinawar sing dilakoni Bekir Subaşı, sing mbrontak ing Baghdad, karo Safawiyah, yaiku putrané, Derviş Mehmed, sing njaga bèntèng njero, masrahaké kutha marang pasukané Syah Abbas. Uculé salah siji kutha lambang warisan kekhalifahan lan pérangan gedhé Irak nuwuhaké nesu gedhé ing Istanbul. Ngrebut manèh Baghdad bakal dadi siji-sijiné tujuan pulitik wétan Utsmaniyah suwéné limalas taun.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Ditumpesé pambrontakan Abaza Mehmed Pasya sing puseré ing Erzurum", "e6da2729"], "d": ["Abaza Mehmed Pasya, beylerbeyi Erzurum, sing mbrontak nglawan Janissari kanthi pangaku males patiné Osman II, pirang-pirang taun nguwasani Anatolia Wétan lan nglawan pusat. Amarga dikepung ing Erzurum déning wazir agung Husrev Pasya, dhèwèké kepeksa nyerah, banjur diapura lan diangkat ing Bosnia. Rampungé pambrontakan iki sarat wigati supaya Murad IV bisa mangkat ing ekspedisi nglawan Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Ukuman pati kapisan tumrap syekhul Islam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Kanthi alesan dadi perantara ing kekacoan militèr lan ngirim pépéling tinulis marang sultan ngenani tata cara pengadilan, Syekhul Islam Ahîzâde Hüseyin Efendi diukum pati cedhak Büyükçekmece. Minangka syekhul Islam Utsmaniyah kapisan sing diukum pati, prastawa iki matahaké adat kuna yèn ukuman paling abot tumrap anggota ilmiye iku pembuwangan. Prastawa iki dianggep lambang saya kerasé wibawa Murad IV lan rusaké imbangan antarané nagara lan ulama.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Penaklukan Revan déning Murad IV", "b65a9b73"], "d": ["Murad IV, sing mangkat saka Istanbul tanggal 28 Maret 1635, ngepung Revan tanggal 28-29 Juli lan nampa nyerahé bèntèng tanggal 8 Agustus; banjur mlebu Tabriz sing wis dikosongaké lan mrentahaké kutha dirusak. Kanggo ngèlingi kamenangan, sultan mbangun Paviliun Revan ing Kraton Topkapı. Ekspedisi iki operasi gedhé wétan kapisan sawisé telung puluh taun, ing ngendi sultan dhéwé mimpin wadyabala.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Revan ilang direbut Safawiyah", "fbb8dd25"], "d": ["Sawisé wadyabala Utsmaniyah mundur, pasukané Syah Safi ngepung Revan lan sajroné wolung sasi ngrebut manèh. Cepeté bèntèng iki ucul nuduhaké sepira angèlé, sacara logistik, njaga pangwasa tetep ing Kaukasus. Revan uga bakal ditinggal ing Iran miturut Prajanjian Qasr-i Shirin 1639, lan Utsmaniyah bakal ngeculaké pangakuné marang Azerbaijan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Penaklukan manèh Baghdad", "4d2f27f3"], "d": ["Murad IV, sing mangkat saka Istanbul tanggal 8 Mei 1638, sawisé pengepungan sengit suwéné patang puluh dina ngrebut manèh Baghdad, sing wis limalas taun ana ing tangané Safawiyah; Wazir Tayyar Mehmed Pasya gugur ing pengepungan iku. Kanthi penaklukan kutha, pamaréntahan Utsmaniyah diadegaké manèh ing Irak, lan sultan nampa sesebutan 'Sang Penakluk Baghdad'. Penaklukan iki dadi tetep lumantar Prajanjian Qasr-i Shirin ing taun sabanjuré lan masang dhasar tapel wates Turki-Iran saiki.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Sédané Murad IV lan jumenengé Sultan Ibrahim", "e2ca1ca0"], "d": ["Sawisé Murad IV séda ing umur pitulikur taun (wolulikur miturut étungan Hijriyah), sadulure, Ibrahim, siji-sijiné anggota lanang wangsa sing isih urip, jumeneng. Ing pamaréntahané sultan anyar, sing pirang-pirang taun urip ing kafes, belanja kraton lan rebutan pengaruh ing njero kraton nggoncang tatanan nagara. Wolung taun sawisé, kanthi dilèngsèraké lan dipatèni, bakal kedadéan pamatènan sultan kapindho ing sajarah Utsmaniyah.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Bèntèng Azov direbut manèh saka wong Cossack", "e5fcf160"], "d": ["Bèntèng Azov, sing direbut wong Cossack Don ing 1637, dikosongaké ngadhepi operasi bebarengan Sultanzâde Mehmed Pasya lan Khan Krimea Mehmed Giray IV; wong Cossack ngobong bèntèng banjur mundur. Direbuté manèh gapura lor Segara Ireng nutup jaman mbebayani nalika serbuan Cossack tekan Selat Bosporus Istanbul. Ing 1696 bèntèng iku bakal ilang manèh, wektu iki direbut Tsar Rusia Pyotr I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Wiwitané ekspedisi Kreta lan penaklukan Canea", "a1b0c77f"], "d": ["Kanthi alesan bajak laut Malta nyerang kapal kaji Utsmaniyah banjur ngungsi menyang Kreta, perang marang Venesia diumumaké, lan armada ing pangwasané Yûsuf Pasya ndharataké prajurit ing pulo iku. Sawisé pengepungan sèket papat dina, bèntèng Canea direbut lan pangkalan Utsmaniyah tetep kapisan ing Kreta diadegaké. Kanthi mangkono diwiwiti perang paling dawa ing sajarah Utsmaniyah; pulo iku lagi bisa ditelukaké sakabèhé patlikur taun sawisé, ing 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Penaklukan Rethymno — Kréta dipérang dadi loro", "8f2c4353"], "d": ["Setaun sawisé Chania direbut, bèntèng Rethymno ing tengahé pulo uga tiba, lan setengah kulon Kréta mlebu kabèh ing pamaréntahan Utsmaniyah. Ing tangan Venesia mung kari ibu kutha Kandia lan pucuk wétan; pulo iku sajrone telulikur taun urip dipérang dadi loro. Direbuté Rethymno dadi langkah sing miwiti pengepungan Kandia — pengepungan paling dawa ing sajarah diwiwiti ing kene.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Klis ilang direbut Venesia", "5473c22c"], "d": ["Ing front Dalmatia Perang Kreta (Kandia), serangan walesan komandan Venesia Leonardo Foscolo uga nyakup Klis, sing wiwit 1537 dadi puser sancak; bèntèng iku pindhah menyang Venesia. Amarga Utsmaniyah musataké kabèh kakuwatané ing Kreta, ora bisa ngrebut manèh sing ilang ing tapel wates Dalmatia iki — Klis ora bakal bali manèh menyang pamaréntahan Utsmaniyah; puser sancak dipindhah menyang Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Wiwitané pengepungan Kandia", "13016b10"], "d": ["Sawisé Canea lan Rethymno direbut, wadyabala Utsmaniyah ngepung Kandia, sandharan gedhé pungkasané Venesia ing pulo iku. Blokadé iki, sing bakal suwéné selikur taun, kacathet minangka salah siji pengepungan paling dawa ing sajarah militèr donya. Sajroné pengepungan, usaha armada Venesia nutup Selat Dardanelles bakal nggawa perang menyang jantung Aegea.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Valide Sultan Agung Kösem dipatèni", "9d763f79"], "d": ["Kösem Sultan, umur watara sawidak loro taun, ditemoni ing siji kamar ing Harem lan dipatèni déning Başlala Uzun Suleyman Agha sarta anak buahé, sing tumindak miturut dhawuhé Turhan Sultan, ibuné Mehmed IV. Sédané wanita wangsa sing kuwat iki, sing ngarahaké pulitik nagara ing jaman telung sultan, dianggep pungkasan nyata jaman sing diarani 'Kasultanan Para Wanita'. Wibawa sing dadi kothong iku, limang taun sawisé, mbukak dalan kanggo Köprülü Mehmed Pasya dadi wazir agung kanthi wewenang mirunggan.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Kakalahan ing Dardanelles lan ilangé Bozcaada sarta Lemnos", "e01a1f7e"], "d": ["Kamenangan segara gedhé sing diraih laksamana Venesia Mocenigo ing ngarep Selat Dardanelles ing Juni 1656 meh numpes kabèh armada Utsmaniyah; banjur Bozcaada, Lemnos, lan Samothrace didhudhuki. Amarga Selat kena blokadé Venesia, rega pangan ing Istanbul mundhak drastis lan wedi yèn krajan diserang nyebar. Bencana iki dadi sebab langsung Köprülü Mehmed Pasya diangkat dadi wazir agung ing September 1656 kanthi sarat lan wewenang mirunggan.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Kamenangan Dardanelles lan direbuté manèh Bozcaada", "603da863"], "d": ["Armada sing dikerahaké Köprülü Mehmed Pasya ngalahaké mutlak armada Venesia ing ngarep Selat tanggal 19 Juli 1657; banjur pasukan ing pangwasané Kurd Pasya ngrebut manèh Bozcaada tanggal 25 Agustus, lan tanggal 30 Agustus wong Venesia ngosongaké pulo iku kabèh. Ing sasi November Lemnos uga diluwari, blokadé Dardanelles pecah, lan dalan pasokan pangan Istanbul kabukak manèh. Köprülü dhéwé nyabrang menyang pulo lan mrentahaké bèntèng-bèntèng didandani; kasil iki tambahan militèr gedhé kapisan ing jaman Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Penaklukan Yanova (Ineu) lan ekspedisi Transylvania", "d1089616"], "d": ["Köprülü Mehmed Pasya, sing mangkat ing ekspedisi kanggo ngukum Pangéran Transylvania George II Rákóczi, sing nerak pangayoman Utsmaniyah kanthi mangkat ing ekspedisi Polandia tanpa idin, maju liwat Beograd lan ngrebut bèntèng strategis Yanova. Pangéran anyar diangkat ing Transylvania, lan tali vasal diélingaké kanthi keras. Ekspedisi iki mata ranté kapisan usahané Utsmaniyah ngadegaké manèh wibawané ing Éropah Tengah. Transylvania pancèn wis dadi kepangéranan bawahan Utsmaniyah; direbuté Yanova dudu penaklukan saka nagara manca, nanging ngetokaké bèntèng Transylvania bawahan iki saka pamaréntahan kepangéranan lan nggandhèngaké langsung karo sancak Utsmaniyah; sisané kepangéranan tetep ing status bawahan.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Ditumpesé pambrontakan Abaza Hasan Pasya", "4ba74321"], "d": ["Abaza Hasan Pasya, sing kasil narik para beylerbeyi Anatolia lan para agha sekban ing pihaké nglawan panumpesan keras Köprülü Mehmed Pasya, miwiti pambrontakan gedhé kanthi nuntut wazir agung dicopot. Pambrontakan ditumpes ing Aleppo lan para pangarepé disingkiraké; iki perlawanan bebarengan pungkasan para pasya dhaérah marang pusat. Kanthi mangkono wibawa Köprülü ora bisa dibantah manèh, lan kalungguhan wazir agung munggah manèh dadi puser eksekutif sejati nagara.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Penaklukan Várad (Oradea)", "0e6ad300"], "d": ["Ing rangka ekspedisi nglawan Pangéran Transylvania George II Rákóczi, sing ngumumaké perang marang Utsmaniyah, bèntèng lan kutha Várad direbut. Kanthi tibané salah siji bèntèng kunci Transylvania, provinsi Utsmaniyah anyar (Provinsi Várad) diadegaké ing tlatah iku. Penaklukan iki ndadèkaké Habsburg waspada lan dadi salah siji sebab langsung perang Utsmaniyah-Austria sing bakal diwiwiti telung taun sawisé. Papan liyané sing gabung ing tanggal sing padha: Varat. Ing kéné uga lemah ora dijupuk saka nagara manca: Transylvania pancèn wis dadi kepangéranan bawahan Utsmaniyah; Várad dadi provinsi mung ateges pamaréntahan kutha iki dijupuk saka kepangéranan bawahan lan digandhèngaké langsung karo sultan, kaya ing Yanova rong taun sadurungé.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Perang St. Gotthard", "61ebc1f2"], "d": ["Pasukan Utsmaniyah sing nyabrang Kali Raab diendheg déning wadyabala sekutu Éropah ing pangwasané Montecuccoli lan nandhang karugèn abot. Perang iki dianggep titik owah ing sajarah militèr amarga sepisanan nuduhaké kanthi cetha unggulé tembakan bedhil infantri sing disiplin marang serbuan pasukan jaranan Utsmaniyah. Sanajan kalah, Utsmaniyah kasil éntuk sarat sing nguntungaké ing Prajanjian Vasvár sing ditandhatangani sangang dina sawisé.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Prajanjian Vasvár", "089c978c"], "d": ["Prajanjian sing ditandhatangani sanajan ana kakalahan St. Gotthard iki netepaké yèn Uyvar lan Várad tetep ana ing Utsmaniyah, Transylvania ditinggal nétral ing pangayoman Utsmaniyah, lan Austria mbayar 'pisungsung' 200.000 kuruş. Tentrem suwéné rong puluh taun iki salah siji conto sing arang, yaiku pihak sing kalah perang malah menang ing méja rembugan. Rasa ora marem sing ditimbulaké prajanjian iku ing panemu umum Habsburg bakal nyuburaké gerakan Hungaria Tengah lan, kanthi ora langsung, ekspedisi Wina 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Wiwitané pamaréntahan dey ing Aljir", "e99faa51"], "d": ["Ocak Aljir lan taife-i reis (golongan kapitan bajak laut) nyopot agha pungkasan lan milih Hacı Mehmed dadi dey saumur urip. Sawisé tanggal iki, Aljir diprentah dudu déning beylerbeyi sing diangkat Istanbul, nanging déning dey sing dipilih ocak lokal saka antarané anggotané dhéwé; sesambungan karo Utsmaniyah mung winates ing diwacané asmané sultan ing khutbah lan kuwajiban gendéra sarta mèlu ekspedisi. Kanthi mangkono Aljir malih saka provinsi dadi ocaklık — owah-owahan sing padha dialami Tunis ing 1705 karo wangsa Husainiyah lan Tripolitania ing 1711 karo wangsa Karamanli.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Ekspedisi Polandia diwiwiti — Mehmed IV lan Fâzıl Ahmed Pasya mimpin wadyabala", "75e15a39"], "d": ["Nalika serangan Polandia marang hetman Ukraina Petro Doroshenko, sing wis mlebu pangayoman Utsmaniyah, lumaku terus, Istanbul njaluk raja Polandia supaya ngendheg serangan; amarga ora ana wangsulan sing becik, diputusaké ekspedisi nglawan Polandia. Wazir agung Fâzıl Ahmed Pasya mangkat menyang Polandia tanggal 4 Juni 1672 bebarengan karo wadyabala, sing sultan uga mèlu. Ekspedisi iku bakal rampung kanthi penaklukan Kamaniçe lan Prajanjian Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Penaklukan Kamaniçe lan adegé Provinsi Podolia", "c3f4f6d0"], "d": ["Sawisé pengepungan sangang dina, Kamaniçe, sing dianggep bèntèng Polandia paling kuwat ing wétan, ditampa nyerah; tanggal 2 September Mehmed IV nindakaké sembahyang Jemuwah kapisan ing masjid sing diowahi saka katedral. Kanthi bèntèng iku didadèkaké puser, Provinsi Podolia diadegaké, lan gendéra Utsmaniyah tekan titik paling lor ing lemah sing saiki Ukraina. Kamaniçe bakal tetep dadi pucuk lor-kulon kakaisaran nganti Prajanjian Karlowitz 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasya nampa nyerahé Uman saka Polandia", "0d3543a0"], "d": ["Kara Mustafa Pasya, sing dikirim nglawan Polandia, nampa nyerahé Uman, salah siji bèntèng sing dicekel Polandia; kutha iku tetep ana ing pamaréntahan Utsmaniyah nganti Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Penaklukan Bèntèng Chyhyryn", "a17cedd0"], "d": ["Sawisé operasi Melek Ibrahim Pasya taun sadurungé ora ana asilé, wazir agung Merzifonlu Kara Mustafa Pasya, sing dhéwé mimpin, ngepung bèntèng kuwat Chyhyryn (19/21 Juli) lan ngrebut tanggal 21 Agustus. Tibané bèntèng, sing dadi lambang saingan Utsmaniyah-Rusia ngenani kahetmanan Cossack ing Ukraina, meksa Rusia tentrem. Kasil iki uga dadi salah siji sumber kapercayan awaké Merzifonlu sing bakal nggawa dhèwèké nuju Wina.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Prajanjian Bakhchysarai — tentrem resmi kapisan karo Rusia", "df82bc0b"], "d": ["Asilé rembugan sing ditindakaké lumantar perantarané Khan Krimea sawisé ekspedisi Chyhyryn, tentrem rong puluh taun ditandhatangani antarané Nagara Utsmaniyah lan Rusia, kanthi Kali Özü (Dnieper) ditampa dadi tapel wates. Minangka prajanjian kapisan sing jangkep antarané rong nagara, iki dianggep dokumèn wiwitané sesambungan Utsmaniyah-Rusia. Amarga tentrem iki, front wétan diamanaké lan wadyabala bisa diarahaké menyang Éropah Tengah.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Imre Thököly diparingi berat kraton Hungaria Tengah", "3cd8d51d"], "d": ["Imre Thököly, bangsawan Hungaria Protestan sing mbrontak nglawan tekanan Habsburg, wiwit April 1682 dianggep 'raja pilihan Hungaria Tengah', lan tanggal 16 September Beylerbeyi Buda Ibrahim Pasya ngaturaké tandha kapangéranan marang dhèwèké. Kanthi mangkono nagara Hungaria vasal anyar diadegaké ing pangayoman Utsmaniyah. Campur tangan iki ndadèkaké perang karo Austria ora bisa diéndhani lan miwiti ranté prastawa menyang Pengepungan Wina Kapindho ing taun sabanjuré.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Ayamavra (Lefkada) ilang direbut Venesia", "e6905fee"], "d": ["Armada Venesia, sing gabung karo Liga Suci, nembaki kutha nganggo mriyem banjur ndhudhuki Pulo Ayamavra ing Segara Ionia. Kanthi Preveza uga tiba ing taun sing padha, pangawasan Utsmaniyah ing cangkem Adriatik pecah. Karugèn-karugèn iki langkah wiwitan operasi sing sajroné telung taun Morosini bakal ngrebut kabèh Morea.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Koroni ilang direbut Venesia", "2ed762bc"], "d": ["Pasukan Venesia ing pangwasané Morosini ngrebut bèntèng Koroni ing pucuk kidul-kulon semenanjung Morea; sawisé iku kutha bakal tetep ana ing pamaréntahan Venesia suwéné telung puluh taun. Tibané Koroni tambahan gedhé kapisan operasi Venesia sing tujuané nelukaké Morea. Bèntèng iku lagi bisa direbut manèh ing 1715 déning wadyabala Utsmaniyah ing pangwasané Silâhdar Ali Pasya.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Athena direbut manèh — Venesia mundur", "03393b46"], "d": ["Morosini, sing ing September 1687 ngebom Akropolis lan mbledhosaké Parthenon, sawisé ngliwati mangsa adhem ing Athena ngerti yen dhèwèké ora bisa tahan ing kutha. Amarga pagebluk pes, angèlé bekal lan pasukan Utsmaniyah sing wis pulih, garnisun Venesia ngosongaké kutha lan mundur menyang Morea. Athena mangkono bali menyang pamaréntahan Utsmaniyah tanpa perang, nanging karusakan sing dialami Parthenon ora bisa dibalèkaké.", "79c8586a"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Pengepungan Venesia marang Negroponte (Eğriboz) dipukul mundur", "aae7e6a0"], "d": ["Morosini, sing sawisé ngrebut Morea nuju Aegea, nyoba ngrebut Negroponte kanthi pengepungan luwih saka telung sasi; nanging ngadhepi bèntèng sing dikuwataké ing mangsa adhem 1687-1688 lan perlawanan garnisun, dhèwèké kepeksa mundur kanthi nandhang karugèn abot. Kagagalan iki ngendheg majuné Venesia ing Aegea lan nggoncang wibawa militèré Morosini. Negroponte uga bakal tetep ana ing tangané Utsmaniyah ing Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Bèntèng Kanizsa ilang direbut Austria", "553b45f3"], "d": ["Kanizsa, sing wiwit Januari 1690 diblokade kenceng déning wadyabala Habsburg 60.000 wong, sawisé pirang-pirang sasi nahan tanpa pitulungan, ucul saka tangan lumantar prajanjian nyerah sing ditandhatangani panjaga pungkasané, Mustafa Pasya. Kanthi mangkono pangwasa Utsmaniyah suwéné sangang puluh taun rampung ing bèntèng sing dièlingi amarga pertahanan kapahlawanané Tiryaki Hasan Pasya. Ilangé Kanizsa ambruké sandharan gedhé pungkasané Utsmaniyah ing Hungaria sisih kulon.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Jumenengé Ahmed II", "52947b14"], "d": ["Nalika Suleyman II séda, sadulure sing umur patang puluh sanga taun, Ahmed II, jumeneng ing Edirne. Pamaréntahané pas karo taun-taun paling abot perang Liga Suci; rong sasi sawisé jumeneng, wazir agung Fâzıl Mustafa Pasya gugur ing Slankamen. Ing sisih liya, sistem mâlikâne sing ditrapaké ing jamané dadi salah siji tatanan paling wigati sing ngowahi susunan jangka dawa keuangan Utsmaniyah.", "d3441b14"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Basrah direbut wong Iran", "a9cdf3a3"], "d": ["Nalika Nagara Utsmaniyah sibuk perang nglawan Liga Suci ing kulon, Basrah, sawisé pagebluk pes 1690, dijarah dhisik déning Mâni, syekh Muntafiq, banjur déning Ferecullah, Khan Huveyza. Wong Iran, manfaataké kekisruhan iki, ing 1696 ngrebut kutha iku lan ninggalaké penjaga ing Basrah.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Prajanjian Istanbul — Azov dipasrahaké marang Rusia", "79db4724"], "d": ["Ing Karlowitz karo Rusia mung bisa digawé gencatan senjata rong taun; tentrem sing langgeng ditandhatangani ing Istanbul sawisé tawar-tinawar angèl suwéné setaun setengah. Nagara Utsmaniyah resmi masrahaké marang Rusia Bèntèng Azov, sing ilang ing 1696, lan lemah sakiwa-tengené, sarta ngeculaké pajeg taunan sing ditampa khan Krimea saka Moskwa. Minangka gantiné, Rusia éntuk hak nduwèni duta tetep ing Istanbul; kanthi mangkono anané Rusia ing pesisir loré Segara Ireng kadhaftar sacara hukum.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Pasya ngrebut manèh Qurna lan Basrah", "7adb777d"], "d": ["Daltaban Mustafa Pasya, sing sawisé Prajanjèn Karlowitz diangkat dadi gubernur Baghdad lan serasker Basrah, maju ngidul karo pasukan Aleppo, Raqqa, Sivas lan Karaman sarta armada kali sing mudhun saka Birecik. Para syekh suku ing sakiwa-tengené manut siji-siji, Dâvud Khan, penjaga Basrah saka Iran, ninggalaké kutha, lan Qurna sarta Basrah mlebu manèh ing pamaréntahan Utsmaniyah.", "60abbe06"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Wiwitané pamaréntahan Kölemen (Mamluk) ing Baghdad", "abe52618"], "d": ["Kanthi Hasan Pasya, asal Georgia, diangkat dadi gubernur Baghdad, diwiwiti jaman ing Irak, yaiku ora manèh gubernur sing diangkat saka pusat, nanging golongan panguwasa sing digulawenthah saka budhak-budhaké dhéwé sing dadi dominan. Kanthi Suleyman Pasya dadi gubernur ing 1749, sistem iku tetep mapan, lan Bab-i Ali ora bisa manèh ngangkat wong sing dikarepaké, nanging kepeksa ngangkat salah siji kölemen sing wis ngrebut pengaruh. Susunan setengah otonom iki, sanajan migunani kanggo njaga tapel wates Iran, ngringkihaké pangawasan wibawa pusat marang Irak suwéné siji setengah abad.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Adegé wangsa Husainiyah ing Tunis", "cb1a98f9"], "d": ["Ing kekosongan wibawa sing tuwuh amarga pasukan Aljir nyerbu Tunis, Husain bin Ali, agha sipahi asal Turk, ngrebut kabèylikan lan éntuk legitimasi kanthi nyatakaké kasetiané marang sultan Utsmaniyah. Wangsa sing diadegaké mréntah Tunis ing taun 1705-1735 lan 1756-1957; tatanan kabèylikan sing diwarisaké saka bapak menyang anak ngganti pamaréntahan ocak. Kanthi mangkono lair conto kapisan, ing ocak-ocak Kulon, susunan wangsa sing gandhèng karo pusat nanging kasunyatané otonom.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Oran (Vahran) lan Mers el-Kébir direbut saka Spanyol", "b67ce06a"], "d": ["Pasukan beylerbeyi Ocak Aljir, sawisé pengepungan suwé, ngrebut Oran, sing wis rong abad ana ing tangané garnisun Spanyol, lan plabuhané, Mers el-Kébir. Iki kasil paling gedhé sing diraih ocak-ocak Kulon ing pangayoman Utsmaniyah ing Segara Tengah sisih Kulon nglawan Spanyol, lan ngamanaké sayap kulon Aljir. Ing 1732 kutha iku bakal didhudhuki Spanyol manèh, lan lagi direbut manèh kanthi tetep ing 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Prajanjian Prut — Azov lan Taganrog direbut manèh", "bac5d2a1"], "d": ["Prajanjian pitung pasal, sing ditandhatangani nalika wadyabala Rusia sing dikepung ing pinggir Kali Prut nyerah, netepaké yèn Bèntèng Azov dibalèkaké marang Utsmaniyah bebarengan karo lemah lan amunisiné. Pertahanan Taganrog, Kamenka, lan Yenikale bakal dirubuhaké, lan loro pihak ora bakal mbangun bèntèng anyar ing tlatah iku. Tatanan armada lan pangkalan sing dibangun Pyotr I suwéné nem belas taun ing Voronezh lan Azov ambruk; mudhuné Rusia menyang Segara Ireng ketundha watara sèket taun.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Adegé wangsa Karamanli ing Tripolitania", "e1105d4a"], "d": ["Ing Tripolitania, sing wis kesel déning padudon para agha ocak, perwira pasukan jaranan Ahmed Karamanlı ngrebut pamaréntahan lan ngresmèkaké kalungguhané nganggo berat beylerbeyilik sing ditampa saka Istanbul. Lumantar Ahmed Pasya, putrané Mehmed Pasya, lan putuné Yûsuf Pasya lair wangsa sing lumaku saka 1711 nganti 1835; muncul susunan setengah mardika sing ngedegaké armadané dhéwé lan nandhatangani prajanjian langsung karo nagara-nagara Éropah. Jaman iki lagi rampung ing 1835, nalika provinsi iku digandhèngaké langsung karo pusat.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Prajanjian Edirne karo Rusia", "14901a70"], "d": ["Amarga janji sing diwènèhaké ing Prut ora ditetepi, perang diumumaké kaping pindho manèh, lan pungkasané, nalika wong Rusia nampa kuwajiban, tentrem sing langgeng ditandhatangani ing Edirne. Prajanjian iki ngukuhaké sarat-sarat Prut; Rusia ora bakal mèlu-mèlu urusan Polandia, bakal mundur saka lemah Cossack, lan ora bakal ngalangi raja Swédia Charles XII, 'Sirah Wesi' (Demirbaş Şarl), bali menyang negarané. Kanthi front lor katutup mangkono, Nagara Utsmaniyah bisa ngadhepaké rainé menyang front Morea lan Venesia. Papan liyané sing gabung ing tanggal sing padha: Khotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Pangumuman perang marang Venesia — persiapan ekspedisi Morea", "d970b122"], "d": ["Kanthi alesan Venesia nyengkuyung pambrontak Montenegro, nyita kapal dagang Utsmaniyah, lan nindhes Morea, sing direbut ing Karlowitz, nganggo pajeg abot, ing Divan diputusaké perang. Ekspedisi sing disiapaké wazir agung Silâhdar Damad Ali Pasya bakal rampung ing taun sabanjuré kanthi direbuté manèh kabèh semenanjung Morea sajroné kurang saka satus dina. Nanging kasil iki bakal ngobahaké Austria lan, ing 1716, mbukak lawang menyang perang sing luwih abot.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos: pasrahé pulo pungkasan Venesia ing Aegea", "4abec891"], "d": ["Armada sing budhal ing ekspedisi Morea, ing dalané, labuh jangkar ing ngarep Tinos, siji-sijiné pulo Venesia sing isih kari ing Aegea. Pulo iku, sing amarga pendhudhuk Latiné isih nggawa gendéra Venesia nganti satus sèket taun manèh sanajan Kadipatèn Naxos wis tiba ing 1566, nyerah tanpa getih sawisé pengepungan cendhak. Kanthi mangkono tapak sikil pungkasan Venesia ing Segara Aegea ilang, lan segara iku dadi kabèh segara pedhalaman Utsmaniyah.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Penaklukan Nafplion — bèntèng kunci Morea", "62a5808a"], "d": ["Nafplion, ibu kutha Venesia ing Morea lan bètèng paling kuwaté, tiba nalika bètèng Palamidi direbut sawisé pengeboman sangang dina. Direbuté bèntèng sing cepet banget iki nugel perlawanan ing sisané semenanjung. Dibalèkaké Morea sing ilang ing Karlowitz ing kanyatan rampung ing kene. Panggonan liya sing ing tanggal sing padha ing atlas pindhah saka Venesia menyang Utsmaniyah: Argos — nderek ranté pusat induk Nafplion (TDV anabolu; kira-kira sing diumumaké).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Pasrahé Modon", "43faa909"], "d": ["Sawisé Nafplion tiba, bèntèng Modon ing pucuk kidul-kulon Morea dikepung déning wadyabala saka dharat lan armada saka segara lan ora suwé nyerah. Plabuhan iki, sing rong atus taun digunakaké Venesia ing ekspedisi Segara Tengah Wétan, minangka titik mampir wajib panggonan kapal njupuk banyu lan bekal. Ilangé mungkasi kabébasan obah armada Venesia ing Aegea.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Pasrahé Koroni — rampungé ekspedisi Morea", "e4b9c8a4"], "d": ["Kanthi nyerahé bèntèng Koroni sing nyekel cangkeming Teluk Messenia, pamaréntahan Venesia ing semenanjung Morea rampung babar pisan. Semenanjung sing ilang ing Karlowitz mangkono direbut manèh kabèh mung telung sasi sawisé ekspedisi diwiwiti. Ing terusané ekspedisi sing padha, ing September 1715, pulo Santa Maura (Lefkada) ing Segara Ionia uga direbut saka Venesia. Kacepetan iki meksa Venesia nyèrèt Austria mlebu perang lan mbukak dalan menyang Passarowitz telung taun sabanjuré.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Direbuté Pulo Çuha (Kythira)", "494de6c6"], "d": ["Pulo Çuha ing pucuk kidul Morea dipasrahaké marang armada sawisé semenanjung rampung. Pulo sing ngawasi dalan antarané Segara Ionia lan Aegea iki minangka pos ngarep sing digunakaké Venesia kanggo ngawasi banyu iki. Nanging pulo iku ora tetep ana ing tangan Utsmaniyah: telung taun sabanjuré ing Passarowitz dibalèkaké marang Venesia.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria lan Venesia gawé persekutuan — gapura Perang Utsmaniyah-Austria 1716-1718", "99511ca2"], "d": ["Sawisé Utsmaniyah ngrebut manèh Morea saka Venesia, Austria, kanthi pangaku yèn Prajanjian Karlowitz wis diterak, nandhatangani prajanjian persekutuan karo Venesia; Pangéran Eugene, ing layangé marang wazir agung, njaluk supaya papan-papan sing direbut saka Venesia dibalèkaké. Ing rembugan ing pakémahan Davutpaşa, amarga tekanan wazir agung Ali Pasya, perang marang Austria diumumaké, lan kanggo iku dijaluk fatwa saka syekhul Islam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Wazir agung Ali Pasya mangkat ing ekspedisi Austria", "2fbdce42"], "d": ["Sawisé perang marang Austria diumumaké, serdâr-ı ekrem Ali Pasya mangkat ing ekspedisi Austria kanthi wadyabala luwih saka 100.000, déné armada ing mangsa panas sing padha nuju Korfu. Wadyabala bakal maju saka Beograd menyang Petrovaradin, lan ing kakalahan ing wiwitan Agustus wazir agung bakal gugur.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Kakalahan ing Petrovaradin (Varadin) — gugure Damad Ali Pasya", "265c1d81"], "d": ["Wadyabala Utsmaniyah, sing nyabrang Kali Donau liwat Beograd, ketemu pasukan Austria ing pangwasané Pangéran Eugene ing ngarep Petrovaradin; sanajan ing gebrakan kapisan serbuan Janissari meksa paritan mungsuh, barisan buyar amarga sayap pasukan jaranan ambruk. Wazir agung Silâhdar Damad Ali Pasya katembak ing bathuk lan gugur, lan pakémahan sarta sakabèhé piranti artileri tiba ing tangané mungsuh. Kakalahan iki, sing ing babad Utsmaniyah dièlingi minangka 'taun Varadin', iku mata ranté kapisan saka ranté menyang ilangé Temesvár lan, ing taun sabanjuré, Beograd.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Pengepungan Korfu gagal", "b2aa7011"], "d": ["Serasker Morea Kara Mustafa Pasya saka dharatan, lan Kaptanıderyâ Canım Hoca Mehmed Pasya kanthi armada saka segara, nggencet Korfu; pulo iku pangkalan kunci Venesia ing Adriatik. Nanging bèntèng sing kuwat banget, bala bantuan sing digawa armada Venesia, lan kabar kakalahan saka front Donau njalari pengepungan diudhari. Ora bisané Korfu direbut mateni semangat sing munggah amarga Morea ditelukaké manèh, lan mindhah pusat abot perang menyang Hungaria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Ilangé Temeşvar (Timişoara) menyang Austria", "27fe1365"], "d": ["Sawisé bedhahé Varadin, Pangéran Eugène langsung maju menyang Temeşvar, lan bèntèng iku nyerah kanthi prajanjèn sawisé dikepung luwih saka patang puluh dina. Kanthi mangkono kutha sing ditaklukaké ing mangsa Sultan Sulaiman Sang Pembuat Undhang-undhang ing taun 1552 lan sajrone 164 taun, minangka pusat beylerbeylik, dianggep dadi pilar wétan pertahanan Hungaria iku uwal saka tangan. Kanthi tibané Temeşvar, kabèh tlatah Banat pindhah menyang Austria lan tapel wates Utsmaniyah kasurung menyang sisih kidul Kali Donau. Panggonan liya sing ing tanggal sing padha ing atlas pindhah saka Utsmaniyah menyang Habsburg: Csákóvár, Facset lan Karánsebes (Caransebeș) — bebarengan karo pasrahé eyalet Temeşvar (TDV timisvar; ing sumber ora ana dina ing tingkat panggonan, ranté pusat induk, kira-kira sing diumumaké).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Bèntèng Haram (Yeni Palanka) dipasrahaké marang Austria — pesisir Donau tlatah Banat uwal saka tangan", "38ee4c6d"], "d": ["Sawisé Temeşvar tiba, Mercy, jéndral pasukan jaran Austria sing ditugasi ngrebut sisané tlatah Banat, ing tanggal 14 November maju menyang Haram (Yeni Palanka) ing pinggir Kali Donau; nalika tekan bèntèng ing tanggal 16 November, garnisun Utsmaniyah sing cacahé 200 wong ngibaraké gendéra putih lan nyerah kanthi sarat kena mundur kanthi bébas. Kanthi mangkono garis Donau ing Banat Kidul, sing wiwit 1552 ana ing tangan Utsmaniyah, uga pindhah menyang Austria. Panggonan liya sing ing tanggal sing padha ing atlas pindhah saka Utsmaniyah menyang Habsburg: Versec — nderek ranté pusat induk Haram (Bánlaky 0019/1703; kira-kira sing diumumaké).", "5b54ecb0"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Ekspedisi Wétan: direbuté Tbilisi lan wiwité perang Iran", "78343dc2"], "d": ["Nalika Nagara Safawiyah ambruk amarga serbuan Afghan lan Rusia mudhun menyang pesisir Segara Kaspia, Nagara Utsmaniyah ngirim wadyabala menyang wétan supaya kekosongan iku ora kabèh dadi ajang pangaribawa Rusia. Tbilisi direbut lan Géorgia digandhèngaké menyang pamaréntahan Utsmaniyah; sawisé iku maju terus menyang arah Ganja, Erivan lan Nakhchivan. Ekspedisi sing ditindakaké ing walik rupa tentreming Mangsa Tulip iki dadi wiwitan lelampahan dawa ing wétan sing bakal lumaku telulas taun lan pungkasané kudu mbalèkaké kabèh panggonan sing wis direbut.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukasemenamé Istanbul — Iran dipérang karo Rusia", "fce8eec2"], "d": ["Supaya Utsmaniyah lan Rusia ora adhep-adhepan rebutan tlatah Safawiyah sing lagi ambruk, prajanjèn pamérangan ditandhatangani kanthi perantara duta Prancis. Pesisir kulon lan kidul Segara Kaspia diwènèhaké marang Rusia, déné Géorgia, Syirvan, Azerbaijan lan kutha-kutha Iran Kulon diwènèhaké marang Nagara Utsmaniyah. Pamérangan iki, sing ing dluwang katon dadi bathi gedhé, ora suwé banjur ora ana gunané ing kanyatan amarga muncule Nadir Syah. Miturut prajanjèn, lemah subur ing Syirvan kaya Shabran lan Mushkur ditinggal ing sisih Rusia (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Direbuté Tabriz — Azerbaijan dikuwasani", "e502a4f7"], "d": ["Tabriz, sing dikepung manèh sawisé upaya sing gagal setaun sadurungé, nyerah marang wadyabala Utsmaniyah sawisé perang atos sing lumaku saka dalan siji menyang dalan sijiné. Marand, Maragha lan Sovukbulak (Mahabad), sing kalebu eyalet Tabriz, uga mlebu ing pamaréntahan Utsmaniyah. Ing taun sing padha Lori, Ganja, Ardabil lan Khorramabad uga direbut, lan tlatah-tlatah sing dadi péranganing Utsmaniyah miturut Mukasemenamé Istanbul dikuwasani kanthi nyata. Jembar sing digayuh ing wétan iki minangka tapel wates paling adoh sawisé mangsa Prajanjèn Ferhad Pasya; nanging njaga tlatah iku mènèhi momotan abot marang wadyabala lan kas nagara.", "e0953563"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Prajanjèn Hamadan — Iran Kulon digabungaké menyang Utsmaniyah", "94a29dc3"], "d": ["Liwat prajanjèn sing ditandhatangani karo panguwasa Afghan, Ashraf Syah, perang sing lumaku patang taun rampung lan lemah Iran Kulon sing dikuwasani Nagara Utsmaniyah diakoni sacara hukum. Minangka imbalané, Ashraf Syah nampa kakhalifahan sultan Utsmaniyah lan nyanggupi supaya khotbah ing Iran diwaca nganggo asmané sultan. Kamenangan diplomatik iki umuré cendhak; serangan wales sing diwiwiti Nadir Syah ing taun 1730 bakal nyapu resik asil prajanjèn iku sajrone sawetara taun.", "fd0174b9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Prajanjèn Ahmed Pasya — bagéan gedhé Iran Kulon dibalèkaké", "590d839f"], "d": ["Amarga kamenangan Nadir Syah ing Malayer lan serangan Iran sing teka urut-urutan, gubernur Baghdad Ahmed Pasya nandhatangani naskah tentrem tanpa rembugan karo pusat. Miturut prajanjèn, Kali Aras ditampa minangka tapel wates; kutha-kutha Iran Kulon kaya Hamadan, Kermanshah, Ardalan, Ardabil lan Tabriz dibalèkaké marang Iran, déné Ganja lan Tbilisi tetep ing tangan Utsmaniyah. Naskah iki, sing ditampa kanthi reaksi ora sarujuk ing Istanbul, uga dianggep kurang déning Nadir Syah, lan sadurungé taun 1732 rampung perang murub manèh. Atlas uga nganggep Kotur, sing nderek ranté Khoy, ing dina iki pindhah saka Utsmaniyah menyang Safawiyah (TDV hoy; ing sumber ora ana dina sing khusus kanggo Kotur — kira-kira sing diumumaké).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Oran (Vahran) ilang manèh menyang Spanyol", "20485027"], "d": ["Armada pendharatan gedhé sing dikirim Raja Spanyol Felipe V teka ing ngarep Oran kanthi pimpinan Count Montemar, ngalahaké pasukan Ojak Aljir lan ngrebut manèh kutha iku. Plabuhan sing ditaklukaké patlikur taun sadurungé iku bakal ana manèh ing tangan garnisun Spanyol sajrone suwidak taun. Kélangan iki, sing nuduhaké watesé kakuwatan ojak-ojak Kulon ing Segara Tengah sisih kulon, lagi bisa ditebus kanthi penaklukan Oran sing mesthi ing taun 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Pambenahan Korps Humbaracı miturut cara Éropah lan adegé Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pasya, wong asal Prancis sing mlebu ing pangabdian Utsmaniyah, kanthi panyengkuyung Wazir Agung Hekimoğlu Ali Pasya ndadèkaké korps humbaracı (pasukan bom mortir) dadi kesatuan sing digaji lan ditata miturut cara Éropah. Telung atus prajurit sing dikumpulaké saka Bosnia diwènèhi latihan tumata adhedhasar petungan lan géometri; anggeran anyar kanggo organisasi, piranti lan pensiun disiapaké, sarta satus mriyem mortir lan sèket èwu bom mortir digawé nganggo téknik jaman iku. Humbarahâne, panggonan géometri diwulangaké, dianggep dadi wiji kapisan pendhidhikan rékayasa militèr modhèrn ing Utsmaniyah.", "181b7161"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Prajanjèn Istanbul — Kaukasus Kidul dipasrahaké marang Iran", "8c205aab"], "d": ["Perang Iran kapindho sing lumaku patang taun rampung kanthi prajanjèn sing ditandhatangani sawisé kalah gedhé ing Arpaçay sarta ilangé Ganja lan Tbilisi. Nagara Utsmaniyah mundur saka kabèh lemah Kaukasus Kidul lan Iran Kulon sing wis direbut wiwit 1723, lan tapel wates bali menyang garis Qasr-e Shirin taun 1639. Sing kari saka ekspedisi wétan telulas taun yaiku momotan dhuwit sing abot lan kas nagara sing kothong; suwaliké, tutupé garis ngarep wétan dadi bathi sing wigati banget kanggo perang anyar sing wis diwiwiti karo Rusia.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Bèntèng Özi (Ochakov) tiba ing tangan Rusia", "f93e61f3"], "d": ["Wadyabala Rusia kanthi pimpinan Marsekal Münnich ngepung Bèntèng Özi ing muara Kali Dnieper; pertahanan ambruk amarga gudhang amunisi mbledhos lan bèntèng iku tiba kanthi korban nyawa akèh banget. Ilangé Özi, sing dianggep dadi kuncining pesisir lor-kulon Segara Ireng, mbukak dalan menyang Krimea kanggo wong Rusia lan nuwuhaké gègèr gedhé ing Istanbul. Taun sabanjuré bèntèng iku ditinggal déning Rusia amarga pagebluk lan angèlé ngirim bekal, lan bali manèh menyang Utsmaniyah.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Kamenangan Banja Luka — Bosnia dislametaké", "f603865a"], "d": ["Nalika pasukan Austria mlebu Bosnia lan ngepung Banja Luka, gubernur Bosnia Hekimoğlu Ali Pasya enggal teka mbiyantu nggawa pasukan sing dikumpulaké saka warga satemené, lan nibakaké kekalahan abot marang mungsuh sing cacahé luwih akèh. Kamenangan iki nggagalaké rancangan Austria kanggo nguwasani Bosnia wiwit gebrakan kapisan, lan sisih lor provinsi iku dibalèkaké kabèh. Banja Luka dadi salah siji titik owah-owahan sing ndandani semangat wadyabala Utsmaniyah, sing sawisé 1683 terus-terusan mundur ngadhepi Austria.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Kamenangan Hisarcık (Grocka) — dalan menyang Beograd kabukak", "2101cdff"], "d": ["Wadyabala Austria sing maju kanggo njaga Beograd dicegat ing selat sempit ing pinggir Kali Donau lan nandhang karugian abot ing perang sing lumaku sedina muput. Nalika pasukan Marsekal Wallis mundur menyang Beograd kanthi semrawut, wadyabala Utsmaniyah tekan ing ngarep bèntèng lan miwiti pengepungan. Hisarcık minangka kamenangan perang lapangan sing paling mesthi nglawan Austria wiwit Karlowitz, lan langsung ndadèkaké Beograd bisa direbut manèh.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Prajanjèn Niš — tentrem karo Rusia, Azov didadèkaké nétral lan serbuan Krimea dimandhegaké", "674f974e"], "d": ["Rusia, sing kari ijèn sawisé Austria sarujuk tentrem ing Beograd, kepeksa mungkasi perang kanthi perantara duta Prancis Villeneuve. Bètèng-bètèng ing Bèntèng Azov dirubuhaké lan tlatah iku diumumaké dadi lemah nétral ing antarané rong nagara; Rusia nampa sarat ora oleh nduwé kapal perang lan kapal dagang ing Segara Ireng. Kanthi mangkono tujuané Rusia kanggo tekan segara mundur sagenerasi manèh, lan Nagara Utsmaniyah kanggo pungkasan ing abad kaping 18 tangi saka méja rembugan kanthi bathi.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi bali saka pendhudhukan Rusia: miturut prajanjian tentrem 1739 bèntèng dipasrahaké sawisé dirubuhaké", "7ecc2bef"], "d": ["Wong Rusia wis ngrebut Özi ing tanggal 11 Juli 1737. Miturut tentrem sing digawé karo Rusia ing taun 1739, bèntèng iku dipasrahaké manèh marang Utsmaniyah sawisé bètèng-bètèngé dirubuhaké; Utsmaniyah nguwasani Özi nganti taun 1788, sadurungé Prajanjèn Jassy.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Pertahanan Mosul — Nadir Syah dipukul mundur", "c03ffbc1"], "d": ["Nadir Syah, sing teka ing ngarep Mosul sawisé ngrebut Kirkuk lan Erbil, nembaki kutha iku nganggo mriyem sajrone patang puluh dina lan nindakaké serangan gedhé urut-urutan. Pertahanan sing dipimpin gubernur Husain Pasya al-Jalili, sing uga mènèhi gaman marang warga kutha, meksa wadyabala Iran mbatalaké pengepungan kanthi karugian abot. Kukuhé Mosul nyegah ilangé kabèh Irak lan ngukuhaké pangaribawané kulawarga Jalili ing kutha iku sajrone seabad.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Sekuthon Diriyah — adegé Kaémiran Saudi kapisan ing Najd", "188751bf"], "d": ["Emir Muhammad bin Saud, sing ngayomi ulama Muhammad bin Abdul Wahhab sing diusir saka Uyaynah ing Diriyah, ngadegaké sekuthon karo ulama iku sing masrahaké panguwasa pulitik kanggo ngabdi dakwah agama. Prejanjian iki miwiti sajarah anyar kanggo kulawarga Saud lan nyawijèkaké kaémiran-kaémiran oasis sing pating slebar ing Najd ing siji gerakan. Kakuwatan iki, sing sajrone setengah abad bakal tekan Karbala, Makkah lan Madinah, bakal meksa Nagara Utsmaniyah mbélani panguwasané ing Hijaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Prajanjèn Kerden — pungkasané perang Utsmaniyah-Iran", "1d3a919e"], "d": ["Liwat prajanjèn sing ditandhatangani sawisé perang pungkasan sing lumaku patang taun, tapel wates Qasr-e Shirin taun 1639 dianyaraké persis padha; ora ana pihak sing olèh tambahan lemah. Panjaluké Nadir Syah sing ngotot supaya Ja'fariyah diakoni minangka madzhab kalima ora diwangsuli, suwaliké diputusaké yen jamaah haji Iran kena nindakaké haji kanthi bébas lan duta kudu diijolaké. Kanthi mangkono perang Utsmaniyah-Iran sing wis lumaku luwih saka rong abad rampung ing kanyatan; tapel wates iki nganti saiki akèh-akèhé isih dijaga.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Sédané Mahmud I lan jumenengé Osman III", "30203700"], "d": ["Mahmud I, sing sajrone patlikur taun mréntah wis ngrebut manèh lemah sing ilang liwat Prajanjèn Beograd lan nyengkuyung pambenahan Korps Humbaracı, séda nalika bali saka selamlık Jumuah. Gantiné yaiku seduluré, Osman III, sing nganti umur sèket wolu taun urip ing kafes (kurungan istana). Pamaréntahan sing cendhak lan ora tentrem diwiwiti; ing mangsa Osman III, sing ngganti nem wazir agung sajrone telung taun, urusan nagara katon mandheg.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Sédané Osman III lan jumenengé Mustafa III", "3ac10f85"], "d": ["Kanthi sédané Osman III sawisé telung taun mréntah, Mustafa III, sing mbukak marang gagasan pambenahan lan nduwé kawigatèn gedhé marang urusan nagara, munggah tahta. Sultan anyar, kanthi ngendelaké pengalaman Wazir Agung Koca Râgıb Pasya, nyoba ndandani kahanan dhuwit nagara lan nganyaraké wadyabala; pasukan mriyem rikat gawéané Baron de Tott diadegaké ing mangsa iki. Nanging perang nglawan Rusia sing diwiwiti ing taun 1768 bakal nutupi kabèh asil pamaréntahan pitulas taun.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Pawartos perang marang Rusia — kadadéan Balta lan wiwité perang 1768-1774", "9c6aabe0"], "d": ["Nalika pasukan Rusia lan Kosak sing ngoyak Konfederasi Bar ing Polandia nggrebeg lan ngobong kutha cilik Balta ing tapel wates Utsmaniyah, Divan mutusaké perang lan duta Rusia dikunjara ing Yedikule. Perang sing dilakoni tanpa persiapan militèr sing tenanan lan diumumaké nem sasi sadurungé iku wiwit pisanan wis ala lakuné. Perjuangan sing bakal lumaku nem taun iki, kanthi serangan ing Çeşme, kekalahan ing Kartal lan pendhudhukan Krimea, dadi salah siji rerangkèn kekalahan paling abot ing sajarah Utsmaniyah.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Bèntèng Khotin ilang menyang Rusia", "66d43ea4"], "d": ["Sanajan rong upaya wadyabala Rusia kanthi pimpinan Pangéran Golitsyn wis dipukul mundur, amarga kekalahan sing dialami wazir agung ing antarané Kamaniçe lan Khotin, wadyabala mundur lan para penjaga ngosongaké bèntèng. Ilangé bètèng Utsmaniyah paling kuwat ing sisih lor Kali Donau tanpa perlawanan mbukak lawang Wallachia lan Moldavia kanggo wong Rusia. Rong kapangéranan iku diduduki ing taun sing padha; Khotin lagi bisa direbut manèh ing taun 1774 liwat Prajanjèn Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Kekalahan ing Dhataran Kartal (Kagul)", "6f408eaf"], "d": ["Telung minggu sawisé armada diobong ing Çeşme, wadyabala utama Utsmaniyah ing sadawané Kali Donau buyar ing dhataran Kartal ngadhepi pasukan Marsekal Rumyantsev sing cacahé adoh luwih sithik nanging tertib. Pakémahan, momotan lan atusan mriyem tiba ing tangan mungsuh; pasukan sing mlayu nandhang korban gedhé nalika nyabrang Kali Donau. Ancuré armada lan wadyabala dharatan sajrone musim panas sing padha njalari Kili, Akkerman, Ismail lan Bender tiba urut-urutan lan Krimea diduduki.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Pendhudhukan Rusia ing semenanjung Krimea", "217837b0"], "d": ["Wadyabala Rusia, sing setaun sadurungé wis ngrebut Bucak, kanthi pimpinan Pangéran Dolgorukov ngliwati Or Kapı (Perekop) lan nyerbu kabèh semenanjung Krimea. Khan diudhunaké saka tahta lan Sahib Giray sing pro-Rusia didadèkaké panguwasa, dadi langkah kapisan kanggo misahaké kakhanan iku saka Utsmaniyah. Ilangé Krimea, sing telung abad dadi taméng lor Utsmaniyah, minangka wiwitan proses kamardikan ing taun 1774 lan aneksasi langsung ing taun 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Sédané Mustafa III lan jumenengé Abdülhamid I", "42cba8e2"], "d": ["Gantiné Mustafa III, sing séda ing wektu paling gawat sajrone perang Rusia, yaiku seduluré Abdülhamid I, sing patang puluh telu taun urip ing kafes kraton, munggah tahta ing umur patang puluh sanga. Sultan anyar sing nampa salah siji mangsa paling angèl nagara iku kepeksa ngadhepi sarat-sarat abot Prajanjèn Küçük Kaynarca sing ditandhatangani ing taun sing padha. Pamaréntahané limalas taun diisi ilangé Krimea lan perang anyar karo Rusia, lan rampung amarga strok sing nibani nalika maca pawarta tibané Özi ing taun 1789.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Kekalahan Kozluca — kalah sing tumuju menyang Küçük Kaynarca", "8e0542f9"], "d": ["Pasukan Utsmaniyah sing nglumpuk ing ngarep Shumen dikalahaké ing Kozluca déning pasukan gabungan Suvorov lan Kamensky, lan bagéan gedhé wadyabala buyar. Kanthi kekalahan iki ora ana manèh kakuwatan sing bisa nahan ing Balkan; pasukan ngarep Rusia ngepung Shumen lan markas wazir agung kaancam. Yen durung ganep sesasi wis lungguh ing méja rembugan ing Küçük Kaynarca lan nampa sarat sing abot banget, iku asil langsung saka kekalahan iki.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Bukovina (Moldavia Lor) dipasrahaké marang Austria", "190f9caa"], "d": ["Austria, sing manfaataké lemahé kahanan amarga Küçük Kaynarca, njaluk tlatah Bukovina sing nyambungaké Moldavia lan Transylvania, lan olèh lemah iku tanpa perang, mung liwat ancaman lan sogokan. Ilangé tlatah subur lan stratégis ing sisih kidul-kulon Khotin iki nyuwèk kavoivodan Moldavia dadi loro ing kanyatan. Pasrah sing kedadéan tanpa sapeluru pun ditembakaké iki dianggep dadi salah siji tandha paling cetha yen Nagara Utsmaniyah wis ora duwé daya kanggo nggetak mungsuh. Kanthi pasrahé Bukovina ing taun 1775, Suceava lan Czernowitz pindhah menyang Austria (dina durung dikonfirmasi).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Basrah dikuwasani Iran", "0161e709"], "d": ["Sadiq Khan, seduluré panguwasa Zand Karim Khan, ngrebut Basrah sawisé pengepungan sing lumaku setaun, lan Nagara Utsmaniyah kélangan plabuhan paling wigati ing Teluk Basrah. Pendhudhukan iku langsung nggoncang dalan dagang India, pametu kurma lan mutiara, sarta pertahanan kidul Irak. Kutha iku lagi bisa direbut manèh ing taun 1779, nalika rebutan tahta kedadéan ing Iran amarga sédané Karim Khan.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihnâme Aynalıkavak — kasepakatan sauntara bab Krimea", "9b3b0468"], "d": ["Rong nagara sing wis ana ing pinggir perang amarga sapa sing bakal dadi pimpinan Kakhanan Krimea, kanthi perantara Prancis, nandhatangani naskah panjelasan ing Paviliun Aynalıkavak. Rusia sarujuk narik prajurité saka Krimea, déné Nagara Utsmaniyah sarujuk ngakoni Şahin Giray sing pro-Rusia dadi khan; hak kakhalifahan agama sultan marang Krimea dikukuhaké. Keseimbangan sing ringkih iki, sing bakal lumaku patang taun, ambruk kabèh nalika Rusia nganeksasi semenanjung iku kanthi langsung ing taun 1783.", "8a428802"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Pawartos perang marang Rusia — Perang Utsmaniyah-Rusia 1787-1792 diwiwiti", "3bfb870c"], "d": ["Amarga lelungan mèwah Katerina II menyang Krimea lan Géorgia sing dilebokaké ing pangayomané, Divan mutusaké perang kanthi tujuan mbalèkaké aneksasi, lan duta Rusia dikunjara manèh ing Yedikule. Nanging wadyabala durung siyap, kas nagara kothong, lan golèk sekuthu ora ana asilé. Perang sing lumaku limang taun iki rampung kanthi tibané Özi sing dibarengi pembantaian, ilangé Ismail lan sarat abot Prajanjèn Jassy.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Austria mèlu perang — perjuangan ing rong garis ngarep", "ae912290"], "d": ["Miturut sekuthon rahasia sing digawé karo Rusia ing taun 1781, kaisar Austria Joseph II mratélakaké perang marang Nagara Utsmaniyah lan obah tumuju Beograd lan Bosnia. Wadyabala Utsmaniyah dumadakan kudu perang ing rong garis ngarep bebarengan, Rusia ing lor lan Austria ing kulon. Sanajan menang nglawan Austria ing Lazarethane, Mehadia lan Şebeş, garis ngarep kulon uga ambruk amarga ilangé Beograd ing taun 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Sekuthon Utsmaniyah-Prusia", "03b88e51"], "d": ["Selim III, sing sanalika munggah tahta golèk sekuthu ing Éropah, nandhatangani prajanjèn sekuthon karo Prusia sing ngemot bab tulung-tinulung; Prusia nyanggupi mratélakaké perang marang Rusia lan Austria, déné Nagara Utsmaniyah nyanggupi ora bakal tentrem sadurungé Krimea direbut manèh. Iki naskah sekuthon timbal balik sejati sing kapisan ditandhatangani karo nagara Éropah ing sajarah Utsmaniyah lan nuduhaké yen pangerten lawas 'ora ana sekuthon karo wong kafir' wis ditinggalaké. Prusia ora mèlu perang, nanging kanthi meksa Austria supaya tentrem, Prusia mbukak dalan kanggo Prajanjèn Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Tibané Bèntèng Ismail lan pembantaiané", "6a296b0c"], "d": ["Bèntèng Ismail, sing dianggep bètèng paling kuwat ing delta Donau, direbut sajrone sedina liwat serangan gedhé sing getih-getihan pimpinan Jéndral Suvorov; garnisun lan warga kutha akèh-akèhé dipatèni nganggo pedhang. Pembantaian iki, sing nuwuhaké gaung amba ing Éropah, gawé kagèt banget masarakat Utsmaniyah lan nugel balung geger garis pertahanan Donau. Bèntèng iku direbut manèh setaun sabanjuré liwat Prajanjèn Jassy, nanging nasibé perang wis ditemtokaké sadurungé.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Prajanjèn Sistova — tutupé garis ngarep Austria", "58741f1d"], "d": ["Amarga tekanan Prusia lan Austria sing sibuk karo Révolusi Prancis ing kulon, rong nagara iku tentrem kanthi dhasar tapel wates sadurungé perang. Austria mbalèkaké kabèh panggonan sing diduduki, kalebu Beograd; Nagara Utsmaniyah mung nampa owah-owahan cilik ing tapel wates Kroasia. Tutupé garis ngarep kulon kanthi sarat iki ndadèkaké Nagara Utsmaniyah bisa nglumpukaké kabèh kakuwatané nglawan Rusia lan matesi kélangan ing Prajanjèn Jassy. Kanthi owah-owahan ing tapel wates Kroasia iki, Cetin (Cetingrad) lan Drežnik Grad pindhah saka Utsmaniyah menyang Habsburg (TDV zistovi-antlasmasi; Korić 2016, cathetan 118, bab 4). Nanging Orsova (Orsova Lawas) minangka siji-sijiné panggonan sing ora dibalèkaké (Bánlaky 0019/1796); atlas nyathet pasrah sacara hukum ing dina iki (pendhudhukan nyata 16 April 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Prajanjèn Jassy — ilangé Krimea sing pungkasan lan tapel wates Turla", "a56fd194"], "d": ["Liwat prajanjèn sing ditandhatangani ing pungkasan perang limang taun, Kali Turla (Dniester) ditampa minangka tapel wates; pinggir kiwa kali dadi duweké Rusia, pinggir tengen tetep duweké Utsmaniyah, lan Özi sakiwa-tengené ilang salawasé. Nagara Utsmaniyah nglalèkaké babar pisan pangarep-arep ngrebut manèh Krimea lan ngakoni aneksasi 1783 sacara hukum; Wallachia lan Moldavia dibalèkaké kanthi pembébasan pajeg rong taun. Kanthi nampa kewajiban mbayar ganti rugi perang rolas yuta kurus, sisih lor Segara Ireng dipasrahaké salawasé marang Rusia. Panggonan liya sing digabungaké ing tanggal sing padha: Ismail.", "277ee99d"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Panguwasan nyata Pazvandoğlu Osman ing Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, sing mbalela nglawan tatanan Nizam-i Jedid, nggawé gubernur Vidin mlayu, ngrebut kutha iku lan ngukuhaké nganggo parit jero ing sadawané Kali Donau. Ing taun 1797, nalika ana ing pucuk kakuwatané, dhèwèké nglumpukaké meh wolung puluh èwu pasukan lan nguwasani Nikopolis, Sistova, Rusçuk, Sofia lan Niš; dhèwèké ngenalaké awaké dudu minangka pembangkang nanging minangka pambenah. Pengepungan Bab-i Ali ing taun 1798-1799 sing lumaku pirang-pirang sasi ora ana asilé, lan nganti sédané ing taun 1807 dhèwèké mréntah Bulgaria Lor kanthi satengah mardika.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Pambukaan Mühendishâne-i Berrî-i Hümâyun (Sekolah Rékayasa Dharat)", "e9a3a34b"], "d": ["Kanggo nggladhi opsir artileri, bètèng lan juru péta kanggo wadyabala Nizam-i Jedid, sekolah rékayasa dharat dibukak ing Hasköy; iki padhanané Sekolah Rékayasa Angkatan Laut sing diadegaké ing taun 1773 kanggo wadyabala dharat. Ing kurikulumé diwulangaké aljabar, géometri, mékanika, bètèng lan balistik, sarta buku matématika lan artileri diterjemahaké saka basa-basa Éropah. Sekolah iki, sing dianggep dadi oyodé pendhidhikan rékayasa modhèrn ing Turki, dianggep dadi wiwitané Universitas Teknik Istanbul saiki.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Pawartos perang marang Prancis lan sekuthon karo Rusia lan Inggris", "80e95bd7"], "d": ["Amarga Napoleon nguwasani Mesir, Nagara Utsmaniyah medhot memitran tradhisional karo Prancis sing wis rong abad setengah lan mratélakaké perang marang Prancis. Ing proses sing padha, kanggo kapisan ing sajarahé, Utsmaniyah gawé sekuthon karo Rusia lan ngidinaké armada Rusia liwat Selat-selat tumuju Segara Tengah; banjur sekuthon karo Inggris uga ditandhatangani. Amarga sekuthon iki Kapuloan Ionia direbut saka Prancis, nanging mbukaké Selat-selat kanggo armada manca dadi conto sing ing tembé regané larang banget.", "7d8a9e45"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Pertahanan Akko — Napoleon dipukul mundur", "56b5c45b"], "d": ["Napoleon, sing maju saka Mesir menyang Suriah, ngepung Akko lan nindakaké serangan urut-urutan sajrone rong sasi; kutha iku dibélani Cezzâr Ahmed Pasya kanthi pitulungan armada Inggris lan pasukan Nizam-i Jedid sing dikirim saka Istanbul. Napoleon, sing kepeksa mbatalaké pengepungan lan mundur menyang Mesir, ngubur impèné mlebu menyang wétan ing ngarep tembok iku. Pawartané ditampa kanthi bungah banget ing Istanbul lan dianggep dadi bukti yen wadyabala latihan sing nembe diadegaké wis lulus ujian abot kapisané.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Serbuan Wahhabi menyang Karbala", "522341ed"], "d": ["Pasukan Wahhabi sing budhal saka Najd mlebu Karbala, njarah kutha, ngrusak pasaréyané Imam Husain lan matèni luwih saka telung èwu wong. Para gubernur Mamluk (kölemen) Nagara Utsmaniyah ing Irak ora bisa nyegah serbuan iku; kadadéan iki nuwuhaké reaksi gedhé ing Iran lan ing Istanbul. Serangan iki dadi pratandha yen gerakan Saudi wis ora mung kaémiran oasis manèh, nanging wis dadi kakuwatan tlatah sing ngancam kutha-kutha suci Utsmaniyah.", "f571ab30"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Prancis ngosongaké Mesir", "00cfdc8c"], "d": ["Amarga operasi bebarengan pasukan Utsmaniyah lan Inggris saka dharat lan segara, wiwitané Kairo banjur Iskandariyah dipasrahaké, lan pasukan Prancis dikirim bali menyang nagarané nganggo kapal. Nalika pendhudhukan telung taun rampung, Mesir ing dluwang bali menyang pamaréntahan Utsmaniyah, nanging rebutan panguwasa antarané para bèy kölemen lan pasukan Albania nyèrèt nagara iku menyang kaanan kisruh. Kekosongan iki sajrone sawetara taun nyiapaké dalan kanggo muncule Muhammad Ali saka Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Prajanjèn Paris — tentrem karo Prancis diadegaké manèh", "1b76991f"], "d": ["Liwat prajanjèn sing ditandhatangani sawisé Mesir dikosongaké, kahanan perang antarané Nagara Utsmaniyah lan Prancis resmi rampung lan kapitulasi lawas dianyaraké. Kapal dagang Prancis diidinaké mlebu Segara Ireng; suwaliké Prancis ngakoni kawutuhan wilayah Utsmaniyah. Adegé tentrem iki mènèhi manèh ruang obah kanggo pulitik njaban Selim III, sing kejepit antarané Rusia lan Inggris.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Wahhabi ngrebut Taif", "7b791359"], "d": ["Pasukan Wahhabi sing dipimpin Saud bin Abdul Aziz, ing gebrakan kapisan menyang Hijaz, ngepung lan njarah Taif; kutha iku tiba minangka lawang kapisan sing mbukak menyang tanah suci. Tumrap sultan Utsmaniyah sing nyandhang gelar pangayom Haramain, iki pukulan sing langsung nggoncang legitimasi kasultanan. Rong sasi setengah sabanjuré wadyabala sing padha bakal maju menyang Makkah.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Wahhabi ngrebut Makkah kanggo kapisan", "21157c05"], "d": ["Rong sasi setengah sawisé Taif tiba, pasukan Wahhabi mlebu Makkah, ngrubuhaké pasaréyan lan ngadegaké tatanan miturut pangertené dhéwé; Syarif Ghalib kepeksa mundur menyang Jeddah. Tutupé dalan kaji dadi gaung ing saindhenging jagad Islam lan meksa Istanbul njaluk pitulungan militèr marang gubernur Mesir, Muhammad Ali. Panguwasan kapisan iki mung bakal lumaku telung sasi.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Syarif Ghalib ngrebut manèh Makkah", "83d08dff"], "d": ["Syarif Ghalib, sing wis mundur menyang Jeddah, ngepung Makkah nganggo pasukan sing dikumpulaké, lan sawisé pengepungan selawé dina ngrebut manèh kutha iku saka Wahhabi; khotbah diwaca manèh nganggo asmané Utsmaniyah. Panguwasan kapindho iki uga ora langgeng; pasukan Saudi bakal ngrebut manèh kutha iku ing taun 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Wiwité Pambrontakan Serbia Kapisan", "0f6e8767"], "d": ["Nalika para dahi Yenisari pembangkang sing ngrebut pamaréntahan ing Beograd mbantai para pinituwa Serbia bebarengan, perlawanan sing nganggo gaman diwiwiti ing sangisoré pimpinan Karađorđe (Kara Yorgi). Gerakan iki, sing wiwitané tetep setya marang sultan lan mung nglawan para dahi, ora suwé dadi pambrontakan nasional sing njaluk otonomi lan kamardikan. Pasukan Serbia ngrebut Beograd ing taun 1806; pambrontakan iki dadi mata ranté kapisan gerakan kamardikan nasionalis ing Balkan.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Wahhabi nguwasani Madinah", "84e310d7"], "d": ["Sawisé Makkah, Madinah uga tiba ing tangan pasukan Wahhabi; kas Raudhah al-Muthahharah dibagi-bagi lan pasaréyan nganggo kubah ing kutha iku dirubuhaké. Kanthi mangkono rong kutha suci uwal bebarengan saka pangawasan Utsmaniyah lan kafilah kaji saka Damaskus lan Mesir pirang-pirang taun ora bisa budhal. Madinah lagi bisa direbut manèh pitung taun sabanjuré, ing taun 1812, déning wadyabala Mesir kanthi pimpinan Tosun Pasya, putrané Muhammad Ali Pasya.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Wiwité perang karo Rusia (Perang Utsmaniyah-Rusia 1806-1812) lan ditutupé Selat-selat", "ea170804"], "d": ["Nalika Selim III, sing sawisé kamenangan Napoleon ing Austerlitz nyedhak marang Prancis, ngudhunaké para voivode Wallachia lan Moldavia sanajan ditekan Rusia, wadyabala Rusia nguwasani rong kapangéranan iku lan perang diwiwiti. Nagara Utsmaniyah nutup Selat-selat kanggo armada Rusia; suwaliké Inggris uga mihak Rusia lan ngirim armada menyang Istanbul. Perang sing bakal lumaku nem taun iki, sing kecampur karo Pambrontakan Kabakçı lan diudhunaké Selim III saka tahta, bakal rampung kanthi ilangé Bessarabia ing Prajanjèn Bukares 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Armada Inggris teka ing ngarep Istanbul (Operasi Duckworth)", "195bb58f"], "d": ["Inggris, sing kepéngin meksa Nagara Utsmaniyah medhot sesambungan karo Prancis, ngliwataké armada pimpinan Laksamana Duckworth ing Dardanella lan nglabuhaké ing ngarep Istanbul. Uga kanthi pitedah duta Prancis Sébastiani, warga Istanbul diobahaké, batre mriyem pesisir dikuwataké sajrone sawetara dina, lan armada kepeksa mundur sadurungé bisa nembaki kutha; nalika bali armada iku nandhang karugian abot ing Dardanella. Kanggo kapisan ibu kutha kaancam saka cedhak banget déning armada manca, lan iku ndadèkaké perkara Selat-selat ana ing tengahé diplomasi Éropah.", "bf71116c"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Prajanjèn Kal'a-i Sultâniyye — tentrem karo Inggris lan kaidhah Selat-selat", "fe282117"], "d": ["Sawisé operasi Duckworth gagal, liwat prajanjèn sing ditandhatangani karo Inggris, perang antarané rong nagara rampung lan hak istimewa lawas para sudagar Inggris dibalèkaké. Katemtuan ing naskah sing diarani 'kaidhah kuna' nyathet yen ing mangsa tentrem ora ana kapal perang manca sing oleh liwat Selat-selat. Prinsip iki dadi dhasar hukum kanggo kabèh tatanan internasional sing sajrone abad kaping 19 mbentuk rézim Selat-selat.", "7ef33a02"]}
});
